package com.windowmarkers;

import java.util.*;

final class ActivityMenu
{
	private static final Map<String, String> NAMES = new LinkedHashMap<>();
	static
	{
		NAMES.put("Abyss", "Abyss runecrafting");
		NAMES.put("Chambers of Xeric/Challenge Mode", "Chambers of Xeric — Challenge Mode");
		NAMES.put("Chaos Temple (church)", "Chaos Altar prayer training");
		NAMES.put("Chest (Rogues' Castle)", "Rogues' Castle chest thieving");
		NAMES.put("Ecumenical key", "Ecumenical key farming");
		NAMES.put("Gout tuber", "Gout tuber gathering");
		NAMES.put("Krystilia", "Wilderness Slayer");
		NAMES.put("Raw anglerfish", "Anglerfish fishing");
		NAMES.put("Shades of Mort'ton (minigame)", "Shades of Mort'ton");
		NAMES.put("Slayer task/Dark beast", "Dark beasts — Slayer");
		NAMES.put("Slayer task/Drakes", "Drakes — Slayer");
		NAMES.put("Sulliuscep", "Sulliuscep woodcutting");
		NAMES.put("TzHaar Fight Cave", "Fight Caves");
	}

	static String canonical(String activity)
	{
		if ("Barbarian Assault/Advanced strategies".equals(activity))
			return "Barbarian Assault";
		if ("Slayer task/Fossil Island wyverns".equals(activity))
			return "Fossil Island Wyverns";
		return activity;
	}

	static String name(String activity)
	{
		return NAMES.getOrDefault(activity, activity);
	}

	static String query(String text)
	{
		String normalized = SearchText.normalize(text);
		for (Map.Entry<String, String> entry : NAMES.entrySet())
			if (SearchText.normalize(entry.getValue()).equals(normalized))
				return entry.getKey();
		return text;
	}

	static List<ActivitySetups.Setup> setups(String activity)
	{
		List<ActivitySetups.Setup> result = new ArrayList<>();
		if (activity != null)
			for (ActivitySetups.Setup setup : ActivitySetups.all())
				if (canonical(setup.activity).equals(canonical(activity)))
					result.add(setup);
		return result;
	}

	static List<BankCatalogue.Choice> choices(List<BankCatalogue.Choice> all)
	{
		List<BankCatalogue.Choice> result = new ArrayList<>();
		Set<String> seen = new HashSet<>();
		for (BankCatalogue.Choice choice : all)
		{
			if (choice.kind == BankCatalogue.Kind.ACTIVITY)
			{
				String activity = canonical((String) choice.value);
				if (!activity.equals("Hespori (Echo)") && seen.add(activity))
					result.add(new BankCatalogue.Choice(BankCatalogue.Kind.ACTIVITY, name(activity), activity));
			}
			else if (choice.kind == BankCatalogue.Kind.CUSTOM_PRESET || choice.kind == BankCatalogue.Kind.SAVED_GROUP)
				result.add(choice);
		}
		return result;
	}

	static List<BankCatalogue.Choice> activities()
	{
		List<BankCatalogue.Choice> raw = new ArrayList<>();
		for (String activity : ActivitySetups.activities(""))
			raw.add(new BankCatalogue.Choice(BankCatalogue.Kind.ACTIVITY, activity, activity));
		return choices(raw);
	}
}

package com.windowmarkers;

import java.awt.Component;
import javax.swing.*;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;

final class ActivitySetupPicker
{
	static ActivitySetups.Setup choose(Component parent)
	{
		return choose(parent, false);
	}

	static ActivitySetups.Setup choose(Component parent, boolean ge)
	{
		return choose(parent, ge, false);
	}

	static ActivitySetups.Setup chooseInventory(Component parent)
	{
		return choose(parent, false, true);
	}

	private static ActivitySetups.Setup choose(Component parent, boolean ge, boolean inventory)
	{
		JTextField search = new JTextField(32);
		JComboBox<BankCatalogue.Choice> activities = new JComboBox<>();
		java.util.List<BankCatalogue.Choice> available = ActivityMenu.activities();
		JComboBox<ActivitySetups.Setup> setups = new JComboBox<>();
		activities.setMaximumRowCount(12);
		setups.setMaximumRowCount(12);
		JTextArea notes = new JTextArea(7, 48);
		notes.setEditable(false);
		notes.setLineWrap(true);
		notes.setWrapStyleWord(true);
		JPanel panel = new MarkerForm();
		panel.add(new JLabel("Search activity"));
		panel.add(search);
		panel.add(activities);
		panel.add(new JLabel("Choose a setup"));
		panel.add(setups);
		panel.add(new JLabel(ge
				? "<html>Bank and GE tiers follow one equipment table and its conditions.<br>Selecting it narrows searches for that activity.<br>Example tables provide matches without tier colours.</html>"
				: "<html>One Wiki table or example at a time.<br>Review its conditions; quantities and a complete loadout are not assumed.<br>These setups keep all alternatives and start unchecked.</html>"));
		panel.add(notes);
		JButton source = new JButton("Open this Wiki setup source");
		source.addActionListener(e ->
		{
			ActivitySetups.Setup setup = (ActivitySetups.Setup) setups.getSelectedItem();
			if (setup != null)
			{
				net.runelite.client.util.LinkBrowser.browse(setup.source);
			}
		});
		panel.add(source);
		setups.addActionListener(e ->
		{
			ActivitySetups.Setup setup = (ActivitySetups.Setup) setups.getSelectedItem();
			notes.setText(setup == null ? "No matching setup."
					: setup.notes.isEmpty() ? "Check the linked guide for skill, quest and encounter requirements."
							: setup.notes);
			notes.setCaretPosition(0);
			source.setEnabled(setup != null);
		});
		activities.addActionListener(e ->
		{
			setups.removeAllItems();
			BankCatalogue.Choice selected = (BankCatalogue.Choice) activities.getSelectedItem();
			for (ActivitySetups.Setup setup : ActivityMenu.setups(selected == null ? null : selected.viewQuery()))
			{
				if (!inventory || SetupLoadout.inventoryTable(setup))
					setups.addItem(setup);
			}
		});
		Runnable refresh = () ->
		{
			Object previous = activities.getSelectedItem();
			activities.removeAllItems();
			java.util.List<BankCatalogue.Choice> found = BankCatalogue.search(available, search.getText(),
					available.size());
			for (BankCatalogue.Choice activity : found)
			{
				activities.addItem(activity);
			}
			if (previous != null && found.contains(previous))
			{
				activities.setSelectedItem(previous);
			}
		};
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			public void insertUpdate(DocumentEvent e)
			{
				refresh.run();
			}

			public void removeUpdate(DocumentEvent e)
			{
				refresh.run();
			}

			public void changedUpdate(DocumentEvent e)
			{
				refresh.run();
			}
		});
		refresh.run();
		if (!MarkerDialogs.confirm(parent, panel, ge ? "Choose bank / GE guide" : "Choose a Wiki activity setup", 680,
				520))
		{
			return null;
		}
		return (ActivitySetups.Setup) setups.getSelectedItem();
	}
}

package com.windowmarkers;

import java.util.*;

final class ActivitySetups
{
	static final class Setup
	{
		final String id, activity, label, source, notes;
		final Set<Integer> itemIds = new HashSet<>();

		Setup(String[] row)
		{
			id = row[0];
			activity = row[1];
			label = row[2];
			source = row[3];
			notes = row[4];
		}

		@Override
		public String toString()
		{
			return label;
		}

		Map<String, List<AutoCategories.Item>> suggest(List<AutoCategories.Item> owned)
		{
			Map<String, List<AutoCategories.Item>> result = new LinkedHashMap<>();
			for (AutoCategories.Item item : owned)
			{
				if (!itemIds.contains(item.id))
				{
					continue;
				}
				String requirement = SetupItemRequirements.reviewReason(id, item);
				String group = ItemVariantState.needsActivityReview(item) ? ItemVariantState.reviewGroup(item)
						: label + " — setup review";
				if (!requirement.isEmpty())
					group = "Needs preparation — " + requirement;
				AutoCategories.add(result, activity + " — " + ItemVariantState.annotate(group, item), item);
			}
			return result;
		}
	}

	private static final Map<String, Setup> SETUPS = new LinkedHashMap<>();
	static
	{
		for (String[] row : ItemTaxonomy.readRows("activity-setups.tsv", 5))
		{
			if (SETUPS.put(row[0], new Setup(row)) != null)
			{
				throw new IllegalStateException("Duplicate activity setup");
			}
		}
		for (String[] row : ItemTaxonomy.readRows("activity-setup-items.tsv", 2))
		{
			Setup setup = SETUPS.get(row[0]);
			if (setup == null)
			{
				throw new IllegalStateException("Missing activity setup");
			}
			setup.itemIds.add(Integer.parseInt(row[1]));
		}
	}

	static List<String> activities(String search)
	{
		String needle = search.trim().toLowerCase(Locale.ROOT);
		Set<String> result = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
		for (Setup setup : SETUPS.values())
		{
			if (setup.activity.toLowerCase(Locale.ROOT).contains(needle))
			{
				result.add(setup.activity);
			}
		}
		return new ArrayList<>(result);
	}

	static List<Setup> all()
	{
		return new ArrayList<>(SETUPS.values());
	}

	static Setup byId(String id)
	{
		return SETUPS.get(id);
	}

	static List<Setup> forActivity(String activity)
	{
		List<Setup> result = new ArrayList<>();
		for (Setup setup : SETUPS.values())
		{
			if (setup.activity.equals(activity))
			{
				result.add(setup);
			}
		}
		return result;
	}
}

package com.windowmarkers;

import java.util.*;

final class AutoCategories
{
	enum Preset
	{
		ALL_CATEGORIES("All classifications"), BROAD_TYPES("Broad item types"),
		SKILLING("Skilling — outfits, tools, boosts and materials"), SKILLING_OUTFITS("Skilling outfits only"),
		COMBAT_GROUPS("General combat and equipment sets"), FOOD_AND_POTIONS("Food, potions and restricted supplies"),
		TRAVEL_AND_UTILITY("Travel, storage and utility"), QUESTS_AND_CLUES("Quest and clue items"),
		COSMETICS("Cosmetic and utility equipment"), RAID_MEGA_RARES("Raid mega-rare weapons"),
		CHAMBERS_OF_XERIC("Chambers of Xeric — Wiki gear and supplies"),
		THEATRE_OF_BLOOD("Theatre of Blood — Wiki gear and supplies"),
		TOMBS_OF_AMASCUT("Tombs of Amascut — Wiki gear and supplies"),
		WIKI_ACTIVITY_SETUP("Choose a Wiki activity and setup…");

		private final String label;

		Preset(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	static final class Item
	{
		final int id;
		final String name;
		final boolean equipment;
		final String[] actions;
		final int slot;
		final int melee, ranged, magic;

		Item(int id, String name, boolean equipment, String[] actions, int melee, int ranged, int magic)
		{
			this(id, name, equipment, actions, melee, ranged, magic, -2);
		}

		Item(int id, String name, boolean equipment, String[] actions, int melee, int ranged, int magic, int slot)
		{
			this.id = id;
			this.name = name.toLowerCase(Locale.ROOT);
			this.equipment = equipment;
			this.actions = actions;
			this.melee = melee;
			this.ranged = ranged;
			this.magic = magic;
			this.slot = slot;
		}

		boolean action(String action)
		{
			return actions != null && Arrays.stream(actions).anyMatch(action::equalsIgnoreCase);
		}
	}

	static Map<String, List<Item>> suggest(Preset preset, List<Item> items)
	{
		Map<String, List<Item>> groups = new LinkedHashMap<>();
		if (preset == Preset.WIKI_ACTIVITY_SETUP)
		{
			return groups;
		}
		if (preset != Preset.RAID_MEGA_RARES && preset != Preset.CHAMBERS_OF_XERIC && preset != Preset.THEATRE_OF_BLOOD
				&& preset != Preset.TOMBS_OF_AMASCUT)
		{
			for (Item item : items)
			{
				if (ItemVariantState.identityNeedsReview(item))
				{
					if (preset == Preset.BROAD_TYPES || preset == Preset.ALL_CATEGORIES)
					{
						add(groups, ItemVariantState.reviewGroup(item), item);
					}
					continue;
				}
				boolean standalone = standaloneSetWeapon(item, items);
				String group;
				if (preset == Preset.BROAD_TYPES || preset == Preset.ALL_CATEGORIES)
				{
					group = standalone ? ItemTaxonomy.weaponRole(ItemVariantState.familyName(item))
							: category(item, true);
				}
				else if (preset == Preset.COMBAT_GROUPS)
				{
					group = WikiCatalogue.category(item, preset);
					String set = ItemTaxonomy.equipmentSet(ItemVariantState.familyName(item)),
							role = ItemTaxonomy.weaponRole(ItemVariantState.familyName(item));
					if (set != null && !standalone)
					{
						group = set;
					}
					else if (role != null && !role.equals("Tools"))
					{
						group = role;
					}
					else if ("Tools".equals(role))
					{
						group = null;
					}
					else if (group == null && item.equipment && !WikiCatalogue.hasFacet(item, "outfit")
							&& !WikiCatalogue.hasFacet(item, "cosmetic") && !WikiCatalogue.hasFacet(item, "skilling"))
					{
						group = "Other — equipment role needs review";
					}
				}
				else
				{
					group = WikiCatalogue.category(item, preset);
				}
				if (group != null)
				{
					add(groups, ItemVariantState.annotate(group, item), item);
				}
			}
			return groups;
		}
		if (preset == Preset.RAID_MEGA_RARES)
		{
			for (Item item : items)
				if (ItemTaxonomy.matchesAny(item, "twisted bow", "scythe of vitur", "tumeken's shadow"))
				{
					add(groups, ItemVariantState.needsActivityReview(item) ? ItemVariantState.reviewGroup(item)
							: "Raid mega-rare weapons", item);
				}
			return groups;
		}
		return RaidRecommendations.suggest(preset, items);
	}

	private static boolean standaloneSetWeapon(Item item, List<Item> bank)
	{
		String set = ItemTaxonomy.equipmentSet(ItemVariantState.familyName(item)),
				role = ItemTaxonomy.weaponRole(ItemVariantState.familyName(item));
		if (set == null || role == null || role.equals("Tools"))
		{
			return false;
		}
		return bank.stream()
				.noneMatch(other -> set.equals(ItemTaxonomy.equipmentSet(ItemVariantState.familyName(other)))
						&& ItemTaxonomy.weaponRole(ItemVariantState.familyName(other)) == null
						&& !ItemTaxonomy.baseName(ItemVariantState.familyName(other)).equals("berserker necklace"));
	}

	static String category(Item item, boolean combat)
	{
		String n = ItemTaxonomy.baseName(ItemVariantState.familyName(item));
		String set = ItemTaxonomy.equipmentSet(n);
		if (set != null)
		{
			return set + (ItemTaxonomy.needsRepair(item.name) ? " — repair needed" : "");
		}
		if (n.contains("rock cake") || n.equals("locator orb"))
		{
			return "Health-lowering utility";
		}
		if (n.startsWith("blighted "))
		{
			return "Restricted-use supplies — blighted";
		}
		if (n.equals("purple sweets"))
		{
			return "Specialist food — purple sweets";
		}
		String catalogue = WikiCatalogue.category(item, Preset.ALL_CATEGORIES);
		String weapon = ItemTaxonomy.weaponRole(n);
		if (weapon != null && !weapon.equals("Tools"))
		{
			return combat ? weapon : "Equipment";
		}
		if (catalogue != null && !catalogue.startsWith("Equipment —")
				&& !catalogue.startsWith("Cosmetic/utility equipment"))
		{
			return catalogue;
		}
		String role = ItemTaxonomy.weaponRole(n);
		if (role != null)
		{
			return combat || role.equals("Tools") ? role : "Equipment";
		}
		if (catalogue != null)
		{
			return catalogue;
		}
		if (item.equipment)
		{
			if (!combat)
			{
				return "Equipment";
			}

			int styles = (item.magic > 0 ? 1 : 0) + (item.ranged > 0 ? 1 : 0) + (item.melee > 0 ? 1 : 0);
			if (styles > 1)
			{
				return "Hybrid equipment";
			}
			if (item.magic > 0)
			{
				return "Magic equipment";
			}
			if (item.ranged > 0)
			{
				return "Ranged equipment";
			}
			if (item.melee > 0)
			{
				return "Melee equipment";
			}
			return "Defensive or utility equipment — review";
		}
		if (n.endsWith(" rune"))
		{
			return "Runes";
		}
		if (item.action("Eat"))
		{
			return "Food — general, not activity advice";
		}
		if (item.action("Drink"))
		{
			if (n.matches(".*(?:potion|serum|antifire|antidote|antipoison|antivenom|anti-venom).*")
					|| n.equals("saradomin brew") || n.equals("zamorak brew") || n.equals("super restore"))
			{
				return "Potions — general, not activity advice";
			}
			return "Drinks and brews — review";
		}
		if (n.endsWith(" ore") || n.endsWith(" logs") || n.equals("logs") || n.endsWith(" seed")
				|| n.startsWith("grimy ") || n.endsWith(" bar") || n.equals("coal") || n.equals("pure essence")
				|| n.equals("rune essence"))
		{
			return "Resources";
		}
		return "Other — review";
	}

	static void add(Map<String, List<Item>> groups, String group, Item item)
	{
		List<Item> list = groups.computeIfAbsent(group, k -> new ArrayList<>());
		if (list.stream().noneMatch(i -> i.id == item.id))
		{
			list.add(item);
		}
	}
}

package com.windowmarkers;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.runelite.api.KeyCode;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseWheelListener;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

final class BankActionBar extends MouseAdapter implements MouseWheelListener
{
	private static final String SPLITTER = "split";
	private static final Color RAIL_BORDER = new Color(110, 110, 100, 95);
	private final BankLayoutController owner;
	private final Map<Widget, Geometry> geometry = new IdentityHashMap<>();
	private final Map<Widget, Boolean> hidden = new IdentityHashMap<>();
	private final Map<Widget, Boolean> hiddenApplied = new IdentityHashMap<>();
	private final BankSharedTagRail sharedTags = new BankSharedTagRail(this);
	private volatile Snapshot snapshot;
	private volatile Snapshot displaySnapshot;
	private Gesture gesture;
	private BankActionLayout draft;
	private String lastDraft;
	private boolean captured, suppressClick, cancelled;
	private volatile long context;
	BankActionLayout.Plan plan;
	private String planned;
	final Overlay overlay = new ActionOverlay();

	BankActionBar(BankLayoutController owner)
	{
		this.owner = owner;
	}

	private static final class Geometry
	{
		final int[] original;
		int[] applied;

		Geometry(Widget w)
		{
			original = read(w);
		}

		static int[] read(Widget w)
		{
			return new int[] { w.getOriginalX(), w.getOriginalY(), w.getOriginalWidth(), w.getOriginalHeight(),
					w.getXPositionMode(), w.getYPositionMode(), w.getWidthMode(), w.getHeightMode() };
		}
	}

	static final class Button
	{
		final Widget button;
		final List<Widget> parts;

		Button(Widget button, Widget... parts)
		{
			this.button = button;
			this.parts = new ArrayList<>(Arrays.asList(parts));
		}

		Button(Widget button, List<Widget> parts)
		{
			this.button = button;
			this.parts = new ArrayList<>(parts);
		}
	}

	private static final class Snapshot
	{
		final Widget bank, items;
		final Rectangle area, bankBounds, itemBounds, tagBounds;
		final Map<String, Rectangle> buttons, placements;
		final Map<String, Character> docks;
		final String layout, profile;
		final boolean tags, adjustableDivider;
		final int bottomHeight, tagTop, tagMaxOffset;
		final long context;

		Snapshot(Widget bank, Widget items, Rectangle area, Map<String, Rectangle> buttons, BankActionLayout.Plan plan,
				String layout, String profile, boolean tags, boolean adjustableDivider, long context,
				Rectangle tagBounds)
		{
			this.bank = bank;
			this.items = items;
			this.area = new Rectangle(area);
			this.buttons = buttons;
			this.layout = layout;
			this.profile = profile;
			this.tags = tags;
			this.bottomHeight = plan.bottomHeight;
			tagTop = plan.tagTop;
			tagMaxOffset = plan.tagMaxOffset;
			this.context = context;
			bankBounds = new Rectangle(BankWidgetGeometry.bounds(bank));
			itemBounds = new Rectangle(BankWidgetGeometry.bounds(items));
			this.tagBounds = tagBounds == null ? null : new Rectangle(tagBounds);
			this.adjustableDivider = adjustableDivider;
			this.placements = new LinkedHashMap<>();
			plan.bounds.forEach((key, r) -> this.placements.put(key, new Rectangle(r)));
			this.docks = new LinkedHashMap<>(plan.docks);
		}

		Rectangle splitter()
		{
			return new Rectangle(area.x + 1, area.y + tagTop - 5, 48, 5);
		}
	}

	private static final class Gesture
	{
		final Snapshot start;
		final String key;
		final Point pressed, point;
		final boolean released;

		Gesture(Snapshot start, String key, Point pressed, Point point, boolean released)
		{
			this.start = start;
			this.key = key;
			this.pressed = pressed;
			this.point = point;
			this.released = released;
		}

		Gesture at(Point p, boolean released)
		{
			return new Gesture(start, key, pressed, p, released);
		}
	}

	boolean enabled()
	{
		if (!owner.active() || !owner.config.bankActionRail())
			return false;
		Widget container = owner.client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		return owner.bankTagsService == null || owner.bankTagsService.getActiveLayout() == null
				|| container != null && container.getWidth() >= 560;
	}

	boolean tagSpace()
	{
		Widget container = owner.client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		return owner.config.bankActionTagSpace() && container != null && container.getHeight() >= 250;
	}

	Map<String, Button> buttons()
	{
		Map<String, Button> result = new LinkedHashMap<>();
		for (BankControl control : BankControl.values())
			add(result, control.name(), owner.client.getWidget(control.button),
					owner.client.getWidget(control.graphic));
		int[] ids = { InterfaceID.Bankmain.WORNITEMS_BUTTON, InterfaceID.Bankmain.MENU_BUTTON,
				InterfaceID.Bankmain.BANK_TUT, InterfaceID.Bankmain.INCINERATOR_TARGET,
				InterfaceID.Bankmain.POPUP_BUTTON_OUT, InterfaceID.Bankmain.GIM_STORAGE,
				InterfaceID.Bankmain.POTIONSTORE_BUTTON };
		String[] names = { "EQUIPMENT", "SETTINGS", "HELP", "INCINERATOR", "POPUP", "GROUP_STORAGE", "POTION_STORE" };
		for (int i = 0; i < ids.length; i++)
		{
			if (ids[i] == InterfaceID.Bankmain.WORNITEMS_BUTTON && owner.config.restoreOriginalWornEquipmentButton())
				continue;
			add(result, names[i], owner.client.getWidget(ids[i]));
		}
		Widget frame = owner.client.getWidget(InterfaceID.Bankmain.FRAME);
		if (frame != null && frame.getChildren() != null)
			for (Widget child : frame.getChildren())
				if (child != null && child.getActions() != null && Arrays.asList(child.getActions()).contains("Close"))
					add(result, "CLOSE", child);
		if (owner.screenshotButton != null)
			add(result, "CAMERA", owner.screenshotButton.widget());
		if (owner.bankPicker != null && visible(owner.bankPicker.widget()))
			result.put("PRESETS", new Button(owner.bankPicker.widget(), owner.bankPicker.parts()));
		return result;
	}

	private static void add(Map<String, Button> buttons, String key, Widget widget, Widget... parts)
	{
		if (visible(widget))
			buttons.put(key, new Button(widget, parts));
	}

	private static boolean visible(Widget w)
	{
		return w != null && !w.isHidden() && w.getWidth() > 0 && w.getHeight() > 0;
	}

	private static Dimension size(String key, Widget button)
	{
		return new Dimension(key.equals("SEARCH") ? 36 : button.getWidth(), button.getHeight());
	}

	BankActionLayout.Plan plan(Widget container)
	{
		Map<String, Dimension> sizes = new LinkedHashMap<>();
		buttons().forEach((key, b) -> sizes.put(key, size(key, b.button)));
		BankActionLayout selected = draft == null ? BankActionLayout.read(owner.config.bankActionLayout()) : draft;
		plan = selected.plan(container.getWidth(), container.getHeight(), sizes, tagSpace());
		planned = signature(container, sizes);
		return plan;
	}

	boolean changed()
	{
		Widget container = owner.client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		if (container == null)
			return true;
		Map<String, Dimension> sizes = new LinkedHashMap<>();
		buttons().forEach((key, b) -> sizes.put(key, size(key, b.button)));
		return !Objects.equals(planned, signature(container, sizes));
	}

	private String signature(Widget container, Map<String, Dimension> sizes)
	{
		return container.getWidth() + ":" + container.getHeight() + ":" + tagSpace() + ":" + sizes + ":"
				+ (draft == null ? owner.config.bankActionLayout() : draft.write());
	}

	void apply(Widget container)
	{
		if (plan == null)
			return;
		restoreHidden();
		restoreGeometry();
		hide(owner.client.getWidget(InterfaceID.Bankmain.SCROLLBAR));
		if (owner.potionsVisible())
		{
			hide(owner.client.getWidget(InterfaceID.Bankmain.ITEMS));
			hide(owner.client.getWidget(InterfaceID.Bankmain.POTIONSTORE_SCROLLBAR));
		}
		Map<String, Button> buttons = buttons();
		for (int id : new int[] { InterfaceID.Bankmain.BOTTOM, InterfaceID.Bankmain.QUANTITY_LAYER })
		{
			Widget w = owner.client.getWidget(id);
			if (w == null)
				continue;
			edit(w, 0, 0, 0, 0, WidgetPositionMode.ABSOLUTE_LEFT, WidgetPositionMode.ABSOLUTE_TOP, WidgetSizeMode.MINUS,
					WidgetSizeMode.MINUS);
		}
		for (int id : new int[] { InterfaceID.Bankmain.BOTTOM_LINE4, InterfaceID.Bankmain.BOTTOM_LINE6,
				InterfaceID.Bankmain.DEPOSIT_LINE })
			hide(owner.client.getWidget(id));
		if (plan.bounds.containsKey("GROUP_STORAGE") || plan.bounds.containsKey("POTION_STORE"))
		{
			Widget storage = owner.client.getWidget(InterfaceID.Bankmain.STORAGE_POPUP_TAB);
			if (storage != null)
				edit(storage, 0, 0, 0, 0, WidgetPositionMode.ABSOLUTE_LEFT, WidgetPositionMode.ABSOLUTE_TOP,
						WidgetSizeMode.MINUS, WidgetSizeMode.MINUS);
			hide(owner.client.getWidget(InterfaceID.Bankmain.STORAGE_POPUP_TAB_FRAME));
		}
		Rectangle area = BankWidgetGeometry.bounds(container);
		Button equipment = buttons.get("EQUIPMENT");
		if (equipment != null && !plan.bounds.containsKey("EQUIPMENT"))
		{
			Rectangle bounds = BankWidgetGeometry.bounds(equipment.button);
			move(equipment.button, area.x + area.width - BankActionLayout.RAIL / 2 - bounds.width / 2,
					area.y + Math.max(0, (BankActionLayout.TOP - bounds.height) / 2));
		}
		for (Map.Entry<String, Rectangle> entry : plan.bounds.entrySet())
		{
			Button button = buttons.get(entry.getKey());
			if (button == null)
				continue;
			Rectangle target = new Rectangle(entry.getValue());
			target.translate(area.x, area.y);
			Rectangle original = BankWidgetGeometry.bounds(button.button);
			List<Rectangle> partBounds = new ArrayList<>();
			for (Widget part : button.parts)
				partBounds.add(part == null ? null : new Rectangle(BankWidgetGeometry.bounds(part)));
			if (entry.getKey().equals("SEARCH"))
				edit(button.button, button.button.getOriginalX(), button.button.getOriginalY(), 36,
						button.button.getOriginalHeight(), button.button.getXPositionMode(),
						button.button.getYPositionMode(), WidgetSizeMode.ABSOLUTE, button.button.getHeightMode());
			move(button.button, target.x, target.y);
			for (int i = 0; i < button.parts.size(); i++)
			{
				Rectangle r = partBounds.get(i);
				Widget part = button.parts.get(i);
				if (r == null)
					continue;
				BankControl standard = null;
				try
				{
					standard = BankControl.valueOf(entry.getKey());
				}
				catch (IllegalArgumentException ignored)
				{
				}
				if (standard != null)
				{
					if (standard.quantity())
						edit(part, part.getOriginalX(), part.getOriginalY(), 25, 21, part.getXPositionMode(),
								part.getYPositionMode(), WidgetSizeMode.ABSOLUTE, WidgetSizeMode.ABSOLUTE);
					move(part, target.x + (standard == BankControl.SEARCH ? 4 : standard.iconX),
							target.y + standard.iconY);
				}
				else
					move(part, target.x + r.x - original.x, target.y + r.y - original.y);
			}
		}
		if (tagSpace())
			sharedTags.apply(container, plan.tagTop);
	}

	void applyCompactSearch()
	{
		if (!owner.config.compactBankSearch() || enabled())
			return;
		Widget button = owner.client.getWidget(InterfaceID.Bankmain.SEARCH);
		Widget icon = owner.client.getWidget(InterfaceID.Bankmain.SEARCH_GRAPHIC);
		if (!visible(button) || !visible(icon) || button.getWidthMode() != WidgetSizeMode.ABSOLUTE
				|| button.getWidth() < 36 || icon.getWidth() > 36)
			return;
		Rectangle iconBounds = BankWidgetGeometry.bounds(icon);
		edit(button, button.getOriginalX(), button.getOriginalY(), 36, button.getOriginalHeight(),
				button.getXPositionMode(), button.getYPositionMode(), WidgetSizeMode.ABSOLUTE, button.getHeightMode());
		Rectangle bounds = BankWidgetGeometry.bounds(button);
		move(icon, bounds.x + (36 - iconBounds.width + 1) / 2, iconBounds.y);
	}

	void move(Widget widget, int x, int y)
	{
		Widget parent = widget.getParent();
		if (parent == null)
			return;
		Rectangle bounds = BankWidgetGeometry.bounds(parent);
		edit(widget, x - bounds.x + parent.getScrollX(), y - bounds.y + parent.getScrollY(), widget.getOriginalWidth(),
				widget.getOriginalHeight(), WidgetPositionMode.ABSOLUTE_LEFT, WidgetPositionMode.ABSOLUTE_TOP,
				widget.getWidthMode(), widget.getHeightMode());
	}

	private void edit(Widget w, int x, int y, int width, int height, int xm, int ym, int wm, int hm)
	{
		Geometry g = geometry.computeIfAbsent(w, Geometry::new);
		int[] current = Geometry.read(w);
		for (int i = 0; i < current.length; i++)
			if (g.applied == null || current[i] != g.applied[i])
				g.original[i] = current[i];
		w.setPos(x, y, xm, ym);
		w.setSize(width, height, wm, hm);
		revalidate(w);
		g.applied = Geometry.read(w);
	}

	private static void revalidate(Widget widget)
	{
		widget.revalidate();
		if (widget.getId() != InterfaceID.Bankmain.SEARCH)
			return;
		Widget[] children = widget.getDynamicChildren();
		if (children != null)
			for (Widget child : children)
				if (child != null)
					child.revalidate();
	}

	private void hide(Widget w)
	{
		visibility(w, true);
	}

	void visibility(Widget w, boolean value)
	{
		if (w == null || w.isSelfHidden() == value)
			return;
		hidden.putIfAbsent(w, w.isSelfHidden());
		hiddenApplied.put(w, value);
		w.setHidden(value);
	}

	void restoreHidden()
	{
		hidden.forEach((w, value) ->
		{
			if (w.isSelfHidden() == hiddenApplied.get(w))
				w.setHidden(value);
		});
		hidden.clear();
		hiddenApplied.clear();
	}

	void beforeFrame()
	{
		sharedTags.beforeFrame();
		restoreHidden();
		restoreGeometry();
	}

	void restore()
	{
		restoreHidden();
		sharedTags.restore();
		restoreGeometry();
		plan = null;
		planned = null;
		snapshot = null;
		displaySnapshot = null;
	}

	private void restoreGeometry()
	{
		geometry.forEach((w, g) ->
		{
			int[] current = Geometry.read(w), r = g.original.clone();
			for (int i = 0; i < r.length; i++)
				if (g.applied == null || current[i] != g.applied[i])
					r[i] = current[i];
			w.setPos(r[0], r[1], r[4], r[5]);
			w.setSize(r[2], r[3], r[6], r[7]);
			revalidate(w);
		});
		geometry.clear();
	}

	@Override
	public synchronized MouseEvent mousePressed(MouseEvent event)
	{
		suppressClick = false;
		Snapshot s = snapshot;
		if (event.isConsumed() || s == null || event.isControlDown() || event.isMetaDown()
				|| event.getButton() != MouseEvent.BUTTON1)
			return event;
		if (s.tags && s.adjustableDivider && s.splitter().contains(event.getPoint()))
		{
			gesture = new Gesture(s, SPLITTER, event.getPoint(), event.getPoint(), false);
			captured = true;
			cancelled = false;
			event.consume();
			return event;
		}
		if (!event.isAltDown())
			return event;
		for (Map.Entry<String, Rectangle> entry : s.buttons.entrySet())
			if (entry.getValue().contains(event.getPoint()))
			{
				gesture = new Gesture(s, entry.getKey(), event.getPoint(), event.getPoint(), false);
				captured = true;
				cancelled = false;
				event.consume();
				break;
			}
		return event;
	}

	@Override
	public synchronized MouseEvent mouseDragged(MouseEvent event)
	{
		if (captured)
		{
			event.consume();
			if (gesture != null)
				gesture = gesture.at(event.getPoint(), false);
		}
		return event;
	}

	@Override
	public synchronized MouseEvent mouseReleased(MouseEvent event)
	{
		if (captured && event.getButton() == MouseEvent.BUTTON1)
		{
			event.consume();
			captured = false;
			suppressClick = true;
			if (gesture != null)
				gesture = gesture.at(event.getPoint(), true);
		}
		return event;
	}

	@Override
	public synchronized MouseEvent mouseClicked(MouseEvent event)
	{
		if (suppressClick && event.getButton() == MouseEvent.BUTTON1)
		{
			event.consume();
			suppressClick = false;
		}
		return event;
	}

	@Override
	public synchronized MouseEvent mouseExited(MouseEvent event)
	{
		if (captured)
			cancel();
		return event;
	}

	synchronized void cancel()
	{
		cancelled = true;
		snapshot = null;
		context++;
	}

	synchronized void clearInput()
	{
		snapshot = null;
		displaySnapshot = null;
		gesture = null;
		draft = null;
		lastDraft = null;
		cancelled = false;
		context++;
	}

	synchronized void resetInput()
	{
		clearInput();
		captured = false;
		suppressClick = false;
	}

	synchronized int update()
	{
		Gesture g = gesture;
		if (g == null)
			return 0;
		Widget bank = owner.client.getWidget(InterfaceID.Bankmain.UNIVERSE),
				container = owner.client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		if (cancelled || !available() || bank != g.start.bank || container == null
				|| !BankWidgetGeometry.bounds(container).equals(g.start.area)
				|| !Objects.equals(profile(), g.start.profile) || context != g.start.context
				|| (g.key.equals(SPLITTER) ? !tagSpace() || !owner.config.bankTagDividerResizable()
						: !buttons().containsKey(g.key)))
		{
			boolean changed = draft != null;
			clearInput();
			return changed ? 2 : 0;
		}
		if (draft == null && g.pressed.distanceSq(g.point) < 16)
		{
			if (g.released)
				clearInput();
			return 0;
		}
		Rectangle area = g.start.area;
		int x = g.point.x - area.x, y = g.point.y - area.y;
		BankActionLayout next = BankActionLayout.read(g.start.layout);
		if (g.key.equals(SPLITTER))
		{
			int original = g.start.tagTop - BankActionLayout.tagTop(area.height, g.start.bottomHeight);
			next.tagOffset = Math.max(0, Math.min(g.start.tagMaxOffset, original + g.point.y - g.pressed.y));
			return preview(next, g.released);
		}
		char dock = y < 0 && g.start.bankBounds.contains(g.point) ? 'N'
				: y >= area.height - g.start.bottomHeight - 6 ? 'B'
						: x >= area.width - 54 ? 'R'
								: x < 52 && g.start.tags && y >= g.start.tagTop ? 'T' : x >= 52 && x < 100 ? 'L' : 0;
		if (!g.start.bankBounds.contains(g.point) || dock == 0)
		{
			if (g.released)
			{
				clearInput();
				return 2;
			}
			return 0;
		}
		Rectangle target = new Rectangle(g.start.buttons.get(g.key));
		Rectangle rail = BankActionLayout.rail(dock, area.width, area.height, g.start.bottomHeight, g.start.tagTop);
		if (dock != 'N')
		{
			boolean valid = target.width <= rail.width && target.height <= rail.height
					&& (dock != 'L' || area.width >= 536);
			if (!valid)
			{
				if (g.released)
				{
					clearInput();
					return 2;
				}
				return 0;
			}
		}
		Point position = new Point(target.x - area.x + g.point.x - g.pressed.x,
				target.y - area.y + g.point.y - g.pressed.y);
		next.insert(g.key, dock, position, rail, g.start.placements, g.start.docks);
		return preview(next, g.released);
	}

	private int preview(BankActionLayout next, boolean released)
	{
		String encoded = next.write();
		boolean changed = !encoded.equals(lastDraft);
		draft = next;
		lastDraft = encoded;
		if (released)
		{
			clearInput();
			owner.configs.setConfiguration("windowmarkers", "bankActionLayout", encoded);
			owner.queueRebuild();
			return 2;
		}
		return changed ? 1 : 0;
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent event)
	{
		Snapshot s = snapshot;
		if (event.isConsumed() || s == null)
			return event;
		boolean tags = s.tagBounds != null && s.tagBounds.contains(event.getPoint());
		if (!tags && !s.itemBounds.contains(event.getPoint()))
			return event;
		int delta = (int) Math.round(event.getPreciseWheelRotation() * 36);
		if (delta == 0)
			return event;
		event.consume();
		owner.clientThread.invokeLater(() ->
		{
			if (s.context != context || !available() || !Objects.equals(s.profile, profile())
					|| owner.activeItems() != s.items
					|| owner.client.getWidget(InterfaceID.Bankmain.UNIVERSE) != s.bank)
				return;
			if (tags)
			{
				sharedTags.scroll(event.getWheelRotation());
				return;
			}
			int max = Math.max(0, s.items.getScrollHeight() - s.items.getHeight());
			int position = (int) Math.max(0, Math.min(max, (long) s.items.getScrollY() + delta));
			s.items.setScrollY(position);
			if (!owner.potionsVisible())
			{
				owner.client.setVarcIntValue(VarClientID.BANK_SCROLLPOS, position);
			}
		});
		return event;
	}

	void capture()
	{
		if (!available(false) || plan == null)
		{
			snapshot = null;
			displaySnapshot = null;
			return;
		}
		Widget bank = owner.client.getWidget(InterfaceID.Bankmain.UNIVERSE),
				container = owner.client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER), items = owner.activeItems();
		Map<String, Rectangle> bounds = new LinkedHashMap<>();
		buttons().forEach((key, b) -> bounds.put(key, new Rectangle(BankWidgetGeometry.bounds(b.button))));
		displaySnapshot = new Snapshot(bank, items, BankWidgetGeometry.bounds(container), bounds, plan,
				draft == null ? owner.config.bankActionLayout() : draft.write(), profile(), tagSpace(),
				owner.config.bankTagDividerResizable(), context, sharedTags.wheelArea);
		snapshot = available() ? displaySnapshot : null;
	}

	private String profile()
	{
		return owner.configs == null || owner.configs.getProfile() == null ? null
				: owner.configs.getProfile().getId() + "";
	}

	private boolean available()
	{
		return available(true);
	}

	private boolean available(boolean input)
	{
		if (!enabled() || owner.client.getGameState() != net.runelite.api.GameState.LOGGED_IN
				|| input && (owner.client.isMenuOpen() || owner.client.getDraggedWidget() != null))
			return false;
		for (int id : new int[] { InterfaceID.Bankmain.UNIVERSE, InterfaceID.Bankmain.ITEMS_CONTAINER })
			if (!visible(owner.client.getWidget(id)))
				return false;
		if (!visible(owner.activeItems()))
			return false;
		for (int id : new int[] { InterfaceID.Bankmain.INCINERATOR_CONFIRM,
				InterfaceID.Bankmain.BANKTAGS_POPUP_STRINGEXPORT_CONTAINER })
			if (visible(owner.client.getWidget(id)))
				return false;
		return true;
	}

	private final class ActionOverlay extends Overlay
	{
		ActionOverlay()
		{
			setPosition(OverlayPosition.DYNAMIC);
			setLayer(OverlayLayer.MANUAL);
			drawAfterInterface(InterfaceID.BANKMAIN);
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			Snapshot s = displaySnapshot;
			if (s == null)
				return null;
			Graphics2D g = (Graphics2D) graphics.create();
			try
			{
				Rectangle r = s.area;
				g.setColor(RAIL_BORDER);
				g.drawLine(r.x + r.width - 51, r.y + BankActionLayout.TOP - 2, r.x + r.width - 51,
						r.y + r.height - s.bottomHeight - 3);
				if (s.tags)
				{
					if (s.adjustableDivider)
					{
						Rectangle divider = s.splitter();
						net.runelite.api.Point mouse = owner.client.getMouseCanvasPosition();
						boolean hover = mouse != null && divider.contains(mouse.getX(), mouse.getY());
						g.setColor(hover ? new Color(105, 190, 220) : RAIL_BORDER);
						g.drawLine(divider.x, divider.y, divider.x + divider.width - 1, divider.y);
						for (int i = 0; i < 3; i++)
							g.fillRect(divider.x + 18 + i * 5, divider.y + 2, 2, 2);
					}
					g.setColor(RAIL_BORDER);
					g.drawLine(r.x + 50, r.y + 41, r.x + 50, r.y + r.height - s.bottomHeight - 3);
				}
				if (owner.client.isKeyPressed(KeyCode.KC_ALT) && !owner.client.isKeyPressed(KeyCode.KC_CONTROL))
				{
					g.setColor(new Color(105, 190, 220, 150));
					g.drawRect(r.x + 1, r.y + r.height - s.bottomHeight - 2, r.width - 3, s.bottomHeight + 1);
					g.drawRect(r.x + r.width - 51, r.y + BankActionLayout.TOP - 2, 50,
							Math.max(1, r.height - BankActionLayout.TOP - s.bottomHeight));
					int leftTop = s.tags ? s.tagTop : BankActionLayout.TOP;
					g.drawRect(r.x + (s.tags ? 1 : 41), r.y + leftTop - 2, 50,
							Math.max(1, r.height - leftTop - s.bottomHeight));
					for (Rectangle button : s.buttons.values())
						g.draw(button);
				}
			}
			finally
			{
				g.dispose();
			}
			return null;
		}
	}
}

package com.windowmarkers;

import java.awt.Dimension;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

final class BankActionLayout
{
	static final int TOP = 54, RAIL = 50, GAP = 2;
	private static final char[] DOCKS = { 'R', 'L', 'T', 'B' };

	static final class Entry
	{
		final char dock;
		int order, offset = -1;

		Entry(char dock, int order)
		{
			this.dock = dock;
			this.order = order;
		}
	}

	static final class Plan
	{
		final Map<String, Rectangle> bounds = new LinkedHashMap<>();
		final Map<String, Character> docks = new LinkedHashMap<>();
		final Map<String, Track> tracks = new LinkedHashMap<>();
		int leftInset, bottomHeight = 36, tagTop, tagMaxOffset;

		void place(String key, Track track, Rectangle bounds)
		{
			this.bounds.put(key, bounds);
			docks.put(key, track.dock);
			tracks.put(key, track);
			track.cursor = track.horizontal ? bounds.x + bounds.width + GAP : bounds.y + bounds.height + GAP;
			if (track.dock == 'L')
				leftInset = RAIL;
		}
	}

	private static final class Track
	{
		final char dock;
		final Rectangle bounds;
		final boolean horizontal;
		int cursor;

		Track(char dock, Rectangle bounds)
		{
			this.dock = dock;
			this.bounds = bounds;
			horizontal = dock == 'B';
			cursor = horizontal ? bounds.x : bounds.y;
		}

		Rectangle next(Dimension size, Map<String, Rectangle> occupied)
		{
			int position = cursor;
			while (true)
			{
				Rectangle candidate = horizontal
						? new Rectangle(position, bounds.y + (bounds.height - size.height) / 2, size.width, size.height)
						: new Rectangle(bounds.x + (bounds.width - size.width) / 2, position, size.width, size.height);
				if (!bounds.contains(candidate))
					return null;
				Rectangle collision = null;
				for (Rectangle other : occupied.values())
				{
					Rectangle spaced = new Rectangle(other);
					spaced.grow(GAP, GAP);
					if (candidate.intersects(spaced))
					{
						collision = spaced;
						break;
					}
				}
				if (collision == null)
					return candidate;
				position = horizontal ? collision.x + collision.width : collision.y + collision.height;
			}
		}

		double distance(Point point, Rectangle candidate)
		{
			Rectangle available = new Rectangle(bounds);
			if (horizontal)
			{
				available.width -= candidate.x - available.x;
				available.x = candidate.x;
			}
			else
			{
				available.height -= candidate.y - available.y;
				available.y = candidate.y;
			}
			int x = Math.max(available.x, Math.min(point.x, available.x + available.width));
			int y = Math.max(available.y, Math.min(point.y, available.y + available.height));
			return point.distanceSq(x, y);
		}
	}

	final Map<String, Entry> entries = new LinkedHashMap<>();
	int tagOffset;

	static BankActionLayout read(String value)
	{
		BankActionLayout layout = new BankActionLayout();
		int i = 0;
		for (BankControl control : BankControl.values())
			layout.entries.put(control.name(), new Entry(control.quantity() ? 'B' : 'R', i++ * 50));
		if (value == null || !(value.startsWith("v1;") || value.startsWith("v2;") || value.startsWith("v3;"))
				|| value.length() > 8192)
			return layout;
		for (String part : value.substring(3).split(";"))
		{
			String[] fields = part.split(":");
			if (fields.length == 2 && fields[0].equals("split"))
			{
				try
				{
					layout.tagOffset = Math.max(0, Math.min(4000, Integer.parseInt(fields[1])));
				}
				catch (NumberFormatException ignored)
				{
				}
				continue;
			}
			if ((fields.length != 3 && fields.length != 5 && !(value.startsWith("v3;") && fields.length == 4))
					|| !fields[0].matches("[A-Z_]{1,32}") || fields[1].length() != 1
					|| "BLRTN".indexOf(fields[1].charAt(0)) < 0)
				continue;
			try
			{
				char dock = fields[1].charAt(0);
				int order = Math.max(0, Math.min(1000, Integer.parseInt(fields[2]))), offset = -1;
				if (fields.length == 5)
				{
					int x = Integer.parseInt(fields[3]), y = Integer.parseInt(fields[4]);
					if (x < 0 || y < 0 || x > 4000 || y > 4000)
						continue;
					offset = dock == 'B' ? x : y;
					order = offset;
				}
				if (fields.length == 4)
					offset = Math.max(0, Math.min(4000, Integer.parseInt(fields[3])));
				Entry entry = new Entry(dock, order);
				entry.offset = offset;
				layout.entries.put(fields[0], entry);
			}
			catch (NumberFormatException ignored)
			{
			}
		}
		for (char dock : DOCKS)
		{
			int order = 0;
			for (String key : layout.ordered(dock))
				layout.entries.get(key).order = order++;
		}
		return layout;
	}

	String write()
	{
		StringBuilder out = new StringBuilder("v3;");
		if (tagOffset > 0)
			out.append("split:").append(tagOffset).append(';');
		entries.forEach((key, e) ->
		{
			out.append(key).append(':').append(e.dock).append(':').append(e.order);
			if (e.offset >= 0)
				out.append(':').append(e.offset);
			out.append(';');
		});
		return out.toString();
	}

	void move(String key, char dock, int order)
	{
		entries.put(key, new Entry(dock, Math.max(0, Math.min(1000, order))));
	}

	void insert(String key, char dock, Point point, Rectangle rail, Map<String, Rectangle> bounds,
			Map<String, Character> docks)
	{
		List<String> keys = ordered(dock);
		keys.remove(key);
		int index = keys.size();
		Rectangle moved = bounds.get(key);
		int coordinate = dock == 'B' ? point.x + (moved == null ? 0 : moved.width / 2)
				: point.y + (moved == null ? 0 : moved.height / 2);
		for (int i = 0; i < keys.size(); i++)
		{
			String other = keys.get(i);
			Rectangle r = bounds.get(other);
			if (r == null || docks.get(other) == null || docks.get(other) != dock)
				continue;
			if (coordinate <= (dock == 'B' ? r.getCenterX() : r.getCenterY()))
			{
				index = i;
				break;
			}
		}
		keys.add(index, key);
		Entry entry = new Entry(dock, 0);
		if (dock != 'N')
			entry.offset = Math.max(0, Math.min(4000, dock == 'B' ? point.x - rail.x : point.y - rail.y));
		entries.put(key, entry);
		for (int i = 0; i < keys.size(); i++)
			entries.get(keys.get(i)).order = i;
	}

	private List<String> ordered(char dock)
	{
		List<String> keys = new ArrayList<>();
		entries.forEach((key, entry) ->
		{
			if (entry.dock == dock)
				keys.add(key);
		});
		keys.sort(Comparator.comparingInt(key -> entries.get(key).order));
		return keys;
	}

	static int tagTop(int height, int bottomHeight)
	{
		return TOP + Math.max(0, height - bottomHeight - TOP) / 2 + 4;
	}

	static Rectangle rail(char dock, int width, int height, int bottomHeight)
	{
		return rail(dock, width, height, bottomHeight, tagTop(height, bottomHeight));
	}

	static Rectangle rail(char dock, int width, int height, int bottomHeight, int tagTop)
	{
		if (dock == 'B')
			return new Rectangle(2, height - bottomHeight - 1, width - 4, bottomHeight);
		int top = dock == 'T' ? tagTop : TOP;
		return new Rectangle(dock == 'L' ? 42 : dock == 'T' ? 2 : width - RAIL + 2, top, RAIL - 4,
				Math.max(0, height - bottomHeight - 4 - top));
	}

	Plan plan(int width, int height, Map<String, Dimension> sizes, boolean tagSpace)
	{
		int rowHeight = Math.max(36, sizes.values().stream().mapToInt(d -> d.height).max().orElse(36));
		Plan plan = new Plan();
		for (int rows = 1; rows * (rowHeight + GAP) - GAP <= height - TOP - 4; rows++)
		{
			plan = basePlan(width, height, sizes, tagSpace, rows, rowHeight);
			if (plan.bounds.size() == sizes.keySet().stream()
					.filter(key -> entries.containsKey(key) && entries.get(key).dock != 'N').count())
				break;
		}
		spaceButtons(plan);
		plan.tagTop = tagTop(height, plan.bottomHeight);
		if (!tagSpace)
			return plan;
		Rectangle rail = rail('T', width, height, plan.bottomHeight);
		int limit = Math.max(0, rail.height);
		for (Map.Entry<String, Rectangle> entry : plan.bounds.entrySet())
		{
			if (plan.docks.get(entry.getKey()) != 'T')
				continue;
			Rectangle r = entry.getValue();
			limit = Math.min(limit, rail.y + rail.height - r.y - r.height);
			for (Map.Entry<String, Rectangle> other : plan.bounds.entrySet())
			{
				if (plan.docks.get(other.getKey()) == 'T')
					continue;
				Rectangle b = other.getValue();
				if (r.x < b.x + b.width && b.x < r.x + r.width && b.y >= r.y + r.height)
					limit = Math.min(limit, Math.max(0, b.y - r.y - r.height - GAP));
			}
		}
		plan.tagMaxOffset = Math.max(0, limit);
		int offset = Math.min(Math.max(0, tagOffset), plan.tagMaxOffset);
		plan.tagTop += offset;
		for (Map.Entry<String, Rectangle> entry : plan.bounds.entrySet())
			if (plan.docks.get(entry.getKey()) == 'T')
				entry.getValue().translate(0, offset);
		return plan;
	}

	private void spaceButtons(Plan plan)
	{
		for (Track track : new java.util.LinkedHashSet<>(plan.tracks.values()))
		{
			List<String> keys = new ArrayList<>();
			plan.tracks.forEach((key, value) ->
			{
				if (value == track)
					keys.add(key);
			});
			Map<String, Rectangle> spaced = new LinkedHashMap<>();
			int start = track.horizontal ? track.bounds.x : track.bounds.y, cursor = start;
			for (String key : keys)
			{
				Rectangle r = new Rectangle(plan.bounds.get(key));
				Entry entry = entries.get(key);
				int preferred = entry.dock == track.dock && entry.offset >= 0 ? start + entry.offset
						: track.horizontal ? r.x : r.y;
				int position = Math.max(cursor, preferred);
				if (track.horizontal)
					r.x = position;
				else
					r.y = position;
				spaced.put(key, r);
				cursor = position + (track.horizontal ? r.width : r.height) + GAP;
			}
			int limit = start + (track.horizontal ? track.bounds.width : track.bounds.height);
			for (int i = keys.size() - 1; i >= 0; i--)
			{
				Rectangle r = spaced.get(keys.get(i));
				int position = Math.min(track.horizontal ? r.x : r.y, limit - (track.horizontal ? r.width : r.height));
				if (track.horizontal)
					r.x = position;
				else
					r.y = position;
				limit = position - GAP;
			}
			boolean valid = true;
			for (Rectangle r : spaced.values())
			{
				if (!track.bounds.contains(r))
				{
					valid = false;
					break;
				}
				for (Map.Entry<String, Rectangle> other : plan.bounds.entrySet())
				{
					if (spaced.containsKey(other.getKey()))
						continue;
					Rectangle occupied = new Rectangle(other.getValue());
					occupied.grow(GAP, GAP);
					if (r.intersects(occupied))
					{
						valid = false;
						break;
					}
				}
				if (!valid)
					break;
			}
			if (valid)
				plan.bounds.putAll(spaced);
		}
	}

	private Plan basePlan(int width, int height, Map<String, Dimension> sizes, boolean tagSpace, int rows,
			int rowHeight)
	{
		Plan plan = new Plan();
		plan.bottomHeight = rows * (rowHeight + GAP) - GAP;
		List<Track> tracks = new ArrayList<>();
		for (char dock : DOCKS)
			if (dock != 'B' && width >= (dock == 'L' ? 536 : 478) && (dock != 'T' || tagSpace))
				tracks.add(new Track(dock, rail(dock, width, height, plan.bottomHeight)));
		Rectangle bottom = rail('B', width, height, plan.bottomHeight);
		for (int i = 0; i < rows; i++)
			tracks.add(
					new Track('B', new Rectangle(bottom.x, bottom.y + i * (rowHeight + GAP), bottom.width, rowHeight)));
		Map<Character, List<String>> overflow = new LinkedHashMap<>();
		for (char dock : DOCKS)
		{
			List<String> remaining = new ArrayList<>();
			overflow.put(dock, remaining);
			boolean full = false;
			for (String key : ordered(dock))
			{
				Dimension size = sizes.get(key);
				if (size == null)
					continue;
				Track selected = null;
				Rectangle target = null;
				if (!full)
					for (Track track : tracks)
						if (track.dock == dock)
						{
							Rectangle candidate = track.next(size, plan.bounds);
							if (candidate != null)
							{
								selected = track;
								target = candidate;
								break;
							}
						}
				if (selected != null)
					plan.place(key, selected, target);
				else
				{
					remaining.add(key);
					if (dock == 'B' || size.width <= RAIL - 4)
						full = true;
				}
			}
		}
		for (Map.Entry<Character, List<String>> group : overflow.entrySet())
		{
			Rectangle source = rail(group.getKey(), width, height, plan.bottomHeight);
			Point origin = new Point(source.x + source.width / 2, source.y);
			for (Map.Entry<String, Rectangle> placed : plan.bounds.entrySet())
				if (plan.docks.get(placed.getKey()).equals(group.getKey()))
				{
					Rectangle r = placed.getValue();
					origin = new Point(r.x + r.width / 2, r.y + r.height / 2);
				}
			Track previous = null;
			for (String key : group.getValue())
			{
				Dimension size = sizes.get(key);
				Track selected = null;
				Rectangle target = null;
				double distance = Double.MAX_VALUE;
				for (Track track : tracks)
				{
					Rectangle candidate = track.next(size, plan.bounds);
					if (candidate == null)
						continue;
					double next = track == previous ? -1 : track.distance(origin, candidate);
					if (next < distance)
					{
						selected = track;
						target = candidate;
						distance = next;
					}
				}
				if (selected == null)
					continue;
				plan.place(key, selected, target);
				previous = selected;
				origin = new Point(target.x + target.width / 2, target.y + target.height / 2);
			}
		}
		return plan;
	}
}

package com.windowmarkers;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageCapture;

final class BankCapture
{
	private static final org.slf4j.Logger log = org.slf4j.LoggerFactory.getLogger(BankCapture.class);
	@Inject
	Client client;
	@Inject
	ClientThread clientThread;
	@Inject
	ItemManager items;
	@Inject
	ImageCapture capture;
	@Inject
	BorderRenderer borders;
	@Inject
	WindowMarkersConfig config;
	LongSupplier clock = System::nanoTime;
	private long revision;
	private boolean pending;

	void cancel()
	{
		revision++;
		pending = false;
	}

	boolean save(List<Marker> markers, BooleanSupplier valid, Consumer<Boolean> completed)
	{
		return save(markers, false, valid, completed);
	}

	boolean save(List<Marker> markers, boolean hideOutlines, BooleanSupplier valid, Consumer<Boolean> completed)
	{
		if (pending || !valid.getAsBoolean())
		{
			return false;
		}
		Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE),
				grid = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (bank == null || grid == null || bank.isHidden() || grid.isHidden() || grid.getDynamicChildren() == null)
		{
			return false;
		}
		List<Icon> icons = new ArrayList<>();
		List<ItemAnchors.Cell> cells = new ArrayList<>();
		int width = grid.getWidth(), height = 32;
		for (Widget child : grid.getDynamicChildren())
		{
			if (child == null || child.isSelfHidden() || child.getItemId() < 0 || child.getItemId() == 6512)
			{
				continue;
			}
			int x = child.getRelativeX(), y = child.getRelativeY();
			if (x < 0 || y < 0)
			{
				continue;
			}
			icons.add(new Icon(child.getItemId(), child.getItemQuantity(), x, y));
			cells.add(new ItemAnchors.Cell(items.canonicalize(child.getItemId()), new Rectangle(x, y, 36, 32)));
			height = Math.max(height, y + 36);
			width = Math.max(width, x + 42);
		}
		if (icons.isEmpty())
		{
			return false;
		}
		List<Group> visible = new ArrayList<>();
		List<List<Rectangle>> regions = new ArrayList<>();
		for (Marker marker : markers)
		{
			List<Rectangle> bounds = marker.linked() ? ItemAnchors.regions(marker.linkedItemIds, cells)
					: Boolean.TRUE.equals(marker.scrollWithItems)
							? java.util.Collections
									.singletonList(new Rectangle(marker.x, marker.y, marker.width, marker.height))
							: java.util.Collections.emptyList();
			if (!bounds.isEmpty() && config.visible())
			{

				visible.add(new Group(marker, config));
				regions.add(bounds);
			}
		}
		int contentHeight = height + 8, totalHeight = contentHeight + 60 + visible.size() * 22;
		if (!reasonableSize(width, totalHeight))
		{
			return false;
		}
		AtomicInteger remaining = new AtomicInteger(icons.size());
		for (Icon icon : icons)
		{
			icon.image = items.getImage(icon.id, icon.quantity, true);
			if (icon.image == null)
			{
				return false;
			}
			var definition = items.getItemComposition(icon.id);
			icon.placeholder = definition != null && definition.getPlaceholderTemplateId() > 0;

			icon.image.onLoaded(remaining::decrementAndGet);
		}
		pending = true;
		final long request = ++revision, started = clock.getAsLong();
		final int captureWidth = width;
		clientThread.invokeLater((BooleanSupplier) () ->
		{
			if (request != revision)
			{
				return true;
			}
			if (!valid.getAsBoolean())
			{
				pending = false;
				return true;
			}
			if (remaining.get() > 0)
			{
				if (clock.getAsLong() - started < TimeUnit.SECONDS.toNanos(10))
				{
					return false;
				}
				pending = false;
				completed.accept(false);
				return true;
			}
			pending = false;
			try
			{
				render(captureWidth, totalHeight, contentHeight, icons, visible, regions, hideOutlines);
				completed.accept(true);
			}
			catch (RuntimeException ex)
			{
				log.warn("Could not capture bank screenshot", ex);
				completed.accept(false);
			}
			return true;
		});
		return true;
	}

	private void render(int width, int totalHeight, int contentHeight, List<Icon> icons, List<Group> visible,
			List<List<Rectangle>> regions, boolean hideOutlines)
	{
		BufferedImage image = new BufferedImage(width, totalHeight, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = image.createGraphics();
		try
		{
			g.setColor(new Color(32, 29, 24));
			g.fillRect(0, 0, width, totalHeight);
			g.setFont(new Font("Arial", Font.BOLD, 16));
			g.setColor(new Color(230, 202, 130));
			g.drawString("Bank — current tab / filter", 12, 24);
			Graphics2D content = (Graphics2D) g.create(0, 40, width, contentHeight);
			try
			{
				for (int i = 0; i < visible.size(); i++)
				{
					Group marker = visible.get(i);
					if (marker.backgroundArgb == null || hideOutlines)
					{
						continue;
					}
					content.setColor(new Color(marker.backgroundArgb, true));
					for (Rectangle r : regions.get(i))
					{
						content.fillRect(r.x, r.y, r.width, r.height);
					}
				}
				for (Icon cell : icons)
				{
					BufferedImage icon = cell.placeholder
							? net.runelite.client.util.ImageUtil.alphaOffset(cell.image, 0.5f)
							: cell.image;
					content.drawImage(icon, cell.x, cell.y, null);
				}
				for (int i = 0; i < visible.size(); i++)
				{
					Group marker = visible.get(i);
					if (!hideOutlines)
						borders.drawRegions(content, regions.get(i), marker.style, marker.borderColor, marker.tint);
				}
			}
			finally
			{
				content.dispose();
			}

			g.setFont(new Font("Arial", Font.PLAIN, 12));
			int y = contentHeight + 55;
			for (Group marker : visible)
			{
				g.setColor(marker.borderColor);
				g.fillRect(12, y - 10, 12, 12);
				g.setColor(Color.WHITE);
				g.drawString(MarkerPresentation.fit(marker.label, g.getFontMetrics(), width - 44), 32, y);
				y += 22;
			}
		}
		finally
		{
			g.dispose();
		}
		capture.saveScreenshot(image, "bank", "bank-markers", true, false);
	}

	private static final class Icon
	{
		final int id, quantity, x, y;
		AsyncBufferedImage image;
		boolean placeholder;

		Icon(int id, int quantity, int x, int y)
		{
			this.id = id;
			this.quantity = quantity;
			this.x = x;
			this.y = y;
		}
	}

	private static final class Group
	{
		final String label;
		final Integer backgroundArgb;
		final WindowMarkersConfig.BorderStyle style;
		final Color borderColor;
		final boolean tint;

		Group(Marker marker, WindowMarkersConfig config)
		{
			label = marker.labelText();
			backgroundArgb = marker.backgroundArgb;
			style = marker.style == null ? config.style() : marker.style;
			tint = marker.borderArgb != null;
			borderColor = tint ? new Color(marker.borderArgb, true) : config.color();
		}
	}

	static boolean reasonableSize(int width, int height)
	{
		return width > 0 && width <= 4096 && height > 0 && height <= 30000 && (long) width * height <= 32000000;
	}
}

package com.windowmarkers;

import java.util.*;

final class BankCatalogue
{
	enum Kind
	{
		CATEGORY, PRESET, WIKI_SETUP, CUSTOM_PRESET, SAVED_GROUP, ACTIVITY
	}

	static final class Choice
	{
		final Kind kind;
		final String name, search;
		final Object value;
		final AutoCategories.Preset presetScope;
		final String customGroup;

		Choice(Kind kind, String name, Object value)
		{
			this(kind, name, value, null, null);
		}

		Choice(Kind kind, String name, Object value, AutoCategories.Preset presetScope, String customGroup)
		{
			this.kind = kind;
			this.name = name;
			this.value = value;
			this.presetScope = presetScope;
			this.customGroup = customGroup;
			String terms = name + " " + aliases(name);
			if (kind == Kind.ACTIVITY)
				for (ActivitySetups.Setup setup : ActivityMenu.setups((String) value))
					terms += " " + setup.activity + " " + setup.label;
			search = SearchText.normalize(terms);
		}

		@Override
		public String toString()
		{
			return name + "  · " + kind.toString().toLowerCase(Locale.ROOT).replace('_', ' ');
		}

		String viewQuery()
		{
			return kind == Kind.ACTIVITY ? (String) value : kind == Kind.PRESET ? name.split(" — ", 2)[0] : name;
		}
	}

	static String aliases(String name)
	{
		if (name.equals(BankCleanup.SELL))
			return "sellable";
		return name.contains("Chambers of Xeric") ? "cox"
				: name.contains("Theatre of Blood") ? "tob" : name.contains("Tombs of Amascut") ? "toa" : "";
	}

	static List<Choice> choices(List<AutoCategories.Item> owned, List<Marker> markers, CustomPresets presets)
	{
		Set<String> categories = new TreeSet<>(WikiCatalogue.groups());
		categories.addAll(ItemTaxonomy.groups());
		categories.addAll(RaidRecommendations.groups());
		categories.addAll(Arrays.asList(BankCleanup.JUNK, BankCleanup.SELL, BankCleanup.ACTIVE, BankCleanup.FUTURE,
				BankCleanup.DONE, BankCleanup.UNKNOWN));
		categories.addAll(Arrays.asList("Hybrid equipment", "Magic equipment", "Ranged equipment", "Melee equipment",
				"Equipment", "Defensive or utility equipment — review", "Health-lowering utility",
				"Restricted-use supplies — blighted", "Specialist food — purple sweets", "Runes",
				"Food — general, not activity advice", "Potions — general, not activity advice",
				"Drinks and brews — review", "Resources", "Other — review", "Other — equipment role needs review",
				"Raid mega-rare weapons"));

		categories.addAll(AutoCategories.suggest(AutoCategories.Preset.ALL_CATEGORIES, owned).keySet());
		for (AutoCategories.Item item : owned)
			if (!ItemVariantState.identityNeedsReview(item))
				for (WikiCatalogue.Entry entry : WikiCatalogue.entries(item))
					categories.add(ItemVariantState.annotate(entry.group, item));
		List<Choice> result = new ArrayList<>();
		for (String category : categories)
			if (!CatalogueArchive.hidden(category))
				result.add(new Choice(Kind.CATEGORY, category, category));
		for (AutoCategories.Preset preset : AutoCategories.Preset.values())
			if (preset != AutoCategories.Preset.CHAMBERS_OF_XERIC && preset != AutoCategories.Preset.THEATRE_OF_BLOOD
					&& preset != AutoCategories.Preset.TOMBS_OF_AMASCUT)
				result.add(new Choice(Kind.PRESET, preset.toString(), preset));
		for (String activity : ActivitySetups.activities(""))
			result.add(new Choice(Kind.ACTIVITY, activity, activity));
		for (CustomPresets.Preset preset : presets.presets)
			result.add(new Choice(Kind.CUSTOM_PRESET, preset.name, preset));
		for (Marker marker : markers)
			result.add(new Choice(Kind.SAVED_GROUP, marker.labelText().isEmpty() ? "Unnamed group" : marker.labelText(),
					marker));
		return result;
	}

	static List<Choice> search(List<Choice> choices, String query, int limit)
	{
		String needle = SearchText.normalize(query);
		if (needle.length() > 100)
			return Collections.emptyList();
		final String original = needle;
		boolean exact = choices.stream().anyMatch(c -> SearchText.containsWords(c.search, original));
		if (!exact)
		{
			Set<String> vocabulary = new HashSet<>();
			for (Choice choice : choices)
				Collections.addAll(vocabulary, choice.search.split(" +"));
			needle = SearchText.correctWholeWords(vocabulary, needle);
			final String corrected = needle;
			exact = choices.stream().anyMatch(c -> SearchText.containsWords(c.search, corrected));
		}
		Map<Choice, Integer> scores = new IdentityHashMap<>();
		for (Choice choice : choices)
		{
			if (exact && !SearchText.containsWords(choice.search, needle))
				continue;
			int score = SearchText.normalizedScore(choice.search, needle);
			if (score != Integer.MAX_VALUE)
				scores.put(choice, score);
		}
		List<Choice> result = new ArrayList<>(scores.keySet());
		result.sort(Comparator.comparingInt((Choice c) -> scores.get(c)).thenComparing(c -> c.name)
				.thenComparing(c -> c.kind));
		return new ArrayList<>(result.subList(0, Math.min(limit, result.size())));
	}

	static Map<String, List<AutoCategories.Item>> categoryGroups(String category, List<AutoCategories.Item> items)
	{
		Map<String, List<AutoCategories.Item>> groups = new LinkedHashMap<>();
		Set<Integer> found = new HashSet<>();
		for (AutoCategories.Item item : items)
			if (!ItemVariantState.identityNeedsReview(item))
				for (WikiCatalogue.Entry entry : WikiCatalogue.entries(item))
				{
					String annotated = ItemVariantState.annotate(entry.group, item);
					if ((entry.group.equals(category) || annotated.equals(category)) && found.add(item.id))
						groups.computeIfAbsent(annotated, k -> new ArrayList<>()).add(item);
				}
		List<AutoCategories.Preset> matching = new ArrayList<>();
		if (category.startsWith("CoX "))
			matching.add(AutoCategories.Preset.CHAMBERS_OF_XERIC);
		else if (category.startsWith("ToB "))
			matching.add(AutoCategories.Preset.THEATRE_OF_BLOOD);
		else if (category.startsWith("ToA "))
			matching.add(AutoCategories.Preset.TOMBS_OF_AMASCUT);
		else
			matching.addAll(Arrays.asList(AutoCategories.Preset.ALL_CATEGORIES, AutoCategories.Preset.COMBAT_GROUPS,
					AutoCategories.Preset.RAID_MEGA_RARES));
		for (AutoCategories.Preset preset : matching)
			for (AutoCategories.Item item : AutoCategories.suggest(preset, items).getOrDefault(category,
					Collections.emptyList()))

				if (found.add(item.id))
					groups.computeIfAbsent(category, k -> new ArrayList<>()).add(item);
		return groups;
	}

	static Map<String, List<AutoCategories.Item>> categoryGroups(Choice choice, List<AutoCategories.Item> items)
	{
		if (choice.presetScope == null)
			return categoryGroups(choice.name, items);
		List<AutoCategories.Item> matches = AutoCategories.suggest(choice.presetScope, items).get(choice.name);
		return matches == null ? Collections.emptyMap() : Collections.singletonMap(choice.name, matches);
	}

	static List<Choice> targets(String membership, List<Choice> available)
	{
		if (membership.startsWith("Category: "))
		{
			String category = membership.substring("Category: ".length());
			return Collections.singletonList(new Choice(Kind.CATEGORY, category, category));
		}
		for (AutoCategories.Preset preset : AutoCategories.Preset.values())
		{
			String prefix = "Preset: " + preset + " / ";
			if (membership.startsWith(prefix))
			{
				String category = membership.substring(prefix.length());
				return Collections.singletonList(new Choice(Kind.CATEGORY, category, category, preset, null));
			}
		}
		List<Choice> matches = new ArrayList<>();
		if (membership.startsWith("Wiki setup: "))
		{

			for (ActivitySetups.Setup setup : ActivitySetups.all())
			{
				String label = "Wiki setup: " + setup.activity + " / " + setup.label;
				if (membership.equals(label) || membership.equals(label + " — state needs review"))
					return Collections.singletonList(new Choice(Kind.ACTIVITY, setup.activity, setup.activity));
			}
		}
		for (Choice choice : available)
		{
			if (choice.kind == Kind.ACTIVITY && membership.equals("Activity: " + choice.name))
				matches.add(choice);
			else if (choice.kind == Kind.WIKI_SETUP)
			{
				ActivitySetups.Setup setup = (ActivitySetups.Setup) choice.value;
				String label = "Wiki setup: " + setup.activity + " / " + setup.label;
				if (membership.equals(label) || membership.equals(label + " — state needs review"))
					matches.add(choice);
			}
			else if (choice.kind == Kind.SAVED_GROUP
					&& membership.equals("Saved group: " + ((Marker) choice.value).labelText()))
				matches.add(choice);
			else if (choice.kind == Kind.CUSTOM_PRESET)
			{
				CustomPresets.Preset preset = (CustomPresets.Preset) choice.value;
				Set<String> seen = new HashSet<>();
				for (Marker group : preset.groups)
					if (membership.equals("Custom preset: " + preset.name + " / " + group.labelText())
							&& seen.add(group.labelText()))
						matches.add(new Choice(Kind.CUSTOM_PRESET, choice.name, choice.value, null, group.labelText()));
			}
		}
		return matches;
	}

	static SortedSet<String> memberships(AutoCategories.Item item, List<AutoCategories.Item> owned,
			List<Marker> markers, CustomPresets custom)
	{
		SortedSet<String> result = new TreeSet<>();
		if (ItemVariantState.needsActivityReview(item))
			result.add("Review: " + ItemVariantState.annotate(ItemVariantState.reviewGroup(item), item));
		if (ItemVariantState.identityNeedsReview(item))
			result.add("Review: " + ItemVariantState.reviewGroup(item));
		else
			for (WikiCatalogue.Entry entry : WikiCatalogue.entries(item))
				if (!CatalogueArchive.hidden(entry.group))
					result.add("Category: " + ItemVariantState.annotate(entry.group, item));

		String set = ItemTaxonomy.equipmentSet(ItemVariantState.familyName(item));
		List<AutoCategories.Item> context = new ArrayList<>();
		if (set != null)
			for (AutoCategories.Item candidate : owned)
				if (set.equals(ItemTaxonomy.equipmentSet(ItemVariantState.familyName(candidate))))
					context.add(candidate);
		if (context.stream().noneMatch(i -> i.id == item.id))
			context.add(item);
		for (AutoCategories.Preset preset : AutoCategories.Preset.values())
			AutoCategories.suggest(preset, context).forEach((group, items) ->
			{
				if (items.stream().anyMatch(i -> i.id == item.id))
					result.add("Preset: " + preset + " / " + group);
			});
		for (ActivitySetups.Setup setup : ActivitySetups.all())
			if (setup.itemIds.contains(item.id))
				result.add("Activity: " + setup.activity);
		for (Marker marker : markers)
			if (marker.linked() && Arrays.stream(marker.linkedItemIds).anyMatch(id -> id == item.id))
				result.add("Saved group: " + marker.labelText());
		for (CustomPresets.Preset preset : custom.presets)
			for (Marker group : preset.groups)
				if (group.linked() && Arrays.stream(group.linkedItemIds).anyMatch(id -> id == item.id))
					result.add("Custom preset: " + preset.name + " / " + group.labelText());
		return result;
	}

	static String compare(String left, Set<String> a, String right, Set<String> b)
	{
		Set<String> shared = new TreeSet<>(a);
		shared.retainAll(b);
		Set<String> onlyA = new TreeSet<>(a);
		onlyA.removeAll(b);
		Set<String> onlyB = new TreeSet<>(b);
		onlyB.removeAll(a);
		return section("Shared", shared) + section("Only " + left, onlyA) + section("Only " + right, onlyB);
	}

	private static String section(String name, Set<String> entries)
	{
		return name + " (" + entries.size() + ")\n" + (entries.isEmpty() ? "None" : String.join("\n", entries))
				+ "\n\n";
	}
}

package com.windowmarkers;

import java.awt.*;
import java.awt.event.*;
import java.util.List;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.swing.*;
import net.runelite.api.Client;
import net.runelite.api.SpriteID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

final class BankCataloguePicker
{
	@Inject
	Client client;
	private static final int WIDTH = 96, HEIGHT = 22, EDGE = 6;
	private static final int[] SPRITES = { SpriteID.BUTTON_CORNER_TOP_LEFT, SpriteID.BUTTON_EDGE_TOP,
			SpriteID.BUTTON_CORNER_TOP_RIGHT, SpriteID.BUTTON_EDGE_LEFT, SpriteID.BUTTON_MIDDLE,
			SpriteID.BUTTON_EDGE_RIGHT, SpriteID.BUTTON_CORNER_BOTTOM_LEFT, SpriteID.BUTTON_EDGE_BOTTOM,
			SpriteID.BUTTON_CORNER_BOTTOM_RIGHT };
	private Widget parent, button;
	private final BankHeaderTitle title = new BankHeaderTitle();
	private final List<Widget> background = new ArrayList<>();
	private volatile JPopupMenu popup;
	private volatile long context;

	Widget widget()
	{
		return button;
	}

	List<Widget> parts()
	{
		return new ArrayList<>(background);
	}

	void update(boolean enabled, Runnable open)
	{
		Widget frame = client.getWidget(InterfaceID.Bankmain.FRAME), close = null;
		if (frame != null && frame.getChildren() != null)
			for (Widget child : frame.getChildren())
				if (child != null && !child.isHidden() && child.getActions() != null
						&& Arrays.asList(child.getActions()).contains("Close"))
				{
					close = child;
					break;
				}
		if (!enabled || frame == null || frame.isHidden() || close == null)
		{
			clear();
			return;
		}
		List<Widget> children = Arrays.asList(frame.getChildren());
		if (parent != frame || button == null || !children.contains(button) || !children.containsAll(background))
		{
			clear();
			parent = frame;

			for (int sprite : SPRITES)
			{
				Widget part = frame.createChild(-1, WidgetType.GRAPHIC);
				part.setSpriteId(sprite);
				part.setSpriteTiling(true);
				background.add(part);
			}
			button = frame.createChild(-1, WidgetType.TEXT);
			button.setOriginalWidth(WIDTH);
			button.setOriginalHeight(HEIGHT);
			button.setFontId(495);
			button.setXTextAlignment(1);
			button.setYTextAlignment(1);
			button.setText("View presets");
			button.setTextColor(0xFF981F);
			button.setTextShadowed(true);
			button.setAction(0, "View presets");
			button.setHasListener(true);
			button.setOnMouseOverListener((JavaScriptCallback) e ->
			{
				if (button != null)
					button.setTextColor(0xFFFFFF);
			});
			button.setOnMouseLeaveListener((JavaScriptCallback) e ->
			{
				if (button != null)
					button.setTextColor(0xFF981F);
			});
			button.setOnOpListener((JavaScriptCallback) e -> open.run());
		}
		Rectangle position = position(frame.getBounds(), close.getBounds());
		if (position == null)
		{
			clear();
			return;
		}
		for (int i = 0; i < background.size(); i++)
		{
			int column = i % 3, row = i / 3;
			Widget part = background.get(i);
			part.setOriginalX(position.x + (column == 0 ? 0 : column == 1 ? EDGE : WIDTH - EDGE));
			part.setOriginalY(position.y + (row == 0 ? 0 : row == 1 ? EDGE : HEIGHT - EDGE));
			part.setOriginalWidth(column == 1 ? WIDTH - 2 * EDGE : EDGE);
			part.setOriginalHeight(row == 1 ? HEIGHT - 2 * EDGE : EDGE);
			part.setHidden(false);
			part.revalidate();
		}
		button.setOriginalX(position.x);
		button.setOriginalY(position.y);
		button.setHidden(false);
		button.revalidate();
		title.update(client.getWidget(InterfaceID.Bankmain.TITLE), position.x - 6);
	}

	static Rectangle position(Rectangle frame, Rectangle close)
	{

		Rectangle result = new Rectangle(close.x - frame.x - 28 - WIDTH,
				close.y - frame.y + (close.height - HEIGHT) / 2, WIDTH, HEIGHT);
		return new Rectangle(0, 0, frame.width, frame.height).contains(result) ? result : null;
	}

	void show(Component canvas, List<BankCatalogue.Choice> choices, boolean canSave,
			Consumer<BankCatalogue.Choice> choose, Runnable save, Runnable closeView)
	{

		if (button == null || button.isHidden() || canvas == null)
			return;
		Rectangle anchor = button.getBounds();
		long token = ++context;
		List<BankCatalogue.Choice> snapshot = new ArrayList<>(choices);
		SwingUtilities.invokeLater(() ->
		{
			if (token != context || !canvas.isShowing())
				return;
			close();
			PickerPanel panel = new PickerPanel(snapshot, choice ->
			{
				close();
				choose.accept(choice);
			}, () ->
			{
				close();
				save.run();
			}, () ->
			{
				close();
				closeView.run();
			}, canSave);
			JPopupMenu menu = new JPopupMenu();
			popup = menu;
			menu.setLightWeightPopupEnabled(false);
			menu.setLayout(new BorderLayout());
			menu.add(panel, BorderLayout.CENTER);
			menu.addPopupMenuListener(new javax.swing.event.PopupMenuListener()
			{
				public void popupMenuWillBecomeVisible(javax.swing.event.PopupMenuEvent e)
				{
				}

				public void popupMenuWillBecomeInvisible(javax.swing.event.PopupMenuEvent e)
				{
					panel.stop();
					if (popup == menu)
						popup = null;
				}

				public void popupMenuCanceled(javax.swing.event.PopupMenuEvent e)
				{
					panel.stop();
				}
			});
			int width = Math.min(400, Math.max(240, canvas.getWidth() - 16));
			panel.setPreferredSize(
					new Dimension(width, Math.min(350, Math.max(200, canvas.getHeight() - anchor.y - 28))));
			menu.show(canvas, Math.max(0, Math.min(anchor.x + anchor.width - width, canvas.getWidth() - width)),
					anchor.y + anchor.height);
			panel.search.requestFocusInWindow();
		});
	}

	void close()
	{
		JPopupMenu current = popup;
		popup = null;
		if (current != null)
			current.setVisible(false);
	}

	void clear()
	{
		context++;
		title.clear();
		if (button != null)
		{
			button.setHidden(true);
			button.clearActions();
			button.setOnOpListener((Object[]) null);
			button.setOnMouseOverListener((Object[]) null);
			button.setOnMouseLeaveListener((Object[]) null);
			button.setHasListener(false);
		}
		for (Widget part : background)
			part.setHidden(true);
		if (parent != null && parent.getChildren() != null)
		{
			Widget[] remaining = parent.getChildren().clone();
			int length = remaining.length;
			for (int i = 0; i < length; i++)
			{
				Widget child = remaining[i];
				if (child == button || background.stream().anyMatch(part -> part == child))
					remaining[i] = null;
			}
			while (length > 0 && remaining[length - 1] == null)
				length--;
			parent.setChildren(Arrays.copyOf(remaining, length));
		}
		background.clear();
		button = null;
		parent = null;
		JPopupMenu old = popup;
		if (old != null)
			SwingUtilities.invokeLater(() ->
			{
				old.setVisible(false);
				if (popup == old)
					popup = null;
			});
	}

	static final class PickerPanel extends JPanel
	{
		final JTextField search = new JTextField();
		final DefaultListModel<BankCatalogue.Choice> rows = new DefaultListModel<>();
		final JList<BankCatalogue.Choice> list = new JList<>(rows);
		final javax.swing.Timer timer;
		long revision;
		boolean closed;

		PickerPanel(List<BankCatalogue.Choice> choices, Consumer<BankCatalogue.Choice> choose, Runnable save,
				Runnable closeView, boolean canSave)
		{
			super(new BorderLayout(6, 6));
			setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
			search.setToolTipText("Search activities and saved presets. Approximate spelling works.");
			JPanel header = new JPanel(new BorderLayout(0, 4));
			header.add(new JLabel("Search activities & saved views"), BorderLayout.NORTH);
			header.add(search, BorderLayout.CENTER);
			add(header, BorderLayout.NORTH);
			add(new JScrollPane(list), BorderLayout.CENTER);
			list.setCellRenderer(new DefaultListCellRenderer()
			{
				@Override
				public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean selected,
						boolean focus)
				{
					JLabel label = (JLabel) super.getListCellRendererComponent(list, value, index, selected, focus);
					label.setToolTipText(value == null ? null : value.toString());
					return label;
				}
			});
			list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
			list.setVisibleRowCount(7);
			Runnable accept = () ->
			{
				if (list.getSelectedValue() != null)
					choose.accept(list.getSelectedValue());
			};
			JButton open = new JButton("Open selected"), saveButton = new JButton("Save current view…"),
					back = new JButton("Return to bank");
			saveButton.setEnabled(canSave);
			open.addActionListener(e -> accept.run());
			saveButton.addActionListener(e -> save.run());
			back.addActionListener(e -> closeView.run());
			JPanel footer = new JPanel(new GridLayout(0, 1, 4, 4));
			footer.add(open);
			footer.add(saveButton);
			footer.add(back);
			add(footer, BorderLayout.SOUTH);
			list.addMouseListener(new MouseAdapter()
			{
				public void mouseClicked(MouseEvent e)
				{
					int i = list.locationToIndex(e.getPoint());
					if (e.getClickCount() == 2 && i >= 0 && list.getCellBounds(i, i).contains(e.getPoint()))
						accept.run();
				}
			});
			search.addActionListener(e -> accept.run());
			list.getInputMap().put(KeyStroke.getKeyStroke("ENTER"), "open");
			list.getActionMap().put("open", new AbstractAction()
			{
				public void actionPerformed(ActionEvent e)
				{
					accept.run();
				}
			});
			search.getInputMap().put(KeyStroke.getKeyStroke("DOWN"), "results");
			search.getActionMap().put("results", new AbstractAction()
			{
				public void actionPerformed(ActionEvent e)
				{
					if (!rows.isEmpty())
					{
						list.requestFocusInWindow();
						list.setSelectedIndex(0);
					}
				}
			});
			Runnable refresh = () ->
			{
				long token = ++revision;
				String text = search.getText();
				new SwingWorker<List<BankCatalogue.Choice>, Void>()
				{
					protected List<BankCatalogue.Choice> doInBackground()
					{
						return BankCatalogue.search(choices, text, choices.size());
					}

					protected void done()
					{
						if (closed || token != revision)
							return;
						try
						{
							rows.clear();
							for (var c : get())
								rows.addElement(c);
							if (!rows.isEmpty())
								list.setSelectedIndex(0);
						}
						catch (Exception ignored)
						{
						}
					}
				}.execute();
			};
			timer = new javax.swing.Timer(150, e -> refresh.run());
			timer.setRepeats(false);
			search.getDocument().addDocumentListener(new javax.swing.event.DocumentListener()
			{
				private void changed()
				{
					revision++;
					rows.clear();
					timer.restart();
				}

				public void insertUpdate(javax.swing.event.DocumentEvent e)
				{
					changed();
				}

				public void removeUpdate(javax.swing.event.DocumentEvent e)
				{
					changed();
				}

				public void changedUpdate(javax.swing.event.DocumentEvent e)
				{
					changed();
				}
			});
			refresh.run();
		}

		void stop()
		{
			closed = true;
			revision++;
			timer.stop();
		}
	}
}

package com.windowmarkers;

import java.util.*;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

final class BankCleanup
{
	static boolean isReview(ItemCatalogueIndex.Rank rank)
	{
		return rank != null && rank.role.startsWith("cleanup:");
	}

	static java.awt.Color colour(ItemCatalogueIndex.Rank rank)
	{
		return new java.awt.Color(rank != null && rank.role.equals("cleanup:niche") ? 0xA0E1BC6B : 0x709AAAAA, true);
	}

	static void style(Marker marker)
	{
		marker.borderArgb = 0x709AAAAA;
		marker.backgroundArgb = null;
		marker.style = WindowMarkersConfig.BorderStyle.PLAIN;
	}

	static final String JUNK = "Junk review", SELL = "Sell candidates", ACTIVE = "Quest items — active quest",
			FUTURE = "Quest items — future quest", DONE = "Quest items — completed uses",
			UNKNOWN = "Quest items — progress unknown";
	private static final List<String[]> RULES = ItemTaxonomy.readRows("bank-cleanup-items.tsv", 5);
	private static final Set<Integer> TOOLS = new HashSet<>(
			Arrays.asList(1265, 1267, 1269, 1271, 1273, 1275, 11920, 1349, 1351, 1353, 1355, 1357, 1359, 6739));

	private static final Set<Integer> REPEAT_TOOLS = new HashSet<>(Arrays.asList(1267, 1349, 1353));
	final Map<Integer, ItemCatalogueIndex.Rank> junk = new LinkedHashMap<>(), sell = new LinkedHashMap<>();
	private final Map<String, Map<Integer, ItemCatalogueIndex.Rank>> questGroups = new HashMap<>();

	static final class Progress
	{
		final QuestState witch, tale, giant, fishing;
		final int cooking, farming, mining, woodcutting;
		final boolean members;

		Progress(QuestState witch, QuestState tale, QuestState giant, QuestState fishing, int cooking, int farming,
				int mining, int woodcutting)
		{
			this(witch, tale, giant, fishing, cooking, farming, mining, woodcutting, false);
		}

		Progress(QuestState witch, QuestState tale, QuestState giant, QuestState fishing, int cooking, int farming,
				int mining, int woodcutting, boolean members)
		{
			this.witch = witch;
			this.tale = tale;
			this.giant = giant;
			this.fishing = fishing;
			this.cooking = cooking;
			this.farming = farming;
			this.mining = mining;
			this.woodcutting = woodcutting;
			this.members = members;
		}

		static Progress unknown()
		{
			return new Progress(null, null, null, null, 0, 0, 0, 0);
		}

		static Progress capture(Client client)
		{
			if (client.getGameState() != GameState.LOGGED_IN)
				return unknown();
			return new Progress(state(Quest.WITCHS_POTION, client), state(Quest.FORGETTABLE_TALE, client),
					state(Quest.THE_GIANT_DWARF, client), state(Quest.FISHING_CONTEST, client),
					client.getRealSkillLevel(Skill.COOKING), client.getRealSkillLevel(Skill.FARMING),
					client.getRealSkillLevel(Skill.MINING), client.getRealSkillLevel(Skill.WOODCUTTING),
					client.getWorldType().contains(net.runelite.api.WorldType.MEMBERS));
		}

		private static QuestState state(Quest quest, Client client)
		{
			try
			{
				return quest.getState(client);
			}
			catch (RuntimeException unavailable)
			{
				return null;
			}
		}

		String note(boolean chicken)
		{
			QuestState state = chicken ? tale : witch;
			String name = chicken ? "Forgettable Tale..." : "Witch's Potion";
			if (state == null)
				return name + ": progress unavailable; keep its quest use in mind.";
			if (state == QuestState.FINISHED)
				return name + ": completed. " + (chicken ? "Repeatable Keldagrim task use remains."
						: "The recorded quest use is finished; collector value may remain.");
			if (state == QuestState.IN_PROGRESS)
				return name + ": in progress. "
						+ (chicken ? "One possible random request; not proof that it is your assigned item."
								: "Needed for this quest unless already handed in.");
			if (!chicken)
				return name + ": not started; no skill or prerequisite quest requirements.";
			List<String> missing = new ArrayList<>();
			if (giant != QuestState.FINISHED)
				missing.add(giant == null ? "The Giant Dwarf progress unknown" : "The Giant Dwarf incomplete");
			if (fishing != QuestState.FINISHED)
				missing.add(fishing == null ? "Fishing Contest progress unknown" : "Fishing Contest incomplete");
			if (cooking < 22)
				missing.add("22 Cooking for completion (boostable)");
			if (farming < 17)
				missing.add("17 Farming (boostable)");
			return name + ": not started. "
					+ (missing.isEmpty() ? "Reviewed skill/prerequisite checks met; other access conditions may apply."
							: "Requirements to review: " + String.join(", ", missing) + ".");
		}
	}

	BankCleanup(List<AutoCategories.Item> bank, Set<Integer> tradeable, Progress progress)
	{
		Map<Integer, AutoCategories.Item> owned = new HashMap<>();
		for (AutoCategories.Item item : bank)
			owned.put(item.id, item);
		for (String[] row : RULES)
		{
			int id = Integer.parseInt(row[0]);
			AutoCategories.Item item = owned.get(id);

			if (item == null || !row[1].equalsIgnoreCase(item.name)
					|| ItemVariantState.identityNeedsReview(item) && !row[2].equals("rare"))
				continue;
			boolean niche = !row[2].equals("review");
			String reason = row[3];
			if (id == 2144 || id == 2146)
			{
				reason = id == 2144 ? reason + "\n" + progress.note(true) : progress.note(false) + "\n" + reason;
				QuestState state = id == 2144 ? progress.tale : progress.witch;
				String group = state == null ? UNKNOWN
						: state == QuestState.FINISHED ? DONE : state == QuestState.IN_PROGRESS ? ACTIVE : FUTURE;
				questGroups.computeIfAbsent(group, k -> new LinkedHashMap<>()).put(id,
						new ItemCatalogueIndex.Rank(0, reason, "cleanup:niche"));
				niche = id == 2144 || state != QuestState.FINISHED;
			}
			junk.put(id,
					new ItemCatalogueIndex.Rank(0,
							row[1] + "\n" + reason + "\nReview only; nothing is discarded or sold.\n" + row[4],
							niche ? "cleanup:niche" : "cleanup:review"));
		}
		List<AutoCategories.Item> tools = new ArrayList<>();
		for (AutoCategories.Item item : bank)
			if (TOOLS.contains(item.id) && tradeable.contains(item.id)
					&& (progress.members || item.id != 11920 && item.id != 6739))
				tools.add(item);
		LowerTierFilter.exclusions(tools, progress.mining, progress.woodcutting, 0).forEach((id, why) ->
		{
			if (!REPEAT_TOOLS.contains(id))
				sell.put(id, new ItemCatalogueIndex.Rank(0, "Sell candidate for ordinary gathering: " + why
						+ ".\nLow-cost spares or personal plans can still justify keeping it. This is not a claim of universal redundancy.",
						"cleanup:sell"));
		});

		for (AutoCategories.Item item : bank)
			if (WikiCatalogue.hasFacet(item, "quest") && item.id != 2144 && item.id != 2146)
				questGroups.computeIfAbsent(UNKNOWN, k -> new LinkedHashMap<>()).put(item.id,
						new ItemCatalogueIndex.Rank(0,
								"Quest-related item. Exact quest/stage uses are not yet mapped here; no completed-quest or disposal claim is made.",
								"cleanup:niche"));
	}

	static String kind(String query)
	{
		String text = SearchText.normalize(query);
		if (text.equals("junk") || text.equals("junk review"))
			return JUNK;
		if (text.equals("sellable") || text.equals("sell candidates"))
			return SELL;
		if (text.equals("quest active") || text.equals(SearchText.normalize(ACTIVE)))
			return ACTIVE;
		if (text.equals("quest future") || text.equals(SearchText.normalize(FUTURE)))
			return FUTURE;
		if (text.equals("quest completed") || text.equals(SearchText.normalize(DONE)))
			return DONE;
		if (text.equals("quest unknown") || text.equals(SearchText.normalize(UNKNOWN)))
			return UNKNOWN;
		return null;
	}

	static boolean isQuery(String query)
	{
		return query != null && kind(query) != null;
	}

	BankSearchIndex.Match search(String query)
	{
		String kind = kind(query);
		if (kind == null)
			return null;
		Map<Integer, ItemCatalogueIndex.Rank> notes = kind.equals(JUNK) ? junk
				: kind.equals(SELL) ? sell : questGroups.getOrDefault(kind, Collections.emptyMap());
		return new BankSearchIndex.Match(new HashSet<>(notes.keySet()), new LinkedHashMap<>(notes), false);
	}
}

package com.windowmarkers;

import net.runelite.api.gameval.InterfaceID;

enum BankControl
{
