	}
}

package com.windowmarkers;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.util.*;
import net.runelite.api.KeyCode;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

final class BankControlDrag extends MouseAdapter
{
	private final BankLayoutController owner;
	private volatile Snapshot snapshot;
	private volatile Gesture gesture;
	private boolean captured, suppressClick;
	private volatile boolean cancel;
	private BankControlLayout draft;
	private String appliedDraft;
	final Overlay overlay = new DragOverlay();

	BankControlDrag(BankLayoutController owner)
	{
		this.owner = owner;
	}

	BankControlLayout draft()
	{
		return draft;
	}

	private static final class Snapshot
	{
		final Widget bank;
		final Rectangle container;
		final Map<BankControl, Rectangle> buttons;
		final String initial, preference;
		final boolean custom;

		Snapshot(Widget bank, Rectangle container, Map<BankControl, Rectangle> buttons, String initial,
				String preference, boolean custom)
		{
			this.bank = bank;
			this.container = container;
			this.buttons = buttons;
			this.initial = initial;
			this.preference = preference;
			this.custom = custom;
		}
	}

	private static final class Gesture
	{
		final Snapshot start;
		final BankControl control;
		final Point pressed, point;
		final boolean released;

		Gesture(Snapshot start, BankControl control, Point pressed, Point point, boolean released)
		{
			this.start = start;
			this.control = control;
			this.pressed = pressed;
			this.point = point;
			this.released = released;
		}

		Gesture at(Point point, boolean released)
		{
			return new Gesture(start, control, pressed, point, released);
		}
	}

	@Override
	public synchronized MouseEvent mousePressed(MouseEvent event)
	{
		suppressClick = false;
		if (captured)
		{
			cancel = true;
			event.consume();
			return event;
		}
		Snapshot current = snapshot;
		if (current == null || !event.isAltDown() || event.isControlDown() || event.isMetaDown()
				|| event.getButton() != MouseEvent.BUTTON1)
			return event;
		for (Map.Entry<BankControl, Rectangle> entry : current.buttons.entrySet())
			if (entry.getValue().contains(event.getPoint()))
			{
				gesture = new Gesture(current, entry.getKey(), event.getPoint(), event.getPoint(), false);
				cancel = false;
				captured = true;
				event.consume();
				break;
			}
		return event;
	}

	@Override
	public synchronized MouseEvent mouseDragged(MouseEvent event)
	{
		if (captured)
		{
			event.consume();
			if (gesture != null)
				gesture = gesture.at(event.getPoint(), false);
		}
		return event;
	}

	@Override
	public synchronized MouseEvent mouseReleased(MouseEvent event)
	{
		if (captured)
		{
			event.consume();
			if (event.getButton() == MouseEvent.BUTTON1)
			{
				captured = false;
				suppressClick = true;
				if (gesture != null)
					gesture = gesture.at(event.getPoint(), true);
			}
		}
		return event;
	}

	@Override
	public synchronized MouseEvent mouseClicked(MouseEvent event)
	{
		if (suppressClick)
		{
			event.consume();
			suppressClick = false;
		}
		return event;
	}

	@Override
	public synchronized MouseEvent mouseExited(MouseEvent event)
	{
		if (captured)
			cancel = true;
		return event;
	}

	void cancel()
	{
		cancel = true;
		snapshot = null;
	}

	synchronized void resetInput()
	{
		clear();
		captured = false;
		suppressClick = false;
	}

	synchronized void clear()
	{

		snapshot = null;
		gesture = null;
		draft = null;
		appliedDraft = null;
		cancel = false;
	}

	synchronized int update()
	{
		Gesture current = gesture;
		if (current == null)
			return 0;
		Widget bank = owner.client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		Widget container = owner.client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		Widget button = owner.client.getWidget(current.control.button);
		if (cancel || bank != current.start.bank || bank == null || bank.isHidden() || container == null
				|| button == null || button.isHidden() || !container.getBounds().equals(current.start.container)
				|| blocked() || !owner.config.bankLayoutEnabled() || !owner.config.bankButtonDragging()
				|| owner.actionBar.enabled())
		{
			boolean changed = draft != null;
			clear();
			return changed ? 2 : 0;
		}
		boolean moved = current.pressed.distanceSq(current.point) >= 16;
		if (!moved && draft == null)
		{
			if (current.released)
				clear();
			return 0;
		}
		boolean first = draft == null;
		BankControlLayout next = BankControlLayout.read(current.start.initial);
		BankControlLayout.Entry selected = next.entries.stream().filter(e -> e.control == current.control).findFirst()
				.get();
		Rectangle bounds = current.start.container;
		int x = current.point.x - bounds.x, y = current.point.y - bounds.y;
		boolean dock = bounds.width >= BankControlLayout.MIN_DOCK_WIDTH
				&& bounds.height >= BankControlLayout.TOP + BankControlLayout.PITCH + 38 && x >= 0
				&& x < BankControlLayout.DOCK_X + BankControlLayout.DOCK_WIDTH + 8 && y >= BankControlLayout.TOP
				&& y < bounds.height - 46;
		selected.left = dock;
		if (dock)
		{
			next.entries.remove(selected);
			List<BankControlLayout.Entry> left = new ArrayList<>();
			for (BankControlLayout.Entry entry : next.entries)
				if (entry.left && current.start.buttons.containsKey(entry.control))
					left.add(entry);
			int index = Math.max(0, Math.min(left.size(), (y - BankControlLayout.TOP) / BankControlLayout.PITCH));
			if (index == left.size())
			{
				selected.position = 1000;
				next.entries.add(selected);
			}
			else
			{
				BankControlLayout.Entry before = left.get(index);
				selected.position = before.position;
				next.entries.add(next.entries.indexOf(before), selected);
			}
		}
		else
		{
			int grab = current.pressed.x - current.start.buttons.get(current.control).x;
			selected.position = Math.max(0,
					Math.min(1000, (x - grab - 2) * 1000 / Math.max(1, bounds.width - current.control.width - 4)));
			next.entries.remove(selected);
			int index = 0;
			while (index < next.entries.size() && (next.entries.get(index).position < selected.position
					|| next.entries.get(index).position == selected.position && current.point.x > current.pressed.x))
				index++;
			next.entries.add(index, selected);
		}
		next.sort();
		String value = next.write();
		boolean changed = !value.equals(appliedDraft);
		draft = next;
		appliedDraft = value;
		if (current.released)
		{
			if (!bounds.contains(current.point))
			{
				clear();
				return 2;
			}

			owner.configs.setConfiguration("windowmarkers", "bankControlLayout", value);
			owner.configs.setConfiguration("windowmarkers", "customBankControls", true);
			clear();
			return 2;
		}
		return first && !current.start.custom ? 2 : changed ? 1 : 0;
	}

	void capture()
	{
		Widget bank = owner.client.getWidget(InterfaceID.Bankmain.UNIVERSE),
				container = owner.client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		Widget items = owner.client.getWidget(InterfaceID.Bankmain.ITEMS),
				bottom = owner.client.getWidget(InterfaceID.Bankmain.BOTTOM);
		if (owner.actionBar.enabled() || !owner.config.bankLayoutEnabled() || !owner.config.bankButtonDragging()
				|| bank == null || bank.isHidden() || container == null || items == null || items.isHidden()
				|| bottom == null || bottom.isHidden() || blocked() || owner.client.getDraggedWidget() != null)
		{
			snapshot = null;
			return;
		}
		Rectangle area = container.getBounds();
		Map<BankControl, Rectangle> buttons = new EnumMap<>(BankControl.class);
		boolean custom = owner.config.customBankControls();
		String preference = custom ? owner.config.bankControlLayout() : "";
		for (BankControl control : BankControl.values())
		{
			Widget widget = owner.client.getWidget(control.button);
			if (widget == null || widget.isHidden())
				continue;
			Rectangle r = widget.getBounds();
			if (!area.contains(r) || r.width <= 0 || r.height <= 0)
				continue;
			buttons.put(control, new Rectangle(r));
		}
		Snapshot previous = snapshot;
		if (previous != null && previous.bank == bank && previous.container.equals(area)
				&& previous.buttons.equals(buttons) && previous.custom == custom
				&& Objects.equals(previous.preference, preference))
			return;
		BankControlLayout initial = BankControlLayout.read(preference);
		for (BankControlLayout.Entry entry : initial.entries)
		{
			Rectangle r = buttons.get(entry.control);
			if (r != null && !custom)
			{
				entry.position = Math.max(0,
						Math.min(1000, (r.x - area.x - 2) * 1000 / Math.max(1, area.width - r.width - 4)));
				entry.left = r.y - area.y < area.height - 40;
			}
		}
		initial.sort();
		snapshot = new Snapshot(bank, new Rectangle(area), buttons, initial.write(), preference, custom);
	}

	private boolean blocked()
	{
		if (owner.client.isMenuOpen())
			return true;
		for (int id : new int[] { InterfaceID.Bankmain.INCINERATOR_CONFIRM,
				InterfaceID.Bankmain.BANKTAGS_POPUP_STRINGEXPORT_CONTAINER })
		{
			Widget modal = owner.client.getWidget(id);
			if (modal != null && !modal.isHidden())
				return true;
		}
		return false;
	}

	private final class DragOverlay extends Overlay
	{
		DragOverlay()
		{
			setPosition(OverlayPosition.DYNAMIC);
			setLayer(OverlayLayer.MANUAL);
			drawAfterInterface(InterfaceID.BANKMAIN);
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			Snapshot current = snapshot;
			Gesture moving = gesture;
			if (current == null || moving == null
					&& (!owner.client.isKeyPressed(KeyCode.KC_ALT) || owner.client.isKeyPressed(KeyCode.KC_CONTROL)))
				return null;
			Rectangle area = current.container;
			Graphics2D g = (Graphics2D) graphics.create();
			try
			{
				g.setColor(new Color(100, 195, 220, 110));
				g.drawRect(area.x + 1, area.y + area.height - 38, area.width - 3, 37);
				if (area.width >= BankControlLayout.MIN_DOCK_WIDTH
						&& area.height >= BankControlLayout.TOP + BankControlLayout.PITCH + 38)
					g.drawRect(area.x + BankControlLayout.DOCK_X - 1, area.y + BankControlLayout.TOP - 1,
							BankControlLayout.DOCK_WIDTH + 1, area.height - BankControlLayout.TOP - 39);
				for (Map.Entry<BankControl, Rectangle> entry : current.buttons.entrySet())
				{
					g.setColor(moving != null && moving.control == entry.getKey() ? new Color(255, 215, 95)
							: new Color(100, 195, 220, 140));
					g.draw(entry.getValue());
				}
				String tip = moving == null ? "Alt-drag bank buttons to arrange"
						: "Release to save position · outside bank to cancel";
				int width = g.getFontMetrics().stringWidth(tip) + 12, x = area.x + (area.width - width) / 2,
						y = area.y + area.height - 58;
				g.setColor(new Color(20, 20, 20, 220));
				g.fillRect(x, y, width, 18);
				g.setColor(new Color(255, 215, 95));
				g.drawString(tip, x + 6, y + 13);
			}
			finally
			{
				g.dispose();
			}
			return null;
		}
	}
}

package com.windowmarkers;

import java.awt.Rectangle;
import java.util.*;

final class BankControlLayout
{
	static final int DOCK_WIDTH = 48, DOCK_X = 42, TOP = 54, PITCH = 38, MIN_DOCK_WIDTH = 526;

	static final class Entry
	{
		final BankControl control;
		int position;
		boolean left;

		Entry(BankControl control, int position, boolean left)
		{
			this.control = control;
			this.position = position;
			this.left = left;
		}

		@Override
		public String toString()
		{
			return control.label + (left ? "  — left dock" : "");
		}
	}

	static final class Plan
	{
		final Map<BankControl, Rectangle> bounds = new EnumMap<>(BankControl.class);
		final Set<BankControl> docked = EnumSet.noneOf(BankControl.class);
		int inset;
	}

	final List<Entry> entries = new ArrayList<>();

	static BankControlLayout read(String value)
	{
		BankControlLayout layout = new BankControlLayout();
		Set<BankControl> seen = EnumSet.noneOf(BankControl.class);
		if (value != null && value.startsWith("v1;") && value.length() < 2048)
			for (String part : value.substring(3).split(";"))
			{
				String[] fields = part.split(":");
				if (fields.length != 3)
					continue;
				try
				{
					BankControl control = BankControl.valueOf(fields[0]);
					int position = Integer.parseInt(fields[1]);
					if ((!fields[2].equals("L") && !fields[2].equals("B")) || !seen.add(control))
						continue;
					layout.entries
							.add(new Entry(control, Math.max(0, Math.min(1000, position)), fields[2].equals("L")));
				}
				catch (IllegalArgumentException ignored)
				{
				}
			}
		for (BankControl control : BankControl.values())
			if (!seen.contains(control))
				layout.entries
						.add(new Entry(control, control.ordinal() * 1000 / (BankControl.values().length - 1), false));
		layout.sort();
		return layout;
	}

	void sort()
	{
		entries.sort(Comparator.comparingInt(e -> e.position));
	}

	String write()
	{
		StringBuilder out = new StringBuilder("v1;");
		for (Entry entry : entries)
			out.append(entry.control.name()).append(':').append(entry.position).append(':')
					.append(entry.left ? 'L' : 'B').append(';');
		return out.toString();
	}

	void move(Entry entry, int direction)
	{
		int index = entries.indexOf(entry), other = index + direction;
		if (other < 0 || other >= entries.size())
			return;
		Entry neighbour = entries.get(other);
		int position = entry.position;
		entry.position = neighbour.position;
		neighbour.position = position;
		Collections.swap(entries, index, other);
	}

	Plan plan(int width, int height, Set<BankControl> visible)
	{
		Plan plan = new Plan();
		List<Entry> row = new ArrayList<>();
		int capacity = width >= MIN_DOCK_WIDTH ? Math.max(0, (height - 38 - TOP) / PITCH) : 0;
		for (Entry entry : entries)
		{
			if (!visible.contains(entry.control))
				continue;
			if (entry.left && plan.docked.size() < capacity)
			{
				plan.bounds.put(entry.control,
						new Rectangle(DOCK_X, TOP + plan.docked.size() * PITCH, entry.control.width, 36));
				plan.docked.add(entry.control);
			}
			else
				row.add(entry);
		}
		plan.inset = plan.docked.isEmpty() ? 0 : DOCK_WIDTH;
		int remaining = row.stream().mapToInt(e -> e.control.width + 2).sum(), cursor = 2;
		for (Entry entry : row)
		{
			int size = entry.control.width;
			remaining -= size + 2;
			int desired = 2 + (int) ((long) entry.position * Math.max(0, width - 4 - size) / 1000);
			int x = Math.max(cursor, Math.min(desired, width - 2 - size - remaining));
			plan.bounds.put(entry.control, new Rectangle(x, height - 37, size, 36));
			cursor = x + size + 2;
		}
		return plan;
	}
}

package com.windowmarkers;

import java.awt.Rectangle;
import java.util.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;

final class BankControlWidgets
{
	private final BankLayoutController owner;
	private final Map<Widget, int[]> applied = new IdentityHashMap<>();
	private String saved;
	private BankControlLayout layout;
	private int visibility = -1, planWidth, planHeight;
	volatile int previewWidth = 478, previewHeight = 290;

	BankControlWidgets(BankLayoutController owner)
	{
		this.owner = owner;
	}

	private Set<BankControl> visible()
	{
		Set<BankControl> result = EnumSet.noneOf(BankControl.class);
		for (BankControl control : BankControl.values())
		{
			Widget button = owner.client.getWidget(control.button);
			if (button != null && !button.isHidden())
				result.add(control);
		}
		return result;
	}

	BankControlLayout.Plan plan(Widget container)
	{
		previewWidth = container.getWidth();
		previewHeight = container.getHeight();
		planWidth = previewWidth;
		planHeight = previewHeight;
		if (!Objects.equals(saved, owner.config.bankControlLayout()) || layout == null)
		{
			saved = owner.config.bankControlLayout();
			layout = BankControlLayout.read(saved);
		}
		BankControlLayout selected = owner.controlDrag.draft();
		return (selected == null ? layout : selected).plan(container.getWidth(), container.getHeight(), visible());
	}

	boolean changed()
	{
		Widget container = owner.client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		if (container == null || visibility < 0 || container.getWidth() != planWidth
				|| container.getHeight() != planHeight)
			return true;
		if (visibility != visibilitySignature())
			return true;
		for (Map.Entry<Widget, int[]> entry : applied.entrySet())
		{
			Widget w = entry.getKey();
			int[] g = entry.getValue();
			if (owner.client.getWidget(w.getId()) != w || w.getOriginalX() != g[0] || w.getOriginalY() != g[1]
					|| w.getOriginalWidth() != g[2] || w.getOriginalHeight() != g[3] || w.getXPositionMode() != g[4]
					|| w.getYPositionMode() != g[5] || w.getWidthMode() != g[6] || w.getHeightMode() != g[7])
				return true;
		}
		return false;
	}

	void clear()
	{
		applied.clear();
		visibility = -1;
	}

	void capture()
	{
		for (Map.Entry<Widget, int[]> entry : applied.entrySet())
			entry.setValue(geometry(entry.getKey()));
		visibility = visibilitySignature();
	}

	private int visibilitySignature()
	{
		int mask = 0;
		for (BankControl control : BankControl.values())
		{
			Widget button = owner.client.getWidget(control.button);
			if (button != null && !button.isHidden())
				mask |= 1 << control.ordinal();
		}
		return mask;
	}

	private static int[] geometry(Widget w)
	{
		return new int[] { w.getOriginalX(), w.getOriginalY(), w.getOriginalWidth(), w.getOriginalHeight(),
				w.getXPositionMode(), w.getYPositionMode(), w.getWidthMode(), w.getHeightMode() };
	}

	private void position(Widget w, int x, int y)
	{
		if (w == null)
			return;
		owner.setPos(w, x, y, WidgetPositionMode.ABSOLUTE_LEFT, WidgetPositionMode.ABSOLUTE_TOP);
		applied.put(w, null);
	}

	void apply(Widget container, BankControlLayout.Plan plan)
	{
		Widget bottom = owner.client.getWidget(InterfaceID.Bankmain.BOTTOM);
		if (bottom == null)
			return;
		int top = plan.docked.isEmpty() ? container.getHeight() - 37 : BankControlLayout.TOP;

		owner.setSize(bottom, 0, container.getHeight() - 1 - top, WidgetSizeMode.MINUS, WidgetSizeMode.ABSOLUTE);
		owner.setPos(bottom, 0, 1, WidgetPositionMode.ABSOLUTE_LEFT, WidgetPositionMode.ABSOLUTE_BOTTOM);
		applied.put(bottom, null);
		Widget quantity = owner.client.getWidget(InterfaceID.Bankmain.QUANTITY_LAYER);
		if (quantity != null)
		{
			position(quantity, 0, 0);
			owner.setSize(quantity, 0, 0, WidgetSizeMode.MINUS, WidgetSizeMode.MINUS);
		}
		for (int id : new int[] { InterfaceID.Bankmain.BOTTOM_LINE4, InterfaceID.Bankmain.BOTTOM_LINE6,
				InterfaceID.Bankmain.DEPOSIT_LINE })
			position(owner.client.getWidget(id), -1000, 0);
		for (BankControl control : BankControl.values())
		{
			Rectangle r = plan.bounds.get(control);
			if (r == null)
				continue;
			Widget button = owner.client.getWidget(control.button), icon = owner.client.getWidget(control.graphic);
			position(button, r.x, r.y - top);
			position(icon, r.x + control.iconX, r.y - top + control.iconY);

			if (icon != null && control.quantity())
				owner.setSize(icon, 25, 21, WidgetSizeMode.ABSOLUTE, WidgetSizeMode.ABSOLUTE);
		}
	}
}

package com.windowmarkers;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
