	void startUp()
	{
		inventoryWidgets.setClient(client);
		if (potionViews != null)
		{
			inventoryWidgets.setVirtualSource(potionViews::validSource);
			potionViews.setMenuSource(inventoryWidgets::source);
		}
		if (anchorAdapter != null)
			anchorAdapter.start();
		active = true;
		lifecycle++;
		rebuildQueued = false;
		controlDrag.resetInput();
		windowDrag.resetInput();
		actionBar.resetInput();
		if (mouseManager != null)
		{
			mouseManager.registerMouseListener(0, controlDrag);
			mouseManager.registerMouseListener(0, windowDrag);
			mouseManager.registerMouseListener(0, actionBar);
			mouseManager.registerMouseWheelListener(0, actionBar);
		}
		if (overlayManager != null)
		{
			overlayManager.add(controlDrag.overlay);
			overlayManager.add(windowDrag.overlay);
			overlayManager.add(actionBar.overlay);
			overlayManager.add(equipmentPreview);
			overlayManager.add(potionIndicators);
		}
		eventBus.register(this);

		frameSubscriber = eventBus.register(ScriptPreFired.class, this::layoutFrame, 10);
		actionFrameSubscriber = eventBus.register(BeforeRender.class, e -> actionBar.beforeFrame(), 10);
		tabFrameSubscriber = eventBus.register(ScriptPostFired.class, this::prepareTabPositions, 1);
		queueRebuild();
	}

	void shutDown()
	{
		potionLayout.clear();
		if (anchorAdapter != null)
			anchorAdapter.stop();
		active = false;
		long stopped = ++lifecycle;
		controlDrag.resetInput();
		windowDrag.resetInput();
		actionBar.resetInput();
		if (mouseManager != null)
		{
			mouseManager.unregisterMouseListener(controlDrag);
			mouseManager.unregisterMouseListener(windowDrag);
			mouseManager.unregisterMouseListener(actionBar);
			mouseManager.unregisterMouseWheelListener(actionBar);
		}
		if (overlayManager != null)
		{
			overlayManager.remove(controlDrag.overlay);
			overlayManager.remove(windowDrag.overlay);
			overlayManager.remove(actionBar.overlay);
			overlayManager.remove(equipmentPreview);
			overlayManager.remove(potionIndicators);
		}
		eventBus.unregister(this);
		eventBus.unregister(frameSubscriber);
		eventBus.unregister(actionFrameSubscriber);
		eventBus.unregister(tabFrameSubscriber);
		clientThread.invokeLater(() ->
		{
			if (lifecycle != stopped || active)
				return;
			restore();
			rebuildBank();
		});
	}

