	@Subscribe(priority = -20)
	public void onBeforeRender(BeforeRender event)
	{
		if (active && layoutEnabled())
		{
			int windowUpdate = windowDrag.update();
			if (windowUpdate == 2)
				restore();
			if (windowUpdate > 0)
				applyFrame();
			int update = actionBar.enabled() ? actionBar.update() : controlDrag.update();
			if (update == 2)
				restore();
			if (update > 0)
				applyFrame();
			reapplyFrame();
			alignTabs();
			if (actionBar.enabled())
			{
				Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER),
						items = client.getWidget(InterfaceID.Bankmain.ITEMS);
				if (container != null && items != null && (!items.isHidden() || potionsVisible()))
				{
					if (actionBar.changed())
						applyFrame();
					else
						actionBar.apply(container);
				}
				else
					actionBar.restore();
				actionBar.capture();
			}
			else if (actionBar.plan != null)
			{
				actionBar.restore();
				actionBar.clearInput();
			}
			controlDrag.capture();
			windowDrag.capture();
			potionLayout.apply(client.getWidget(InterfaceID.Bankmain.POTIONSTORE_ITEMS));
		}
		else
		{
			controlDrag.clear();
			windowDrag.clear();
			actionBar.clearInput();
		}
		if (active)
			actionBar.applyCompactSearch();
		if (active && ownsPreset())
			viewGeometry.restore(client.getWidget(InterfaceID.Bankmain.ITEMS));
	}

	@Subscribe(priority = 30)
	public void onWidgetDrag(net.runelite.api.events.WidgetDrag event)
	{
		if (!active || !ownsPreset())
			return;
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (items == null || items.isHidden())
			return;
		Widget dragged = client.getDraggedWidget();
		if (dragged != null && dragged.getId() == InterfaceID.Bankmain.ITEMS)
			client.setDraggedOnWidget(null);
		String identity = presetIdentity();
		viewGeometry.drag(client, items,
				() -> active && ownsPreset() && java.util.Objects.equals(identity, presetIdentity())
						&& client.getWidget(InterfaceID.Bankmain.ITEMS) == items && !items.isHidden());
	}

	private boolean ownsPreset()
	{
		return searchView != null && searchView.isActive() || groupedSearch();
	}

	private String presetIdentity()
	{
		String identity = searchView != null && searchView.isActive() ? searchView.layoutIdentity() + ":" + searchView.bySlot()
				: nativeSearch == null ? null : nativeSearch.layoutIdentity() + ":true";
		return hiddenWikiSetups == null ? identity : hiddenWikiSetups.layoutIdentity(identity, currentLoadout());
	}

	private SetupLoadout currentLoadout()
	{
		return searchView != null && searchView.isActive() ? searchView.loadout()
				: nativeSearch == null ? null : nativeSearch.loadout();
	}

	void resetPresetPositions()
	{
		if (!active || !ownsPreset() || presetPositions == null || configs == null)
			return;
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (items == null || items.isHidden())
			return;
		presetPositions.save(configs.getRSProfileKey(), presetPositions.key(presetIdentity()),
				new BankPresetPositions.Layout());
		viewGeometry.clear();
		rebuildBank();
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (!active || !layoutEnabled())
		{
			return;
		}
		if (rebuildCooldown > 0)
		{
			rebuildCooldown--;
		}

		reapplyFrame();

		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (appliedSignature != null && items != null && !items.isHidden() && rebuildCooldown == 0
				&& items.getWidth() != reflowedWidth)
		{
			rebuildCooldown = REBUILD_COOLDOWN_TICKS;
			queueRebuild();
		}
	}

	@Subscribe(priority = -20)
	public void onScriptCallbackEvent(net.runelite.api.events.ScriptCallbackEvent event)
	{
		if (active && searchView != null)
			searchView.filter(event);

		if (active && "bankBuildTab".equals(event.getEventName())
				&& client.getWidget(InterfaceID.Bankmain.ITEMS) != null
				&& client.getVarcIntValue(VarClientID.MESLAYERMODE) != InputType.SEARCH.getType() && searchView != null
				&& searchView.isActive())
		{
			int size = client.getIntStackSize();
			if (size > 0)
				client.getIntStack()[size - 1] = 1;
		}
	}

	private void reapplyFrame()
	{
		Widget universe = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		if (universe != null && (appliedSignature != null && !Arrays.equals(signature(universe), appliedSignature)
				|| appliedSignature == null && settingsVisible()
				|| !actionBar.enabled() && customControls() && !settingsVisible() && controls.changed()))
		{
			applyFrame();
		}
	}

	void queueRebuild()
	{
		if (rebuildQueued)
			return;
		rebuildQueued = true;
		long expected = lifecycle;
		clientThread.invokeLater(() ->
		{
			if (expected != lifecycle)
				return;
			rebuildQueued = false;
			if (active)
				rebuildBank();
		});
	}

	private void queueLayoutReset()
	{
		long expected = ++lifecycle;
		rebuildQueued = false;
		clientThread.invokeLater(() ->
		{
			if (!active || expected != lifecycle)
				return;
			restore();
			rebuildBank();
			if (active && expected == lifecycle)
				applyFrame();
		});
	}

