package com.windowmarkers;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
final class BankLayouts
{
	static final int MAX_MARKERS = 250;
	private final ConfigManager configs;
	private final Gson gson;
	CustomPresets customPresets = new CustomPresets();
	final List<Marker> markers = new ArrayList<>();
	String accountKey;
	String layoutKey;
	LayoutCatalog catalog = new LayoutCatalog();
	MarkerHistory history = new MarkerHistory();
	final java.util.Map<String, MarkerHistory> histories = new java.util.LinkedHashMap<>();

	@Inject
	BankLayouts(ConfigManager configs, Gson gson)
	{
		this.configs = configs;
		this.gson = gson;
	}

	void load(java.util.function.Consumer<String> status)
	{
		customPresets = new CustomPresets();
		markers.clear();
		accountKey = configs.getRSProfileKey();
		catalog = new LayoutCatalog();
		if (accountKey != null && baseLayoutKey() != null)
		{
			try
			{
				String rawCatalog = configs.getConfiguration("windowmarkers", accountKey, baseLayoutKey() + "_catalog");
				LayoutCatalog saved = rawCatalog == null ? null : gson.fromJson(rawCatalog, LayoutCatalog.class);
				if (saved != null)
				{
					catalog = saved;
					catalog.normalize();
				}
				String templates = configs.getConfiguration("windowmarkers", accountKey,
						baseLayoutKey() + "_customPresets");
				CustomPresets library = templates == null ? null : gson.fromJson(templates, CustomPresets.class);
				if (library != null)
				{
					library.normalize();
					customPresets = library;
				}
			}
			catch (JsonParseException ex)
			{
				status.accept("Could not read named layouts; using Default.");
			}
		}
		layoutKey = currentLayoutKey();
		String raw = accountKey == null || layoutKey == null ? null
				: configs.getConfiguration("windowmarkers", accountKey, layoutKey);
		readMarkers(raw, status);
		String historyKey = accountKey + "/" + layoutKey;
		if (histories.size() > 40)
		{
			histories.clear();
		}
		history = histories.computeIfAbsent(historyKey, k -> new MarkerHistory());
		String snapshot = gson.toJson(markers);
		if (!history.matches(snapshot))
		{
			history.reset(snapshot);
		}
	}

	void readMarkers(String raw, java.util.function.Consumer<String> status)
	{
		try
		{
			Marker[] saved = raw == null ? null : gson.fromJson(raw, Marker[].class);
			if (saved != null)
			{
				for (Marker marker : saved)
				{
					if (marker != null && marker.valid() && markers.size() < MAX_MARKERS)
					{
						markers.add(marker);
					}
				}
			}
		}
		catch (JsonParseException ex)
		{
			status.accept("Saved markers could not be read.");
		}
	}

	String baseLayoutKey()
	{
		return configs.getProfile() == null ? null : "markersV3_profile_" + configs.getProfile().getId();
	}

	String currentLayoutKey()
	{
		String base = baseLayoutKey();
		return base == null ? null : catalog.storageKey(base);
	}

	boolean currentLayout()
	{
		return accountKey != null && layoutKey != null && accountKey.equals(configs.getRSProfileKey())
				&& layoutKey.equals(currentLayoutKey());
	}

	void save(boolean record)
	{
		String snapshot = gson.toJson(markers);
		if (record)
		{
			history.record(snapshot);
		}
		configs.setConfiguration("windowmarkers", accountKey, layoutKey, snapshot);
	}

	void savePresets()
	{
		configs.setConfiguration("windowmarkers", accountKey, baseLayoutKey() + "_customPresets",
				gson.toJson(customPresets));
	}
}

package com.windowmarkers;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.ImageUtil;

final class BankPotionIndicators extends Overlay
{
	private static final BufferedImage CHEST = ImageUtil.resizeImage(
			ImageUtil.loadImageResource(BankPotionIndicators.class, "sidebar-icon.png"), 14, 14);
	private final BankLayoutController owner;

	BankPotionIndicators(BankLayoutController owner)
	{
		this.owner = owner;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.MANUAL);
		drawAfterInterface(InterfaceID.BANKMAIN);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		BankPotionViews views = owner.potionViews;
		if (!owner.active() || views == null || views.externalBank())
			return null;
		Widget items = owner.client.getWidget(InterfaceID.Bankmain.POTIONSTORE_ITEMS);
		Widget viewport = owner.client.getWidget(InterfaceID.Bankmain.POTIONSTORE_CONTAINER);
		if (items == null || items.isHidden() || viewport == null || viewport.isHidden())
			return null;
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.clip(viewport.getBounds());
			for (BankPotionStock.Potion potion : views.stock.potions())
			{
				if (views.settings.bankTab(potion.enumId) < 0)
					continue;
				int index = potion.index * 5;
				Widget row = items.getChild(index), icon = items.getChild(index + 1), heart = items.getChild(index + 4);
				if (row == null || row.isHidden() || icon == null || !potion.variants.contains(icon.getItemId())
						|| heart == null || heart.isHidden())
					continue;
				Rectangle bounds = heart.getBounds();
				if (bounds.width > 0 && bounds.height > 0)
					g.drawImage(CHEST, bounds.x - CHEST.getWidth() - 2,
							bounds.y + (bounds.height - CHEST.getHeight()) / 2, null);
			}
		}
		finally
		{
			g.dispose();
		}
		return null;
	}
}

package com.windowmarkers;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

final class BankPotionItemOrder
{
	static List<Integer> read(BankPotionSettings settings, int tab, List<Integer> nativeOrder)
	{
		String value = settings.configs.getRSProfileConfiguration("windowmarkers", key(tab));
		if (value == null || value.length() > 64000)
			return nativeOrder;
		try
		{
			String[] parts = value.split("\\|", -1);
			if (parts.length != 2)
				return nativeOrder;
			List<Integer> previous = parse(parts[0]), saved = parse(parts[1]);
			Set<Integer> liveIds = new HashSet<>(nativeOrder), previousIds = new HashSet<>(previous);
			List<Integer> surviving = previous.stream().filter(liveIds::contains).collect(Collectors.toList());
			List<Integer> current = nativeOrder.stream().filter(previousIds::contains).collect(Collectors.toList());
			if (!surviving.equals(current))
				return nativeOrder;
			List<Integer> result = saved.stream().filter(liveIds::contains).collect(Collectors.toList());
			Set<Integer> included = new HashSet<>(result);
			for (int i = nativeOrder.size() - 1; i >= 0; i--)
				if (included.add(nativeOrder.get(i)))
				{
					int before = i + 1 < nativeOrder.size() ? result.indexOf(nativeOrder.get(i + 1)) : result.size();
					result.add(before, nativeOrder.get(i));
				}
			return result;
		}
		catch (IllegalArgumentException ignored)
		{
			return nativeOrder;
		}
	}

	static void save(BankPotionSettings settings, int tab, List<Integer> nativeOrder, List<Integer> displayOrder)
	{
		settings.configs.setRSProfileConfiguration("windowmarkers", key(tab), join(nativeOrder) + "|" + join(displayOrder));
	}

	private static String key(int tab)
	{
		return BankPotionSettings.PREFIX + "bankItems." + tab;
	}

	private static List<Integer> parse(String value)
	{
		if (value.isEmpty())
			return new ArrayList<>();
		List<Integer> result = Arrays.stream(value.split(",")).map(Integer::parseInt).collect(Collectors.toList());
		if (result.size() > 2000 || result.stream().anyMatch(id -> id < 0)
				|| result.stream().distinct().count() != result.size())
			throw new IllegalArgumentException();
		return result;
	}

	private static String join(List<Integer> values)
	{
		return values.stream().map(String::valueOf).collect(Collectors.joining(","));
	}
}

package com.windowmarkers;

import java.util.ArrayList;
import java.util.List;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.SpriteID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.WidgetConfig;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

final class BankPotionLayout
{
	private Widget parent;
	private Widget[] nativeChildren;
	private final List<Row> rows = new ArrayList<>();
	private final List<Widget> dividers = new ArrayList<>();
	private final List<Widget> fillers = new ArrayList<>();
	private final List<Extra> extras = new ArrayList<>();
	private int childCount;
	private long generation;

	void clear()
	{
		generation++;
		parent = null;
		nativeChildren = null;
		rows.clear();
		dividers.clear();
		fillers.clear();
		extras.clear();
		childCount = 0;
	}

	void capture(Widget items)
	{
		clear();
		if (items == null || items.isHidden() || items.getWidth() < 100)
			return;
		Widget[] children = items.getDynamicChildren();
		if (children == null)
			return;
		parent = items;
		nativeChildren = children.clone();
		childCount = children.length;
		int half = items.getWidth() / 2, lastY = -1;
		for (int i = 0; i + 4 < children.length; i += 5)
		{
			Widget a = children[i], icon = children[i + 1], name = children[i + 2], dose = children[i + 3],
					heart = children[i + 4];
			if (a == null || icon == null || name == null || dose == null || heart == null
					|| a.getType() != WidgetType.GRAPHIC || a.isSelfHidden() || icon.getItemId() < 0
					|| name.getType() != WidgetType.TEXT || dose.getType() != WidgetType.TEXT
					|| heart.getType() != WidgetType.GRAPHIC || a.getOriginalWidth() < 36)
				continue;
			int column = a.getOriginalX() > 0 || lastY == a.getOriginalY() ? 1 : 0;
			rows.add(new Row(i, new Widget[] { a, icon, name, dose, heart }, column));
			lastY = a.getOriginalY();
		}
		int rowEnd = rows.isEmpty() ? 0 : rows.get(rows.size() - 1).index + 5;
		for (int i = 0; i < children.length; i++)
		{
			Widget child = children[i];
			if (child != null && child.getType() == WidgetType.RECTANGLE && child.getOriginalWidth() == 1
					&& child.getOriginalX() == half)
				dividers.add(child);
			if (i >= rowEnd && child != null && child.getType() == WidgetType.GRAPHIC
					&& child.getSpriteId() == SpriteID.RESIZEABLE_MODE_SIDE_PANEL_BACKGROUND
					&& child.getOriginalX() > 0 && child.getOriginalHeight() == 36)
				fillers.add(child);
		}
	}

	void apply(Widget items)
	{
		if (items == null || items != parent || items.isHidden() || items.getWidth() < 100)
			return;
		Widget[] children = items.getDynamicChildren();
		if (children == null || children.length < nativeChildren.length)
			return;
		for (int i = 0; i < nativeChildren.length; i++)
			if (children[i] != nativeChildren[i])
				return;
		if (items.getScrollWidth() != 0 && items.getScrollWidth() != items.getWidth())
		{
			items.setScrollWidth(items.getWidth());
			for (Widget child : children)
				if (child != null)
					child.revalidate();
		}
		if (children.length != childCount)
		{
			extras.clear();
			childCount = children.length;
			for (int i = nativeChildren.length; i + 2 < children.length; i += 3)
			{
				Widget back = children[i], fill = children[i + 1], text = children[i + 2];
				if (back == null || fill == null || text == null || back.getType() != WidgetType.RECTANGLE
						|| fill.getType() != WidgetType.RECTANGLE || text.getType() != WidgetType.TEXT)
					continue;
				for (Row row : rows)
				{
					Widget dose = row.parts[3];
					if (back.getOriginalX() == dose.getOriginalX() && back.getOriginalY() == dose.getOriginalY()
							&& fill.getOriginalX() == back.getOriginalX() && fill.getOriginalY() == back.getOriginalY()
							&& text.getOriginalX() == back.getOriginalX() + 2
							&& text.getOriginalY() == back.getOriginalY() + 1)
					{
						extras.add(new Extra(back, dose, 0, 0, false));
						extras.add(new Extra(fill, dose, 0, 0, false));
						extras.add(new Extra(text, dose, 2, 1, text.getOriginalWidth() == dose.getOriginalWidth()));
						break;
					}
				}
			}
		}
		int half = items.getWidth() / 2;
		for (Row row : rows)
		{
			Widget background = row.parts[0];
			int currentX = background.getOriginalX();
			if (currentX != row.lastX)
				row.column = currentX > 0 ? 1 : 0;
			int x = row.column == 0 ? 0 : (items.getWidth() + 1) / 2, y = background.getOriginalY();
			for (int i = 0; i < 5; i++)
			{
				Widget part = row.parts[i];
				int px = x + (i == 4 ? half - row.heartInset : row.dx[i]);
				int width = i == 0 || i == 2 || i == 3 ? half : part.getOriginalWidth();
				place(part, px, y + row.dy[i], width);
			}
			row.lastX = x;
		}
		for (Extra extra : extras)
			place(extra.widget, extra.anchor.getOriginalX() + extra.x, extra.anchor.getOriginalY() + extra.y,
					extra.widthFollows ? extra.anchor.getOriginalWidth() : extra.widget.getOriginalWidth());
		for (Widget divider : dividers)
			place(divider, half, divider.getOriginalY(), divider.getOriginalWidth());
		for (Widget filler : fillers)
			place(filler, (items.getWidth() + 1) / 2, filler.getOriginalY(), half);
	}

	void enableMovement(Client client, BankPotionViews views)
	{
		if (parent == null || !views.config.moveStoredPotions() || views.externalOrder())
			return;
		Map<Integer, BankPotionStock.Potion> stocked = new HashMap<>();
		for (BankPotionStock.Potion potion : views.stock.potions())
			stocked.put(potion.index * 5, potion);
		Map<Integer, List<Row>> sections = new HashMap<>();
		for (Row row : rows)
		{
			BankPotionStock.Potion potion = stocked.get(row.index);
			if (potion == null)
				continue;
			int section = row.parts[4].getSpriteId() == SpriteID.FAIRY_RING_REMOVE_FAVOURITE ? 0
					: potion.unfinished ? 2 : 1;
			sections.computeIfAbsent(section, key -> new ArrayList<>()).add(row);
		}
		Widget expected = parent;
		long expectedGeneration = generation;
		for (Map.Entry<Integer, List<Row>> entry : sections.entrySet())
		{
			List<Row> section = entry.getValue();
			section.sort(Comparator.comparingInt((Row row) -> row.parts[0].getOriginalY())
					.thenComparingInt(row -> row.parts[0].getOriginalX()));
			int top = section.get(0).parts[0].getOriginalY();
			int height = section.get(0).parts[0].getOriginalHeight();
			List<Integer> saved = views.settings.order(entry.getKey());
			section.sort(Comparator.comparingInt(row ->
			{
				int position = saved.indexOf(stocked.get(row.index).enumId);
				return position < 0 ? Integer.MAX_VALUE : position;
			}));
			positionRows(section, top, height);
			for (Row row : section)
			{
				Widget background = row.parts[0];
				background.setDragParent(parent);
				background.setClickMask(background.getClickMask() | WidgetConfig.DRAG | WidgetConfig.DRAG_ON);
				background.setDragDeadTime(Math.max(5, background.getDragDeadTime()));
				background.setHasListener(true);
				background.setOnDragCompleteListener((JavaScriptCallback) event ->
				{
					if (generation != expectedGeneration || parent != expected || parent.isHidden()
							|| views.externalOrder() || !views.config.moveStoredPotions()
							|| parent.getChild(row.index) != background)
						return;
					net.runelite.api.Point mouse = client.getMouseCanvasPosition();
					if (mouse == null)
						return;
					Row target = null;
					for (Row other : section)
					{
						if (other.parts[0].getBounds().contains(mouse.getX(), mouse.getY()))
							target = other;
					}
					if (target == null || target == row)
						return;
					int from = section.indexOf(row);
					int to = section.indexOf(target);
					if (client.getVarbitValue(VarbitID.BANK_INSERTMODE) == 1)
					{
						section.remove(from);
						section.add(to, row);
					}
					else
						java.util.Collections.swap(section, from, to);
					positionRows(section, top, height);
					apply(parent);
					List<Integer> order = new ArrayList<>();
					for (Row placed : section)
						order.add(stocked.get(placed.index).enumId);
					views.settings.setOrder(entry.getKey(), order);
				});
			}
		}
		apply(parent);
	}

	private void positionRows(List<Row> section, int top, int height)
	{
		for (int i = 0; i < section.size(); i++)
		{
			Row row = section.get(i);
			row.column = i % 2;
			row.lastX = row.column == 0 ? 0 : (parent.getWidth() + 1) / 2;
			row.parts[0].setOriginalX(row.lastX);
			row.parts[0].setOriginalY(top + i / 2 * height);
		}
	}

	private static void place(Widget widget, int x, int y, int width)
	{
		if (widget.getOriginalX() == x && widget.getOriginalY() == y && widget.getOriginalWidth() == width)
			return;
		widget.setOriginalX(x);
		widget.setOriginalY(y);
		widget.setOriginalWidth(width);
		widget.revalidate();
	}

	private static final class Row
	{
		final int index, heartInset;
		final Widget[] parts;
		final int[] dx = new int[5], dy = new int[5];
		int column, lastX;

		Row(int index, Widget[] parts, int column)
		{
			this.index = index;
			this.parts = parts;
			this.column = column;
			lastX = parts[0].getOriginalX();
			for (int i = 0; i < 5; i++)
			{
				dx[i] = parts[i].getOriginalX() - lastX;
				dy[i] = parts[i].getOriginalY() - parts[0].getOriginalY();
			}
			heartInset = parts[0].getOriginalWidth() - dx[4];
		}
	}

	private static final class Extra
	{
		final Widget widget, anchor;
		final int x, y;
		final boolean widthFollows;

		Extra(Widget widget, Widget anchor, int x, int y, boolean widthFollows)
		{
			this.widget = widget;
			this.anchor = anchor;
			this.x = x;
			this.y = y;
			this.widthFollows = widthFollows;
		}
	}
}

package com.windowmarkers;

import java.awt.BorderLayout;
import java.awt.Component;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.DefaultCellEditor;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTable;
import javax.swing.SwingUtilities;
import javax.swing.table.AbstractTableModel;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;

@Singleton
final class BankPotionPanel
{
	private static final String[] DESTINATIONS = { "Hidden", "Untabbed", "Tab 1", "Tab 2", "Tab 3", "Tab 4", "Tab 5",
			"Tab 6", "Tab 7", "Tab 8", "Tab 9" };

	@Inject
	Client client;
	@Inject
	ClientThread clientThread;
	@Inject
	ConfigManager configs;
	@Inject
	WindowMarkersConfig config;
	@Inject
	BankPotionStock stock;
	@Inject
	BankPotionSettings settings;
	@Inject
	BankPotionViews views;

	private static final class Row
	{
		final int id;
		final String name;
		final int count;
		int tab;
		boolean search;

		Row(int id, String name, int count, int tab, boolean search)
		{
			this.id = id;
			this.name = name;
			this.count = count;
			this.tab = tab;
			this.search = search;
		}
	}

	void open(Component parent)
	{
		clientThread.invokeLater(() ->
		{
			String context = context();
			List<Row> rows = new ArrayList<>();
			for (BankPotionStock.Potion potion : stock.potions())
			{
				rows.add(new Row(potion.enumId, client.getItemDefinition(potion.itemId).getName(), potion.quantity,
						settings.bankTab(potion.enumId), settings.search(potion.enumId)));
			}
			rows.sort(java.util.Comparator.comparing(row -> row.name));
			boolean external = views.externalBank();
			SwingUtilities.invokeLater(() -> show(parent, rows, context, external));
		});
	}

	private String context()
	{
		return (configs.getProfile() == null ? "" : configs.getProfile().getId()) + ":" + configs.getRSProfileKey();
	}

	private void save(String expected, Runnable change)
	{
		clientThread.invokeLater(() ->
		{
			if (Objects.equals(expected, context()))
				change.run();
		});
	}

	private void show(Component parent, List<Row> rows, String context, boolean external)
	{
		JPanel panel = new JPanel(new BorderLayout(0, 8));
		JLabel help = new JLabel(rows.isEmpty() ? "Open the bank to load stored potions."
				: external ? "Potion Storage currently manages normal bank tabs and searches."
						: "Right-click a stored potion to add it to bank and search.");
		help.setToolTipText(
				"Choices apply to each potion type, across its doses. Numbered tabs must already exist. Changes save immediately for this character and profile.");
		panel.add(help, BorderLayout.NORTH);
		AbstractTableModel model = new AbstractTableModel()
		{
			private final String[] columns = { "Potion", "Available", "Bank tab", "Searches" };

			public int getRowCount()
			{
				return rows.size();
			}

			public int getColumnCount()
			{
				return columns.length;
			}

			public String getColumnName(int column)
			{
				return columns[column];
			}

			public Class<?> getColumnClass(int column)
			{
				return column == 3 ? Boolean.class : column == 1 ? Integer.class : String.class;
			}

			public boolean isCellEditable(int row, int column)
			{
				return column >= 2 && !external && Objects.equals(context, context());
			}

			public Object getValueAt(int index, int column)
			{
				Row row = rows.get(index);
				switch (column)
				{
					case 0:
						return row.name;
					case 1:
						return row.count;
					case 2:
						return DESTINATIONS[row.tab + 1];
					default:
						return row.search;
				}
			}

			public void setValueAt(Object value, int index, int column)
			{
				Row row = rows.get(index);
				if (column == 2)
				{
					int tab = java.util.Arrays.asList(DESTINATIONS).indexOf(value) - 1;
					if (tab < -1 || tab > 9)
						return;
					row.tab = tab;
					save(context, () -> settings.setBankTab(row.id, tab));
				}
				else if (column == 3 && value instanceof Boolean)
				{
					boolean search = (Boolean) value;
					row.search = search;
					save(context, () -> settings.setSearch(row.id, search));
				}
				fireTableCellUpdated(index, column);
			}
		};
		JTable table = new JTable(model);
		table.setRowHeight(26);
		table.getColumnModel().getColumn(0).setPreferredWidth(260);
		table.getColumnModel().getColumn(2).setCellEditor(new DefaultCellEditor(new JComboBox<>(DESTINATIONS)));
		panel.add(new JScrollPane(table), BorderLayout.CENTER);
		JCheckBox move = new JCheckBox("Drag to rearrange potion-storage rows", config.moveStoredPotions());
		move.setToolTipText(
				"Uses the bank's swap or insert mode within each section. Disable Potion Storage Customizer to use this plugin's ordering.");
		move.addActionListener(event ->
		{
			boolean selected = move.isSelected();
			save(context, () -> configs.setConfiguration("windowmarkers", "moveStoredPotions", selected));
		});
		panel.add(move, BorderLayout.SOUTH);
		MarkerDialogs.show(parent, panel, "Stored potions", 620, 440);
	}
}

package com.windowmarkers;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.Collections;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.BooleanSupplier;
import java.util.stream.Collectors;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

final class BankPotionPlacement
{
	private final List<Section> sections = new ArrayList<>();
	private final Map<Widget, Integer> itemKeys = new IdentityHashMap<>();
	private long revision;
	private Widget held;
	private long heldRevision;
	private boolean released;
	private BooleanSupplier heldCurrent;
	private int heldItem;

	void clear()
	{
		sections.clear();
		itemKeys.clear();
		revision++;
	}

	void capture(Client client, int tab, List<Widget> cells, Map<Widget, BankPotionStock.Potion> potions,
			BankPotionSettings settings)
	{
		cells.sort(Comparator.comparingInt(Widget::getOriginalY).thenComparingInt(Widget::getOriginalX));
		List<Widget> ordered = new ArrayList<>(cells);
		List<Widget> nativeCells = cells.stream().filter(cell -> !potions.containsKey(cell))
				.sorted(Comparator.comparingInt(Widget::getIndex)).collect(Collectors.toList());
		for (Widget cell : nativeCells)
		{
			net.runelite.api.ItemComposition item = client.getItemDefinition(cell.getItemId());
			itemKeys.put(cell, item != null && item.getPlaceholderTemplateId() > 0
					? item.getPlaceholderId() : cell.getItemId());
		}
		List<Integer> nativeOrder = ids(nativeCells, potions);
		List<Integer> displayOrder = BankPotionItemOrder.read(settings, tab, nativeOrder);
		if (!displayOrder.equals(nativeOrder))
		{
			Map<Integer, Integer> ranks = new HashMap<>();
			for (int i = 0; i < displayOrder.size(); i++)
				ranks.put(displayOrder.get(i), i);
			nativeCells.sort(Comparator.comparingInt(cell -> ranks.get(itemKeys.get(cell))));
			int next = 0;
			for (int i = 0; i < ordered.size(); i++)
				if (!potions.containsKey(ordered.get(i)))
					ordered.set(i, nativeCells.get(next++));
		}
		List<Widget> saved = new ArrayList<>();
		for (Widget cell : cells)
			if (potions.containsKey(cell) && settings.bankPosition(potions.get(cell).enumId) >= 0)
				saved.add(cell);
		saved.sort(Comparator.comparingInt(cell -> settings.bankPosition(potions.get(cell).enumId)));
		ordered.removeAll(saved);
		for (Widget cell : saved)
			ordered.add(Math.min(ordered.size(), settings.bankPosition(potions.get(cell).enumId)), cell);
		int[][] slots = new int[cells.size()][2];
		for (int i = 0; i < cells.size(); i++)
			slots[i] = new int[] { cells.get(i).getOriginalX(), cells.get(i).getOriginalY() };
		for (int i = 0; i < ordered.size(); i++)
		{
			Widget cell = ordered.get(i);
			cell.setOriginalX(slots[i][0]);
			cell.setOriginalY(slots[i][1]);
			cell.revalidate();
		}
		sections.add(new Section(tab, ordered, nativeOrder));
	}

	void drag(Client client, Widget parent, Map<Widget, BankPotionStock.Potion> potions,
			BankPotionSettings settings, BooleanSupplier current)
	{
		Widget dragged = client.getDraggedWidget();
		Section source = section(dragged);
		Widget target = client.getDraggedOnWidget();
		Section destination = section(target);
		boolean stored = potions.containsKey(dragged), ontoStored = potions.containsKey(target);
		if (stored || ontoStored)
			client.setDraggedOnWidget(null);
		if (client.getMouseCurrentButton() != 0)
		{
			if (held != dragged || released)
			{
				held = dragged;
				heldRevision = revision;
				heldCurrent = current;
				heldItem = dragged == null ? -1 : dragged.getItemId();
				released = false;
			}
			return;
		}
		if (released || held != dragged)
			return;
		released = true;
		if (heldRevision != revision || heldCurrent == null || !heldCurrent.getAsBoolean()
				|| !current.getAsBoolean() || !client.isDraggingWidget()
				|| parent.isHidden() || source == null || destination == null || dragged == target
				|| dragged.getItemId() != heldItem
				|| parent.getChild(dragged.getIndex()) != dragged || parent.getChild(target.getIndex()) != target
				|| dragged.isSelfHidden() || target.isSelfHidden())
			return;
		Point mouse = client.getMouseCanvasPosition();
		if (mouse == null || !BankWidgetGeometry.bounds(parent).contains(mouse.getX(), mouse.getY()))
			return;
		if (stored || ontoStored)
		{
			if (source != destination && !stored)
			{
				Widget tabs = client.getWidget(net.runelite.api.gameval.InterfaceID.Bankmain.TABS);
				Widget tab = tabs == null ? null : tabs.getChild(10 + destination.tab);
				if (tab != null)
					client.setDraggedOnWidget(tab);
				return;
			}
			move(dragged, target, destination, potions, settings, true);
		}
		else if (source == destination)
		{
			boolean insert = client.getVarbitValue(VarbitID.BANK_INSERTMODE) == 1;
			reorder(source.nativeOrder, itemKeys.get(dragged), itemKeys.get(target), insert);
			move(dragged, target, destination, potions, settings, insert);
		}
	}

	private Section section(Widget widget)
	{
		for (Section section : sections)
			if (section.cells.contains(widget))
				return section;
		return null;
	}

	private void move(Widget dragged, Widget target, Section destination,
			Map<Widget, BankPotionStock.Potion> potions, BankPotionSettings settings, boolean insert)
	{
		for (Section section : sections)
		{
			List<Widget> ordered = new ArrayList<>(section.cells);
			boolean removed = ordered.contains(dragged);
			if (section == destination && removed)
				reorder(ordered, dragged, target, insert);
			else
			{
				ordered.remove(dragged);
				if (section == destination)
					ordered.add(ordered.indexOf(target), dragged);
			}
			if (removed || section == destination)
			{
				List<Integer> displayOrder = ids(ordered, potions);
				if (!displayOrder.equals(section.nativeOrder)
						|| settings.configs.getRSProfileConfiguration("windowmarkers", BankPotionSettings.PREFIX + "bankItems." + section.tab) != null)
					BankPotionItemOrder.save(settings, section.tab, section.nativeOrder, displayOrder);
				for (int i = 0; i < ordered.size(); i++)
				{
					BankPotionStock.Potion potion = potions.get(ordered.get(i));
					if (potion != null)
					{
						settings.setBankTab(potion.enumId, section.tab);
						settings.setBankPosition(potion.enumId, i);
					}
				}
			}
		}
		revision++;
	}

	private static <T> void reorder(List<T> order, T source, T target, boolean insert)
	{
		int from = order.indexOf(source), to = order.indexOf(target);
		if (from < 0 || to < 0)
			return;
		if (insert)
		{
			order.remove(from);
			order.add(to, source);
		}
		else
			Collections.swap(order, from, to);
	}

	private List<Integer> ids(List<Widget> cells, Map<Widget, BankPotionStock.Potion> potions)
	{
		return cells.stream().filter(cell -> !potions.containsKey(cell)).map(itemKeys::get).collect(Collectors.toList());
	}

	private static final class Section
	{
		final int tab;
		final List<Widget> cells;
		final List<Integer> nativeOrder;

		Section(int tab, List<Widget> cells, List<Integer> nativeOrder)
		{
			this.tab = tab;
			this.cells = cells;
			this.nativeOrder = nativeOrder;
		}
	}
}

package com.windowmarkers;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
final class BankPotionSettings
{
	static final String PREFIX = "storedPotion.";
	@Inject
	ConfigManager configs;

	int bankTab(int potion)
	{
		String value = configs.getRSProfileConfiguration("windowmarkers", PREFIX + potion + ".tab");
		try
		{
			int tab = Integer.parseInt(value);
			return tab >= 0 && tab <= 9 ? tab : -1;
		}
		catch (NumberFormatException ignored)
		{
			return -1;
		}
	}

	boolean search(int potion)
	{
		return Boolean.parseBoolean(configs.getRSProfileConfiguration("windowmarkers", PREFIX + potion + ".search"));
	}

	int bankPosition(int potion)
	{
		String value = configs.getRSProfileConfiguration("windowmarkers", PREFIX + potion + ".position");
		try
		{
			int position = Integer.parseInt(value);
			return position >= 0 && position <= 4000 ? position : -1;
		}
		catch (NumberFormatException ignored)
		{
			return -1;
		}
	}

	void setBankPosition(int potion, int position)
	{
		configs.setRSProfileConfiguration("windowmarkers", PREFIX + potion + ".position", position);
	}

	void setBankTab(int potion, int tab)
	{
		configs.setRSProfileConfiguration("windowmarkers", PREFIX + potion + ".tab", Math.max(-1, Math.min(9, tab)));
	}

	void setSearch(int potion, boolean shown)
	{
		configs.setRSProfileConfiguration("windowmarkers", PREFIX + potion + ".search", shown);
	}

	List<Integer> order(int section)
	{
		String value = configs.getRSProfileConfiguration("windowmarkers", PREFIX + "order." + section);
		if (value == null || value.isEmpty() || value.length() > 4096)
		{
			return Collections.emptyList();
		}
		List<Integer> result = new ArrayList<>();
		for (String part : value.split(","))
		{
			try
			{
				int id = Integer.parseInt(part);
				if (id > 0 && !result.contains(id))
				{
					result.add(id);
				}
			}
			catch (NumberFormatException ignored)
			{
				return Collections.emptyList();
			}
		}
		return result;
	}

	void setOrder(int section, List<Integer> order)
	{
		List<String> values = new ArrayList<>();
		for (int id : order)
		{
			values.add(Integer.toString(id));
		}
		configs.setRSProfileConfiguration("windowmarkers", PREFIX + "order." + section, String.join(",", values));
	}
}

package com.windowmarkers;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.ScriptID;
import net.runelite.api.EnumID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;

@Singleton
final class BankPotionStock
{
	static final class Potion
	{
		final int enumId;
		final int index;
		final int itemId;
		final int quantity;
		final boolean unfinished;
		final List<Integer> variants;

		Potion(int enumId, int index, int itemId, int quantity, boolean unfinished, List<Integer> variants)
		{
			this.enumId = enumId;
			this.index = index;
			this.itemId = itemId;
			this.quantity = quantity;
			this.unfinished = unfinished;
			this.variants = Collections.unmodifiableList(variants);
		}
	}

	@Inject
	Client client;
	private List<Potion> potions = Collections.emptyList();
	private final Set<Integer> triggers = new HashSet<>();
	private boolean dirty = true;

	List<Potion> potions()
	{
		return potions;
	}

	void clear()
	{
		potions = Collections.emptyList();
		triggers.clear();
		dirty = true;
	}

	void changed(int varp)
	{
		if (triggers.contains(varp) || varp == VarPlayerID.POTIONSTORE_BASE_VAR_1
				|| varp == VarPlayerID.POTIONSTORE_BASE_VAR_2 || varp == VarPlayerID.POTIONSTORE_BASE_VAR_3
				|| varp == VarPlayerID.POTIONSTORE_BASE_VAR_4 || varp == VarPlayerID.POTIONSTORE_BASE_VAR_5
				|| varp == VarPlayerID.POTIONSTORE_BASE_VAR_6)
		{
			dirty = true;
		}
	}

	boolean refresh()
	{
		if (!dirty)
		{
			return false;
		}
		Widget items = client.getWidget(InterfaceID.Bankmain.POTIONSTORE_ITEMS);
		if (items == null)
		{
			return false;
		}
		EnumComposition finished = client.getEnum(EnumID.POTIONSTORE_POTIONS);
		EnumComposition unfinished = client.getEnum(EnumID.POTIONSTORE_UNFINISHED_POTIONS);
		if (finished == null || unfinished == null)
		{
			return false;
		}
		List<Potion> next = new ArrayList<>();
		int index = 0;
		for (EnumComposition list : new EnumComposition[] { finished, unfinished })
		{
			for (int enumId : list.getIntVals())
			{
				EnumComposition definition = client.getEnum(enumId);
				int row = index++;
				if (definition == null)
				{
					continue;
				}
				client.runScript(ScriptID.POTIONSTORE_DOSES, enumId);
				int doses = client.getIntStack()[0];
				client.runScript(ScriptID.POTIONSTORE_WITHDRAW_DOSES, enumId);
				int withdraw = client.getIntStack()[0];
				if (withdraw <= 0 || doses < withdraw)
				{
					continue;
				}
				int itemId = definition.getIntValue(withdraw);
				if (itemId <= 0)
				{
					continue;
				}
				List<Integer> variants = new ArrayList<>();
				for (int dose = 1; dose <= 4; dose++)
				{
					int variant = definition.getIntValue(dose);
					if (variant > 0)
					{
						variants.add(variant);
					}
				}
				next.add(new Potion(enumId, row, itemId, doses / withdraw, list == unfinished, variants));
			}
		}
		int[] vars = items.getVarTransmitTrigger();
		if (vars != null)
		{
			for (int varp : vars)
			{
				triggers.add(varp);
			}
		}
		dirty = false;
		boolean changed = next.size() != potions.size();
		for (int i = 0; !changed && i < next.size(); i++)
		{
			Potion before = potions.get(i);
			Potion after = next.get(i);
			changed = before.enumId != after.enumId || before.itemId != after.itemId
					|| before.quantity != after.quantity;
		}
		potions = Collections.unmodifiableList(next);
		return changed;
	}
}

package com.windowmarkers;

