@Singleton
final class BankPotionViews
{
	private static final int[] TABS = { VarbitID.BANK_TAB_1, VarbitID.BANK_TAB_2, VarbitID.BANK_TAB_3,
			VarbitID.BANK_TAB_4, VarbitID.BANK_TAB_5, VarbitID.BANK_TAB_6, VarbitID.BANK_TAB_7, VarbitID.BANK_TAB_8,
			VarbitID.BANK_TAB_9 };

	@Inject
	Client client;
	@Inject
	ClientThread clientThread;
	@Inject
	EventBus events;
	@Inject
	ConfigManager configs;
	@Inject
	PluginManager plugins;
	@Inject
	BankPotionStock stock;
	@Inject
	BankPotionSettings settings;
	@Inject
	BankSearchView searchView;
	@Inject
	WindowMarkersConfig config;
	private final Map<Widget, BankPotionStock.Potion> drawn = new IdentityHashMap<>();
	private final BankPotionPlacement placement = new BankPotionPlacement();
	private final Map<MenuEntry, Click> clicks = new java.util.WeakHashMap<>();
	private Widget parent;
	private java.util.function.Function<Widget, Widget> menuSource = java.util.function.Function.identity();
	private Runnable changed;
	private volatile long generation;
	private volatile boolean active;
	private boolean externalBank;
	private boolean externalOrder;

	private static final class Click
	{
		final Widget parent;
		final Widget source;
		final BankPotionStock.Potion potion;
		final String context;

		Click(Widget parent, Widget source, BankPotionStock.Potion potion, String context)
		{
			this.parent = parent;
			this.source = source;
			this.potion = potion;
			this.context = context;
		}
	}

	private String context()
	{
		return generation + ":" + (configs.getProfile() == null ? "" : configs.getProfile().getId()) + ":"
				+ configs.getRSProfileKey();
	}

	void start(Runnable changed)
	{
		this.changed = changed;
		active = true;
		generation++;
		events.register(this);
		refreshProviders();
	}

	void stop()
	{
		active = false;
		generation++;
		events.unregister(this);
		long stopped = generation;
		clientThread.invokeLater(() ->
		{
			if (!active && generation == stopped)
				reset();
		});
	}

	boolean externalOrder()
	{
		return externalOrder;
	}

	boolean externalBank()
	{
		return externalBank;
	}

	private void refreshProviders()
	{
		externalBank = false;
		externalOrder = false;
		for (net.runelite.client.plugins.Plugin plugin : plugins.getPlugins())
		{
			if (!plugins.isPluginActive(plugin))
				continue;
			String name = plugin.getClass().getName();
			externalBank |= name.equals("com.potionstorage.PotionStoragePlugin");
			externalOrder |= name.equals("com.potionstoragecustomizer.PotionStorageCustomizerPlugin");
		}
	}

	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		defer(() ->
		{
			refreshProviders();
			changed.run();
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if ("windowmarkers".equals(event.getGroup())
				&& (event.getKey().startsWith(BankPotionSettings.PREFIX) || event.getKey().equals("moveStoredPotions")))
		{
			defer(changed);
		}
	}

	private void defer(Runnable action)
	{
		long expected = generation;
		clientThread.invokeLater(() ->
		{
			if (active && expected == generation)
				action.run();
		});
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		if (active && client.getGameState() == GameState.LOGGED_IN && bank != null && !bank.isHidden()
				&& stock.refresh())
		{
			changed.run();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		stock.changed(event.getVarpId());
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
			reset();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
			reset();
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		generation++;
		defer(this::reset);
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		generation++;
		defer(this::reset);
	}

	private void reset()
	{
		generation++;
		clearWidgets();
		stock.clear();
	}

	@Subscribe(priority = -15)
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() == ScriptID.BANKMAIN_BUILD)
			clearWidgets();
		if (event.getScriptId() == ScriptID.BANKMAIN_FINISHBUILDING)
			append();
	}

	void append()
	{
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		if (items == null || items.isHidden() || bank == null)
			return;
		boolean preset = searchView.isActive();
		if (!preset && (externalBank || searchView.bankTags.getActiveBankTag() != null))
			return;
		boolean searching = client.getVarcIntValue(VarClientID.MESLAYERMODE) == net.runelite.api.vars.InputType.SEARCH
				.getType();
		String query = Objects.toString(client.getVarcStrValue(VarClientID.MESLAYERINPUT), "")
				.toLowerCase(java.util.Locale.ROOT);
		int tab = client.getVarbitValue(VarbitID.BANK_CURRENTTAB);
		if (tab < 0 || tab > 9)
			return;
		parent = items;
		placement.clear();
		Map<Integer, List<BankPotionStock.Potion>> groups = new LinkedHashMap<>();
		for (BankPotionStock.Potion potion : stock.potions())
		{
			int target = settings.bankTab(potion.enumId);
			if (preset)
			{
				if (potion.variants.stream().noneMatch(searchView.bankTags.getActiveBankTag()::contains))
					continue;
				if (alreadyShown(items, potion.itemId))
					continue;
				target = 0;
			}
			else if (searching)
			{
				if (!settings.search(potion.enumId) || !client.getItemDefinition(potion.itemId).getName()
						.toLowerCase(java.util.Locale.ROOT).contains(query))
					continue;
				target = 0;
			}
			else if (target < 0 || tab != 0 && target != tab
					|| target > 0 && client.getVarbitValue(TABS[target - 1]) == 0)
			{
				continue;
			}
			groups.computeIfAbsent(target, ignored -> new ArrayList<>()).add(potion);
		}
		for (int selected = 0; selected < 10; selected++)
		{
			List<BankPotionStock.Potion> potions = groups.get(selected);
			List<Widget> cells = sectionItems(items, selected, bank.size());
			if (potions == null)
			{
				if (!preset && !searching)
					placement.capture(client, selected, cells, drawn, settings);
				continue;
			}
			if (!preset && !searching && selected > 0 && cells.isEmpty())
				continue;
			int bottom = preset || searching ? sectionBottom(items, -1)
					: cells.stream().mapToInt(cell -> cell.getOriginalY() + 36).max().orElse(0);
			int filled = preset || searching ? 0 : cells.size() % 8;
			int firstRow = bottom - (filled > 0 ? 36 : 0);
			int freeSlots = filled == 0 ? 0 : 8 - filled;
			int extraRows = (Math.max(0, potions.size() - freeSlots) + 7) / 8;
			int height = extraRows * 36;
			for (Widget child : items.getDynamicChildren())
			{
				if (height > 0 && child != null && !child.isSelfHidden() && child.getOriginalY() >= bottom)
				{
					child.setOriginalY(child.getOriginalY() + height);
					child.revalidate();
				}
			}
			for (int i = 0; i < potions.size(); i++)
			{
				Widget widget = create(items, potions.get(i));
				widget.setOriginalX(51 + (filled + i) % 8 * 48);
				widget.setOriginalY(firstRow + (filled + i) / 8 * 36);
				widget.revalidate();
				cells.add(widget);
			}
			if (!preset && !searching)
				placement.capture(client, selected, cells, drawn, settings);
		}
		if (!groups.isEmpty())
		{
			int height = 0;
			for (Widget child : items.getDynamicChildren())
			{
				if (child != null && !child.isSelfHidden())
					height = Math.max(height, child.getOriginalY() + child.getHeight());
			}
			int argument = client.getIntStackSize() - 9;
			if (argument >= 0)
				client.getIntStack()[argument] = Math.max(client.getIntStack()[argument], height + 4);
		}
	}

	private List<Widget> sectionItems(Widget items, int tab, int bankSize)
	{
		int start = 0;
		int end = bankSize;
		for (int i = 1; i <= 9; i++)
		{
			int size = client.getVarbitValue(TABS[i - 1]);
			if (tab == i)
			{
				end = start + size;
				break;
			}
			start += size;
		}
		List<Widget> result = new ArrayList<>();
		for (int i = start; i < end; i++)
		{
			Widget cell = items.getChild(i);
			if (cell != null && !cell.isSelfHidden() && cell.getItemId() >= 0)
				result.add(cell);
		}
		return result;
	}

	private boolean alreadyShown(Widget items, int id)
	{
		for (Widget child : items.getDynamicChildren())
		{
			if (child != null && !child.isSelfHidden() && child.getItemId() == id && child.getItemQuantity() > 0)
				return true;
		}
		return false;
	}

	private int sectionBottom(Widget items, int section)
	{
		int start = 0;
		int end = items.getDynamicChildren().length;
		if (section > 0)
		{
			for (int i = 1; i <= 9; i++)
			{
				int size = client.getVarbitValue(TABS[i - 1]);
				if (i == section)
				{
					end = start + size;
					break;
				}
				start += size;
			}
		}
		else
			start = 0;
		int bottom = 0;
		Widget[] children = items.getDynamicChildren();
		for (int i = start; i < Math.min(end, children.length); i++)
		{
			Widget widget = children[i];
			if (widget != null && !widget.isSelfHidden() && widget.getItemId() >= 0)
				bottom = Math.max(bottom, widget.getOriginalY() + 36);
		}
		return bottom;
	}

	private Widget create(Widget items, BankPotionStock.Potion potion)
	{
		Widget widget = items.createChild(-1, WidgetType.GRAPHIC);
		widget.setOriginalWidth(36);
		widget.setOriginalHeight(32);
		widget.setItemId(potion.itemId);
		widget.setItemQuantity(potion.quantity);
		widget.setItemQuantityMode(ItemQuantityMode.STACKABLE);
		widget.setBorderType(1);
		widget.setName("<col=ff9040>" + client.getItemDefinition(potion.itemId).getName() + "</col> (storage)");
		int requested = client.getVarbitValue(VarbitID.BANK_REQUESTEDQUANTITY);
		String[] quantities = { "1", "5", "10", Integer.toString(Math.max(1, requested)), "All" };
		int selected = Math.max(0, Math.min(4, client.getVarbitValue(VarbitID.BANK_QUANTITY_TYPE)));
		String[] actions = { quantities[selected], "1", "5", "10", Integer.toString(requested), "X", "All",
				"All-but-1" };
		int mask = 0;
		for (int i = 0; i < actions.length; i++)
		{
			if (i == 1 && selected == 0 || i == 4 && requested <= 0)
				continue;
			widget.setAction(i, "Withdraw-" + actions[i]);
			mask |= WidgetConfig.transmitAction(i);
		}
		widget.setClickMask(mask | WidgetConfig.DRAG | WidgetConfig.DRAG_ON);
		widget.setDragParent(items);
		widget.setDragDeadTime(5);
		widget.setDragDeadZone(5);
		widget.setHasListener(true);
		drawn.put(widget, potion);
		return widget;
	}

	boolean validSource(Widget source)
	{
		BankPotionStock.Potion original = drawn.get(source);
		if (original == null)
		{
			if (!externalBank || source == null || source.isSelfHidden() || source.getItemQuantity() <= 0)
				return false;
			return stock.potions().stream().anyMatch(p -> p.itemId == source.getItemId() && p.quantity > 0);
		}
		return stock.potions().stream()
				.anyMatch(p -> p.enumId == original.enumId && p.itemId == original.itemId && p.quantity > 0);
	}

	void setMenuSource(java.util.function.Function<Widget, Widget> source)
	{
		menuSource = source;
	}

	@Subscribe(priority = 10)
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		MenuEntry menu = event.getMenuEntry();
		addStorageMenuEntry(menu);
		clicks.remove(menu);
		if (parent == null || menu.getParam1() != InterfaceID.Bankmain.ITEMS)
			return;
		Widget source = menuSource.apply(parent.getChild(menu.getParam0()));
		BankPotionStock.Potion potion = drawn.get(source);
		if (potion != null)
			clicks.put(menu, new Click(parent, source, potion, context()));
	}

	private void addStorageMenuEntry(MenuEntry entry)
	{
		if (!active || externalBank || entry.getParam1() != InterfaceID.Bankmain.POTIONSTORE_ITEMS
				|| entry.getParam0() < 0 || entry.getParam0() % 5 != 0 || entry.getIdentifier() != 1
				|| entry.getType() != MenuAction.CC_OP && entry.getType() != MenuAction.CC_OP_LOW_PRIORITY)
			return;
		Widget store = client.getWidget(InterfaceID.Bankmain.POTIONSTORE_ITEMS);
		BankPotionStock.Potion potion = stock.potions().stream()
				.filter(candidate -> candidate.index * 5 == entry.getParam0()).findFirst().orElse(null);
		if (potion == null || !storageRowCurrent(store, potion))
			return;
		boolean shown = settings.bankTab(potion.enumId) >= 0 && settings.search(potion.enumId);
		String option = shown ? "Remove potion from bank window" : "Add potion to bank window";
		for (MenuEntry existing : client.getMenuEntries())
			if (option.equals(existing.getOption()) && existing.getParam1() == entry.getParam1()
					&& existing.getParam0() == entry.getParam0())
				return;
		String expected = context();
		Widget row = store.getChild(entry.getParam0());
		client.createMenuEntry(0).setOption(option).setTarget(entry.getTarget())
				.setType(MenuAction.RUNELITE_LOW_PRIORITY).setParam0(entry.getParam0())
				.setParam1(entry.getParam1()).onClick(clicked ->
				{
					if (!active || externalBank || !expected.equals(context())
							|| row != store.getChild(potion.index * 5) || !storageRowCurrent(store, potion))
						return;
					if (shown)
					{
						settings.setBankTab(potion.enumId, -1);
						settings.setSearch(potion.enumId, false);
					}
					else
					{
						if (settings.bankTab(potion.enumId) < 0)
						{
							settings.setBankPosition(potion.enumId, -1);
							settings.setBankTab(potion.enumId, 0);
						}
						settings.setSearch(potion.enumId, true);
					}
				});
	}

	private boolean storageRowCurrent(Widget store, BankPotionStock.Potion potion)
	{
		if (store == null || store.isHidden() || client.getWidget(InterfaceID.Bankmain.POTIONSTORE_ITEMS) != store)
			return false;
		Widget row = store.getChild(potion.index * 5);
		Widget icon = store.getChild(potion.index * 5 + 1);
		return row != null && !row.isSelfHidden() && icon != null && potion.variants.contains(icon.getItemId())
				&& stock.potions().stream().anyMatch(current -> current.enumId == potion.enumId
						&& current.index == potion.index && current.quantity > 0);
	}

	@Subscribe(priority = 10)
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event.isConsumed() || event.getParam1() != InterfaceID.Bankmain.ITEMS
				|| event.getMenuAction() != MenuAction.CC_OP && event.getMenuAction() != MenuAction.CC_OP_LOW_PRIORITY)
			return;
		Click click = clicks.get(event.getMenuEntry());
		if (click == null)
			return;
		Widget source = click.source;
		BankPotionStock.Potion potion = click.potion;
		if (!Objects.equals(click.context, context()) || parent != click.parent
				|| client.getWidget(InterfaceID.Bankmain.ITEMS) != parent
				|| parent.getChild(event.getParam0()) != source || source.isSelfHidden() || !validSource(source)
				|| event.getItemId() > 0 && event.getItemId() != potion.itemId || event.getId() < 1
				|| event.getId() > 8)
		{
			event.consume();
			return;
		}
		Widget store = client.getWidget(InterfaceID.Bankmain.POTIONSTORE_ITEMS);
		if (store == null)
		{
			event.consume();
			return;
		}
		int index = potion.index * 5;
		if (store.getChild(index) == null)
		{
			int count = store.getChildren() == null ? 0 : store.getChildren().length;
			for (int i = count; i <= index; i++)
				store.createChild(i, WidgetType.GRAPHIC);
		}
		MenuEntry menu = event.getMenuEntry();
		menu.setParam1(InterfaceID.Bankmain.POTIONSTORE_ITEMS);
		menu.setParam0(index);
	}

	@Subscribe(priority = -25)
	public void onWidgetDrag(WidgetDrag event)
	{
		Widget items = parent;
		Widget source = client.getDraggedWidget();
		Widget target = client.getDraggedOnWidget();
		String expected = context();
		if (items != null && !searchView.isActive())
			placement.drag(client, items, drawn, settings,
					() -> active && expected.equals(context()) && parent == items
							&& client.getWidget(InterfaceID.Bankmain.ITEMS) == items && !externalBank
							&& !searchView.isActive() && searchView.bankTags.getActiveBankTag() == null
							&& client.getGameState() == GameState.LOGGED_IN
							&& (!drawn.containsKey(source) || validSource(source))
							&& (!drawn.containsKey(target) || validSource(target)));
		else if (drawn.containsKey(source) || drawn.containsKey(client.getDraggedOnWidget()))
			client.setDraggedOnWidget(null);
	}

	private void clearWidgets()
	{
		placement.clear();
		if (parent != null && parent.getChildren() != null)
		{
			Widget[] children = parent.getChildren().clone();
			int size = children.length;
			while (size > 0 && drawn.containsKey(children[size - 1]))
				size--;
			for (int i = 0; i < children.length; i++)
			{
				if (drawn.containsKey(children[i]))
				{
					children[i].setHidden(true);
					children[i] = null;
				}
			}
			parent.setChildren(Arrays.copyOf(children, size));
		}
		drawn.clear();
		parent = null;
	}
}

package com.windowmarkers;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.nio.charset.StandardCharsets;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.UUID;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;

final class BankPresetPositions
{
	@Inject
	ConfigManager configs;
	@Inject
	Gson gson;

	static final class Layout
	{
		Map<String, int[]> cells = new LinkedHashMap<>();
	}

	String key(String view)
	{
		if (configs == null || configs.getProfile() == null || view == null)
			return null;
		return "presetPositions_" + configs.getProfile().getId() + "_v2_"
				+ UUID.nameUUIDFromBytes(view.getBytes(StandardCharsets.UTF_8));
	}

	Layout read(String account, String view, int width)
	{
		String shared = key(view);
		if (account != null && shared != null && configs.getConfiguration("windowmarkers", account, shared) != null)
			return read(account, shared);
		return read(account, key(view, width));
	}

	String key(String view, int width)
	{
		if (configs == null || configs.getProfile() == null || view == null)
			return null;
		return "presetPositions_" + configs.getProfile().getId() + "_"
				+ UUID.nameUUIDFromBytes((view + "/" + width).getBytes(StandardCharsets.UTF_8));
	}

	Layout read(String account, String key)
	{
		Layout result = null;
		if (account != null && key != null)
		{
			String raw = configs.getConfiguration("windowmarkers", account, key);
			try
			{
				result = raw == null ? null : gson.fromJson(raw, Layout.class);
			}
			catch (JsonParseException ignored)
			{
			}
		}
		if (result == null)
			result = new Layout();
		if (result.cells == null || result.cells.size() > 4000)
			result.cells = new LinkedHashMap<>();
		result.cells.entrySet().removeIf(e -> e.getKey() == null || e.getValue() == null || e.getValue().length != 2
				|| e.getValue()[0] < 0 || e.getValue()[0] > 4000 || e.getValue()[1] < 0 || e.getValue()[1] > 50000);
		return result;
	}

	void save(String account, String key, Layout layout)
	{
		if (account != null && key != null && configs.getProfile() != null
				&& key.startsWith("presetPositions_" + configs.getProfile().getId() + "_")
				&& account.equals(configs.getRSProfileKey()))
			configs.setConfiguration("windowmarkers", account, key, gson.toJson(layout));
	}
}

package com.windowmarkers;

import java.awt.Component;
import java.util.*;
import java.util.List;
import javax.swing.*;

final class BankPresetReview
{
	private final JPanel panel = new MarkerForm();
	private final JCheckBox includeGrouped, showView;
	private final Map<JCheckBox, Marker> replacements = new LinkedHashMap<>();
	private final Map<JCheckBox, List<AutoCategories.Item>> choices = new LinkedHashMap<>();
	private final Map<String, List<AutoCategories.Item>> groups;
	private final AutoCategories.Preset preset;
	private final ActivitySetups.Setup setup;

	BankPresetReview(Map<String, List<AutoCategories.Item>> groups, AutoCategories.Preset preset,
			Map<Integer, String> exclusions, ActivitySetups.Setup setup, boolean explicitCategory, boolean slotView,
			boolean requestedView)
	{
		this.groups = groups;
		this.preset = preset;
		this.setup = setup;
		panel.add(new JLabel(
				"<html>Wiki classifications describe uses, not one combined loadout.<br>Outfit groups include owned pieces; partial ownership does<br>not activate a full-set bonus. Tools are grouped separately.<br>Raid lists depend on role, spellbook, charges and invocations.<br>Unresolved items stay in an unchecked review group.</html>"));
		if (setup != null && !setup.notes.isEmpty())
		{
			JTextArea notes = new JTextArea(setup.notes);
			notes.setEditable(false);
			notes.setLineWrap(true);
			notes.setWrapStyleWord(true);
			notes.setColumns(42);
			panel.add(notes);
		}
		if (!exclusions.isEmpty())
		{
			JTextArea excluded = new JTextArea("Excluded lower-tier items:\n" + String.join("\n", exclusions.values()));
			excluded.setEditable(false);
			excluded.setLineWrap(true);
			excluded.setWrapStyleWord(true);
			excluded.setColumns(42);
			panel.add(excluded);
		}
		JButton source = new JButton("Open Wiki source");
		source.addActionListener(e -> net.runelite.client.util.LinkBrowser
				.browse(setup == null ? WikiCatalogue.source(preset) : setup.source));
		panel.add(source);
		includeGrouped = new JCheckBox("Include items already in other groups", explicitCategory);
		panel.add(includeGrouped);
		showView = new JCheckBox("Show selected groups as a temporary bank view", requestedView || slotView);
		panel.add(showView);
		if (slotView)
			panel.add(new JLabel(
					"<html>View groups equipment by slot, then tools and supplies.<br>Save it from the bank dropdown. Your bank order stays unchanged.</html>"));
		panel.add(new JLabel(
				"<html>Including grouped items keeps their existing groups too.<br>To replace old groups instead, check their names below.<br>Replacing removes the entire checked marker. Undo restores it.</html>"));
	}

	void addExistingMarkers(List<Marker> markers)
	{
		for (Marker marker : markers)
		{
			if (!marker.linked())
			{
				continue;
			}
			JCheckBox replace = new JCheckBox("Replace: " + marker.labelText(), false);
			replacements.put(replace, marker);
			panel.add(replace);
		}
	}

	boolean show(Component parent)
	{
		for (java.util.Map.Entry<String, List<AutoCategories.Item>> entry : groups.entrySet())
		{
			JCheckBox choose = new JCheckBox(entry.getKey(), RaidRecommendations.defaultSelected(entry.getKey()));
			choices.put(choose, entry.getValue());
			panel.add(choose);
			JTextArea items = new JTextArea(
					entry.getValue().stream().map(i -> i.name).collect(java.util.stream.Collectors.joining(", ")));
			items.setLineWrap(true);
			items.setWrapStyleWord(true);
			items.setEditable(false);
			items.setColumns(42);
			items.setBackground(panel.getBackground());
			panel.add(items);
		}

		return MarkerDialogs.confirm(parent, panel,
				"Review " + (setup == null ? preset : setup.activity + " — " + setup.label), 620, 620);
	}

	Map<String, List<AutoCategories.Item>> selectedGroups()
	{
		Map<String, List<AutoCategories.Item>> selected = new LinkedHashMap<>();
		choices.forEach((box, items) ->
		{
			if (box.isSelected())
				selected.put(box.getText(), items);
		});
		return selected;
	}

	List<Marker> replacedMarkers()
	{
		List<Marker> selected = new ArrayList<>();
		replacements.forEach((box, marker) ->
		{
			if (box.isSelected())
				selected.add(marker);
		});
		return selected;
	}

	boolean includeGrouped()
	{
		return includeGrouped.isSelected();
	}

	boolean showView()
	{
		return showView.isSelected();
	}
}

package com.windowmarkers;

import java.awt.Rectangle;
import java.util.Arrays;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.api.gameval.InterfaceID;

final class BankScreenshotButton
{
	@Inject
	Client client;
	private Widget button, parent;

	Widget widget()
	{
		return button;
	}

	void update(boolean enabled, Runnable capture)
	{
		Widget frame = client.getWidget(InterfaceID.Bankmain.FRAME);
		Widget close = findClose(frame);
		if (!enabled || frame == null || frame.isHidden() || close == null)
		{
			if (button != null)
			{
				button.setHidden(true);
			}
			return;
		}
		Widget[] children = frame.getChildren();
		if (parent != frame || button == null || children == null || !Arrays.asList(children).contains(button))
		{
			clear();
			parent = frame;
			button = frame.createChild(-1, WidgetType.GRAPHIC);
			button.setOriginalWidth(20);
			button.setOriginalHeight(20);
			button.setSpriteId(573);
			button.setAction(0, "Save bank screenshot");
			button.setOnOpListener((JavaScriptCallback) e -> capture.run());
			button.setHasListener(true);
		}
		Rectangle position = position(frame.getBounds(), close.getBounds());
		if (position == null)
		{
			button.setHidden(true);
			return;
		}
		button.setOriginalX(position.x);
		button.setOriginalY(position.y);
		button.setHidden(false);
		button.revalidate();
	}

	static Rectangle position(Rectangle frame, Rectangle close)
	{
		Rectangle result = new Rectangle(close.x - frame.x - 24, close.y - frame.y + (close.height - 20) / 2, 20, 20);
		return new Rectangle(0, 0, frame.width, frame.height).contains(result) ? result : null;
	}

	private static Widget findClose(Widget frame)
	{
		if (frame == null || frame.getChildren() == null)
		{
			return null;
		}
		for (Widget child : frame.getChildren())
		{
			if (child == null || child.isHidden() || child.getActions() == null)
			{
				continue;
			}
			for (String action : child.getActions())
			{
				if ("Close".equalsIgnoreCase(action))
				{
					return child;
				}
			}
		}
		return null;
	}

	void clear()
	{
		if (button != null)
		{
			button.setHidden(true);
			button.clearActions();
			button.setOnOpListener((Object[]) null);
			button.setHasListener(false);
		}
		button = null;
		parent = null;
	}
}

package com.windowmarkers;

import java.util.*;

final class BankSearchIndex
{
	private final Map<String, Set<Integer>> documents = new LinkedHashMap<>();
	private final Map<String, Set<Integer>> customDocuments = new LinkedHashMap<>();
	private final ItemCatalogueIndex catalogue;
	private final int hitpoints;
	private final BankCleanup cleanup;
	private final Map<String, Map<Integer, ItemCatalogueIndex.Rank>> markerRanks = new HashMap<>();
	private List<String> lastKeys = Collections.emptyList();
	private List<int[]> lastMembers = Collections.emptyList();
	private Map<Integer, ItemCatalogueIndex.Rank> lastRanks = Collections.emptyMap();
	private final Set<String> activities = new HashSet<>(), ordinaryNames = new HashSet<>();

	BankSearchIndex(List<AutoCategories.Item> owned, List<Marker> markers, CustomPresets presets)
	{
		this(owned, markers, presets, 99);
	}

	BankSearchIndex(List<AutoCategories.Item> owned, List<Marker> markers, CustomPresets presets, int hitpoints)
	{
		this(owned, markers, presets, hitpoints, Collections.emptySet(), BankCleanup.Progress.unknown());
	}

	BankSearchIndex(List<AutoCategories.Item> owned, List<Marker> markers, CustomPresets presets, int hitpoints,
			Set<Integer> tradeable, BankCleanup.Progress progress)
	{
		this(owned, markers, presets, hitpoints, tradeable, progress, SetupPlayerState.unknown());
	}

	BankSearchIndex(List<AutoCategories.Item> owned, List<Marker> markers, CustomPresets presets, int hitpoints,
			Set<Integer> tradeable, BankCleanup.Progress progress, SetupPlayerState playerState)
	{
		this.hitpoints = Math.max(1, Math.min(99, hitpoints));
		cleanup = new BankCleanup(owned, tradeable, progress);
		List<ItemCatalogueIndex.Item> facts = new ArrayList<>();
		for (AutoCategories.Item item : owned)
			facts.add(new ItemCatalogueIndex.Item(item, item.name,
					item.slot == -2 ? ItemCatalogueIndex.fallbackSlot(item.id, item.name) : item.slot));
		catalogue = new ItemCatalogueIndex(facts, false, playerState);
		Set<Integer> ids = new HashSet<>();
		for (AutoCategories.Item item : owned)
		{
			ids.add(item.id);
			add(item.name, item.id);
			ordinaryNames.add(SearchText.normalize(item.name));
			if (!ItemVariantState.identityNeedsReview(item))
				for (WikiCatalogue.Entry entry : WikiCatalogue.entries(item))
					add(ItemVariantState.annotate(entry.group, item), item.id);
		}
		for (AutoCategories.Preset preset : AutoCategories.Preset.values())
		{
			if (SetupItemLayout.activityPreset(preset))
				activity(preset.toString());
			for (int id : catalogue.presetIds(preset))
				add(preset.toString(), id);
		}
		catalogue.categoryDocuments().forEach((name, items) ->
		{
			for (int id : items)
				add(name, id);
		});
		for (ActivitySetups.Setup setup : ActivitySetups.all())
		{
			activity(setup.activity);
			activity(setup.activity + " — " + setup.label);
			for (int id : setup.itemIds)
				if (ids.contains(id))
					add(setup.activity + " — " + setup.label, id);
		}
		for (Marker marker : markers)
			if (marker.linked())
				for (int id : marker.linkedItemIds)
					if (ids.contains(id))
						addCustom(marker.labelText(), id);
		for (CustomPresets.Preset preset : presets.presets)
			for (Marker marker : preset.groups)
				if (marker.linked())
					for (int id : marker.linkedItemIds)
						if (ids.contains(id))
						{
							addCustom(preset.name, id);
							addCustom(marker.labelText(), id);
						}
		for (CustomPresets.Preset preset : presets.presets)
			if (preset.groupBySlot)
				activity(preset.name);
		ordinaryNames.addAll(Arrays.asList("food", "potions", "weapons", "armour", "armor", "equipment", "resources",
				"tools", "capes", "head", "farming", "fishing", "mining", "woodcutting"));
		for (net.runelite.api.Skill skill : net.runelite.api.Skill.values())
			ordinaryNames.add(SearchText.normalize(skill.getName()));
		for (Marker marker : markers)
			indexRank(marker);
		for (CustomPresets.Preset preset : presets.presets)
			for (Marker marker : preset.groups)
				indexRank(marker);
	}

	private void addCustom(String text, int id)
	{
		add(text, id);
		customDocuments.computeIfAbsent(SearchText.normalize(text), k -> new HashSet<>()).add(id);
	}

	private void indexRank(Marker marker)
	{
		if (marker.guideQuery != null && !marker.guideQuery.isEmpty())
			markerRanks.computeIfAbsent(marker.rankKey(),
					key -> BankCleanup.isQuery(marker.guideQuery) ? cleanup.search(marker.guideQuery).ranks
							: catalogue.guideRanks(marker.guideQuery,
									marker.guideContext == null ? "" : marker.guideContext, hitpoints));
	}

	Map<Integer, ItemCatalogueIndex.Rank> ranks(List<Marker> groups)
	{
		boolean same = groups.size() == lastKeys.size();
		for (int i = 0; same && i < groups.size(); i++)
			same = groups.get(i).rankKey().equals(lastKeys.get(i)) && groups.get(i).linkedItemIds == lastMembers.get(i);
		if (same)
			return lastRanks;
		Map<Integer, ItemCatalogueIndex.Rank> result = new HashMap<>();
		for (Marker marker : groups)
			if (marker.linked())
			{

				if (BankCleanup.isQuery(marker.guideQuery))
					indexRank(marker);
				Map<Integer, ItemCatalogueIndex.Rank> ranks = markerRanks.getOrDefault(marker.rankKey(),
						Collections.emptyMap());
				for (int id : marker.linkedItemIds)
					if (ranks.containsKey(id))
						result.merge(id, ranks.get(id), TierPresentation::merge);
			}
		lastKeys = new ArrayList<>();
		lastMembers = new ArrayList<>();
		for (Marker group : groups)
		{
			lastKeys.add(group.rankKey());
			lastMembers.add(group.linkedItemIds);
		}
		lastRanks = Collections.unmodifiableMap(result);
		return lastRanks;
	}

	static final class Match
	{
		final Set<Integer> ids;
		final Map<Integer, ItemCatalogueIndex.Rank> ranks;
		final boolean slots;
		final SetupLoadout loadout;

		Match(Set<Integer> ids, Map<Integer, ItemCatalogueIndex.Rank> ranks, boolean slots)
		{
			this(ids, ranks, slots, null);
		}

		Match(Set<Integer> ids, Map<Integer, ItemCatalogueIndex.Rank> ranks, boolean slots, SetupLoadout loadout)
		{
			this.ids = ids;
			this.ranks = ranks;
			this.slots = slots;
			this.loadout = loadout;
		}
	}

	private void activity(String name)
	{
		activities.add(SearchText.normalize(name));
		String alias = BankCatalogue.aliases(name);
		if (!alias.isEmpty())
			activities.add(alias);
	}

	boolean groupBySlot(String query)
	{
		String normalized = SearchText.normalize(query);
		if (normalized.length() < 3 || ordinaryNames.contains(normalized) || !plainQuery(query))
			return false;

		return activities.stream().anyMatch(name -> name.equals(normalized) || name.startsWith(normalized + " "));
	}

	private void add(String text, int id)
	{
		String key = SearchText.normalize(text + " " + BankCatalogue.aliases(text));
		if (!key.isEmpty())
			documents.computeIfAbsent(key, k -> new HashSet<>()).add(id);
	}

	static boolean plainQuery(String query)
	{
		return query != null && !query.trim().isEmpty() && !query.matches(".*[:<>=!|&].*");
	}

	Set<Integer> find(String query)
	{
		return search(query, "").ids;
	}

	Match search(String query, String context)
	{
		return search(query, context, "");
	}

	Match search(String query, String context, String inventoryContext)
	{
		return search(query, context, inventoryContext, hitpoints);
	}

	Match search(String query, String context, String inventoryContext, int hitpoints)
	{
		Set<Integer> result = new HashSet<>();
		if (!plainQuery(query))
			return new Match(result, Collections.emptyMap(), false);
		Match review = cleanup.search(query);
		if (review != null)
			return review;
		String normalized = SearchText.normalize(query);
		ItemCatalogueIndex.Result common = catalogue.find(query, context, inventoryContext, hitpoints);
		if (common != null)
			for (ItemCatalogueIndex.Item item : common.items)
				result.add(item.id);

		if (common != null && SupplySearch.parse(query) != null)
			return new Match(result, common.ranks, false);
		Map<String, Set<Integer>> extra = common == null ? documents : customDocuments;
		boolean exact = extra.keySet().stream().anyMatch(t -> t.contains(normalized));
		for (Map.Entry<String, Set<Integer>> entry : extra.entrySet())
			if (entry.getKey().contains(normalized) || (!exact && normalized.length() >= 3
					&& SearchText.normalizedScore(entry.getKey(), normalized) != Integer.MAX_VALUE))
				result.addAll(entry.getValue());
		SearchQuery qualifiers = SearchQuery.parse(query);
		if (common != null && !qualifiers.tiers.isEmpty())
			result.removeIf(id -> !qualifiers.accepts(common.ranks.get(id)));
		return new Match(result, common == null ? Collections.emptyMap() : common.ranks,
				common != null && common.activity || groupBySlot(query), common == null ? null : common.loadout);
	}
}

package com.windowmarkers;

import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.banktags.BankTag;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;

@Singleton
final class BankSearchView
{
	@Inject
	net.runelite.api.Client client;
	@Inject
	BankTagsService bankTags;
	@Inject
	net.runelite.client.plugins.PluginManager plugins;
	static final String BANK_TAGS_REQUIRED = "Enable Bank Tags in RuneLite to use preset views.";

	boolean available()
	{
		return plugins.getPlugins().stream().anyMatch(
				p -> p instanceof net.runelite.client.plugins.banktags.BankTagsPlugin && plugins.isPluginActive(p));
	}

	@Inject
	TagManager tags;
	@Inject
	ItemManager items;
	@Inject
	net.runelite.client.callback.ClientThread clientThread;
	private final String tagName = "improved banking " + UUID.randomUUID();
	private BankTag tag;
	private String name;
	private String layoutIdentity;

	String layoutIdentity()
	{
		return isActive() ? layoutIdentity : null;
	}

	private boolean slots;
	private boolean reopen, reopenQueued;
	private SetupLoadout loadout;
	private Marker highlight;

	Marker highlight()
	{
		return isActive() ? highlight : null;
	}

	private Map<Integer, ItemCatalogueIndex.Rank> ranks = Collections.emptyMap();

	SetupLoadout loadout()
	{
		return isActive() ? loadout : null;
	}

	Map<Integer, ItemCatalogueIndex.Rank> ranks()
	{
		return isActive() ? ranks : Collections.emptyMap();
	}

	private List<Marker> groups = Collections.emptyList();

	boolean show(String name, List<Marker> groups, boolean slots)
	{
		return show(name, groups, slots, null, Collections.emptyMap());
	}

	boolean show(String name, List<Marker> groups, boolean slots, SetupLoadout loadout,
			Map<Integer, ItemCatalogueIndex.Rank> ranks)
	{
		return show(name, groups, slots, loadout, ranks, "saved:" + name);
	}

	boolean show(String name, List<Marker> groups, boolean slots, SetupLoadout loadout,
			Map<Integer, ItemCatalogueIndex.Rank> ranks, String layoutIdentity)
	{
		if (!available())
			return false;
		clear();
		this.loadout = loadout;
		this.ranks = ranks;
		this.name = name;
		this.groups = new ArrayList<>(groups);
		this.slots = slots;
		this.layoutIdentity = layoutIdentity;
		Set<Integer> ids = new HashSet<>();
		for (Marker group : groups)
			if (group.linked())
				for (int id : group.linkedItemIds)
					ids.add(id);
		if (ids.isEmpty() && (loadout == null || !loadout.hasExamples()))
		{
			this.groups = Collections.emptyList();
			return false;
		}
		if (loadout != null && !ids.isEmpty())
		{
			highlight = new Marker(0, 0, 48, 36);
			highlight.scrollWithItems = true;
			highlight.linkedItemIds = ids.stream().mapToInt(Integer::intValue).toArray();
		}

		ids.addAll(InventoryPotionDoses.alternatives(new ArrayList<>(ids)));
		Set<Integer> canonical = new HashSet<>();
		for (int id : ids)
			canonical.add(items.canonicalize(id));
		tag = id -> ids.contains(id) || canonical.contains(items.canonicalize(id));
		tags.registerTag(tagName, tag);
		bankTags.openBankTag(tagName, BankTagsService.OPTION_NO_LAYOUT | BankTagsService.OPTION_HIDE_TAG_NAME);
		return true;
	}

	private boolean ownsTag()
	{
		return tag != null && tagName.equals(bankTags.getActiveTag());
	}

	boolean isActive()
	{
		return ownsTag() && available();
	}

	void filter(net.runelite.api.events.ScriptCallbackEvent event)
	{
		if (!"bankSearchFilter".equals(event.getEventName()) || !isActive()
				|| client.getWidget(net.runelite.api.gameval.InterfaceID.Bankmain.ITEMS) == null
				|| client.getVarcIntValue(
						net.runelite.api.gameval.VarClientID.MESLAYERMODE) == net.runelite.api.vars.InputType.SEARCH
								.getType())
			return;
		int size = client.getIntStackSize();
		if (size < 2)
			return;
		int[] stack = client.getIntStack();
		if (stack[size - 1] < 0)
			return;

		stack[size - 2] = tag.contains(stack[size - 1]) ? 1 : 0;
	}

	boolean bySlot()
	{
		return slots;
	}

	String name()
	{
		return name;
	}

	List<Marker> groups()
	{
		return isActive() ? new ArrayList<>(groups) : Collections.emptyList();
	}

	java.util.function.BooleanSupplier unchangedContext()
	{
		var bank = client.getWidget(net.runelite.api.gameval.InterfaceID.Bankmain.UNIVERSE);
		if (!available() || client.getGameState() != net.runelite.api.GameState.LOGGED_IN || bank == null
				|| bank.isHidden())
			return () -> false;
		String activeName = bankTags.getActiveTag();
		BankTag activeTag = bankTags.getActiveBankTag();
		int nativeTab = client.getVarbitValue(net.runelite.api.gameval.VarbitID.BANK_CURRENTTAB);
		int inputMode = client.getVarcIntValue(net.runelite.api.gameval.VarClientID.MESLAYERMODE);
		String input = client.getVarcStrValue(net.runelite.api.gameval.VarClientID.MESLAYERINPUT);
		return () -> available() && client.getGameState() == net.runelite.api.GameState.LOGGED_IN && bank != null
				&& !bank.isHidden() && client.getWidget(net.runelite.api.gameval.InterfaceID.Bankmain.UNIVERSE) == bank
				&& nativeTab == client.getVarbitValue(net.runelite.api.gameval.VarbitID.BANK_CURRENTTAB)
				&& Objects.equals(activeName, bankTags.getActiveTag()) && activeTag == bankTags.getActiveBankTag()
				&& inputMode == client.getVarcIntValue(net.runelite.api.gameval.VarClientID.MESLAYERMODE)
				&& Objects.equals(input, client.getVarcStrValue(net.runelite.api.gameval.VarClientID.MESLAYERINPUT));
	}

	void bankClosed()
	{
		if (isActive())
			reopen = true;
		else if (!reopen)
			forget();
	}

	private boolean bankOpen()
	{
		var bank = client.getWidget(net.runelite.api.gameval.InterfaceID.Bankmain.UNIVERSE);
		return bank != null && !bank.isHidden();
	}

	private boolean canReopen()
	{
		String active = bankTags.getActiveTag();
		return (active == null || tagName.equals(active))
				&& client.getVarbitValue(net.runelite.api.gameval.VarbitID.BANK_CURRENTTAB) == 0
				&& client.getVarcIntValue(
						net.runelite.api.gameval.VarClientID.MESLAYERMODE) != net.runelite.api.vars.InputType.SEARCH
								.getType();
	}

	void update()
	{
		if (tag == null || !available() || !bankOpen())
			return;
		if (reopen)
		{
			if (!canReopen())
			{
				forget();
				return;
			}
			if (!reopenQueued)
			{
				reopenQueued = true;
				BankTag expected = tag;
				var unchanged = unchangedContext();

				clientThread.invokeLater(() ->
				{
					if (tag != expected)
						return;
					reopenQueued = false;
					if (!bankOpen())
						return;
					if (!unchanged.getAsBoolean() || !canReopen())
					{
						forget();
						return;
					}
					reopen = false;
					bankTags.openBankTag(tagName,
							BankTagsService.OPTION_NO_LAYOUT | BankTagsService.OPTION_HIDE_TAG_NAME);
				});
			}
			return;
		}
		if (tag != null && !isActive())
			forget();
		if (isActive())
		{
			var title = client.getWidget(net.runelite.api.gameval.InterfaceID.Bankmain.TITLE);
			if (title != null)
				title.setText("Bank view: "
						+ name.replace('<', ' ').replace('>', ' ').substring(0, Math.min(48, name.length()))
						+ (loadout != null && loadout.notEnoughGear() ? " - not enough gear in bank" : ""));
		}
	}

	void clear()
	{
		if (ownsTag() || tag != null && reopen && bankTags.getActiveTag() == null)
		{
			bankTags.closeBankTag();
		}
		forget();
	}

	private void forget()
	{
		if (tag != null)
			tags.unregisterTag(tagName);
		tag = null;
		name = null;
		slots = false;
		reopen = false;
		reopenQueued = false;
		loadout = null;
		highlight = null;
		ranks = Collections.emptyMap();
		groups = Collections.emptyList();
	}
}

package com.windowmarkers;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;

final class BankSharedTagRail
{
	private final BankActionBar owner;
	private final Map<Widget, Object[]> originalOps = new IdentityHashMap<>(), appliedOps = new IdentityHashMap<>();
	private Widget parent;
	private int offset, count, capacity;
	Rectangle wheelArea;

	BankSharedTagRail(BankActionBar owner)
	{
		this.owner = owner;
	}

	void apply(Widget container, int tagTop)
	{
		if (parent != container)
		{
			restore();
			parent = container;
			offset = 0;
		}
		Widget[] children = container.getDynamicChildren();
		if (children == null)
			return;
		Widget up = null, down = null, scroll = null;
		List<Widget[]> tabs = new ArrayList<>();
		for (int i = 0; i < children.length; i++)
		{
			Widget w = children[i];
			if (w == null)
				continue;
			List<String> actions = w.getActions() == null ? java.util.Collections.emptyList()
					: Arrays.asList(w.getActions());
			if (actions.contains("Scroll up"))
				up = w;
			else if (actions.contains("Scroll down"))
				down = w;
			else if (actions.contains("View tag tab"))
			{
				Widget icon = i + 1 < children.length ? children[i + 1] : null;
				if (icon == null || icon.getItemId() < 0 || icon.getOriginalX() != 4)
					icon = null;
				tabs.add(new Widget[] { w, icon });
			}
			else if (w.getNoScrollThrough() && w.getOriginalX() <= 3 && w.getWidth() <= 43)
				scroll = w;
		}
		if (up == null || down == null)
		{
			wheelArea = null;
			return;
		}
		int divider = tagTop - 5;
		int top = 41, tabTop = top + up.getHeight() + 1;
		capacity = Math.max(0, (divider - down.getHeight() - tabTop) / 41);
		count = tabs.size();
		offset = Math.max(0, Math.min(offset, Math.max(0, count - Math.max(1, capacity))));
		Rectangle area = BankWidgetGeometry.bounds(container);
		wheelArea = new Rectangle(area.x, area.y + top, 50, Math.max(0, divider - top));
		owner.move(up, area.x + 1, area.y + top);
		owner.move(down, area.x + 1, area.y + divider - down.getHeight());
		replace(up, -1);
		replace(down, 1);
		if (scroll != null)
			owner.visibility(scroll, true);
		for (int i = 0; i < tabs.size(); i++)
		{
			Widget[] pair = tabs.get(i);
			boolean shown = i >= offset && i < offset + capacity;
			owner.visibility(pair[0], !shown);
			if (pair[1] != null)
				owner.visibility(pair[1], !shown);
			if (shown)
			{
				int y = area.y + tabTop + (i - offset) * 41;
				owner.move(pair[0], area.x + 1, y);
				if (pair[1] != null)
					owner.move(pair[1], area.x + 4, y + 4);
			}
		}
	}

	void scroll(int delta)
	{
		offset = (int) Math.max(0, Math.min(Math.max(0, count - Math.max(1, capacity)), (long) offset + delta));
	}

	private void replace(Widget button, int delta)
	{
		Object[] callback = { (JavaScriptCallback) e ->
		{
			if (owner.enabled())
				scroll(delta);
		} };
		if (!originalOps.containsKey(button) || !Arrays.equals(button.getOnOpListener(), appliedOps.get(button)))
			originalOps.put(button, button.getOnOpListener());
		appliedOps.put(button, callback);
		button.setOnOpListener(callback);
	}

	void beforeFrame()
	{
		originalOps.forEach((w, ops) ->
		{
			if (Arrays.equals(w.getOnOpListener(), appliedOps.get(w)))
				w.setOnOpListener(ops);
		});
		originalOps.clear();
		appliedOps.clear();
		wheelArea = null;
	}

	void restore()
	{
		beforeFrame();
		parent = null;
		offset = 0;
		count = capacity = 0;
	}
}

