final class CatalogueBrowser
{
	static BankCatalogue.Choice choose(Component parent, List<BankCatalogue.Choice> choices, String initial)
	{
		JPanel panel = new JPanel(new BorderLayout(0, 8));
		JTextField search = new JTextField(initial);
		java.util.List<BankCatalogue.Kind> kinds = new java.util.ArrayList<>();
		kinds.add(null);
		JComboBox<String> kind = new JComboBox<>();
		kind.addItem("Everything");
		for (BankCatalogue.Kind value : BankCatalogue.Kind.values())
			if (choices.stream().anyMatch(c -> c.kind == value))
			{
				kinds.add(value);
				kind.addItem(value.toString().toLowerCase(java.util.Locale.ROOT).replace('_', ' '));
			}
		JPanel top = new JPanel(new BorderLayout(6, 0));
		top.add(search, BorderLayout.CENTER);
		top.add(kind, BorderLayout.EAST);
		panel.add(top, BorderLayout.NORTH);
		DefaultListModel<BankCatalogue.Choice> rows = new DefaultListModel<>();
		JList<BankCatalogue.Choice> list = new JList<>(rows);
		list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		list.setVisibleRowCount(14);
		boolean[] chosen = { false };
		Runnable activate = () ->
		{
			if (list.getSelectedValue() == null)
				return;
			chosen[0] = true;
			Window window = SwingUtilities.getWindowAncestor(panel);
			if (window instanceof JDialog)
				window.dispose();
		};
		list.addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseClicked(java.awt.event.MouseEvent e)
			{
				int index = list.locationToIndex(e.getPoint());
				if (e.getClickCount() == 2 && index >= 0 && list.getCellBounds(index, index).contains(e.getPoint()))
					activate.run();
			}
		});
		list.getInputMap().put(KeyStroke.getKeyStroke("ENTER"), "choose");
		list.getActionMap().put("choose", new AbstractAction()
		{
			public void actionPerformed(java.awt.event.ActionEvent e)
			{
				activate.run();
			}
		});
		list.addListSelectionListener(e ->
		{
			BankCatalogue.Choice value = list.getSelectedValue();
			list.setToolTipText(value == null ? null : value.name);
		});
		panel.add(new JScrollPane(list), BorderLayout.CENTER);
		JPanel footer = new MarkerForm();
		footer.add(new JLabel(
				"<html>Type to search; approximate spellings and CoX/ToB/ToA work.<br>Choose a result to continue.<br>Manage saved views in Legend → Saved views.</html>"));
		panel.add(footer, BorderLayout.SOUTH);
		Runnable refresh = () ->
		{
			rows.clear();
			int selectedKind = kind.getSelectedIndex();
			List<BankCatalogue.Choice> filtered = new java.util.ArrayList<>();
			for (BankCatalogue.Choice choice : choices)
				if (selectedKind == 0 || choice.kind == kinds.get(selectedKind))
					filtered.add(choice);
			for (BankCatalogue.Choice choice : BankCatalogue.search(filtered, search.getText(), filtered.size()))
				rows.addElement(choice);
		};
		javax.swing.Timer timer = new javax.swing.Timer(150, e -> refresh.run());
		timer.setRepeats(false);
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			public void insertUpdate(DocumentEvent e)
			{
				timer.restart();
			}

			public void removeUpdate(DocumentEvent e)
			{
				timer.restart();
			}

			public void changedUpdate(DocumentEvent e)
			{
				timer.restart();
			}
		});
		kind.addActionListener(e -> refresh.run());
		refresh.run();
		try
		{
			boolean accepted = MarkerDialogs.confirm(parent, panel, "Activities and saved views", 760, 540);
			return accepted || chosen[0] ? list.getSelectedValue() : null;
		}
		finally
		{
			timer.stop();
		}
	}
}

package com.windowmarkers;

import javax.swing.SwingWorker;

final class CatalogueWorkQueue
{
	private SwingWorker<?, ?> running, waiting;

	synchronized void submit(SwingWorker<?, ?> task)
	{
		if (running != null)
		{
			waiting = task;
			return;
		}
		running = task;
		task.execute();
	}

	synchronized void finished(SwingWorker<?, ?> task)
	{
		if (task != running)
			return;
		running = waiting;
		waiting = null;
		if (running != null)
			running.execute();
	}

	synchronized void clearPending()
	{
		waiting = null;
	}
}

package com.windowmarkers;

import java.awt.Color;
import java.util.*;

final class CategoryGroups
{
	static final class Result
	{
		final List<Marker> selected = new ArrayList<>();
		int added, existing, skipped, limited;
	}

	static Result add(List<Marker> markers, Map<String, List<AutoCategories.Item>> groups, String preset,
			boolean includeGrouped, Color defaultColor, int limit)
	{
		Result result = new Result();
		Set<Integer> assigned = new HashSet<>();
		List<Color> colors = new ArrayList<>();
		for (Marker marker : markers)
		{
			if (marker.linked())
				for (int id : marker.linkedItemIds)
					assigned.add(id);
			colors.add(marker.borderArgb == null ? defaultColor : new Color(marker.borderArgb, true));
		}
		for (Map.Entry<String, List<AutoCategories.Item>> entry : groups.entrySet())
		{
			int[] requested = entry.getValue().stream().mapToInt(i -> i.id).distinct().sorted().toArray();
			Marker existing = markers.stream()
					.filter(m -> m.linked() && entry.getKey().equals(m.category) && preset.equals(m.preset)
							&& Arrays.equals(requested, Arrays.stream(m.linkedItemIds).distinct().sorted().toArray()))
					.findFirst().orElse(null);
			if (existing != null)
			{
				result.existing++;
				result.selected.add(existing);
				continue;
			}
			int[] ids = Arrays.stream(requested).filter(id -> includeGrouped || !assigned.contains(id)).toArray();
			if (ids.length == 0)
			{
				result.skipped++;
				continue;
			}
			if (markers.size() >= limit)
			{
				result.limited++;
				continue;
			}
			Marker marker = new Marker(0, 0, 48, 36);
			marker.scrollWithItems = true;
			marker.linkedItemIds = ids;
			marker.label = MarkerPresentation.title(entry.getKey());
			marker.labelOnce = true;
			marker.category = entry.getKey();
			marker.preset = preset;
			marker.labelFont = "Arial";
			marker.labelSize = 12;
			marker.labelPlacement = Marker.LabelPlacement.ABOVE;
			marker.style = WindowMarkersConfig.BorderStyle.PLAIN;
			Color color = MarkerPresentation.nextColor(colors);
			colors.add(color);
			marker.borderArgb = color.getRGB();
			marker.backgroundArgb = new Color(color.getRed(), color.getGreen(), color.getBlue(), 65).getRGB();
			markers.add(marker);
			result.selected.add(marker);
			result.added++;
			for (int id : ids)
				assigned.add(id);
		}
		return result;
	}
}

package com.windowmarkers;

import java.util.HashMap;
import java.util.Map;

final class CombatEquivalence
{
	private static final Map<Integer, String> FAMILIES = new HashMap<>();
	private static final Map<Integer, Boolean> MAX_REQUIREMENTS = new HashMap<>();
	static
	{
		for (String resource : new String[] { "combat-equivalences.tsv", "cosmetic-combat-equivalences.tsv" })
			for (String[] row : ItemTaxonomy.readRows(resource, 3))
			{
				int id = Integer.parseInt(row[0]);
				if (FAMILIES.put(id, row[1]) != null || (!row[2].equals("true") && !row[2].equals("false")))
				{
					throw new IllegalStateException("Invalid combat equivalence: " + id);
				}
				MAX_REQUIREMENTS.put(id, Boolean.parseBoolean(row[2]));
			}
	}

	static String familyName(AutoCategories.Item item)
	{
		return FAMILIES.getOrDefault(item.id, ItemVariantState.familyName(item));
	}

	static boolean requiresMaxedSkills(AutoCategories.Item item)
	{
		return MAX_REQUIREMENTS.getOrDefault(item.id, false);
	}

	static boolean matches(AutoCategories.Item item, String expected)
	{
		String family = familyName(item);
		if (family.equals("imbued ancient cape")
				&& (expected.equals("god capes") || expected.equals("imbued god cape")))
		{
			return true;
		}
		return ItemTaxonomy.matches(family, expected);
	}

	static boolean matchesAny(AutoCategories.Item item, String... expected)
	{
		for (String name : expected)
		{
			if (matches(item, name))
			{
				return true;
			}
		}
		return false;
	}
}

package com.windowmarkers;

import java.util.*;

final class CustomPresets
{
	static final int LIMIT = 50;
	List<Preset> presets = new ArrayList<>();

	static final class Preset
	{
		String name;
		boolean bankView, groupBySlot;
		List<Marker> groups = new ArrayList<>();

		@Override
		public String toString()
		{
			return name;
		}
	}

	void normalize()
	{
		if (presets == null)
			presets = new ArrayList<>();
		Set<String> names = new HashSet<>();
		presets.removeIf(p -> p == null || p.name == null || p.name.trim().isEmpty());
		if (presets.size() > LIMIT)
			presets = new ArrayList<>(presets.subList(0, LIMIT));
		for (Preset p : presets)
		{
			p.name = p.name.trim().substring(0, Math.min(60, p.name.trim().length()));
			if (p.groups == null)
				p.groups = new ArrayList<>();
			p.groups.removeIf(m -> m == null || !m.valid() || !m.linked() || m.linkedItemIds.length > 4000);
			if (p.groups.size() > 250)
				p.groups = new ArrayList<>(p.groups.subList(0, 250));
			for (Marker group : p.groups)
				group.linkedItemIds = Arrays.stream(group.linkedItemIds).filter(id -> id >= 0).distinct().toArray();
			p.groups.removeIf(m -> !m.linked());
		}
		presets.removeIf(p -> !names.add(p.name.toLowerCase(Locale.ROOT)) || p.groups.isEmpty());
	}
}

package com.windowmarkers;

import java.awt.*;
import java.util.*;
import java.util.List;
import javax.swing.*;

final class CustomViewEditor extends JPanel
{
	final CustomPresets.Preset draft;
	final JTextField name = new JTextField(), groupName = new JTextField();
	final DefaultListModel<Marker> groups = new DefaultListModel<>();
	final JList<Marker> list = new JList<>(groups);
	private final JCheckBox slots = new JCheckBox("Keep equipment / inventory layout");
	private final JLabel notice = new JLabel("Changes apply only when you save this custom view.");
	private final JPanel items = new JPanel(new BorderLayout(0, 6));
	private final BankItemSearch search;
	private final Set<Integer> bank;
	private final Map<Integer, BankItemSearch.Choice> known = new HashMap<>();
	private Marker current;
	private ItemPalette palette;
	private boolean changing;

	CustomViewEditor(CustomPresets.Preset draft, BankItemSearch search, Set<Integer> bank,
			List<BankItemSearch.Choice> choices)
	{
		super(new BorderLayout(8, 8));
		this.draft = draft;
		this.search = search;
		this.bank = new HashSet<>(bank);
		for (BankItemSearch.Choice choice : choices)
			known.put(choice.id, choice);
		name.setText(draft.name);
		slots.setSelected(draft.groupBySlot);
		JPanel heading = new MarkerForm();
		heading.add(new JLabel("Custom view name"));
		heading.add(name);
		heading.add(slots);
		heading.add(new JLabel(
				"<html>Select a group, add items, then Save changes.<br>Drag items in the open preset to save their positions. Bank order stays unchanged.</html>"));
		add(heading, BorderLayout.NORTH);
		for (Marker group : draft.groups)
			groups.addElement(group);
		list.setSelectionMode(ListSelectionModel.MULTIPLE_INTERVAL_SELECTION);
		list.setCellRenderer((owner, group, index, selected, focus) ->
		{
			JLabel label = new JLabel();
			label.putClientProperty("html.disable", Boolean.TRUE);
			label.setText(
					group.labelText() + " (" + (group.linkedItemIds == null ? 0 : group.linkedItemIds.length) + ")");
			label.setOpaque(true);
			label.setBackground(selected ? owner.getSelectionBackground() : owner.getBackground());
			label.setForeground(selected ? owner.getSelectionForeground() : owner.getForeground());
			label.setBorder(BorderFactory.createCompoundBorder(
					BorderFactory.createMatteBorder(0, 4, 0, 0,
							new Color(group.borderArgb == null ? 0xFFDAA520 : group.borderArgb, true)),
					BorderFactory.createEmptyBorder(6, 6, 6, 4)));
			label.setToolTipText("Group: " + group.labelText());
			return label;
		});
		JPanel left = new JPanel(new BorderLayout(0, 6));
		left.add(new JScrollPane(list), BorderLayout.CENTER);
		JPanel actions = new MarkerForm();
		button(actions, "Add group", this::addGroup);
		button(actions, "Remove selected groups", this::removeGroups);
		JPanel order = new JPanel(new GridLayout(1, 2, 4, 0));
		button(order, "Move up", () -> move(-1));
		button(order, "Move down", () -> move(1));
		actions.add(order);
		left.add(actions, BorderLayout.SOUTH);
		left.setPreferredSize(new Dimension(220, 400));
		JSplitPane split = new JSplitPane(JSplitPane.HORIZONTAL_SPLIT, left, items);
		split.setResizeWeight(0.25);
		split.setContinuousLayout(true);
		split.setBorder(null);
		add(split, BorderLayout.CENTER);
		add(notice, BorderLayout.SOUTH);
		list.addListSelectionListener(e ->
		{
			if (!e.getValueIsAdjusting() && !changing)
				selectGroup();
		});
		if (!groups.isEmpty())
			list.setSelectedIndex(0);
		else
			selectGroup();
	}

	private static void button(JPanel parent, String title, Runnable action)
	{
		JButton button = new JButton(title);
		button.addActionListener(e -> action.run());
		parent.add(button);
	}

	void flush()
	{
		if (current == null || palette == null)
			return;
		current.label = groupName.getText().trim();
		current.linkedItemIds = palette.ids();
		for (BankItemSearch.Choice choice : palette.choices())
			known.put(choice.id, choice);
		list.repaint();
	}

	private void selectGroup()
	{
		flush();
		if (palette != null)
			palette.close();
		palette = null;
		current = null;
		items.removeAll();
		if (list.getSelectedIndices().length == 1)
		{
			current = list.getSelectedValue();
			groupName.setText(current.labelText());
			JPanel heading = new MarkerForm();
			heading.add(new JLabel("Group label"));
			heading.add(groupName);
			JPanel colours = new JPanel(new GridLayout(1, 2, 5, 0));
			button(colours, "Border colour", () -> colour(false));
			button(colours, "Background", () -> colour(true));
			heading.add(colours);
			items.add(heading, BorderLayout.NORTH);
			List<BankItemSearch.Choice> selected = new ArrayList<>();
			if (current.linkedItemIds != null)
				for (int id : current.linkedItemIds)
					selected.add(known.getOrDefault(id, new BankItemSearch.Choice(id, "Item " + id)));
			palette = new ItemPalette(search, bank, selected, 4000);
			items.add(palette, BorderLayout.CENTER);
		}
		else
			items.add(new JLabel("Select one group to edit its items, or several to move/remove."), BorderLayout.NORTH);
		items.revalidate();
		items.repaint();
	}

	private void colour(boolean background)
	{
		if (current == null)
			return;
		Integer argb = background ? current.backgroundArgb : current.borderArgb;
		Color chosen = MarkerDialogs.chooseColor(this, background ? "Group background" : "Group border",
				new Color(argb == null ? 0xFFDAA520 : argb, true));
		if (chosen != null)
		{
			if (background)
				current.backgroundArgb = new Color(chosen.getRed(), chosen.getGreen(), chosen.getBlue(),
						argb == null ? 65 : new Color(argb, true).getAlpha()).getRGB();
			else
				current.borderArgb = chosen.getRGB();
			list.repaint();
		}
	}

	void addGroup()
	{
		flush();
		if (groups.size() >= 250)
		{
			notice.setText("A view can contain up to 250 groups.");
			return;
		}
		Marker group = new Marker(0, 0, 48, 36);
		group.label = "New group";
		group.preset = "Custom";
		group.scrollWithItems = true;
		List<Color> used = new ArrayList<>();
		for (Marker marker : Collections.list(groups.elements()))
			if (marker.borderArgb != null)
				used.add(new Color(marker.borderArgb, true));
		Color colour = MarkerPresentation.nextColor(used);
		group.borderArgb = colour.getRGB();
		group.backgroundArgb = new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), 65).getRGB();
		groups.addElement(group);
		list.setSelectedIndex(groups.size() - 1);
		list.ensureIndexIsVisible(groups.size() - 1);
	}

	void removeGroups()
	{
		flush();
		List<Marker> selected = list.getSelectedValuesList();
		changing = true;
		for (Marker group : selected)
			groups.removeElement(group);
		changing = false;
		list.clearSelection();
		if (!groups.isEmpty())
			list.setSelectedIndex(0);
		else
			selectGroup();
	}

	void move(int direction)
	{
		flush();
		List<Marker> all = Collections.list(groups.elements()), selected = list.getSelectedValuesList();
		int[] indices = list.getSelectedIndices();
		if (indices.length == 0)
			return;
		int drop = direction < 0 ? Math.max(0, indices[0] - 1) : Math.min(all.size(), indices[indices.length - 1] + 2);
		if (!GroupEdits.reorder(all, new ArrayList<>(all), selected, drop))
			return;
		changing = true;
		groups.clear();
		for (Marker group : all)
			groups.addElement(group);
		for (int i = 0; i < groups.size(); i++)
			if (selected.contains(groups.get(i)))
				list.addSelectionInterval(i, i);
		changing = false;
		selectGroup();
	}

	boolean valid()
	{
		flush();
		String title = name.getText().trim();
		if (title.isEmpty() || title.length() > 60)
		{
			notice.setText("Enter a view name between 1 and 60 characters.");
			return false;
		}
		if (groups.isEmpty())
		{
			notice.setText("Add at least one group, or Cancel to keep the saved view.");
			return false;
		}
		for (Marker group : Collections.list(groups.elements()))
			if (group.labelText().isEmpty() || group.label.length() > 60 || !group.linked())
			{
				notice.setText(
						"Each group needs a 1–60 character label and at least one item. Select the group to finish it.");
				return false;
			}
		draft.name = title;
		draft.bankView = true;
		draft.groupBySlot = slots.isSelected();
		draft.groups = Collections.list(groups.elements());
		return true;
	}

	void close()
	{
		if (palette != null)
			palette.close();
	}

	void error(String text)
	{
		notice.setText(text);
	}
}

