			this(items, ranks, activity, null);
		}

		Result(List<Item> items, Map<Integer, Rank> ranks, boolean activity, SetupLoadout loadout)
		{
			this(items, ranks, activity, loadout, Collections.emptyList());
		}

		Result(List<Item> items, Map<Integer, Rank> ranks, boolean activity, SetupLoadout loadout,
				List<ActivitySetups.Setup> setups)
		{
			this.items = items;
			this.ranks = ranks;
			this.activity = activity;
			this.loadout = loadout;
			this.setups = Collections.unmodifiableList(new ArrayList<>(setups));
		}

		short[] ids()
		{
			short[] ids = new short[items.size()];
			for (int i = 0; i < ids.length; i++)
				ids[i] = (short) items.get(i).id;
			return ids;
		}
	}

	private static final class Field
	{
		final String slot, note;
		final int tier;

		Field(String[] row)
		{
			slot = row[2];
			tier = Integer.parseInt(row[3]);
			note = row[4];
		}
	}

	private static final Map<String, Map<Integer, List<Field>>> RANKS = new HashMap<>();
	private static final Map<Integer, String[]> SLOTS = new HashMap<>();
	private static final List<String[]> PURCHASE_VARIANTS = ItemTaxonomy.readRows("ge-purchase-variants.tsv", 5);
	private static final Map<Integer, String[]> FUNCTIONAL_SLOTS = new HashMap<>();
	private static final Map<Integer, String[]> VARIANT_NOTES = new HashMap<>();
	static
	{
		for (String[] row : ItemTaxonomy.readRows("activity-setup-ranks.tsv", 5))
			RANKS.computeIfAbsent(row[0], k -> new HashMap<>())
					.computeIfAbsent(Integer.parseInt(row[1]), k -> new ArrayList<>()).add(new Field(row));
		for (String[] row : ItemTaxonomy.readRows("ge-item-slots.tsv", 3))
			SLOTS.put(Integer.parseInt(row[0]), row);
		for (String[] row : ItemTaxonomy.readRows("ge-functional-slots.tsv", 5))
			FUNCTIONAL_SLOTS.put(Integer.parseInt(row[0]), row);
		for (String[] row : ItemTaxonomy.readRows("catalogue-variant-notes.tsv", 4))
			VARIANT_NOTES.put(Integer.parseInt(row[0]), row);
	}

	static int fallbackSlot(int id, String name)
	{
		String[] row = SLOTS.get(id);
		return row != null && row[2].equalsIgnoreCase(name) ? Integer.parseInt(row[1]) : -1;
	}

	static Item guideItem(int id)
	{
		String[] row = SLOTS.get(id);
		return row == null ? null : new Item(id, row[2], Integer.parseInt(row[1]), new String[] { "Wear" });
	}

	private final Map<Integer, Item> items = new HashMap<>();
	private final Map<String, Set<Integer>> categories = new LinkedHashMap<>();
	private final Map<AutoCategories.Preset, Set<Integer>> presets = new EnumMap<>(AutoCategories.Preset.class);
	private final Map<String, Map<String, Set<Integer>>> activityCategories = new LinkedHashMap<>();
	private final List<ActivitySetups.Setup> setups = ActivitySetups.all();
	private final Map<String, String> setupText = new HashMap<>();
	private final Map<String, Set<Integer>> setupItems = new HashMap<>();
	private final Map<String, Map<Integer, String>> purchaseNotes = new HashMap<>();
	private final Set<String> exactNames = new HashSet<>();
	private final Set<String> vocabulary = new HashSet<>();
	private final boolean ge;
	private final SetupPlayerState playerState;

	ItemCatalogueIndex(List<Item> catalogue)
	{
		this(catalogue, true);
	}

	ItemCatalogueIndex(List<Item> catalogue, boolean ge)
	{
		this(catalogue, ge, SetupPlayerState.unknown());
	}

	ItemCatalogueIndex(List<Item> catalogue, boolean ge, SetupPlayerState playerState)
	{
		this.playerState = playerState;
		this.ge = ge;
		Map<Integer, List<String>> itemGroups = new HashMap<>();
		for (Item item : catalogue)
		{
			if (item.id < 0 || item.id > 65535)
				continue;
			items.put(item.id, item);
			exactNames.add(normalize(item.name));
			if (!ItemVariantState.identityNeedsReview(item.fact))
				for (WikiCatalogue.Entry entry : WikiCatalogue.entries(item.fact))
				{
					add(entry.group, item.id);
					itemGroups.computeIfAbsent(item.id, k -> new ArrayList<>()).add(normalize(entry.group));

					add(entry.facet, item.id);
					if (entry.facet.equals("outfit"))
					{
						add("skilling outfits", item.id);
					}
					if (entry.facet.equals("combat"))
						add("general combat", item.id);
					if (entry.facet.equals("skilling") && entry.group.contains(" — ")
							&& "Tools".equals(ItemTaxonomy.weaponRole(ItemVariantState.familyName(item.fact))))
						add(entry.group.substring(0, entry.group.indexOf(" — ")) + " tools", item.id);
				}
		}

		List<AutoCategories.Item> facts = new ArrayList<>();
		items.values().forEach(item -> facts.add(item.fact));
		for (AutoCategories.Preset preset : AutoCategories.Preset.values())
		{
			Set<Integer> membership = new HashSet<>();
			presets.put(preset, membership);
			AutoCategories.suggest(preset, facts).forEach((group, members) ->
			{
				for (AutoCategories.Item item : members)
				{
					add(group, item.id);
					if (!group.startsWith("Other"))
						membership.add(item.id);
				}
			});
		}
		Map<String, Set<Integer>> byActivity = new HashMap<>();
		for (ActivitySetups.Setup setup : setups)
		{
			setupText.put(setup.id, normalize(setup.activity + " " + setup.label));
			Set<Integer> ids = new HashSet<>(setup.itemIds);
			for (String[] rule : PURCHASE_VARIANTS)
			{
				int reference = Integer.parseInt(rule[0]), target = Integer.parseInt(rule[1]);
				Item item = items.get(target);
				if (setup.itemIds.contains(reference) && item != null && item.name.equalsIgnoreCase(rule[2])
						&& ids.add(target))
					purchaseNotes.computeIfAbsent(setup.id, k -> new HashMap<>()).put(target, rule[3]);
			}
			setupItems.put(setup.id, ids);
			byActivity.computeIfAbsent(normalize(setup.activity), k -> new HashSet<>()).addAll(ids);
		}
		byActivity.forEach((activity, ids) ->
		{
			Map<String, Set<Integer>> groups = new HashMap<>();
			for (int id : ids)
				for (String group : itemGroups.getOrDefault(id, Collections.emptyList()))
					groups.computeIfAbsent(activity + " " + group, k -> new HashSet<>()).add(id);
			activityCategories.put(activity, groups);
		});
		setupText.values().forEach(this::indexWords);
		categories.keySet().forEach(this::indexWords);
		activityCategories.values().forEach(groups -> groups.keySet().forEach(this::indexWords));
	}

	private void indexWords(String text)
	{
		Collections.addAll(vocabulary, text.split(" +"));
	}

	private void add(String text, int id)
	{
		categories.computeIfAbsent(normalize(text), k -> new HashSet<>()).add(id);
	}

	Map<String, Set<Integer>> categoryDocuments()
	{
		return Collections.unmodifiableMap(categories);
	}

	Set<Integer> presetIds(AutoCategories.Preset preset)
	{
		return Collections.unmodifiableSet(presets.get(preset));
	}

	static String normalize(String query)
	{
		String s = " " + SearchText.normalize(query) + " ";
		String[][] aliases = { { "toa", "tombs of amascut" }, { "cox", "chambers of xeric" },
				{ "tob", "theatre of blood" }, { "kbd", "king black dragon" }, { "kq", "kalphite queen" },
				{ "dks", "dagannoth kings" }, { "corp", "corporeal beast" }, { "mage", "magic" }, { "range", "ranged" },
				{ "armor", "armour" } };
		for (String[] alias : aliases)
			s = s.replace(" " + alias[0] + " ", " " + alias[1] + " ");
		return s.trim();
	}

	static int slot(String token)
	{
		switch (token)
		{
			case "head":
			case "helm":
			case "helmet":
			case "hat":
			case "hood":
			case "headgear":
			case "helms":
			case "helmets":
			case "hats":
				return 0;
			case "cape":
			case "back":
			case "capes":
				return 1;
			case "neck":
			case "amulet":
			case "necklace":
			case "amulets":
			case "necklaces":
			case "pendant":
				return 2;
			case "weapon":
			case "weapons":
				return 3;
			case "body":
			case "chest":
			case "torso":
			case "top":
			case "tops":
			case "platebody":
			case "robetop":
				return 4;
			case "shield":
			case "shields":
			case "offhand":
			case "defender":
				return 5;
			case "legs":
			case "leg":
			case "bottom":
			case "bottoms":
			case "platelegs":
			case "plateskirt":
			case "chaps":
			case "tassets":
			case "skirt":
				return 7;
			case "hands":
			case "hand":
			case "gloves":
			case "glove":
			case "gauntlets":
			case "bracers":
				return 9;
			case "feet":
			case "foot":
			case "boots":
			case "boot":
			case "shoes":
				return 10;
			case "ring":
			case "rings":
				return 12;
			case "ammo":
			case "ammunition":
			case "arrows":
			case "bolts":
				return 13;
			default:
				return -1;
		}
	}

	private static boolean matches(String text, String query, boolean fuzzy)
	{
		boolean exact = true;
		for (String word : query.split(" +"))
			if (!text.contains(word))
			{
				exact = false;
				break;
			}
		return exact || fuzzy && SearchText.normalizedScore(text, query) != Integer.MAX_VALUE;
	}

	private static boolean mentionsActivity(String query, String activity, boolean fuzzy)
	{
		for (String word : normalize(activity).split(" +"))
		{
			if (word.length() < 3 || word.equals("the") || word.equals("and"))
				continue;
			for (String term : query.split(" +"))
				if (term.length() >= 3 && matches(word, term, fuzzy))
					return true;
		}
		return false;
	}

	private boolean exactCategoryMatch(String terms)
	{
		if (setupText.values().stream().anyMatch(t -> matches(t, terms, false))
				|| categories.keySet().stream().anyMatch(t -> matches(t, terms, false)))
			return true;
		for (Map.Entry<String, Map<String, Set<Integer>>> activity : activityCategories.entrySet())
			if (mentionsActivity(terms, activity.getKey(), false)
					&& activity.getValue().keySet().stream().anyMatch(t -> matches(t, terms, false)))
				return true;
		return false;
	}

	private String correctWholeWords(String terms)
	{
		return SearchText.correctWholeWords(vocabulary, terms);
	}

	Result find(String raw, String context)
	{
		return find(raw, context, "");
	}

	Result find(String raw, String context, String inventoryContext)
	{
		return find(raw, context, inventoryContext, 99);
	}

	Result find(String raw, String context, String inventoryContext, int hitpoints)
	{
		if (!BankSearchIndex.plainQuery(raw) || raw.length() > 100)
			return null;
		SupplySearch.Query supply = SupplySearch.parse(raw);
		if (supply != null)
			return SupplySearch.find(supply, items.values(), hitpoints);
		String query = normalize(ActivityMenu.query(raw));
		ActivitySetups.Setup chosen = setups.stream().filter(s -> s.id.equals(context)).findFirst().orElse(null);

		boolean selectedActivity = chosen != null && mentionsActivity(query, chosen.activity, false);
		if (query.length() < 3
				|| exactNames.contains(normalize(raw)) && !categories.containsKey(query) && !selectedActivity)
			return null;
		SearchQuery qualifiers = SearchQuery.parse(raw);
		query = normalize(ActivityMenu.query(qualifiers.text));
		boolean exactActivityQuery = false;
		for (ActivitySetups.Setup setup : setups)
			if (normalize(setup.activity).equals(query))
			{
				exactActivityQuery = true;
				break;
			}
		int wantedSlot = -1;
		List<String> words = new ArrayList<>();
		for (String word : query.split(" +"))
		{
			int candidate = exactActivityQuery ? -1 : slot(word);
			if (candidate >= 0)
			{
				if (wantedSlot >= 0 && wantedSlot != candidate)
					return null;
				wantedSlot = candidate;
			}
			else
				words.add(word);
		}
		String terms = String.join(" ", words);

		boolean fuzzy = !terms.isEmpty() && !exactCategoryMatch(terms);
		if (fuzzy)
		{

			String corrected = correctWholeWords(terms);
			if (!corrected.equals(terms) && exactCategoryMatch(corrected))
			{
				terms = corrected;
				fuzzy = false;
			}
		}
		Set<Integer> found = new HashSet<>();
		List<ActivitySetups.Setup> matched = new ArrayList<>();
		boolean useContext = chosen != null && mentionsActivity(terms, chosen.activity, fuzzy);
		boolean recognized = terms.isEmpty() && wantedSlot >= 0;
		if (recognized)
			found.addAll(items.keySet());
		if (!terms.isEmpty())
		{
			String exactActivity = "";
			for (ActivitySetups.Setup setup : setups)
				if (normalize(setup.activity).equals(terms))
				{
					exactActivity = terms;
					break;
				}
			for (ActivitySetups.Setup setup : setups)
				if (matches(setupText.get(setup.id), terms, fuzzy))
				{

					if (!exactActivity.isEmpty() && !normalize(setup.activity).equals(exactActivity)
							&& !family(setup.activity).equals(exactActivity))
						continue;
					recognized = true;

					if (useContext && family(chosen.activity).equals(family(setup.activity)) && chosen != setup)
						continue;
					if (mentionsActivity(terms, setup.activity, fuzzy))
						matched.add(setup);
					found.addAll(setupItems.get(setup.id));
				}
			for (Map.Entry<String, Set<Integer>> category : categories.entrySet())
				if (matches(category.getKey(), terms, fuzzy))
				{
					recognized = true;
					found.addAll(category.getValue());
				}
			for (Map.Entry<String, Map<String, Set<Integer>>> activity : activityCategories.entrySet())
				if ((exactActivity.isEmpty() || normalize(activity.getKey()).equals(exactActivity)
						|| family(activity.getKey()).equals(exactActivity))
						&& mentionsActivity(terms, activity.getKey(), fuzzy))
					for (Map.Entry<String, Set<Integer>> group : activity.getValue().entrySet())
						if (matches(group.getKey(), terms, fuzzy))
						{
							recognized = true;
							found.addAll(group.getValue());
						}
		}
		if (!recognized)
			return null;
		if (useContext)
			found.retainAll(setupItems.get(chosen.id));

		String ordinary = SearchText.normalize(raw);
		for (Item item : items.values())
			if (item.search.contains(ordinary))
				found.add(item.id);
		final int filterSlot = wantedSlot;
		List<Item> result = found.stream().map(items::get).filter(Objects::nonNull)
				.filter(i -> filterSlot < 0 || fitsSlot(i, filterSlot) || i.search.contains(ordinary)).sorted(Comparator
						.comparing((Item i) -> i.name, String.CASE_INSENSITIVE_ORDER).thenComparingInt(i -> i.id))
				.collect(Collectors.toList());
		Map<Integer, Rank> ranks = new HashMap<>();
		if (!ge || result.size() <= LIMIT || !matched.isEmpty() || !qualifiers.tiers.isEmpty())
			for (Item item : result)
			{
				String locked = playerState.locked(item);
				ranks.put(item.id, locked.isEmpty() ? rank(item, matched, wantedSlot)
						: new Rank(0, "Not currently equipable: " + locked));
			}
		if (!qualifiers.tiers.isEmpty())
		{
			result.removeIf(item -> !qualifiers.accepts(ranks.get(item.id)));
			Set<Integer> retained = result.stream().map(item -> item.id).collect(Collectors.toSet());
			ranks.keySet().retainAll(retained);
		}
		SetupLoadout loadout = !ge && wantedSlot < 0 && qualifiers.tiers.isEmpty()
				? SetupLoadout.build(matched, playerState.usable(items), playerState.visible(found), inventoryContext, playerState)
				: null;
		if (loadout != null)
		{
			playerState.annotate(loadout);
			if (loadout.wildernessBudget)
			{
				result.removeIf(item -> !WildernessLoadout.allowed(item));
				Set<Integer> retained = result.stream().map(i -> i.id).collect(Collectors.toSet());
				ranks.keySet().retainAll(retained);
			}
			Set<Integer> included = result.stream().map(i -> i.id).collect(Collectors.toSet());
			for (int id : loadout.itemIds())
				if (items.containsKey(id) && included.add(id))
				{
					result.add(items.get(id));
					ranks.put(id, new Rank(0,
							"Owned alternative completing this setup. Not ranked by this activity's source table."));
				}
		}
		return new Result(result, ranks, !matched.isEmpty(), loadout, matched);
	}

	Map<Integer, Rank> guideRanks(String query, String context)
	{
		return guideRanks(query, context, 99);
	}

	Map<Integer, Rank> guideRanks(String query, String context, int hitpoints)
	{
		Result result = find(query, context, "", hitpoints);
		return result == null ? Collections.emptyMap() : result.ranks;
	}

	private static String family(String activity)
	{
		return normalize(ActivityMenu.canonical(activity).split("/", 2)[0]);
	}

	private static String[] functionalSlot(Item item)
	{
		String[] row = FUNCTIONAL_SLOTS.get(item.id);
		return row != null && row[1].equalsIgnoreCase(item.name) ? row : null;
	}

	private static boolean fitsSlot(Item item, int slot)
	{
		String[] row = functionalSlot(item);
		return item.slot == slot || row != null && Integer.parseInt(row[2]) == slot;
	}

	private Rank rank(Item item, List<ActivitySetups.Setup> matched, int wantedSlot)
	{
		Set<String> notes = new LinkedHashSet<>();
		String[] variant = VARIANT_NOTES.get(item.id);
		if (variant != null && variant[1].equalsIgnoreCase(item.name))
			notes.add(variant[2]);
		for (ActivitySetups.Setup setup : matched)
		{
			String note = purchaseNotes.getOrDefault(setup.id, Collections.emptyMap()).get(item.id);
			if (note != null)
				notes.add(note);
			String requirement = SetupItemRequirements.reviewReason(setup.id, item.fact);
			if (!requirement.isEmpty())
				notes.add(setup.activity + " / " + setup.label + ": " + requirement);
		}
		String[] functional = functionalSlot(item);
		if (functional != null)
			notes.add(functional[3]);
		String state = ItemVariantState.annotate("Item state", item.fact);
		if (!state.equals("Item state"))
			notes.add(state);
		String extra = notes.isEmpty() ? "" : "\n" + String.join("\n", notes);
		boolean inventoryUse = matched.stream()
				.anyMatch(s -> SetupLoadout.inventoryTable(s)
						&& (s.itemIds.contains(item.id) || InventoryPotionDoses.listed(s.itemIds, item.fact))
						&& !ItemVariantState.needsInventoryReview(item.fact, s));
		if (ItemVariantState.needsActivityReview(item.fact) && !inventoryUse)
			return new Rank(0, ItemVariantState.annotate(ItemVariantState.reviewGroup(item.fact), item.fact)
					+ ". Purchase state is not a ready-to-use loadout." + extra);
		if (inventoryUse && !ItemVariantState.inventoryUseNote(item.fact).isEmpty())
			extra += "\n" + ItemVariantState.inventoryUseNote(item.fact);
		Set<Integer> tiers = new HashSet<>();
		Set<String> roles = new HashSet<>();
		List<String> sources = new ArrayList<>();
		for (ActivitySetups.Setup setup : matched)
		{
			List<Field> fields = RANKS.getOrDefault(setup.id, Collections.emptyMap()).get(item.id);
			if (fields == null)
				continue;
			for (Field field : fields)
			{
				int sourceSlot = field.slot.equals("special") || field.slot.equals("2h") ? 3 : slot(field.slot);

				if (item.slot < 0 || !fitsSlot(item, sourceSlot) || wantedSlot >= 0 && sourceSlot != wantedSlot)
					continue;
				boolean reduced = ItemVariantState.needsRankReview(item.fact, setup.activity, setup.label)
						|| !SetupItemRequirements.reviewReason(setup.id, item.fact).isEmpty();
				int value = reduced ? 0 : field.tier;
				tiers.add(value);
				roles.add(field.slot.equals("special") ? "special attack"
						: field.slot.equals("ammo") ? "ammunition"
								: field.slot.equals("shield") ? "shield" : "equipment");
				if (sources.size() < 3)
					sources.add(setup.activity + " / " + setup.label + " / " + field.slot + ": "
							+ (reduced ? "reduced function; charge-dependent guide rank withheld"
									: value == 0 ? "provisional or ordered choices; review guide"
											: "Wiki column " + value)
							+ (field.note.isEmpty() ? "" : ". " + field.note));
			}
		}
		int tier = tiers.size() == 1 && roles.size() == 1 ? tiers.iterator().next() : 0;
		String reason = tiers.isEmpty() ? "Category or example match; no ranked recommendation for this search."
				: tier == 0
						? "Ranking differs by setup/role, or needs review. Refine the search or use Legend / Saved views / Guide choices."
						: "Wiki tier " + tier
								+ " for the matching setup(s), not a universal ranking. Requirements and set bonuses still apply.";
		return new Rank(tier, reason + extra + (sources.isEmpty() ? "" : "\n" + String.join("\n", sources)),
				roles.size() == 1 ? roles.iterator().next() : "");
	}
}

package com.windowmarkers;

import java.awt.*;
import java.awt.event.*;
import java.util.*;
import java.util.List;
import javax.swing.*;

final class ItemLookupPanel extends JPanel
{
	static final class Row
	{
		final String membership, owner;

		Row(String membership, String owner)
		{
			this.membership = membership;
			this.owner = owner;
		}

		@Override
		public String toString()
		{
			return owner + " · " + membership;
		}
	}

	final JList<Row> list;
	final JButton send = new JButton("Send filter to Legend");
	final JButton highlight = new JButton("Highlight this item(s)");
	String filter;
	String membership;
	boolean highlightRequested;

	ItemLookupPanel(List<String> names, List<? extends Set<String>> memberships)
	{
		super(new BorderLayout(0, 10));
		if (names.isEmpty() || names.size() > 2 || names.size() != memberships.size())
			throw new IllegalArgumentException("Choose one or two items");
		JTextArea hint = new JTextArea(String.join("  /  ", names)
				+ "\nSend a classification to review and add its owned items as colored Legend groups. Double-click also sends it.\nMembership describes a use; item state and activity requirements still apply.");
		hint.setLineWrap(true);
		hint.setWrapStyleWord(true);
		hint.setEditable(false);
		hint.setOpaque(false);
		add(hint, BorderLayout.NORTH);
		DefaultListModel<Row> rows = new DefaultListModel<>();
		Set<String> shared = new TreeSet<>(memberships.get(0));
		if (memberships.size() == 2)
			shared.retainAll(memberships.get(1));
		for (String value : shared)
			rows.addElement(new Row(value, names.size() == 1 ? "Item" : "Both items"));
		if (names.size() == 2)
			for (int i = 0; i < 2; i++)
				for (String value : new TreeSet<>(memberships.get(i)))
					if (!shared.contains(value))
						rows.addElement(new Row(value, "Only " + names.get(i)));
		list = new JList<>(rows);
		list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		list.setVisibleRowCount(16);
		list.setCellRenderer((view, row, index, selected, focus) ->
		{
			JPanel cell = new JPanel(new GridLayout(0, 1));
			cell.setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 6));
			cell.setBackground(selected ? view.getSelectionBackground() : view.getBackground());
			for (String text : new String[] { row.membership, row.owner })
			{
				JLabel label = new JLabel(text);
				label.setForeground(selected ? view.getSelectionForeground() : view.getForeground());
				cell.add(label);
			}
			return cell;
		});
		add(new JScrollPane(list), BorderLayout.CENTER);
		JPanel buttons = new JPanel(new GridLayout(0, 1, 0, 5));
		buttons.add(send);
		buttons.add(highlight);
		buttons.add(new JLabel(rows.isEmpty() ? "No recorded memberships. You can still highlight the selected items."
				: "Highlighting is temporary. Use Legend → Clear highlight to clear it."));
		add(buttons, BorderLayout.SOUTH);
		send.setEnabled(false);
		list.addListSelectionListener(e -> send.setEnabled(
				list.getSelectedValue() != null && !list.getSelectedValue().membership.startsWith("Review: ")));
		send.addActionListener(e ->
		{
			Row row = list.getSelectedValue();
			if (row != null)
			{
				membership = row.membership;
				filter = filterText(membership);
				close();
			}
		});
		highlight.addActionListener(e ->
		{
			highlightRequested = true;
			close();
		});
		list.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				int i = list.locationToIndex(e.getPoint());
				if (e.getClickCount() == 2 && i >= 0 && list.getCellBounds(i, i).contains(e.getPoint()))
					send.doClick();
			}
		});
		list.getInputMap().put(KeyStroke.getKeyStroke(KeyEvent.VK_ENTER, 0), "send");
		list.getActionMap().put("send", new AbstractAction()
		{
			public void actionPerformed(ActionEvent e)
			{
				send.doClick();
			}
		});
		setPreferredSize(new Dimension(700, 460));
	}

	static String filterText(String membership)
	{
		int prefix = membership.indexOf(": ");
		String text = prefix < 0 ? membership : membership.substring(prefix + 2);
		if (membership.startsWith("Preset: "))
		{
			int slash = text.indexOf(" / ");
			if (slash >= 0)
				text = text.substring(slash + 3);
		}
		else if (membership.startsWith("Wiki setup: "))
			text = text.replace(" / ", " — ").replace(" — state needs review", "");
		else if (membership.startsWith("Custom preset: "))
			text = text.replace(" / ", " ");
		return text;
	}

	private void close()
	{
		Window window = SwingUtilities.getWindowAncestor(this);
		if (window instanceof JDialog)
			window.dispose();
	}
}

