		add(middle, BorderLayout.CENTER);
		picked.setVisibleRowCount(3);
		picked.setSelectionMode(ListSelectionModel.MULTIPLE_INTERVAL_SELECTION);
		picked.setCellRenderer((list, choice, index, isSelected, focus) ->
		{
			JLabel label = new JLabel(choice.toString(), choice.image == null ? null : new ImageIcon(choice.image),
					SwingConstants.LEFT);
