	static final class Entry
	{
		final Marker marker;
		final String name, detail;
		final Color color;

		Entry(Marker marker, String name, Color color)
		{
			this(marker, name, color,
					marker.linked()
							? java.util.Arrays.stream(marker.linkedItemIds).distinct().count() + " linked item types"
							: "Area marker");
		}

		Entry(Marker marker, String name, Color color, String detail)
		{
			this.marker = marker;
			this.name = name;
			this.color = color;
			this.detail = detail;
		}
	}

	static List<Entry> forTab(List<Marker> markers, List<ItemAnchors.Cell> cells, Rectangle bank, Rectangle area,
			int scroll, Color defaultColor)
	{
		List<Entry> entries = new java.util.ArrayList<>();
		if (bank == null || area == null)
		{
			return entries;
		}
		java.util.Set<Integer> tabIds = new java.util.HashSet<>();
		for (ItemAnchors.Cell cell : cells)
		{
			tabIds.add(cell.id);
		}
		for (int i = 0; i < markers.size(); i++)
		{
			Marker marker = markers.get(i);
			java.util.Set<Integer> matches = new java.util.HashSet<>();
			Rectangle bounds = marker.linked() ? null : marker.onScreen(bank, area, scroll);
			if (marker.linked())
			{
				for (int id : marker.linkedItemIds)
				{
					if (tabIds.contains(id))
					{
						matches.add(id);
					}
				}
			}
			else
				for (ItemAnchors.Cell cell : cells)
				{
					if (bounds != null && bounds.contains(cell.icon.getCenterX(), cell.icon.getCenterY()))
					{
						matches.add(cell.id);
					}
				}
			if (matches.isEmpty())
			{
				continue;
			}
			entries.add(new Entry(marker, marker.labelText().isEmpty() ? "Marker " + (i + 1) : marker.labelText(),
					marker.borderArgb == null ? defaultColor : new Color(marker.borderArgb, true),
					matches.size() + " item types in this tab" + (marker.linked() ? "" : " · area")));
		}
		return entries;
	}

	static boolean same(List<Entry> a, List<Entry> b)
	{
		if (a == null || a.size() != b.size())
		{
			return false;
		}
		for (int i = 0; i < a.size(); i++)
		{
			Entry x = a.get(i), y = b.get(i);
			if (x.marker != y.marker || !x.name.equals(y.name) || !x.detail.equals(y.detail)
					|| !x.color.equals(y.color))
			{
				return false;
			}
		}
		return true;
	}

