	List<Marker> selected()
	{
		List<Marker> result = new java.util.ArrayList<>();
		for (Entry entry : list.getSelectedValuesList())
			result.add(entry.marker);
		return result;
	}

	private List<Marker> visible()
	{
		List<Marker> result = new java.util.ArrayList<>();
		for (int i = 0; i < rows.size(); i++)
			result.add(rows.get(i).marker);
		return result;
	}

	private void shift(int direction)
	{
		int[] selected = list.getSelectedIndices();
		if (selected.length == 0 || actions == null)
			return;
		int index = direction < 0 ? Math.max(0, selected[0] - 1)
				: Math.min(rows.size(), selected[selected.length - 1] + 2);
		actions.reorder(visible(), selected(), index);
	}

	void replace(List<Entry> entries)
	{
		replace(entries, entries);
	}

	void replace(List<Entry> tab, List<Entry> all)
	{
		tabEntries = tab;
		allEntries = all;
		String selected = (String) preset.getSelectedItem();
		refreshing = true;
		preset.removeAllItems();
		preset.addItem("All presets");
		java.util.Set<String> names = new java.util.TreeSet<>();
		for (Entry entry : all)
			names.add(entry.marker.preset == null ? "Custom / older groups" : entry.marker.preset);
		for (String name : names)
			preset.addItem(name);
		if (names.contains(selected))
			preset.setSelectedItem(selected);
		refreshing = false;
		filter();
	}

	void catalogue(List<BankCatalogue.Choice> choices)
	{
		this.choices = choices;
		filter();
	}

	void showGroups(List<Marker> groups)
	{
		search.setText("");
		preset.setSelectedIndex(0);
		if (scope.getSelectedIndex() == 0 && tabEntries.stream().noneMatch(e -> groups.contains(e.marker)))
			scope.setSelectedIndex(1);
		filter();
		list.clearSelection();
		for (int i = 0; i < rows.size(); i++)
			if (groups.contains(rows.get(i).marker))
				list.addSelectionInterval(i, i);
		if (list.getSelectedIndex() >= 0)
			list.ensureIndexIsVisible(list.getSelectedIndex());
	}

	void resetContext()
	{
		search.setText("");
		preset.setSelectedIndex(0);
		list.clearSelection();
	}

	void close()
	{
		timer.stop();
	}

	void filter()
	{
		revision++;
		List<Marker> selected = selected();
		list.setValueIsAdjusting(true);
		rows.clear();
		List<Entry> base = scope.getSelectedIndex() == 0 ? tabEntries : allEntries;
		String needle = search.getText();
		String presetName = (String) preset.getSelectedItem();
		for (Entry entry : base)
		{
			String groupPreset = entry.marker.preset == null ? "Custom / older groups" : entry.marker.preset;
			if (preset.getSelectedIndex() > 0 && !groupPreset.equals(presetName))
				continue;
			if (SearchText.score(entry.name + " " + entry.marker.category + " " + groupPreset + " "
					+ BankCatalogue.aliases(groupPreset), needle) == Integer.MAX_VALUE)
				continue;
			rows.addElement(entry);
		}
		for (int i = 0; i < rows.size(); i++)
			if (selected.contains(rows.get(i).marker))
				list.addSelectionInterval(i, i);
		list.setValueIsAdjusting(false);
		suggestions.clear();
		if (!needle.trim().isEmpty())
			for (BankCatalogue.Choice choice : BankCatalogue.search(choices, needle, 4))
				suggestions.addElement(choice);
		suggestionScroll.setVisible(!suggestions.isEmpty());
		revalidate();
		hover.accept(null);
	}

	private final class GroupTransfer extends TransferHandler
	{
		private final java.awt.datatransfer.DataFlavor flavor = new java.awt.datatransfer.DataFlavor(
				java.awt.datatransfer.DataFlavor.javaJVMLocalObjectMimeType + ";class=java.lang.Object",
				"Legend groups");

		@Override
		public int getSourceActions(JComponent c)
		{
			return MOVE;
		}

		@Override
		protected java.awt.datatransfer.Transferable createTransferable(JComponent c)
		{
			Drag drag = new Drag(MarkerLegend.this, revision, visible(), selected());
			return new java.awt.datatransfer.Transferable()
			{
				public java.awt.datatransfer.DataFlavor[] getTransferDataFlavors()
				{
					return new java.awt.datatransfer.DataFlavor[] { flavor };
				}

				public boolean isDataFlavorSupported(java.awt.datatransfer.DataFlavor f)
				{
					return flavor.equals(f);
				}

				public Object getTransferData(java.awt.datatransfer.DataFlavor f)
						throws java.awt.datatransfer.UnsupportedFlavorException
				{
					if (!isDataFlavorSupported(f))
						throw new java.awt.datatransfer.UnsupportedFlavorException(f);
					return drag;
				}
			};
		}

		@Override
		public boolean canImport(TransferSupport support)
		{
			return actions != null && support.isDrop() && support.getComponent() == list
					&& support.isDataFlavorSupported(flavor);
		}

		@Override
		public boolean importData(TransferSupport support)
		{
			if (!canImport(support))
				return false;
			try
			{
				Drag drag = (Drag) support.getTransferable().getTransferData(flavor);
				if (drag.owner != MarkerLegend.this || drag.revision != revision)
					return false;
				actions.reorder(drag.visible, drag.selected,
						((JList.DropLocation) support.getDropLocation()).getIndex());
				return true;
			}
			catch (java.awt.datatransfer.UnsupportedFlavorException | java.io.IOException ex)
			{
				return false;
			}
		}
	}

	private static final class Drag
	{
		final MarkerLegend owner;
		final long revision;
		final List<Marker> visible, selected;

		Drag(MarkerLegend owner, long revision, List<Marker> visible, List<Marker> selected)
		{
			this.owner = owner;
			this.revision = revision;
			this.visible = visible;
			this.selected = selected;
		}
	}
