package com.windowmarkers;

import java.util.*;

final class RaidGearFilter
{
	private static final List<String[]> RANKS = ItemTaxonomy.readRows("raid-ranks.tsv", 5);
	private static final List<String[]> REQUIREMENTS = ItemTaxonomy.readRows("raid-wear-requirements.tsv", 8);

	static void filter(AutoCategories.Preset preset, Map<String, List<AutoCategories.Item>> groups, int[] levels,
			Map<Integer, String> exclusions)
	{
		filter(preset, groups, levels, false, exclusions);
	}

	static void filter(AutoCategories.Preset preset, Map<String, List<AutoCategories.Item>> groups, int[] levels,
			boolean ancientRingsUnlocked, Map<Integer, String> exclusions)
	{
		filter(preset, groups, levels, ancientRingsUnlocked, false, exclusions);
	}

	static void filter(AutoCategories.Preset preset, Map<String, List<AutoCategories.Item>> groups, int[] levels,
			boolean ancientRingsUnlocked, boolean allSkillsMaxed, Map<Integer, String> exclusions)
	{
		if (preset != AutoCategories.Preset.CHAMBERS_OF_XERIC && preset != AutoCategories.Preset.THEATRE_OF_BLOOD
				&& preset != AutoCategories.Preset.TOMBS_OF_AMASCUT)
		{
			return;
		}
		String raid = RaidRecommendations.raid(preset);
		for (Map.Entry<String, List<AutoCategories.Item>> group : groups.entrySet())
		{
			String style = group.getKey().contains("Magic") ? "Magic"
					: group.getKey().contains("Ranged") ? "Ranged" : group.getKey().endsWith("Melee") ? "Melee" : "";
			if (style.isEmpty())
			{
				continue;
			}
			List<AutoCategories.Item> candidates = new ArrayList<>(group.getValue());
			group.getValue().removeIf(item ->
			{
				if (protectedUse(item))
				{
					return false;
				}
				for (String[] lower : RANKS)
				{
					if (!lower[0].equals(raid) || !lower[1].equals(style) || !CombatEquivalence.matches(item, lower[4]))
					{
						continue;
					}
					for (String[] higher : RANKS)
					{
						if (!higher[0].equals(raid) || !higher[1].equals(style) || !higher[2].equals(lower[2])
								|| Integer.parseInt(higher[3]) >= Integer.parseInt(lower[3]))
						{
							continue;
						}
						for (AutoCategories.Item upgrade : candidates)
						{
							if (upgrade.id == item.id || protectedUse(upgrade)
									|| !CombatEquivalence.matches(upgrade, higher[4])
									|| !sameRole(lower[2], item, upgrade)
									|| !canWear(upgrade, levels, ancientRingsUnlocked, allSkillsMaxed))
							{
								continue;
							}
							String reason = group.getKey() + ": " + item.name + " → " + upgrade.name + " (Wiki "
									+ lower[2].toLowerCase(Locale.ROOT) + " ranking)";
							exclusions.merge(item.id, reason, (a, b) -> a + "; " + b);
							return true;
						}
					}
				}
				return false;
			});
		}
		groups.values().removeIf(List::isEmpty);
	}

	private static boolean canWear(AutoCategories.Item item, int[] levels, boolean ancientRingsUnlocked,
			boolean allSkillsMaxed)
	{
		if (CombatEquivalence.requiresMaxedSkills(item) && !allSkillsMaxed)
		{
			return false;
		}
		if (ItemTaxonomy.matchesAny(item, "ultor ring", "magus ring", "venator ring", "bellator ring"))
		{
			return ancientRingsUnlocked;
		}
		for (String[] row : REQUIREMENTS)
		{
			if (!CombatEquivalence.matches(item, row[0]))
			{
				continue;
			}
			for (int i = 0; i < 7; i++)
			{
				if ((i < levels.length ? levels[i] : 1) < Integer.parseInt(row[i + 1]))
				{
					return false;
				}
			}
			return true;
		}
		return false;
	}

	private static boolean sameRole(String slot, AutoCategories.Item lower, AutoCategories.Item higher)
	{
		String n = ItemTaxonomy.baseName(CombatEquivalence.familyName(lower));
		if (slot.contains("weapon"))
		{

			if (n.equals("abyssal whip"))
			{
				return CombatEquivalence.matchesAny(higher, "abyssal tentacle", "blade of saeldor");
			}
			if (n.equals("trident of the seas"))
			{
				return CombatEquivalence.matchesAny(higher, "trident of the swamp", "sanguinesti staff");
			}
			if (n.equals("warped sceptre"))
			{
				return CombatEquivalence.matchesAny(higher, "trident of the seas", "trident of the swamp",
						"sanguinesti staff");
			}
			if (n.equals("rune crossbow"))
			{
				return CombatEquivalence.matchesAny(higher, "dragon crossbow", "armadyl crossbow", "zaryte crossbow",
						"dragon hunter crossbow");
			}
			return false;
		}
		if (slot.equals("Ring"))
		{
			return (n.equals("berserker ring (i)") && CombatEquivalence.matches(higher, "ultor ring"))
					|| (n.equals("seers ring (i)") && CombatEquivalence.matches(higher, "magus ring"));
		}
		if (slot.equals("Shield"))
		{
			return (n.equals("dragon defender") && CombatEquivalence.matches(higher, "avernic defender"))
					|| (n.equals("elidinis' ward") && CombatEquivalence.matches(higher, "elidinis' ward (f)"));
		}
		return true;
	}

	private static boolean protectedUse(AutoCategories.Item item)
	{
		String n = ItemTaxonomy.baseName(CombatEquivalence.familyName(item));
		return ItemVariantState.needsActivityReview(item) || ItemTaxonomy.equipmentSet(n) != null
				|| n.startsWith("virtus ") || n.startsWith("bloodbark ") || n.startsWith("oathplate ")
				|| n.equals("serpentine helm") || n.contains("blood fury") || n.startsWith("mixed hide ");
	}
}

package com.windowmarkers;

import java.util.*;

final class RaidRecommendations
{
	private static final List<String[]> EQUIPMENT = new ArrayList<>();
	private static final List<String[]> ROOMS = ItemTaxonomy.readRows("raid-layout-rooms.tsv", 2);
	static
	{
		EQUIPMENT.addAll(ItemTaxonomy.readRows("raid-equipment.tsv", 3));
		EQUIPMENT.addAll(ItemTaxonomy.readRows("raid-context-equipment.tsv", 3));
	}

	static Map<String, List<AutoCategories.Item>> suggest(AutoCategories.Preset preset, List<AutoCategories.Item> items)
	{
		String raid = raid(preset), prefix = raid.equals("cox") ? "CoX" : raid.equals("tob") ? "ToB" : "ToA";
		Map<String, List<AutoCategories.Item>> groups = new LinkedHashMap<>();
		for (String[] row : EQUIPMENT)
		{
			if (!row[0].equals(raid))
			{
				continue;
			}
			for (AutoCategories.Item item : items)
			{
				if (!CombatEquivalence.matches(item, row[2]))
				{
					continue;
				}

				if (row[1].startsWith("Learner") && EQUIPMENT.stream().anyMatch(other -> other[0].equals(raid)
						&& !other[1].startsWith("Learner") && CombatEquivalence.matches(item, other[2])))
				{
					continue;
				}
				String group = row[1];
				if (ItemVariantState.needsActivityReview(item, group))
				{
					group = ItemVariantState.reviewGroup(item);
				}
				else if (isVoid(ItemVariantState.familyName(item)))
				{
					group = completeVoid(items) ? "Elite Void switches — choose helm for role"
							: "Incomplete Void set — review";
				}
				else if (isCrystal(ItemVariantState.familyName(item)))
				{
					group = completeCrystal(items) ? "Crystal bow setup" : "Incomplete crystal setup — review";
				}
				else if (raid.equals("tob") && group.equals("Magic"))
				{
					group = "Magic switches — freezer role";
				}
				else if (raid.equals("tob") && group.equals("Ranged"))
				{
					group = "Ranged switches — ranger/Tbow use";
				}

				if (group.startsWith("Guardians tools") || group.startsWith("Special attacks"))
				{
					group = ItemVariantState.annotate(group, item);
				}
				AutoCategories.add(groups, prefix + " " + group, item);
			}
		}
		for (AutoCategories.Item item : items)
		{
			String supply = supplyGroup(raid, ItemVariantState.familyName(item));
			if (supply != null)
			{
				if (ItemVariantState.needsActivityReview(item))
				{
					supply = ItemVariantState.reviewGroup(item);
				}
				AutoCategories.add(groups, prefix + " " + supply, item);
			}
		}
		return groups;
	}

	static String raid(AutoCategories.Preset preset)
	{
		return preset == AutoCategories.Preset.CHAMBERS_OF_XERIC ? "cox"
				: preset == AutoCategories.Preset.THEATRE_OF_BLOOD ? "tob" : "toa";
	}

	static String layoutGroup(String activity, AutoCategories.Item item)
	{
		String raid = activity.startsWith("Chambers of Xeric") ? "cox"
				: activity.startsWith("Theatre of Blood") ? "tob"
						: activity.startsWith("Tombs of Amascut") ? "toa" : "";
		if (raid.isEmpty() || ItemVariantState.needsActivityReview(item))
			return "";
		Set<String> rooms = new LinkedHashSet<>();
		String special = "";
		for (String[] row : EQUIPMENT)
			if (row[0].equals(raid) && CombatEquivalence.matches(item, row[2]))
			{
				String role = row[1];
				if (role.equals("Melee") || role.equals("Magic") || role.equals("Ranged") || role.startsWith("Learner"))
					continue;
				if (role.startsWith("Special attacks"))
					special = "Special attacks — strategy dependent";
				else
					rooms.add(role.replace("Guardians tools (room dependent)", "Guardians — pickaxes"));
			}
		if (!rooms.isEmpty())
			return String.join(" / ", rooms);
		String supply = supplyGroup(raid, ItemVariantState.familyName(item));
		return supply != null ? supply : special;
	}

	static Set<String> layoutGroups(String activity, AutoCategories.Item item)
	{
		Set<String> groups = new LinkedHashSet<>();
		if (ItemVariantState.needsActivityReview(item))
			return groups;
		for (String[] row : ROOMS)
		{
			ActivitySetups.Setup setup = ActivitySetups.byId(row[0]);
			if (setup != null && setup.activity.equals(activity) && setup.itemIds.contains(item.id))
			{
				String label = row[1];
				if (label.equals("Guardians — pickaxes")
						&& !"Tools".equals(ItemTaxonomy.weaponRole(CombatEquivalence.familyName(item))))
					label = "Guardians — defence-drain specials";
				groups.add(label);
			}
		}
		String utility = layoutGroup(activity, item);
		if (groups.isEmpty() && !utility.isEmpty())
			groups.add(utility);
		return groups;
	}

	static String roomNote(String activity, String heading)
	{
		for (String[] row : ROOMS)
			if (row[1].equals(heading)
					|| heading.equals("Guardians — defence-drain specials") && row[1].equals("Guardians — pickaxes"))
			{
				ActivitySetups.Setup setup = ActivitySetups.byId(row[0]);
				if (setup != null && setup.activity.equals(activity))
					return activity + " / " + setup.label + ". " + setup.notes;
			}
		return "";
	}

	static Set<String> groups()
	{
		Set<String> result = new TreeSet<>();
		for (String raid : Arrays.asList("cox", "tob", "toa"))
		{
			String prefix = raid.equals("cox") ? "CoX" : raid.equals("tob") ? "ToB" : "ToA";
			Set<String> roles = new TreeSet<>();
			for (String[] row : EQUIPMENT)
				if (row[0].equals(raid))
				{
					String role = row[1];
					if (raid.equals("tob") && role.equals("Magic"))
						role = "Magic switches — freezer role";
					if (raid.equals("tob") && role.equals("Ranged"))
						role = "Ranged switches — ranger/Tbow use";
					roles.add(role);
				}
			roles.addAll(Arrays.asList("Elite Void switches — choose helm for role", "Incomplete Void set — review",
					"Crystal bow setup", "Incomplete crystal setup — review"));
			roles.addAll(Arrays.asList("Needs repair/charge — review", "Check charges — review",
					"Unverified item identity — review", "Activity restrictions — review", "Check item use — review",
					"Reduced function — review", "Preparation needed — review", "Check contents — review",
					"Empty — review"));
			for (String name : Arrays.asList("saradomin brew", "super restore", "prayer potion", "stamina potion",
					"sanfew serum", "super combat potion", "ranging potion", "anglerfish", "cooked karambwan",
					"saturated heart", "salve amulet (e)", "salve amulet(ei)", "water rune", "blood rune", "air rune",
					"antidote++", "keris partisan of the sun", "rune pouch"))
			{
				String group = supplyGroup(raid, name);
				if (group != null)
					roles.add(group);
			}
			for (String role : roles)
				result.add(prefix + " " + role);
		}
		return result;
	}

	static String source(AutoCategories.Preset preset)
	{
		switch (preset)
		{
			case CHAMBERS_OF_XERIC:
				return "https://oldschool.runescape.wiki/w/Chambers_of_Xeric/Strategies";
			case THEATRE_OF_BLOOD:
				return "https://oldschool.runescape.wiki/w/Theatre_of_Blood/Strategies";
			case TOMBS_OF_AMASCUT:
				return "https://oldschool.runescape.wiki/w/Tombs_of_Amascut/Strategies";
			default:
				return "https://oldschool.runescape.wiki/w/Weapons/Types";
		}
	}

	static boolean defaultSelected(String group)
	{
		return !group.startsWith("Other") && !group.contains("review") && !group.contains("Incomplete")
				&& !group.contains("Needs repair");
	}

	private static boolean owns(List<AutoCategories.Item> items, String... names)
	{
		return items.stream()
				.anyMatch(i -> !ItemVariantState.needsActivityReview(i) && ItemTaxonomy.matchesAny(i, names));
	}

	private static boolean completeVoid(List<AutoCategories.Item> items)
	{
		return owns(items, "elite void top") && owns(items, "elite void robe") && owns(items, "void knight gloves")
				&& owns(items, "void melee helm", "void ranger helm", "void mage helm");
	}

	private static boolean completeCrystal(List<AutoCategories.Item> items)
	{
		return owns(items, "crystal helm") && owns(items, "crystal body") && owns(items, "crystal legs")
				&& owns(items, "bow of faerdhinen");
	}

	private static boolean isVoid(String name)
	{
		String set = ItemTaxonomy.equipmentSet(name);
		return set != null && set.startsWith("Void —");
	}

	private static boolean isCrystal(String name)
	{
		String set = ItemTaxonomy.equipmentSet(name);
		return set != null && set.startsWith("Crystal —");
	}

	static String supplyGroup(String raid, String name)
	{
		String n = ItemTaxonomy.baseName(name);

		if (raid.equals("tob"))
		{
			if (oneOf(n, "saradomin brew", "super restore", "prayer potion", "stamina potion"))
			{
				return "Restoration supplies";
			}
			if (oneOf(n, "super combat potion", "divine super combat potion", "ranging potion"))
			{
				return "Combat boosts — role/prepot";
			}
			if (oneOf(n, "anglerfish"))
			{
				return "Food — overheal/Maiden";
			}
			if (oneOf(n, "cooked karambwan"))
			{
				return "Food — combo eating";
			}
			if (oneOf(n, "saturated heart", "imbued heart"))
			{
				return "Magic boost — freezer role";
			}
			if (oneOf(n, "salve amulet (e)", "salve amulet(ei)", "salve amulet (ei)"))
			{
				return "Bloat — undead melee";
			}
			if (oneOf(n, "water rune", "death rune", "blood rune"))
			{
				return "Ice Barrage runes — Ancients/freezer";
			}
		}
		else if (raid.equals("cox"))
		{
			if (oneOf(n, "saradomin brew", "super restore", "prayer potion"))
			{
				return "Restoration supplies";
			}
			if (oneOf(n, "stamina potion"))
			{
				return "Stamina — solo Olm/running";
			}
			if (oneOf(n, "sanfew serum"))
			{
				return "Poison protection — shamans";
			}
			if (oneOf(n, "super combat potion", "ranging potion"))
			{
				return "Combat boosts — layout/prepot";
			}
			if (oneOf(n, "anglerfish"))
			{
				return "Food — pre-raid overheal";
			}
			if (oneOf(n, "salve amulet(ei)", "salve amulet (ei)"))
			{
				return "Mystics — no Shadow setup";
			}
		}
		else if (raid.equals("toa"))
		{
			if (oneOf(n, "saradomin brew"))
			{
				return "Brews — excludes Dehydration";
			}
			if (oneOf(n, "super restore", "prayer potion", "sanfew serum"))
			{
				return "Prayer/restoration supplies";
			}
			if (oneOf(n, "super combat potion", "divine super combat potion", "ranging potion",
					"divine ranging potion"))
			{
				return "Combat boosts — path/prepot";
			}
			if (oneOf(n, "antidote++"))
			{
				return "Poison protection — path dependent";
			}
			if (oneOf(n, "anglerfish"))
			{
				return "Food — pre-raid (On a Diet restricts eating)";
			}
			if (oneOf(n, "saturated heart", "imbued heart"))
			{
				return "Magic boost — pre-raid";
			}
			if (oneOf(n, "keris partisan of the sun"))
			{
				return "Healing utility — needs special energy";
			}
		}
		if (oneOf(n, "rune pouch", "divine rune pouch", "book of the dead"))
		{
			return "Spell supplies — choose spellbook";
		}
		if (oneOf(n, "air rune", "cosmic rune", "blood rune"))
		{
			return "Thrall runes — Arceuus only";
		}
		return null;
	}

	private static boolean oneOf(String name, String... names)
	{
		return Arrays.asList(names).contains(name);
	}
}

package com.windowmarkers;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ProfileChanged;

@Singleton
final class ReleaseNotesNotice
{
	static final String RELEASE = "2026-11-19-presets";
	static final String SEEN_KEY = "releaseNotesShown";
	private static final String[] UPDATES = {
			"Updated Wiki setups with activity-specific owned alternatives and separate combat methods.",
			"Missing equipment now appears as a faded recommendation instead of leaving an unexplained gap.",
			"Presets distinguish banked, carried and equipped items, with potion quantities and requirement notes.",
			"Hide setups or alternative rows with x; restore them from Hidden sections at the top of the view.",
			"Repeated banked inventory items now retain their normal withdrawal actions from every copy." };

	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private ConfigManager configManager;
	@Inject
	private ChatMessageManager chat;
	@Inject
	private net.runelite.client.eventbus.EventBus eventBus;
	private volatile boolean running;
	private volatile int generation;

	public synchronized void start()
	{
		if (running)
			return;
		running = true;
		generation++;
		eventBus.register(this);
		schedule();
	}

	public synchronized void stop()
	{
		if (!running)
			return;
		running = false;
		generation++;
		eventBus.unregister(this);
	}

	private void schedule()
	{
		final int scheduledGeneration = generation;
		clientThread.invokeLater(() ->
		{
			if (running && generation == scheduledGeneration)
				showIfNeeded();
		});
	}

	private void showIfNeeded()
	{
		if (client.getGameState() != GameState.LOGGED_IN
				|| RELEASE.equals(configManager.getConfiguration("windowmarkers", SEEN_KEY)))
			return;
		send("Updates:<br>* " + String.join("<br>* ", UPDATES));
		configManager.setConfiguration("windowmarkers", SEEN_KEY, RELEASE);
	}

	private void send(String text)
	{
		String message = new ChatMessageBuilder().append(ChatColorType.NORMAL).append("[")
				.append(ChatColorType.HIGHLIGHT).append("Improved Banking").append(ChatColorType.NORMAL).append("] ")
				.build() + text;
		chat.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE).runeLiteFormattedMessage(message).build());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (running && event.getGameState() == GameState.LOGGED_IN)
			schedule();
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{

		generation++;
		if (running)
			schedule();
	}
}

package com.windowmarkers;

import java.util.*;

final class SearchQuery
{
	final String text;
	final Set<Integer> tiers;

	private SearchQuery(String text, Set<Integer> tiers)
	{
		this.text = text;
		this.tiers = Collections.unmodifiableSet(tiers);
	}

	static SearchQuery parse(String raw)
	{
		List<String> words = new ArrayList<>();
		Set<Integer> tiers = new HashSet<>();
		for (String word : SearchText.normalize(raw).split(" +"))
		{

			if (SupplySearch.foodQuery(raw) && word.matches("[0-9]+"))
			{
				words.add(word);
				continue;
			}
			switch (word)
			{
				case "1":
				case "1st":
				case "first":
				case "bis":
					tiers.add(1);
					break;
				case "2":
				case "2nd":
				case "second":
					tiers.add(2);
					break;
				case "3":
				case "3rd":
				case "third":
					tiers.add(3);
					break;
				default:
					words.add(word);
			}
		}
		return new SearchQuery(String.join(" ", words), tiers);
	}

	boolean accepts(ItemCatalogueIndex.Rank rank)
	{
		return tiers.isEmpty() || rank != null && tiers.contains(rank.tier);
	}
}

package com.windowmarkers;

import java.text.Normalizer;
import java.util.Locale;

final class SearchText
{
	static String normalize(String text)
	{
		return Normalizer.normalize(text == null ? "" : text, Normalizer.Form.NFKD).replaceAll("\\p{M}", "")
				.toLowerCase(Locale.ROOT).replace("'", "").replace("’", "").replaceAll("[^a-z0-9]+", " ").trim();
	}

	static int score(String text, String query)
	{
		return normalizedScore(normalize(text), normalize(query));
	}

	static boolean containsWords(String text, String query)
	{
		for (String word : query.split(" +"))
			if (!text.contains(word))
				return false;
		return true;
	}

	static String correctWholeWords(java.util.Set<String> vocabulary, String terms)
	{
		java.util.List<String> corrected = new java.util.ArrayList<>();
		for (String term : terms.split(" +"))
		{
			String replacement = term;
			if (term.length() >= 4 && !vocabulary.contains(term))
			{
				int allowed = term.length() < 8 ? 1 : 2, best = allowed + 1;
				boolean tied = false;
				for (String candidate : vocabulary)
				{
					if (Math.abs(candidate.length() - term.length()) > allowed)
						continue;
					int cost = distance(candidate, term);
					if (cost < best)
					{
						best = cost;
						replacement = candidate;
						tied = false;
					}
					else if (cost == best)
						tied = true;
				}
				if (best > allowed || tied)
					replacement = term;
			}
			corrected.add(replacement);
		}
		return String.join(" ", corrected);
	}

	static int normalizedScore(String text, String query)
	{
		if (query.isEmpty() || text.equals(query))
			return 0;
		if (query.length() > 256)
			return Integer.MAX_VALUE;
		if (text.startsWith(query))
			return 1;
		if (text.contains(query))
			return 2;
		int score = 3;
		String[] words = text.split(" ");
		for (String needle : query.split(" "))
		{
			if (text.contains(needle))
				continue;
			int allowed = needle.length() < 4 ? 0 : needle.length() < 8 ? 1 : 2;
			boolean match = false;
			for (String word : words)
				if (matchesWord(word, needle, allowed))
				{
					match = true;
					break;
				}
			if (!match)
				return Integer.MAX_VALUE;
			score += 2;
		}
		return score;
	}

	private static boolean matchesWord(String word, String needle, int allowed)
	{
		if (allowed == 0)
			return false;

		for (int length = Math.max(1, needle.length() - allowed); length <= Math.min(word.length(),
				needle.length() + allowed); length++)
			if (distance(word.substring(0, length), needle) <= allowed)
				return true;
		return false;
	}

	static int distance(String a, String b)
	{
		int[][] d = new int[a.length() + 1][b.length() + 1];
		for (int i = 0; i <= a.length(); i++)
			d[i][0] = i;
		for (int j = 0; j <= b.length(); j++)
			d[0][j] = j;
		for (int i = 1; i <= a.length(); i++)
			for (int j = 1; j <= b.length(); j++)
			{
				d[i][j] = Math.min(d[i - 1][j] + 1,
						Math.min(d[i][j - 1] + 1, d[i - 1][j - 1] + (a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1)));
				if (i > 1 && j > 1 && a.charAt(i - 1) == b.charAt(j - 2) && a.charAt(i - 2) == b.charAt(j - 1))
					d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1);
			}
		return d[a.length()][b.length()];
	}
}

package com.windowmarkers;

import java.util.*;

final class SetupActivityRules
{
	private static final Map<String, String[]> RULES = new HashMap<>();
	static
	{
		for (String[] row : ItemTaxonomy.readRows("setup-activity-rules.tsv", 4))
			RULES.put(row[0], row);
	}

	static boolean fallbackSlot(String activity, int slot)
	{
		String[] rule = RULES.get(activity);
		return rule != null && !rule[1].equals("guide") && slot != 3 && slot != 13
				&& !Arrays.asList(rule[2].split(",")).contains(Integer.toString(slot));
	}

	static String purpose(String activity, String style)
	{
		String[] rule = RULES.get(activity);
		return rule != null && rule[1].equals("defence") ? style + " defence" : style;
	}

	static String note(String activity)
	{
		String[] rule = RULES.get(activity);
		return rule == null ? "Check this method's equipment and supply requirements." : rule[3];
	}

	static boolean sameMethod(SetupLoadout.Table a, SetupLoadout.Table b)
	{
		return a.context.equalsIgnoreCase(b.context) && a.style.equalsIgnoreCase(b.style);
	}

	static boolean inventoryCompatible(String activity, SetupLoadout.Table gear, SetupLoadout.Table inventory)
	{
		if (activity.equals("Abyssal Sire"))
			return true;
		String a = method(gear.context), b = method(inventory.context);
		return a.isEmpty() || b.isEmpty() || a.equals(b);
	}

	private static String method(String context)
	{
		return context.toLowerCase(Locale.ROOT).replaceAll("\\b(?:equipment|inventory|setup|setups|recommended)\\b", "")
				.replaceAll("[ /]+", " ").trim();
	}

	private SetupActivityRules()
	{
	}
}

package com.windowmarkers;

import java.util.*;

final class SetupCompletion
{
	private SetupCompletion()
	{
	}

	static String style(String label)
	{
		String text = label.toLowerCase(Locale.ROOT);
		int styles = (text.contains("magic") || text.contains("mage") ? 1 : 0)
				+ (text.contains("ranged") || text.contains("range ") || text.equals("range") ? 1 : 0)
				+ (text.contains("melee") || text.contains("flinching") ? 1 : 0);
		if (styles > 1)
			return "";
		if (text.contains("magic") || text.contains("mage"))
			return "magic";
		if (text.contains("ranged") || text.contains("range ") || text.equals("range"))
			return "ranged";
		if (text.contains("melee") || text.contains("flinching"))
			return "melee";
		return "";
	}

	static Set<Integer> protectedSlots(String activity)
	{
		String name = activity.toLowerCase(Locale.ROOT);
		if (name.contains("lizardman shaman"))
			return new HashSet<>(Arrays.asList(0, 4, 7, 9, 10));
		if (name.contains("wyvern") || name.contains("basilisk"))
			return Collections.singleton(5);
		if (name.contains("smoke devil"))
			return Collections.singleton(0);
		return Collections.emptySet();
	}

	static void fill(Map<Integer, List<Integer>> gear, Map<Integer, ItemCatalogueIndex.Item> owned, String style,
			Map<Integer, String> notes, Set<Integer> protectedSlots)
	{

		int[] boots = style.equals("magic")
				? new int[] { 31097, 31093, 31095, 31096, 31088, 31091, 31092, 31094, 13235 }
				: style.equals("ranged") ? new int[] { 31097, 31092, 31094, 31096, 31088, 31091, 31093, 31095, 13237 }
						: new int[] { 31097, 31091, 31094, 31095, 13239, 31088, 31092, 31093, 31096, 11840 };
		List<Integer> existing = gear.getOrDefault(10, Collections.emptyList());

		if (!protectedSlots.contains(10) && (existing.isEmpty() || existing.stream()
				.anyMatch(id -> id >= 31088 && id <= 31097 || id == 13235 || id == 13237 || id == 13239)))
		{
			List<Integer> choices = new ArrayList<>();
			for (int id : boots)
			{
				ItemCatalogueIndex.Item item = owned.get(id);
				if (item != null && item.slot == 10 && !ItemVariantState.needsActivityReview(item.fact))
					choices.add(id);
			}
			for (int id : existing)
				if (!choices.contains(id))
					choices.add(id);
			if (!choices.isEmpty())
			{
				gear.put(10, choices);
				for (int id : choices)
					if (!existing.contains(id))
						notes.put(id,
								"Owned boots completing this style's equipment. Avernic upgrades apply only to their associated combat style; check equip requirements.");
			}
		}
		if (gear.containsKey(13))
			return;
		ItemCatalogueIndex.Item weapon = gear.containsKey(3) ? owned.get(gear.get(3).get(0)) : null;
		List<Integer> blessings = new ArrayList<>();
		for (int id : new int[] { 22947, 22945, 20220, 20223, 20226, 20229, 20232, 20235, 22943, 22941 })
		{
			ItemCatalogueIndex.Item item = owned.get(id);
			if (item != null && item.slot == 13 && !ItemVariantState.needsActivityReview(item.fact)
					&& SetupEquipmentChoice.allowed(item, "", weapon, owned.values()))
			{
				blessings.add(id);
				notes.put(id,
						"Owned prayer-slot alternative. A blessing does not replace ammunition required by the selected weapon.");
			}
		}
		if (!blessings.isEmpty())
			gear.put(13, blessings);
	}
}

package com.windowmarkers;

import java.util.*;

final class SetupEquipmentChoice
{
	private SetupEquipmentChoice()
	{
	}

	static boolean allowed(ItemCatalogueIndex.Item item, String note, ItemCatalogueIndex.Item weapon,
			Collection<ItemCatalogueIndex.Item> owned)
	{
		return allowed(item, note, weapon, owned, false);
	}

	static boolean allowed(ItemCatalogueIndex.Item item, String note, ItemCatalogueIndex.Item weapon,
			Collection<ItemCatalogueIndex.Item> owned, boolean onTask)
	{
		String text = note.toLowerCase(Locale.ROOT), name = ItemVariantState.familyName(item.fact);
		String main = weapon == null ? "" : ItemVariantState.familyName(weapon.fact);
		if (item.slot == 13)
		{
			boolean blessing = name.contains("blessing");
			if (Arrays.asList("toxic blowpipe", "blazing blowpipe", "bow of faerdhinen", "crystal bow", "craw's bow",
					"webweaver bow").contains(main))
				return blessing;
			SupplySearch.Query ammo = weapon == null ? null : SupplySearch.parse("ammo " + main);
			if (ammo != null)
				return blessing ? ammo.ids.isEmpty() : ammo.ids.contains(item.id);

			if (!blessing)
				return false;
		}

		if (text.isEmpty() || text.startsWith("set to ") || text.startsWith("use stab attack style")
				|| text.startsWith("on crush") || text.startsWith("on stab") || text.startsWith("on slash"))
			return true;

		if (item.id == 22947 && text.contains("diary"))
			return true;
		if (text.startsWith("only for phase "))
			return true;
		if (text.contains("after completing") || text.contains("elite kourend") || text.contains("diary"))
			return false;
		boolean taskRequired = text.contains("slayer task") || text.contains("slayer assignment")
				|| text.contains("task only") || text.contains("assigned as a slayer") || text.contains("on task");
		if (taskRequired && !onTask)
			return false;
		if (text.startsWith("only on ") && !taskRequired)
			return false;
		if (text.contains("blood moon") && (text.contains("full") || text.contains("set")))
		{
			if (text.contains("without full"))
				return true;
			return (main.equals("dual macuahuitl") || name.equals("dual macuahuitl")) && owns(owned, "blood moon helm")
					&& owns(owned, "blood moon chestplate") && owns(owned, "blood moon tassets");
		}
		if (text.contains("void") && (text.contains("full") || text.startsWith("with ") || text.contains("only")))
			return !(text.contains("do not use with emberlight")
					&& (main.equals("emberlight") || main.equals("arclight") || main.startsWith("scythe of vitur")))
					&& ownsPrefix(owned, "void ", 0)
					&& (owns(owned, "elite void top") || owns(owned, "void knight top"))
					&& (owns(owned, "elite void robe") || owns(owned, "void knight robe"))
					&& owns(owned, "void knight gloves");
		if (text.contains("when using scythe") || text.startsWith("with scythe"))
			return main.startsWith("scythe of vitur");
		if (text.contains("if using a crossbow") || text.contains("if bringing a crossbow"))
			return main.contains("crossbow");
		if (text.contains("if using a twisted bow") || text.equals("with a twisted bow"))
			return main.equals("twisted bow");
		if (text.contains("if using a 1-handed weapon") || text.contains("with 1 handed staffs"))
			return true;
		if (text.contains("bow of faerdhinen")
				&& (text.startsWith("with ") || text.startsWith("only ") || text.startsWith("if ")))
			return main.equals("bow of faerdhinen") && (!text.contains("full crystal")
					|| owns(owned, "crystal helm") && owns(owned, "crystal body") && owns(owned, "crystal legs"));

		return taskRequired || !(text.startsWith("if ") || text.startsWith("when ") || text.startsWith("only ")
				|| text.startsWith("with ") || text.startsWith("without ") || text.startsWith("requires ")
				|| text.startsWith("best used with ") || text.startsWith("use only "));
	}

	private static boolean owns(Collection<ItemCatalogueIndex.Item> owned, String family)
	{
		return owned.stream().anyMatch(i -> !ItemVariantState.needsActivityReview(i.fact)
				&& family.equals(ItemVariantState.familyName(i.fact)));
	}

	private static boolean ownsPrefix(Collection<ItemCatalogueIndex.Item> owned, String prefix, int slot)
	{
		return owned.stream().anyMatch(i -> i.slot == slot && !ItemVariantState.needsActivityReview(i.fact)
				&& ItemVariantState.familyName(i.fact).startsWith(prefix));
	}

	static List<Integer> inventoryAlternatives(List<Integer> exact)
	{

		List<Integer> result = InventoryPotionDoses.alternatives(exact);
		if (exact.contains(8013))
			for (int id : new int[] { 9789, 9790, 13280, 13342 })
				if (!result.contains(id))
					result.add(id);

		if (exact.stream().anyMatch(id -> id >= 11866 && id <= 11873) && !result.contains(21268))
			result.add(21268);
		return result;
	}

	static String inventoryAlternativeNote(List<Integer> exact)
	{
		return exact.contains(8013)
				? "Owned home-teleport alternative. Construction and ordinary Max capes retain the home teleport; combat Max capes do not. Check your house settings and facilities."
				: exact.stream().anyMatch(id -> id >= 11866 && id <= 11873)
						? "Owned eternal Slayer ring replaces the finite ring's teleports. Destination unlocks still apply; unlimited charges do not unlock quest-gated destinations."
						: "Owned combat variant or activity-listed ranged accessory alternative. Lower-tier gear can have different stats and effects; this does not inherit the example item's guide rank.";
	}
}

package com.windowmarkers;

import java.util.*;

final class SetupEquipmentExamples
{
	static void fill(SetupLoadout plan, Map<Integer, ItemCatalogueIndex.Item> owned, SetupPlayerState state)
	{
		if (plan == null)
			return;
		for (SetupLoadout section : plan.sections())
		{
			SetupLoadout.Table table = section.equipmentTable();
			if (table == null)
				continue;
			List<SetupLoadout.Field> fields = new ArrayList<>(table.fields);
			fields.sort(Comparator.comparingInt((SetupLoadout.Field f) -> f.slot() == 3 ? 0 : 1)
					.thenComparingInt(SetupLoadout.Field::order));
			Set<Integer> slots = new LinkedHashSet<>();
			for (SetupLoadout.Field field : fields)
				if (field.slot() >= 0)
					slots.add(field.slot());
			List<ItemCatalogueIndex.Item> wearing = new ArrayList<>();
			for (List<Integer> ids : section.equipment.values())
				if (!ids.isEmpty())
					wearing.add(owned.get(ids.get(0)));
			ItemCatalogueIndex.Item weapon = section.equipment.containsKey(3)
					? owned.get(section.equipment.get(3).get(0)) : null;
			for (int slot : slots)
			{
				if (section.equipment.containsKey(slot))
					continue;
				ItemCatalogueIndex.Item example = choose(section, fields, slot, weapon, wearing, state);
				if (example != null)
				{
					section.equipmentExample.put(slot, example.id);
					wearing.add(example);
					if (slot == 3)
						weapon = example;
				}
			}
		}
	}

	private static ItemCatalogueIndex.Item choose(SetupLoadout section, List<SetupLoadout.Field> fields, int slot,
			ItemCatalogueIndex.Item weapon, List<ItemCatalogueIndex.Item> wearing, SetupPlayerState state)
	{
		ActivitySetups.Setup setup = ActivitySetups.byId(section.equipmentSource);
		for (boolean checkConditions : new boolean[] { true, false })
			for (SetupLoadout.Field field : fields)
				if (field.slot() == slot)
					for (int id : field.ids)
					{
						ItemCatalogueIndex.Item item = ItemCatalogueIndex.guideItem(id);
						if (item == null || item.slot != slot || !ItemVariantState.canPreviewEquipment(item.fact)
								|| !SetupItemRequirements.reviewReason(setup.id, item.fact).isEmpty()
								|| ItemVariantState.needsRankReview(item.fact, setup.activity, setup.label))
							continue;
						String note = field.itemNotes.getOrDefault(id, field.note);
						if (!SetupEquipmentChoice.allowed(item, checkConditions ? note : "", weapon, wearing,
								state.onTask(section.activity)))
							continue;
						String locked = state.locked(item);
						section.equipmentNotes.put(id,
								("Wiki equipment suggestion. No suitable owned item selected; preview only. "
										+ ItemVariantState.annotate(note, item.fact)
										+ (locked.isEmpty() ? "" : " Requires: " + locked + ".")).trim());
						return item;
					}
		return null;
	}

	private SetupEquipmentExamples()
	{
	}
}

package com.windowmarkers;

import java.util.*;

final class SetupFallbacks
{
	private static final List<String[]> ALTERNATIVES = ItemTaxonomy.readRows("setup-fallbacks.tsv", 3);

	static void fill(Map<Integer, List<Integer>> gear, ActivitySetups.Setup setup, SetupLoadout.Table table,
			Map<Integer, ItemCatalogueIndex.Item> owned, Collection<ItemCatalogueIndex.Item> wearing,
			Map<Integer, String> notes)
	{
		String style = SetupCompletion.style(table.style);
		if (style.isEmpty())
			return;
		String purpose = SetupActivityRules.purpose(setup.activity, style);
		Set<Integer> missing = new HashSet<>();
		for (SetupLoadout.Field field : table.fields)
			if (!field.ids.isEmpty() && !gear.containsKey(field.slot())
					&& SetupActivityRules.fallbackSlot(setup.activity, field.slot()))
				missing.add(field.slot());
		ItemCatalogueIndex.Item weapon = gear.containsKey(3) ? owned.get(gear.get(3).get(0)) : null;
		for (String[] row : ALTERNATIVES)
		{
			int slot = Integer.parseInt(row[1]);
			if (!missing.contains(slot) || !row[0].equals(purpose) && !row[0].equals("all"))
				continue;
			owned.values().stream().filter(item -> item.slot == slot && CombatEquivalence.matches(item.fact, row[2]))
					.sorted(Comparator.comparingInt(item -> item.id)).forEach(item ->
					{
						if (!SetupLoadout.equipmentReady(setup, item)
								|| !SetupEquipmentChoice.allowed(item, "", weapon, wearing))
							return;
						List<Integer> choices = gear.computeIfAbsent(slot, key -> new ArrayList<>());
						if (!choices.contains(item.id))
						{
							choices.add(item.id);
							notes.put(item.id, "Owned " + purpose
									+ " fallback for a missing guide slot; no Wiki tier assigned. Check method requirements.");
						}
					});
		}
	}

	private SetupFallbacks()
	{
	}
}

package com.windowmarkers;

import java.util.*;
import net.runelite.api.*;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
