			this.text = text;
			this.x = x;
			this.y = y;
			this.emptySlot = emptySlot;
			this.setupId = setupId;
		}

		String displayText(int width)
		{
			return MarkerPresentation.fit(text, METRICS,
					Math.min(380, width - x - 6) - (setupId.isEmpty() ? 0 : 22));
		}

		int buttonX(int width)
		{
			return x + METRICS.stringWidth(displayText(width)) + 6;
		}
	}

	static final class InventoryNote
	{
		final String text;
		final int x, y;

		InventoryNote(String text, int x, int y)
		{
			this.text = text;
			this.x = x;
			this.y = y;
		}
	}

	private static final int[][] EQUIPMENT = { { 0, 1, 0 }, { 1, 0, 1 }, { 2, 1, 1 }, { 13, 2, 1 }, { 3, 0, 2 },
			{ 4, 1, 2 }, { 5, 2, 2 }, { 7, 1, 3 }, { 9, 0, 4 }, { 10, 1, 4 }, { 12, 2, 4 } };
	private static final String[] BUCKET_NAMES = { "Head alternatives", "Cape alternatives", "Neck alternatives",
			"Weapon alternatives", "Body alternatives", "Off-hand alternatives", "Leg alternatives",
			"Glove alternatives", "Boot alternatives", "Ring alternatives", "Ammunition", "Tools", "Food", "Potions",
			"Runes", "Other supplies", "Other", "Other", "Other", "Needs repair / charging / review" };

	static int[] apply(Widget container, ItemManager manager, int columns, int pitch, int padding, SetupLoadout plan,
			Map<Integer, ItemCatalogueIndex.Rank> ranks, List<Heading> headings)
	{
		return apply(container, manager, columns, pitch, padding, plan, ranks, headings, null, new ArrayList<>());
	}

	static int[] apply(Widget container, ItemManager manager, int columns, int pitch, int padding, SetupLoadout plan,
			Map<Integer, ItemCatalogueIndex.Rank> ranks, List<Heading> headings, SetupInventoryWidgets copies,
			List<InventoryNote> notes)
	{
		return apply(container, manager, columns, pitch, padding, plan, ranks, headings, copies, notes, null);
	}

	static int[] apply(Widget container, ItemManager manager, int columns, int pitch, int padding, SetupLoadout plan,
			Map<Integer, ItemCatalogueIndex.Rank> ranks, List<Heading> headings, SetupInventoryWidgets copies,
			List<InventoryNote> notes, Set<String> hiddenSetups)
	{
		headings.clear();
		notes.clear();
		if (plan == null)
			return apply(container, manager, columns, pitch, padding);
		Widget[] children = container.getDynamicChildren();
		if (children == null)
			children = new Widget[0];
		List<Widget> cells = new ArrayList<>();
		Map<Integer, Widget> byId = new HashMap<>();
		int oldEnd = 0;
		for (Widget cell : children)
			if (cell != null && !cell.isSelfHidden() && cell.getItemId() >= 0 && cell.getItemId() != 6512
					&& cell.getOriginalWidth() == 36 && cell.getOriginalHeight() == 32)
			{
				cells.add(cell);
				byId.putIfAbsent(manager.canonicalize(cell.getItemId()), cell);
				oldEnd = Math.max(oldEnd, cell.getOriginalY() + 36);
			}
		if (cells.isEmpty() && !plan.hasExamples())
			return null;
		List<Widget> runes = new ArrayList<>();
		for (Widget cell : cells)
			if (bucket(manager.canonicalize(cell.getItemId()), manager, plan.activity) == 14)
				runes.add(cell);
		runes.sort(Comparator.comparingInt(Widget::getItemId));
		Set<Widget> placed = Collections.newSetFromMap(new IdentityHashMap<>());
		Set<Map<Integer, SetupLoadout.Field>> shownInventories = new HashSet<>();
		int y = padding + (HiddenWikiSetups.forPlan(hiddenSetups, plan).isEmpty() ? 0 : 22);
		for (SetupLoadout section : plan.sections())
		{
			if (hiddenSetups != null && hiddenSetups.contains(section.equipmentSource))
				continue;
			boolean hideable = hiddenSetups != null && !section.equipmentSource.isEmpty();
			boolean hasTitle = plan.sectionCount() > 1 || section.notEnoughGear();
			if (hasTitle)
			{
				String title = section.sectionName.isEmpty() ? section.activity : section.sectionName;
				headings.add(
						new Heading(title + (section.notEnoughGear() ? " - not enough gear in bank" : ""), 51, y + 12,
								false, hideable ? section.equipmentSource : ""));
				y += 18;
			}
			int firstHeading = headings.size();
			y = placeSection(container, manager, columns, pitch, y, section, byId, placed, headings, copies, notes,
					shownInventories.add(section.inventoryExample), runes);
			if (hideable && !hasTitle)
			{
				Heading heading = headings.get(firstHeading);
				headings.set(firstHeading, new Heading(heading.text, heading.x, heading.y, false, section.equipmentSource));
			}
			runes = Collections.emptyList();
		}
		Map<String, List<Widget>> extras = new TreeMap<>();
		for (Widget cell : cells)
			if (!placed.contains(cell))
			{
				int id = manager.canonicalize(cell.getItemId()), bucket = bucket(id, manager, plan.activity);
				var definition = manager.getItemComposition(id);
				Set<String> roles = definition == null ? Collections.emptySet()
						: RaidRecommendations.layoutGroups(plan.activity, new AutoCategories.Item(id,
								definition.getName(), bucket < 11, definition.getInventoryActions(), 0, 0, 0));
				if (roles.isEmpty())
					extras.computeIfAbsent(
							String.format(Locale.ROOT, "%02d:%s", bucket, BUCKET_NAMES[Math.min(19, bucket)]),
							k -> new ArrayList<>()).add(cell);
				else
					for (String role : roles)
						extras.computeIfAbsent("11:" + role, k -> new ArrayList<>()).add(cell);
			}
		for (var entry : extras.entrySet())
		{
			String id = HiddenWikiSetups.rowId(plan.activity, entry.getKey());
			if (hiddenSetups != null && hiddenSetups.contains(id))
				continue;
			List<Widget> group = entry.getValue();
			group.sort(Comparator.comparingInt((Widget cell) ->
			{
				var rank = ranks.get(manager.canonicalize(cell.getItemId()));
				return rank == null || rank.tier <= 0 ? Integer.MAX_VALUE : rank.tier;
			}).thenComparingInt(Widget::getItemId));
			String heading = entry.getKey().substring(3);
			headings.add(new Heading(heading, 51, y + 12, false, hiddenSetups == null ? "" : id));
			y += 18;
			String roomNote = RaidRecommendations.roomNote(plan.activity, heading);
			for (int i = 0; i < group.size(); i++)
			{
				Widget cell = group.get(i);
				if (!placed.add(cell))
				{
					if (copies == null)
						continue;
					cell = copies.add(container, cell, cell.getItemId(), manager);
				}
				place(cell, 51 + (i % columns) * pitch, y + (i / columns) * 36);
				if (!roomNote.isEmpty())
					notes.add(new InventoryNote(roomNote, 51 + (i % columns) * pitch, y + (i / columns) * 36));
			}
			y += ((group.size() + columns - 1) / columns) * 36 + 8;
		}
		if (hiddenSetups != null && copies != null)
			for (Widget cell : cells)
				if (!placed.contains(cell))
					copies.hide(container, cell);
		return new int[] { oldEnd, y };
	}

	private static int placeSection(Widget container, ItemManager manager, int columns, int pitch, int padding,
			SetupLoadout plan, Map<Integer, Widget> byId, Set<Widget> placed, List<Heading> headings,
			SetupInventoryWidgets copies, List<InventoryNote> notes, boolean showInventory, List<Widget> runes)
	{
		Map<Integer, Widget> chosen = new HashMap<>();
		for (var entry : plan.equipment.entrySet())
			for (int id : entry.getValue())
				if (byId.containsKey(id) && !plan.heldEquipment.contains(entry.getKey()))
				{
					chosen.put(entry.getKey(), byId.get(id));
					break;
				}

		if (plan.wildernessBudget && plan.equipmentExample.containsKey(13))
		{
			chosen.remove(13);
			Widget ammo = byId.get(plan.equipmentExample.get(13));
			if (ammo != null)
				chosen.put(13, ammo);
		}

		boolean fullVoid = true;
		for (int slot : new int[] { 0, 4, 7, 9 })
			if (!isVoid(chosen.get(slot), manager)
					&& !(plan.heldEquipment.contains(slot) && manager.getItemComposition(plan.equipmentExample.get(slot))
							.getName().toLowerCase(Locale.ROOT).contains("void")))
				fullVoid = false;
		if (!fullVoid)
			for (int slot : new int[] { 0, 4, 7, 9 })
				if (isVoid(chosen.get(slot), manager))
				{
					chosen.remove(slot);
					for (int id : plan.equipment.getOrDefault(slot, Collections.emptyList()))
						if (byId.containsKey(id) && !isVoid(byId.get(id), manager))
						{
							chosen.put(slot, byId.get(id));
							break;
						}
				}
		Widget weapon = chosen.get(3);
		boolean twoHanded = false;
		Integer exampleWeapon = plan.equipmentExample.get(3);
		if (weapon != null || exampleWeapon != null)
		{
			var stats = manager.getItemStats(weapon == null ? exampleWeapon : manager.canonicalize(weapon.getItemId()));
			if (stats != null && stats.getEquipment() != null && stats.getEquipment().isTwoHanded())
			{
				chosen.remove(5);
				twoHanded = true;
			}
		}
		boolean showEquipment = !plan.equipmentName.isEmpty();
		int gearY = padding + 18, gearEnd = showEquipment ? gearY + 5 * 36 : gearY;
		int runeColumns = Math.min(columns, 3), runeY = gearEnd + 18;
		if (!runes.isEmpty())
			gearEnd = runeY + ((runes.size() + runeColumns - 1) / runeColumns) * 36;
		int inventoryY = showEquipment && columns < 8 || !showEquipment && !runes.isEmpty() ? gearEnd + 18 : gearY;
		int inventoryX = 51 + (showEquipment && columns >= 8 ? 4 * pitch : 0);
		if (showEquipment)
			headings.add(new Heading("Equipment", 51, padding + 12));
		headings.add(new Heading(
				plan.inventoryExample.isEmpty() ? "No Wiki inventory example"
						: showInventory ? "Recommended inventory" : "Shared inventory above",
				inventoryX, inventoryY - 6));
		for (int[] position : EQUIPMENT)
		{
			Widget cell = chosen.get(position[0]);
			int col = position[1] % columns, row = position[2] + position[1] / columns;
			int x = 51 + col * pitch, y = gearY + row * 36;
			if (cell != null)
			{
				String note = plan.equipmentNotes.getOrDefault(manager.canonicalize(cell.getItemId()), "");
				if (!placed.add(cell))
				{
					if (copies == null)
						continue;
					cell = copies.add(container, cell, cell.getItemId(), manager);
				}
				place(cell, x, y);
				if (!note.isEmpty())
					notes.add(new InventoryNote(note, x, y));
			}
			else if (showEquipment)
			{
				boolean offhand = position[0] == 5 && twoHanded;
				Integer example = offhand ? null : plan.equipmentExample.get(position[0]);
				String label = offhand ? "2H" : slotLabel(position[0]);
				if (example != null && copies != null)
				{
					place(copies.add(container, null, example, manager), x, y);
					notes.add(new InventoryNote(
							!plan.wildernessBudget || plan.heldEquipment.contains(position[0]) ? plan.equipmentNotes.get(example)
									: "Budget gear suggestion: no matching usable item selected from your bank. Check equip requirements; this is not owned stock or a new guide rank.",
							x, y));
				}
				else
				{
					headings.add(new Heading(label, x, y, true));
					notes.add(new InventoryNote(offhand ? "Off-hand unavailable with the selected two-handed weapon."
							: "No suitable ready owned item for " + label.toLowerCase(Locale.ROOT)
									+ ". Check ownership, charges and setup requirements.",
							x, y));
				}
			}
		}
		if (!runes.isEmpty())
		{
			headings.add(new Heading("Suggested runes", 51, runeY - 6));
			for (int i = 0; i < runes.size(); i++)
			{
				Widget rune = runes.get(i);
				if (!placed.add(rune))
				{
					if (copies == null)
						continue;
					rune = copies.add(container, rune, rune.getItemId(), manager);
				}
				int x = 51 + i % runeColumns * pitch, y = runeY + i / runeColumns * 36;
				place(rune, x, y);
				notes.add(new InventoryNote(
						"Runes listed for this activity. Choose those needed for your spellbook, spell and rune pouch; this is not a required combined rune loadout.",
						x, y));
			}
		}
		int inventoryColumns = Math.min(4, columns), inventoryEnd = inventoryY;
		for (var entry : plan.inventoryExample.entrySet())
		{
			if (!showInventory)
				break;
			Integer id = plan.inventory.get(entry.getKey());
			if (!plan.stockKnown && (id == null || !byId.containsKey(id)))
			{
				for (int alternative : InventoryPotionDoses.alternatives(entry.getValue().ids))
				{
					if (InventoryPotionDoses.known(alternative) && byId.containsKey(alternative))
					{
						id = alternative;
						break;
					}
				}
			}
			Widget source = id == null || plan.unavailableInventory.contains(entry.getKey()) ? null : byId.get(id), cell = source;
			if (source == null || !placed.add(source))
			{
				if (copies == null)
					continue;
				cell = copies.add(container, source, id == null ? entry.getValue().ids.get(0) : id, manager);
			}
			int position = entry.getKey(), x = inventoryX + (position % inventoryColumns) * pitch;
			int y = inventoryY + (position / inventoryColumns) * 36;
			place(cell, x, y);
			inventoryEnd = Math.max(inventoryEnd, y + 36);
			String stockNote = plan.inventoryNotes.getOrDefault(entry.getKey(), "");
			String note = entry.getValue().note;
			if (id != null && !entry.getValue().ids.contains(id))
				note = InventoryPotionDoses.known(id) ? InventoryPotionDoses.note(id)
						: SetupEquipmentChoice.inventoryAlternativeNote(entry.getValue().ids);
			if (source == null)
			{
				if (!entry.getValue().guideOnly)
					note = "Guide example: no ready bank item for this slot. Check ownership, charges and requirements."
							+ (note.isEmpty() ? "" : " " + note);
			}
			else if (!note.isEmpty())
				note = "Showing an owned alternative; live prices are not compared. " + note;
			if (source != null)
			{
				var definition = manager.getItemComposition(id);
				if (definition != null)
				{
					String state = ItemVariantState.annotate("Item state", new AutoCategories.Item(id,
							definition.getName(), false, definition.getInventoryActions(), 0, 0, 0));
					if (!state.equals("Item state"))
						note += (note.isEmpty() ? "" : " ") + state;
					String use = ItemVariantState.inventoryUseNote(new AutoCategories.Item(id, definition.getName(),
							false, definition.getInventoryActions(), 0, 0, 0));
					if (!use.isEmpty())
						note += (note.isEmpty() ? "" : " ") + use;
				}
			}
			if (!stockNote.isEmpty())
				note = stockNote + (note.isEmpty() ? "" : " " + note);
			if (!note.isEmpty())
				notes.add(new InventoryNote(note, x, y));
		}
		return Math.max(gearEnd, inventoryEnd) + 8;
	}

	private static String slotLabel(int slot)
	{
		switch (slot)
		{
			case 0:
				return "Head";
			case 1:
				return "Cape";
			case 2:
				return "Neck";
			case 3:
				return "Main";
			case 4:
				return "Body";
			case 5:
				return "Off";
			case 7:
				return "Legs";
			case 9:
				return "Hands";
			case 10:
				return "Feet";
			case 12:
				return "Ring";
			default:
				return "Ammo";
		}
	}

	private static boolean isVoid(Widget widget, ItemManager manager)
	{
		if (widget == null)
			return false;
		var definition = manager.getItemComposition(manager.canonicalize(widget.getItemId()));
		return definition != null && definition.getName() != null
				&& definition.getName().toLowerCase(Locale.ROOT).contains("void");
	}

	private static void place(Widget cell, int x, int y)
	{
		cell.setOriginalX(x);
		cell.setOriginalY(y);
		cell.revalidate();
	}

	static boolean activityPreset(AutoCategories.Preset preset)
	{
		return preset == AutoCategories.Preset.SKILLING || preset == AutoCategories.Preset.SKILLING_OUTFITS
				|| preset == AutoCategories.Preset.COMBAT_GROUPS || preset == AutoCategories.Preset.CHAMBERS_OF_XERIC
				|| preset == AutoCategories.Preset.THEATRE_OF_BLOOD || preset == AutoCategories.Preset.TOMBS_OF_AMASCUT
				|| preset == AutoCategories.Preset.WIKI_ACTIVITY_SETUP;
	}

	static int bucket(int id, ItemManager manager)
	{
		return bucket(id, manager, "");
	}

	private static int bucket(int id, ItemManager manager, String activity)
	{
		var definition = manager.getItemComposition(id);
		if (definition == null)
			return 19;
		var stats = manager.getItemStats(id);
		String name = definition.getName();
		AutoCategories.Item item = new AutoCategories.Item(id, name, stats != null && stats.isEquipable(),
				definition.getInventoryActions(), 0, 0, 0);
		boolean reviewedSupply = !activity.isEmpty() && ActivitySetups.forActivity(activity).stream()
				.anyMatch(s -> SetupLoadout.inventoryTable(s)
						&& (s.itemIds.contains(id) || InventoryPotionDoses.listed(s.itemIds, item))
						&& !ItemVariantState.needsInventoryReview(item, s)
						&& SetupItemRequirements.reviewReason(s.id, item).isEmpty());
		if (ItemVariantState.needsActivityReview(item) && !reviewedSupply)
			return 19;
		if ("Tools".equals(ItemTaxonomy.weaponRole(ItemVariantState.familyName(item))) || WikiCatalogue.entries(item)
				.stream().anyMatch(e -> e.group.equals("Shared tools") || e.group.endsWith("— tools")))
			return 11;
		if (stats != null && stats.getEquipment() != null)
		{
			int slot = stats.getEquipment().getSlot();
			for (int i = 0; i < SLOTS.length; i++)
				if (SLOTS[i] == slot)
					return i;
		}
		if (item.action("Eat"))
			return 12;
		if (item.action("Drink"))
			return 13;
		if (item.name.endsWith(" rune"))
			return 14;
		return 15;
	}

	static int[] apply(Widget container, ItemManager manager, int columns, int pitch, int padding)
	{
		Widget[] children = container.getDynamicChildren();
		if (children == null || manager == null)
			return null;
		List<Widget> cells = new ArrayList<>();
		for (Widget child : children)
			if (child != null && !child.isSelfHidden() && child.getItemId() >= 0 && child.getItemId() != 6512
					&& child.getOriginalWidth() == 36 && child.getOriginalHeight() == 32)
				cells.add(child);
		if (cells.isEmpty())
			return null;
		cells.sort(Comparator.comparingInt(Widget::getOriginalY).thenComparingInt(Widget::getOriginalX));
		Map<Integer, List<Widget>> groups = new TreeMap<>();
		int oldEnd = 0;
		Map<Integer, Integer> buckets = new HashMap<>();
		for (Widget cell : cells)
		{
			oldEnd = Math.max(oldEnd, cell.getOriginalY() + 36);
			int id = manager.canonicalize(cell.getItemId());
			groups.computeIfAbsent(buckets.computeIfAbsent(id, k -> bucket(k, manager)), k -> new ArrayList<>())
					.add(cell);
		}
		int y = padding;
		for (List<Widget> group : groups.values())
		{
			for (int i = 0; i < group.size(); i++)
			{
				Widget cell = group.get(i);
				cell.setOriginalX(51 + (i % columns) * pitch);
				cell.setOriginalY(y + (i / columns) * 36);
				cell.revalidate();
			}
			y += ((group.size() + columns - 1) / columns) * 36;
		}
		return new int[] { oldEnd, y };
	}
}

package com.windowmarkers;

import java.util.*;

final class SetupItemRequirements
{
	private static final Map<String, Map<Integer, String[]>> REQUIREMENTS = new HashMap<>();
	static
	{
		for (String[] row : ItemTaxonomy.readRows("setup-item-requirements.tsv", 5))
			REQUIREMENTS.computeIfAbsent(row[0], key -> new HashMap<>()).put(Integer.parseInt(row[1]), row);
	}

	static String reviewReason(String setupId, AutoCategories.Item item)
	{
		String[] row = REQUIREMENTS.getOrDefault(setupId, Collections.emptyMap()).get(item.id);
		return row != null && row[2].equalsIgnoreCase(item.name) ? row[3] : "";
	}
}

package com.windowmarkers;

import java.util.*;

final class SetupLoadout
{
	static final class Field
	{
		final String name, note;
		final List<Integer> ids = new ArrayList<>();
		final boolean guideOnly;
		final Map<Integer, String> itemNotes = new HashMap<>();

		Field(String[] row)
		{
			this(row, false);
		}

		Field(String[] row, boolean guideOnly)
		{
			name = row[1];
			note = row[3];
			this.guideOnly = guideOnly;
			for (String id : row[2].split(","))
				if (!id.isEmpty())
					ids.add(Integer.parseInt(id));
		}

		int slot()
		{
			return name.matches("2h[0-9]*") ? 3 : ItemCatalogueIndex.slot(name.replaceAll("[0-9]+$", ""));
		}

		int order()
		{
			String number = name.replaceFirst("^2h", "weapon").replaceAll("[^0-9]", "");
			return number.isEmpty() ? 0 : Integer.parseInt(number);
		}

		boolean inventoryChoice()
		{
			return !guideOnly && (note.isEmpty() || note.startsWith("The Wiki chooses ")
					|| note.startsWith("The Vale Totems magiclog variable "));
		}
	}

	static final class Table
	{
		final String kind, context, style;
		final List<Field> fields = new ArrayList<>();

		Table(String[] row)
		{
			kind = row[1];
			context = row[2];
			style = row[3];
		}
	}

	private static final Map<String, Table> TABLES = new LinkedHashMap<>();
	private static final Map<String, String> INVENTORY_PAIRS = new HashMap<>();
	private static final Map<String, String> SWITCH_NOTES = new HashMap<>();
	static
	{
		for (String[] row : ItemTaxonomy.readRows("setup-layout-tables.tsv", 4))
			TABLES.put(row[0], new Table(row));
		for (String[] row : ItemTaxonomy.readRows("setup-layout-fields.tsv", 4))
		{
			Table table = TABLES.get(row[0]);
			if (table != null)
				table.fields.add(new Field(row));
		}
		Map<String, List<String[]>> choices = new LinkedHashMap<>();
		for (String[] row : ItemTaxonomy.readRows("setup-layout-options.tsv", 5))
			choices.computeIfAbsent(row[0] + "/" + row[1], key -> new ArrayList<>()).add(row);
		for (Map.Entry<String, Table> entry : TABLES.entrySet())
			for (Field field : entry.getValue().fields)
			{
				List<String[]> rows = choices.get(entry.getKey() + "/" + field.name);
				if (rows == null)
					continue;
				field.ids.clear();
				for (String[] row : rows)
				{
					int id = Integer.parseInt(row[2]);
					field.ids.add(id);
					field.itemNotes.put(id, row[4]);
				}
			}
		for (String[] row : ItemTaxonomy.readRows("setup-inventory-previews.tsv", 6))
		{
			Table table = TABLES.get(row[0]);
			if (table != null && table.kind.equals("inventory"))
				table.fields.add(new Field(new String[] { row[0], row[1], row[2], row[4] }, true));
		}
		for (String[] row : ItemTaxonomy.readRows("setup-inventory-pairs.tsv", 2))
			INVENTORY_PAIRS.put(row[0], row[1]);
		for (String[] row : ItemTaxonomy.readRows("setup-switch-notes.tsv", 2))
			SWITCH_NOTES.put(row[0], row[1]);
	}
	final String equipmentName, inventoryName;
	final String activity;
	final Map<Integer, List<Integer>> equipment;
	final Map<Integer, Integer> inventory;
	final Map<Integer, Field> inventoryExample;
	final Map<Integer, String> equipmentNotes = new HashMap<>();
	final Map<Integer, String> inventoryNotes = new HashMap<>();
	final Set<Integer> unavailableInventory = new HashSet<>();
	final Set<Integer> heldEquipment = new HashSet<>();
	boolean stockKnown;
	String equipmentNote = "";
	String sectionName = "";
	boolean wildernessBudget;
	String equipmentSource = "";
	final Map<Integer, Integer> equipmentExample = new LinkedHashMap<>();

	Table equipmentTable()
	{
		return TABLES.get(equipmentSource);
	}

	boolean notEnoughGear()
	{
		if (!wildernessBudget)
			return false;
		for (SetupLoadout part : sections())
			for (int slot : new int[] { 0, 3, 4, 7 })
				if (part.equipmentTable() != null
						&& part.equipmentTable().fields.stream().anyMatch(f -> f.slot() == slot)
						&& part.equipment.getOrDefault(slot, Collections.emptyList()).isEmpty())
					return true;
		return false;
	}

	boolean hasExamples()
	{
		return sections().stream().anyMatch(s -> !s.equipmentExample.isEmpty() || !s.inventoryExample.isEmpty());
	}

	private List<SetupLoadout> sections = Collections.emptyList();

	List<SetupLoadout> sections()
	{
		return sections.isEmpty() ? Collections.singletonList(this) : sections;
	}

	int sectionCount()
	{
		return sections.isEmpty() ? 1 : sections.size();
	}

	Set<Integer> itemIds()
	{
		Set<Integer> result = new LinkedHashSet<>();
		for (SetupLoadout section : sections())
		{
			section.equipment.values().forEach(result::addAll);
			result.addAll(section.inventory.values());
		}
		return result;
	}

	private SetupLoadout(String activity, String equipmentName, String inventoryName,
			Map<Integer, List<Integer>> equipment, Map<Integer, Integer> inventory,
			Map<Integer, Field> inventoryExample)
	{
		this.activity = activity;
		this.equipmentName = equipmentName;
		this.inventoryName = inventoryName;
		this.equipment = equipment;
		this.inventory = inventory;
		this.inventoryExample = inventoryExample;
	}

	static boolean inventoryTable(ActivitySetups.Setup setup)
	{
		Table table = TABLES.get(setup.id);
		return table != null && table.kind.equals("inventory");
	}

	SetupLoadout retainItems(Set<Integer> allowed)
	{
		Map<Integer, List<Integer>> gear = new LinkedHashMap<>();
		equipment.forEach((slot, ids) ->
		{
			List<Integer> kept = new ArrayList<>();
			for (int id : ids)
				if (allowed.contains(id))
					kept.add(id);
			if (!kept.isEmpty())
				gear.put(slot, kept);
		});
		Map<Integer, Integer> bag = new LinkedHashMap<>();
		inventory.forEach((slot, id) ->
		{
			if (allowed.contains(id))
				bag.put(slot, id);
		});
		Map<Integer, Field> example = new LinkedHashMap<>();
		inventoryExample.forEach((slot, field) ->
		{
			if (bag.containsKey(slot))
				example.put(slot, field);
		});
		SetupLoadout result = new SetupLoadout(activity, equipmentName, inventoryName, gear, bag, example);
		equipmentNotes.forEach((id, note) ->
		{
			if (allowed.contains(id))
				result.equipmentNotes.put(id, note);
		});
		result.equipmentNote = equipmentNote;
		result.inventoryNotes.putAll(inventoryNotes);
		result.unavailableInventory.addAll(unavailableInventory);
		result.stockKnown = stockKnown;
		for (int slot : heldEquipment)
			if (gear.containsKey(slot))
			{
				result.heldEquipment.add(slot);
				result.equipmentExample.put(slot, equipmentExample.get(slot));
			}
		result.sectionName = sectionName;
		result.wildernessBudget = wildernessBudget;
		result.equipmentSource = equipmentSource;

		if (!sections.isEmpty())
		{
			List<SetupLoadout> kept = new ArrayList<>();
			for (SetupLoadout section : sections)
				kept.add(section.retainItems(allowed));
			result.sections = Collections.unmodifiableList(kept);
		}
		return result;
	}

	private static boolean ready(ItemCatalogueIndex.Item item)
	{
		return item != null && !ItemVariantState.needsActivityReview(item.fact);
	}

	private static boolean inventoryReady(ActivitySetups.Setup setup, ItemCatalogueIndex.Item item)
	{
		return item != null && !ItemVariantState.needsInventoryReview(item.fact, setup)
				&& SetupItemRequirements.reviewReason(setup.id, item.fact).isEmpty();
	}

	static boolean equipmentReady(ActivitySetups.Setup setup, ItemCatalogueIndex.Item item)
	{
		return ready(item) && SetupItemRequirements.reviewReason(setup.id, item.fact).isEmpty()
				&& !ItemVariantState.needsRankReview(item.fact, setup.activity, setup.label);
	}

	static SetupLoadout build(List<ActivitySetups.Setup> matched, Map<Integer, ItemCatalogueIndex.Item> owned,
			Set<Integer> visible, String inventoryContext)
	{
		return build(matched, owned, visible, inventoryContext, SetupPlayerState.unknown());
	}

	static SetupLoadout build(List<ActivitySetups.Setup> matched, Map<Integer, ItemCatalogueIndex.Item> owned,
			Set<Integer> visible, String inventoryContext, SetupPlayerState state)
	{
		if (!WildernessLoadout.applies(matched))
		{
			SetupLoadout plan = buildSections(matched, owned, visible, inventoryContext, state);
			SetupEquipmentExamples.fill(plan, owned, state);
			return plan;
		}
		Map<Integer, ItemCatalogueIndex.Item> budget = new LinkedHashMap<>();
		owned.forEach((id, item) ->
		{
			if (WildernessLoadout.allowed(item))
				budget.put(id, item);
		});
		Set<Integer> shown = new HashSet<>(visible);
		shown.retainAll(budget.keySet());

		if (inventoryContext.isEmpty())
			for (ActivitySetups.Setup setup : matched)
				if (inventoryTable(setup) && setup.label.toLowerCase(Locale.ROOT).contains("low-risk"))
				{
					inventoryContext = setup.id;
					break;
				}
		SetupLoadout plan = buildSections(WildernessLoadout.defaults(matched), budget, shown, inventoryContext, state);
		if (plan != null)
			WildernessLoadout.finish(plan);
		return plan;
	}

	private static SetupLoadout buildSections(List<ActivitySetups.Setup> matched,
			Map<Integer, ItemCatalogueIndex.Item> owned, Set<Integer> visible, String inventoryContext, SetupPlayerState state)
	{

		if (matched.size() < 2)
			return buildOne(matched, owned, visible, inventoryContext, state);
		Set<String> activities = new HashSet<>();
		matched.forEach(s -> activities.add(s.activity));
		Set<String> families = new HashSet<>();
		activities.forEach(a -> families.add(ActivityMenu.canonical(a).split("/", 2)[0]));
		if (families.size() != 1)
			return buildOne(matched, owned, visible, inventoryContext, state);
		String activityName = families.iterator().next();
		Map<String, List<ActivitySetups.Setup>> groups = new LinkedHashMap<>();
		boolean recommended = matched.stream().anyMatch(s -> TABLES.containsKey(s.id)
				&& TABLES.get(s.id).kind.equals("recommended equipment") && layoutTable(TABLES.get(s.id)));
		for (ActivitySetups.Setup setup : matched)
		{
			Table table = TABLES.get(setup.id);
			if (table == null || !table.kind.contains("equipment") || !layoutTable(table)
					|| recommended && !table.kind.equals("recommended equipment"))
				continue;
			String phase = table.context.toLowerCase(Locale.ROOT).contains("phase")
					? table.context.replaceFirst("^Equipment / ", "")
					: "";
			String style = SetupCompletion.style(table.style);
			String name = phase.isEmpty() ? table.style
					: phase + " / " + (style.isEmpty() ? table.style
							: style.substring(0, 1).toUpperCase(Locale.ROOT) + style.substring(1));
			if (activities.size() > 1 && !setup.activity.equals(activityName))
				name = (setup.activity.startsWith(activityName + "/")
						? setup.activity.substring(activityName.length() + 1)
						: setup.activity.split("/", 2)[0]) + " / " + name;
			groups.computeIfAbsent(name, k -> new ArrayList<>()).add(setup);
		}
		if (groups.size() < 2)
			return buildOne(matched, owned, visible, inventoryContext, state);
		List<SetupLoadout> parts = new ArrayList<>();
		groups.forEach((name, setups) ->
		{
			SetupLoadout part = buildOne(setups, owned, visible, inventoryContext, state);
			if (part != null)
			{
				part.sectionName = name;
				parts.add(part);
			}
		});
		if (parts.isEmpty())
			return buildOne(matched, owned, visible, inventoryContext, state);
		SetupLoadout first = parts.get(0);
		SetupLoadout result = new SetupLoadout(activityName, first.equipmentName, first.inventoryName, first.equipment,
				first.inventory, first.inventoryExample);
		result.equipmentNotes.putAll(first.equipmentNotes);
		result.equipmentNote = first.equipmentNote;
		result.sections = Collections.unmodifiableList(parts);
		return result;
	}

	private static int slotCount(Table table)
	{
		Set<Integer> slots = new HashSet<>();
		for (Field field : table.fields)
			if (field.slot() >= 0)
				slots.add(field.slot());
		return slots.size();
	}

	private static boolean layoutTable(Table table)
	{
		return slotCount(table) >= 3 || slotCount(table) > 0
				&& (table.context + " " + table.style).toLowerCase(Locale.ROOT).contains("phase");
	}

	private static SetupLoadout buildOne(List<ActivitySetups.Setup> matched,
			Map<Integer, ItemCatalogueIndex.Item> owned, Set<Integer> visible, String inventoryContext, SetupPlayerState state)
	{
		ActivitySetups.Setup gear = null;
		int best = -1;
		for (ActivitySetups.Setup setup : matched)
		{
			Table table = TABLES.get(setup.id);
			if (table == null || !table.kind.contains("equipment"))
				continue;
			if (!layoutTable(table))
				continue;
			Map<Integer, List<Integer>> available = chooseEquipment(equipmentFields(table), setup, owned, visible,
					owned.values(), new HashMap<>(), state);
			int score = available.size() * 100 + (table.kind.equals("recommended equipment") ? 20 : 0) + slotCount(table);
			if (score > best)
			{
				gear = setup;
				best = score;
			}
		}
		ActivitySetups.Setup anchor = gear;
		if (anchor == null)
			for (ActivitySetups.Setup setup : matched)
				if (inventoryTable(setup))
				{
					anchor = setup;
					break;
				}
		if (anchor == null)
			return null;
		Table table = TABLES.get(anchor.id);
		Map<Integer, List<Integer>> equipment = new LinkedHashMap<>();
		List<Field> fields = gear == null ? Collections.emptyList() : equipmentFields(table);
		Map<Integer, String> equipmentNotes = new HashMap<>();
		Collection<ItemCatalogueIndex.Item> requirements = owned.values();
		for (int pass = 0; pass < 4; pass++)
		{
			Map<Integer, List<Integer>> selected = chooseEquipment(fields, gear, owned, visible, requirements,
					equipmentNotes, state);
			if (gear != null)
				completeEquipment(selected, gear, table, owned, requirements, equipmentNotes);
			if (selected.equals(equipment))
				break;
			equipment = selected;
			List<ItemCatalogueIndex.Item> wearing = new ArrayList<>();
			for (List<Integer> options : equipment.values())
				if (!options.isEmpty())
					wearing.add(owned.get(options.get(0)));
			requirements = wearing;
		}
		ActivitySetups.Setup inventory = null;
		best = -1;
		int bestPreference = -1;
		for (ActivitySetups.Setup setup : ActivitySetups.forActivity(anchor.activity))
		{
			if (!inventoryTable(setup))
				continue;
			Table candidate = TABLES.get(setup.id);
			int score = 0;
			Set<List<Integer>> distinct = new HashSet<>();
			for (Field field : candidate.fields)
				if (field.inventoryChoice() && distinct.add(field.ids))
				{

					int available = 0;
					for (int id : inventoryAlternatives(setup, field, owned))
						if (inventoryReady(setup, owned.get(id)))
							available = Math.max(available, owned.get(id).slot >= 0 ? 20 : 1);
					score += available;
				}
			boolean paired = gear != null && setup.id.equals(INVENTORY_PAIRS.get(gear.id));
			boolean sameStyle = gear != null && !table.style.isEmpty() && candidate.style.equalsIgnoreCase(table.style);
			boolean sameContext = gear != null && SetupActivityRules.sameMethod(table, candidate);
			if (gear != null && !paired && !sameContext && !setup.id.equals(inventoryContext)
					&& !SetupActivityRules.inventoryCompatible(anchor.activity, table, candidate))
				continue;

			int preference = setup.id.equals(inventoryContext) ? 5
					: paired ? 4 : sameContext ? 3 : sameStyle ? 2 : matched.contains(setup) ? 1 : 0;
			if (preference > bestPreference || preference == bestPreference && score > best)
			{
				inventory = setup;
				best = score;
				bestPreference = preference;
			}
		}
		Map<Integer, Integer> inventoryItems = new TreeMap<>();
		Map<Integer, Field> inventoryExample = new TreeMap<>();
		if (inventory != null)
			for (Field field : TABLES.get(inventory.id).fields)
			{
				int position = field.order() - 1;
				if (!(field.name.matches("[0-9]+") || field.name.startsWith("inventory")) || position < 0
						|| position >= 28 || field.ids.isEmpty())
					continue;
				inventoryExample.put(position, field);
				if (!field.inventoryChoice())
					continue;
				for (int id : inventoryAlternatives(inventory, field, owned))
					if (inventoryReady(inventory, owned.get(id)) && (!InventoryPotionDoses.known(id)
							|| InventoryPotionDoses.listed(field.ids, owned.get(id).fact)))
					{
						inventoryItems.put(position, id);
						break;
					}
			}
		SetupLoadout result = new SetupLoadout(anchor.activity, gear == null ? "" : gear.activity + " / " + gear.label,
				inventory == null ? "No inventory example" : inventory.label, equipment, inventoryItems,
				inventoryExample);
		result.equipmentSource = gear == null ? "" : gear.id;
		result.equipmentNotes.putAll(equipmentNotes);
		result.equipmentNote = (gear == null ? "" : SWITCH_NOTES.getOrDefault(gear.id, "") + " ")
				+ SetupActivityRules.note(anchor.activity);
		return result;
	}

	private static List<Field> equipmentFields(Table table)
	{
		List<Field> fields = new ArrayList<>(table.fields);
		fields.sort(Comparator.comparingInt((Field f) -> f.slot() == 3 ? 0 : 1).thenComparingInt(Field::order));
		return fields;
	}

	private static List<Integer> inventoryAlternatives(ActivitySetups.Setup inventory, Field wanted,
			Map<Integer, ItemCatalogueIndex.Item> owned)
	{
		List<Integer> result = InventoryGearAlternatives
				.equivalents(SetupEquipmentChoice.inventoryAlternatives(wanted.ids), owned);
		if (wanted.ids.stream().noneMatch(InventoryGearAlternatives::rangedAccessory))
			return result;

		for (ActivitySetups.Setup guide : ActivitySetups.forActivity(inventory.activity))
		{
			Table table = TABLES.get(guide.id);
			if (table == null || !table.kind.equals("recommended equipment")
					|| !SetupCompletion.style(table.style).equals("ranged"))
				continue;
			Set<Integer> slots = new HashSet<>();
			for (Field field : table.fields)
				if (field.ids.stream().anyMatch(
						id -> wanted.ids.stream().anyMatch(w -> InventoryGearAlternatives.sameCombatItem(w, id))))
					slots.add(field.slot());
			slots.removeAll(SetupCompletion.protectedSlots(inventory.activity));
			List<Field> fields = new ArrayList<>(table.fields);
			fields.sort(Comparator.comparingInt(Field::order));
			for (Field field : fields)
				if (slots.contains(field.slot()))
					for (int id : InventoryGearAlternatives.equivalents(field.ids, owned))
					{
						ItemCatalogueIndex.Item item = owned.get(id);
						String note = field.itemNotes.getOrDefault(id, field.note);
						if (item != null && item.slot == field.slot() && equipmentReady(guide, item)
								&& SetupEquipmentChoice.allowed(item, note, null, owned.values())
								&& !result.contains(id))
							result.add(id);
					}
		}
		return result;
	}

	private static void completeEquipment(Map<Integer, List<Integer>> equipment, ActivitySetups.Setup gear, Table table,
			Map<Integer, ItemCatalogueIndex.Item> owned, Collection<ItemCatalogueIndex.Item> requirements,
			Map<Integer, String> notes)
	{
		SetupFallbacks.fill(equipment, gear, table, owned, requirements, notes);
		if (gear.activity.equals("Abyssal Sire"))
			SetupCompletion.fill(equipment, owned, SetupCompletion.style(table.style), notes, Collections.emptySet());
	}

	private static Map<Integer, List<Integer>> chooseEquipment(List<Field> fields, ActivitySetups.Setup gear,
			Map<Integer, ItemCatalogueIndex.Item> owned, Set<Integer> visible,
			Collection<ItemCatalogueIndex.Item> requirements, Map<Integer, String> equipmentNotes, SetupPlayerState state)
	{
		Map<Integer, List<Integer>> equipment = new LinkedHashMap<>();
		equipmentNotes.clear();
		ItemCatalogueIndex.Item weapon = null;
		for (Field field : fields)
		{
			int slot = field.slot();
			if (slot < 0)
				continue;
			for (int id : field.ids)
			{
				ItemCatalogueIndex.Item item = owned.get(id);
				if (!visible.contains(id) || !equipmentReady(gear, item) || item.slot != slot)
					continue;
				String note = field.itemNotes.getOrDefault(id, field.note);
				if (!SetupEquipmentChoice.allowed(item, note, weapon, requirements, state.onTask(gear.activity)))
					continue;
				List<Integer> options = equipment.computeIfAbsent(slot, k -> new ArrayList<>());
				if (!options.contains(id))
				{
					options.add(id);
					equipmentNotes.put(id, note);
				}
				if (slot == 3 && weapon == null)
					weapon = item;
			}
		}
		return equipment;
	}

}

