package com.windowmarkers;

import java.util.*;
import net.runelite.api.*;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;

final class SetupPlayerState
{
	private static final java.util.List<String[]> TASKS = ItemTaxonomy.readRows("setup-slayer-targets.tsv", 2);
	private final GeRequirements requirements;
	private final Map<Integer, Integer> bank, carried, worn;
	private final String task;
	private final Map<Integer, ItemCatalogueIndex.Item> held = new HashMap<>();
	private final Map<String, String> additionalLocks = new HashMap<>();

	SetupPlayerState(GeRequirements requirements, Map<Integer, Integer> bank, Map<Integer, Integer> carried,
			Map<Integer, Integer> worn, String task)
	{
		this.requirements = requirements;
		this.bank = new HashMap<>(bank);
		this.carried = new HashMap<>(carried);
		this.worn = new HashMap<>(worn);
		this.task = task;
	}

	static SetupPlayerState unknown()
	{
		return new SetupPlayerState(null, Collections.emptyMap(), Collections.emptyMap(), Collections.emptyMap(), "");
	}

	static SetupPlayerState capture(Client client, ItemManager manager, List<BankPotionStock.Potion> potions,
			java.util.function.IntFunction<AutoCategories.Item> facts)
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getRealSkillLevel(Skill.HITPOINTS) < 1)
			return unknown();
		Map<Integer, Integer> bank = counts(client, manager, InventoryID.BANK);
		for (BankPotionStock.Potion potion : potions)
			bank.merge(manager.canonicalize(potion.itemId), potion.quantity, SetupPlayerState::sum);
		GeRequirements requirements = GeRequirements.capture(client,
				Quest.DESERT_TREASURE_II__THE_FALLEN_EMPIRE.getState(client) == QuestState.FINISHED);
		SetupPlayerState result = new SetupPlayerState(requirements, bank, counts(client, manager, InventoryID.INV),
				counts(client, manager, InventoryID.WORN), task(client));
		Set<Integer> ids = new HashSet<>(result.carried.keySet());
		ids.addAll(result.worn.keySet());
		for (int id : ids)
		{
			AutoCategories.Item fact = facts.apply(id);
			result.held.put(id, new ItemCatalogueIndex.Item(fact, fact.name, fact.slot));
		}
		Map<Quest, Boolean> quests = new EnumMap<>(Quest.class);
		for (String[] rule : ItemTaxonomy.readRows("setup-quest-requirements.tsv", 2))
		{
			Quest quest = Quest.valueOf(rule[1]);
			if (!quests.computeIfAbsent(quest, q -> q.getState(client) == QuestState.FINISHED))
				result.additionalLocks.put(rule[0], quest.getName());
		}
		for (String[] rule : ItemTaxonomy.readRows("setup-other-skill-requirements.tsv", 3))
		{
			Skill skill = Skill.valueOf(rule[1]);
			if (client.getRealSkillLevel(skill) < Integer.parseInt(rule[2]))
				result.additionalLocks.merge(rule[0], rule[2] + " " + skill.getName(), (a, b) -> a + ", " + b);
		}
		return result;
	}

	private static int sum(int a, int b)
	{
		return (int) Math.min(Integer.MAX_VALUE, (long) a + b);
	}

	private static Map<Integer, Integer> counts(Client client, ItemManager manager, int containerId)
	{
		Map<Integer, Integer> result = new HashMap<>();
		ItemContainer container = client.getItemContainer(containerId);
		if (container != null)
			for (Item item : container.getItems())
				if (item.getId() >= 0 && item.getQuantity() > 0)
					result.merge(manager.canonicalize(item.getId()), item.getQuantity(), SetupPlayerState::sum);
		return result;
	}

	private static String task(Client client)
	{
		if (client.getVarpValue(VarPlayerID.SLAYER_COUNT) <= 0)
			return "";
		int id = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
		List<Integer> rows = id == 98
				? client.getDBRowsByValue(DBTableID.SlayerTaskSublist.ID, DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID,
						0, client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID))
				: client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, id);
		if (rows == null || rows.isEmpty())
			return "";
		int row = id == 98 ? (Integer) client.getDBTableField(rows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0)[0]
				: rows.get(0);
		return (String) client.getDBTableField(row, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0];
	}

	boolean onTask(String activity)
	{
		String current = SearchText.normalize(task).replaceFirst("^the ", "");
		String target = SearchText.normalize(activity).replaceFirst("^slayer task ", "");
		if (current.isEmpty())
			return false;
		if (current.equals(target) || current.equals(target + "s"))
			return true;
		for (String[] row : TASKS)
			if (row[0].equals(activity) && Arrays.asList(row[1].split(",")).contains(current))
				return true;
		return false;
	}

	Map<Integer, ItemCatalogueIndex.Item> usable(Map<Integer, ItemCatalogueIndex.Item> items)
	{
		if (requirements == null)
			return items;
		Map<Integer, ItemCatalogueIndex.Item> result = new HashMap<>();
		Map<Integer, ItemCatalogueIndex.Item> available = new HashMap<>(held);
		available.putAll(items);
		available.forEach((id, item) ->
		{
			if (locked(item).isEmpty())
				result.put(id, item);
		});
		return result;
	}

	String locked(ItemCatalogueIndex.Item item)
	{
		if (requirements == null || item.slot < 0)
			return "";
		String levels = requirements.locked(item);
		for (Map.Entry<String, String> rule : additionalLocks.entrySet())
			if (CombatEquivalence.matches(item.fact, rule.getKey()))
				return levels.isEmpty() ? rule.getValue() : levels + ", " + rule.getValue();
		return levels;
	}

	Set<Integer> visible(Set<Integer> bankItems)
	{
		Set<Integer> result = new HashSet<>(bankItems);
		result.addAll(held.keySet());
		return result;
	}

	void annotate(SetupLoadout plan)
	{
		if (plan == null || requirements == null)
			return;
		for (SetupLoadout section : plan.sections())
		{
			section.stockKnown = true;
			for (Map.Entry<Integer, List<Integer>> entry : section.equipment.entrySet())
			{
				int id = entry.getValue().get(0);
				if (!bank.containsKey(id) && held.containsKey(id))
				{
					section.heldEquipment.add(entry.getKey());
					section.equipmentExample.put(entry.getKey(), id);
					section.equipmentNotes.put(id, (worn.containsKey(id) ? "Already equipped." : "Already carried.")
							+ " This preview has no bank action.");
				}
			}
			Map<Integer, Integer> used = new HashMap<>();
			for (Map.Entry<Integer, Integer> entry : section.inventory.entrySet())
			{
				int id = entry.getValue(), position = entry.getKey();
				if (used.getOrDefault(id, 0) >= bank.getOrDefault(id, 0) && InventoryPotionDoses.known(id))
					for (int alternative : InventoryPotionDoses.alternatives(Collections.singletonList(id)))
						if (used.getOrDefault(alternative, 0) < bank.getOrDefault(alternative, 0))
						{
							id = alternative;
							entry.setValue(id);
							break;
						}
				int required = used.merge(id, 1, Integer::sum);
				int available = bank.getOrDefault(id, 0);
				String note = "Bank / storage: " + available + ". Carried: " + carried.getOrDefault(id, 0)
						+ ". Equipped: " + worn.getOrDefault(id, 0) + ".";
				if (required > available)
				{
					section.unavailableInventory.add(position);
					note += " No additional bank item for this example slot.";
				}
				if (InventoryPotionDoses.known(id))
				{
					long doses = 0;
					int wanted = 0;
					List<Integer> variants = InventoryPotionDoses.alternatives(Collections.singletonList(id));
					for (int variant : variants)
						doses += (long) InventoryPotionDoses.doses(variant) * bank.getOrDefault(variant, 0);
					for (SetupLoadout.Field field : section.inventoryExample.values())
						for (int example : field.ids)
							if (variants.contains(example))
							{
								wanted += InventoryPotionDoses.doses(example);
								break;
							}
					note += " Withdrawable bank/storage doses of this potion: " + doses + "; example doses: " + wanted + ".";
				}
				section.inventoryNotes.put(position, note);
			}
			for (Map.Entry<Integer, SetupLoadout.Field> entry : section.inventoryExample.entrySet())
				if (!section.inventory.containsKey(entry.getKey()))
					for (int id : entry.getValue().ids)
						if (carried.containsKey(id) || worn.containsKey(id))
						{
							section.inventoryNotes.put(entry.getKey(), "Already carried: " + carried.getOrDefault(id, 0)
									+ "; equipped: " + worn.getOrDefault(id, 0) + ". This preview has no bank action.");
							break;
						}
		}
	}
}

package com.windowmarkers;

import java.util.*;

final class SupplySearch
{
	private static final Map<Integer, Food> FOODS = new HashMap<>();
	private static final Map<String, Set<Integer>> GROUPS = new LinkedHashMap<>();
	private static final Map<String, String> ALIASES = new HashMap<>();
	static
	{
		for (String[] row : ItemTaxonomy.readRows("food-search-facts.tsv", 12))
			FOODS.put(Integer.parseInt(row[0]), new Food(row));
		for (String[] row : ItemTaxonomy.readRows("supply-search-groups.tsv", 3))
			GROUPS.computeIfAbsent(SearchText.normalize(row[2]), k -> new HashSet<>())
					.add(Integer.parseInt(row[0].substring(2)));
		alias("blowpipe", "toxic blowpipe", "blazing blowpipe", "bp");
		alias("twisted bow", "tbow");
		alias("rune crossbow", "rcb");
		alias("armadyl crossbow", "acb");
		alias("zaryte crossbow", "zcb");
		alias("dragon hunter crossbow", "dhcb");
		alias("karil crossbow", "karils crossbow", "karils");
		alias("hunters crossbow", "hunter crossbow");
		alias("hunters sunlight crossbow", "sunlight crossbow", "hunter sunlight crossbow");
		alias("comp ogre bow", "composite ogre bow");
		alias("cannon", "dwarf multicannon", "multicannon");
		alias("eclipse atlatl", "atlatl");
		alias("ballista", "heavy ballista", "light ballista");
		for (String bow : Arrays.asList("oak", "willow", "maple", "yew", "magic"))
			alias(bow + " bow", bow + " shortbow", bow + " longbow");
		alias("magic bow", "magic shortbow i", "magic shortbow", "magic longbow");
		alias("prayer restore", "prayer restoration", "restore prayer");
		alias("stat restore", "stat restoration", "restore stats");
		alias("run energy", "energy", "run restoration");
		alias("aggression", "aggro", "goading");
		alias("poison cure", "antipoison");
		alias("venom cure", "antivenom", "anti venom");
		alias("antifire", "dragonfire", "dragonfire protection");
		alias("special attack", "spec", "special restore");
	}

	private static void alias(String canonical, String... aliases)
	{
		for (String alias : aliases)
			ALIASES.put(alias, canonical);
	}

	static boolean foodQuery(String raw)
	{
		String text = " " + SearchText.normalize(raw) + " ";
		return text.contains(" food ") || text.contains(" foods ");
	}

	static final class Query
	{
		final Set<String> flags = new HashSet<>();
		final Set<Integer> ids = new HashSet<>();
		boolean food, raw;
		int minimum = -1;
		String explanation = "";
	}

	static Query parse(String raw)
	{
		String text = SearchText.normalize(raw);
		if (foodQuery(raw))
		{
			Query q = new Query();
			q.food = true;
			for (String word : text.split(" +"))
			{
				if (word.matches("[0-9]{1,3}"))
				{
					if (q.minimum >= 0)
						return null;
					q.minimum = Integer.parseInt(word);
					continue;
				}
				switch (word)
				{
					case "food":
					case "foods":
					case "cooked":
					case "ready":
					case "to":
					case "eat":
					case "eating":
					case "healing":
					case "hp":
					case "bite":
					case "bites":
					case "only":
					case "cooking":
					case "inputs":
					case "area":
						break;
					case "raw":
					case "uncooked":
						q.raw = true;
						break;
					case "fast":
					case "combo":
					case "instant":
					case "delayed":
					case "multi":
					case "unrestricted":
						q.flags.add(word);
						break;
					case "overheal":
					case "overhealing":
						q.flags.add("overheal");
						break;
					case "wilderness":
					case "blighted":
					case "restricted":
						q.flags.add("restricted");
						break;
					default:
						return null;
				}
			}
			if (q.raw)
				q.ids.addAll(GROUPS.getOrDefault("raw food cooking inputs", Collections.emptySet()));
			return q;
		}
		String kind = text.matches(".*\\b(?:potion|potions)\\b.*") ? "potions"
				: text.matches(".*\\b(?:ammo|ammunition)\\b.*") ? "ammo" : "";
		if (kind.isEmpty())
			return null;
		String terms = text.replaceAll("\\b(?:potion|potions|ammo|ammunition|for)\\b", " ").replaceAll(" +", " ")
				.trim();
		terms = ALIASES.getOrDefault(terms, terms);
		if (kind.equals("potions") && Arrays
				.asList("attack", "strength", "defence", "defense", "magic", "ranged", "agility", "fishing", "hunter")
				.contains(terms))
			terms = (terms.equals("defense") ? "defence" : terms) + " boost";
		Query q = new Query();
		String key = kind + " " + terms;

		if (kind.equals("ammo") && Arrays
				.asList("bowfa", "bow of faerdhinen", "crystal bow", "craws bow", "webweaver bow").contains(terms))
		{
			q.explanation = "This weapon uses charges, not interchangeable ammunition. Check its charging requirements.";
			return q;
		}
		if (kind.equals("potions") && terms.equals("prayer"))
		{
			q.ids.addAll(GROUPS.getOrDefault("potions prayer restore", Collections.emptySet()));
			q.ids.addAll(GROUPS.getOrDefault("potions prayer regeneration", Collections.emptySet()));
		}
		else if (GROUPS.containsKey(key))
			q.ids.addAll(GROUPS.get(key));
		else
			return null;
		q.explanation = kind.equals("ammo")
				? "Compatible ammunition for " + terms + ". Weapon, Slayer and area requirements still apply."
				: "Potion effect: " + terms
						+ ". Strength, duration and side effects vary; this is not an activity recommendation.";
		return q;
	}

	static ItemCatalogueIndex.Result find(Query query, Collection<ItemCatalogueIndex.Item> items, int hitpoints)
	{
		List<ItemCatalogueIndex.Item> selected = new ArrayList<>();
		Map<Integer, ItemCatalogueIndex.Rank> notes = new HashMap<>();
		int hp = Math.max(1, Math.min(99, hitpoints));
		for (ItemCatalogueIndex.Item item : items)
		{
			String note = query.explanation;
			if (query.food && !query.raw)
			{
				Food food = FOODS.get(item.id);
				if (food == null || !food.name.equalsIgnoreCase(item.name) || !food.accepts(query, hp))
					continue;
				note = food.explanation(hp);
			}
			else
			{
				if (!query.ids.contains(item.id))
					continue;
				if (item.name.toLowerCase(Locale.ROOT).startsWith("blighted "))
					note += " Blighted: area restrictions apply.";
				if (query.raw)
				{

					if (query.minimum >= 0 || !query.flags.isEmpty())
						continue;
					note = "Raw cooking input; prepare it before eating.";
				}
			}
			selected.add(item);
			notes.put(item.id, new ItemCatalogueIndex.Rank(0, note));
		}
		selected.sort(Comparator.comparing((ItemCatalogueIndex.Item item) -> item.name, String.CASE_INSENSITIVE_ORDER)
				.thenComparingInt(item -> item.id));
		return new ItemCatalogueIndex.Result(selected, notes, false);
	}

	private static final class Food
	{
		final String name, formula;
		final int instant, delayed;
		final boolean multi, fast, combo, overheal, restricted;

		Food(String[] row)
		{
			name = row[1];
			instant = Integer.parseInt(row[2]);
			delayed = Integer.parseInt(row[3]);
			formula = row[4];
			multi = row[5].equals("1");
			fast = row[6].equals("1");
			combo = row[7].equals("1");
			overheal = row[8].equals("1");
			restricted = row[9].equals("1");
		}

		int immediate(int hp)
		{
			switch (formula)
			{
				case "anglerfish":
					return hp / 10 + 2 * (hp / 25) + 5 * (hp / 93) + 2;
				case "strawberry":
					return 1 + hp * 6 / 100;
				case "watermelon":
					return 1 + hp / 20;
				case "sweetcorn":
					return 1 + hp / 10;
				default:
					return instant;
			}
		}

		boolean accepts(Query q, int hp)
		{
			if (q.flags.contains("fast") && !fast || q.flags.contains("combo") && !combo
					|| q.flags.contains("multi") && !multi || q.flags.contains("overheal") && !overheal
					|| q.flags.contains("delayed") && delayed == 0 || q.flags.contains("instant") && delayed > 0
					|| q.flags.contains("restricted") && !restricted || q.flags.contains("unrestricted") && restricted)
				return false;
			if (q.minimum < 0)
				return true;
			if (formula.equals("unknown") || formula.equals("random"))
				return false;
			return immediate(hp) + delayed >= q.minimum;
		}

		String explanation(int hp)
		{
			String heal = formula
					.equals("unknown")
							? "Healing varies; check the item's requirements"
							: formula.equals("random") ? "Unreliable healing; excluded from healing thresholds"
									: immediate(hp) + " HP immediately"
											+ (delayed > 0 ? " + " + delayed
													+ " delayed HP (pending hunter-food healing can be replaced)" : "")
											+ " per bite";
			if (!Arrays.asList("fixed", "range", "random", "unknown").contains(formula))
				heal += " at your base " + hp + " Hitpoints";
			if (formula.equals("range"))
				heal += " (minimum; the actual amount varies)";
			return heal + "." + (multi ? " Multiple bites per item; thresholds use one bite." : "")
					+ (combo ? " Combo-eating food." : "") + (fast ? " Non-standard attack/eating delay." : "")
					+ (overheal ? " Can overheal; PvP restrictions apply." : "")
					+ (restricted ? " Blighted: Wilderness/PvP-world restrictions apply." : "");
		}
	}
}

package com.windowmarkers;

import java.awt.*;

final class TierPresentation
{
	static String ordinal(int tier)
	{
		return tier == 1 ? "1st" : tier == 2 ? "2nd" : tier == 3 ? "3rd" : tier > 0 ? tier + "th" : "";
	}

	static String key(WindowMarkersConfig config)
	{
		StringBuilder text = new StringBuilder("<html>Guide tiers: ");
		for (int i = 1; i <= 3; i++)
		{
			if (i > 1)
				text.append(" · ");
			text.append("<font color='#").append(String.format("%06x", colour(config, i).getRGB() & 0xffffff))
					.append("'>").append(ordinal(i)).append("</font>");
		}
		return text.append("</html>").toString();
	}

	static Color colour(WindowMarkersConfig config, int tier)
	{
		return tier == 1 ? config.geFirstColour() : tier == 2 ? config.geSecondColour() : config.geThirdColour();
	}

	static ItemCatalogueIndex.Rank merge(ItemCatalogueIndex.Rank a, ItemCatalogueIndex.Rank b)
	{
		if (a.tier == b.tier && a.role.equals(b.role))
			return a;
		return new ItemCatalogueIndex.Rank(0,
				"Different selected guide roles or requirements; select a single setup to see its tier.");
	}

	static void draw(Graphics2D g, Rectangle grid, int tier, WindowMarkersConfig config)
	{
		if (tier < 1 || tier > 3)
			return;
		Color colour = colour(config, tier);
		g.setStroke(new BasicStroke(2));
		BorderRenderer.plain(g, grid, colour);
		drawLabel(g, grid, tier, config);
	}

	static void drawLabel(Graphics2D g, Rectangle grid, int tier, WindowMarkersConfig config)
	{
		if (tier < 1 || tier > 3)
			return;
		Color colour = colour(config, tier);
		g.setFont(new Font("Arial", Font.BOLD, 9));
		String text = ordinal(tier);
		FontMetrics fm = g.getFontMetrics();
		int width = fm.stringWidth(text) + 4, height = fm.getHeight();
		int x = grid.x + grid.width - width, y = grid.y + grid.height - height;
		g.setColor(new Color(15, 15, 15, 220));
		g.fillRoundRect(x, y, width, height, 3, 3);
		g.setColor(colour);
		g.drawRoundRect(x, y, width - 1, height - 1, 3, 3);
		g.setColor(Color.WHITE);
		g.drawString(text, x + 2, y + fm.getAscent());
	}
}

package com.windowmarkers;

import java.util.*;

final class WikiCatalogue
{
	static final class Entry
	{
		final String facet, group;

		Entry(String facet, String group)
		{
			this.facet = facet;
			this.group = group;
		}
	}

	private static final Map<String, List<Entry>> INDEX = new HashMap<>();
	private static final Map<String, List<Entry>> CATEGORY_SUPPLEMENT = new HashMap<>();
	private static final Map<String, List<Entry>> ROLE_EXCLUSIONS = new HashMap<>();
	private static final Set<Integer> AMBIGUOUS_NAMES = new HashSet<>();
	private static final Set<Integer> EXCLUDED_IDENTITIES = new HashSet<>();
	static
	{
		for (String[] row : ItemTaxonomy.readRows("item-catalogue.tsv", 3))
		{
			INDEX.computeIfAbsent(row[0], k -> new ArrayList<>()).add(new Entry(row[1], row[2]));
		}
		for (String[] row : ItemTaxonomy.readRows("ambiguous-item-names.tsv", 1))
		{
			AMBIGUOUS_NAMES.add(Integer.parseInt(row[0]));
		}
		for (String[] row : ItemTaxonomy.readRows("catalogue-identity-exclusions.tsv", 1))
		{
			EXCLUDED_IDENTITIES.add(Integer.parseInt(row[0]));
		}

		for (String resource : new String[] { "wiki-category-supplement.tsv", "combat-equivalence-categories.tsv",
				"wiki-recipe-roles.tsv", "wiki-role-updates.tsv", "supply-search-groups.tsv" })
			for (String[] row : ItemTaxonomy.readRows(resource, 3))
			{
				if (!row[0].matches("I:[0-9]+"))
				{
					throw new IllegalStateException("Wiki category requires an exact item ID");
				}
				List<Entry> entries = CATEGORY_SUPPLEMENT.computeIfAbsent(row[0], k -> new ArrayList<>());
				if (entries.stream().noneMatch(e -> e.facet.equals(row[1]) && e.group.equals(row[2])))
				{
					entries.add(new Entry(row[1], row[2]));
				}
			}
		for (String[] row : ItemTaxonomy.readRows("catalogue-role-exclusions.tsv", 3))
		{
			if (!row[0].matches("I:[0-9]+"))
			{
				throw new IllegalStateException("Role correction requires an exact item ID");
			}
			ROLE_EXCLUSIONS.computeIfAbsent(row[0], k -> new ArrayList<>()).add(new Entry(row[1], row[2]));
		}
	}

	static List<Entry> entries(AutoCategories.Item item)
	{
		if (EXCLUDED_IDENTITIES.contains(item.id))
		{
			return Collections.emptyList();
		}
		List<Entry> result = INDEX.get("I:" + item.id);
		boolean nameSafe = !AMBIGUOUS_NAMES.contains(item.id);
		if (result == null && nameSafe)
		{
			result = INDEX.get("N:" + item.name);
		}
		if (result == null && nameSafe)
		{
			result = INDEX.get("N:" + ItemTaxonomy.baseName(item.name));
		}
		if (result == null && nameSafe && item.name.matches(".*\\s*\\([1-8]\\)$"))
		{
			List<Entry> charged = INDEX.get("N:" + item.name.replaceFirst("\\s*\\([1-8]\\)$", ""));
			if (charged != null && charged.stream().anyMatch(e -> e.facet.equals("travel")))
			{
				result = charged;
			}
		}
		List<Entry> supplement = CATEGORY_SUPPLEMENT.get("I:" + item.id);
		List<Entry> exclusions = ROLE_EXCLUSIONS.get("I:" + item.id);
		if (supplement == null && exclusions == null)
		{
			return result == null ? Collections.emptyList() : result;
		}

		List<Entry> combined = result == null ? new ArrayList<>() : new ArrayList<>(result);
		if (supplement != null)
			for (Entry entry : supplement)
			{
				if (combined.stream().noneMatch(e -> e.facet.equals(entry.facet) && e.group.equals(entry.group)))
				{
					combined.add(entry);
				}
			}

		if (exclusions != null)
		{
			combined.removeIf(
					e -> exclusions.stream().anyMatch(x -> x.facet.equals(e.facet) && x.group.equals(e.group)));
		}
		return combined;
	}

	static boolean hasFacet(AutoCategories.Item item, String facet)
	{
		return entries(item).stream().anyMatch(e -> e.facet.equals(facet));
	}

	static Set<String> groups()
	{
		Set<String> groups = new TreeSet<>();
		for (Map<String, List<Entry>> index : Arrays.asList(INDEX, CATEGORY_SUPPLEMENT))
			for (List<Entry> entries : index.values())
				for (Entry entry : entries)
					groups.add(entry.group);
		return groups;
	}

	static String category(AutoCategories.Item item, AutoCategories.Preset preset)
	{
		if (preset == AutoCategories.Preset.FOOD_AND_POTIONS && !hasFacet(item, "supply")
				&& !hasFacet(item, "restricted") && !item.action("Eat") && !item.action("Drink"))
		{
			return null;
		}
		Entry best = null;
		for (Entry entry : entries(item))
		{
			if (!accepts(preset, entry) || CatalogueArchive.hidden(entry.group))
			{
				continue;
			}
			if (best == null || priority(entry) < priority(best)
					|| (priority(entry) == priority(best) && entry.group.compareTo(best.group) < 0))
			{
				best = entry;
			}
		}
		return best == null ? null : best.group;
	}

	private static int priority(Entry e)
	{
		switch (e.facet)
		{
			case "outfit":
				return 0;
			case "restricted":
				return 1;
			case "boost":
				return 2;
			case "skilling":
				return e.group.contains("materials") || e.group.contains("ingredients") || e.group.contains("products")
						|| e.group.endsWith("recipe inputs") || e.group.endsWith("guild access")
						|| e.group.endsWith("pouch protection") || e.group.endsWith("warm clothing") ? 9 : 3;
			case "travel":
				return 4;
			case "combat":
				return e.group.startsWith("Prayer") ? 7 : 5;
			case "supply":
				return 6;
			case "utility":
				return 8;
			case "quest":
				return 10;
			case "clue":
				return 11;
			default:
				return 12;
		}
	}

	private static boolean accepts(AutoCategories.Preset p, Entry e)
	{
		switch (p)
		{
			case ALL_CATEGORIES:
			case BROAD_TYPES:
				return true;
			case SKILLING:
				return e.facet.equals("outfit") || e.facet.equals("skilling")
						|| (e.facet.equals("boost") && !e.group.startsWith("Combat"));
			case SKILLING_OUTFITS:
				return e.facet.equals("outfit");
			case COMBAT_GROUPS:
				return e.facet.equals("combat") || (e.facet.equals("boost") && e.group.startsWith("Combat"));
			case FOOD_AND_POTIONS:
				return e.facet.equals("supply") || e.facet.equals("boost") || e.facet.equals("restricted");
			case TRAVEL_AND_UTILITY:
				return e.facet.equals("travel") || e.facet.equals("utility");
			case QUESTS_AND_CLUES:
				return e.facet.equals("quest") || e.facet.equals("clue");
			case COSMETICS:
				return e.facet.equals("cosmetic");
			default:
				return false;
		}
	}

	static String source(AutoCategories.Preset preset)
	{
		switch (preset)
		{
			case SKILLING:
			case SKILLING_OUTFITS:
				return "https://oldschool.runescape.wiki/w/Skilling_equipment";
			case FOOD_AND_POTIONS:
				return "https://oldschool.runescape.wiki/w/Potions";
			case TRAVEL_AND_UTILITY:
				return "https://oldschool.runescape.wiki/w/Container_items";
			case QUESTS_AND_CLUES:
				return "https://oldschool.runescape.wiki/w/Quest_items";
			case COSMETICS:
				return "https://oldschool.runescape.wiki/w/Clothes";
			case ALL_CATEGORIES:
			case BROAD_TYPES:
			case COMBAT_GROUPS:
				return "https://oldschool.runescape.wiki/w/Equipment";
			default:
				return RaidRecommendations.source(preset);
		}
	}
}

package com.windowmarkers;

import java.util.*;

final class WildernessLoadout
{
	private static final Set<String> ACTIVITIES = new HashSet<>(Arrays.asList("Callisto", "Artio", "Venenatis",
			"Spindel", "Vet'ion", "Calvar'ion", "Scorpia", "Chaos Fanatic", "Chaos Elemental", "Revenants", "Krystilia",
			"King Black Dragon", "Green dragon", "Crazy archaeologist", "Lava dragon", "Chaos Temple (church)", "Abyss", "Chest (Rogues' Castle)"));
	private static final Map<Integer, String[]> BUDGET = new HashMap<>();
	private static final Set<Integer> EQUIPMENT = new HashSet<>();
	static
	{
		for (String[] row : ItemTaxonomy.readRows("wilderness-budget-items.tsv", 4))
			BUDGET.put(Integer.parseInt(row[0]), row);
		for (String[] row : ItemTaxonomy.readRows("ge-item-slots.tsv", 3))
			if (Integer.parseInt(row[1]) >= 0)
				EQUIPMENT.add(Integer.parseInt(row[0]));
	}

	private WildernessLoadout()
	{
	}

	static boolean applies(List<ActivitySetups.Setup> matched)
	{
		return matched.size() > 1 && ACTIVITIES.contains(matched.get(0).activity)
				&& matched.stream().allMatch(s -> s.activity.equals(matched.get(0).activity));
	}

	static boolean allowed(ItemCatalogueIndex.Item item)
	{
		if (item.slot < 0 && !EQUIPMENT.contains(item.id))
			return true;
		String[] row = BUDGET.get(item.id);
		return row != null && row[1].equalsIgnoreCase(item.name) && Integer.parseInt(row[2]) == item.slot;
	}

	static boolean allowedPreview(int id)
	{
		return !EQUIPMENT.contains(id) || BUDGET.containsKey(id);
	}

	static boolean wildernessWeapon(int id)
	{
		return BUDGET.containsKey(id) && BUDGET.get(id)[3].equals("wilderness weapon");
	}

	static List<ActivitySetups.Setup> defaults(List<ActivitySetups.Setup> matched)
	{
		List<ActivitySetups.Setup> result = new ArrayList<>();
		for (ActivitySetups.Setup setup : matched)
		{
			String label = setup.label.toLowerCase(Locale.ROOT);
			if (!label.contains("high-risk") && !label.contains("bis smuggle") && !label.contains("gravestone"))
				result.add(setup);
		}
		return result;
	}

	private static final List<Integer> EXAMPLES = Arrays.asList(3749, 10499, 1704, 2503, 2497, 2491, 6328, 12788, 892,
			4089, 2412, 4091, 4093, 7460, 4097, 28585, 11907, 1434, 3105, 3842, 12612);

	private static ItemCatalogueIndex.Item exampleItem(int id)
	{
		String[] row = BUDGET.get(id);
		if (row == null)
			return null;
		int slot = Integer.parseInt(row[2]);
		return new ItemCatalogueIndex.Item(
				new AutoCategories.Item(id, row[1], true, new String[] { "Wear" }, 0, 0, 0, slot), row[1], slot);
	}

	private static void recommendMissing(SetupLoadout part)
	{
		SetupLoadout.Table table = part.equipmentTable();
		if (table == null)
			return;
		List<SetupLoadout.Field> fields = new ArrayList<>(table.fields);
		fields.sort(Comparator.comparingInt((SetupLoadout.Field f) -> f.slot() == 3 ? 0 : 1)
				.thenComparingInt(SetupLoadout.Field::order));
		Map<Integer, List<Integer>> candidates = new LinkedHashMap<>();
		Map<Integer, String> notes = new HashMap<>();
		for (var field : fields)
			if (field.slot() >= 0)
				for (int id : field.ids)
				{
					var item = exampleItem(id);
					if (item == null || item.slot != field.slot() || wildernessWeapon(id)
							|| ItemVariantState.needsActivityReview(item.fact)
							|| !SetupItemRequirements.reviewReason(part.equipmentSource, item.fact).isEmpty())
						continue;
					candidates.computeIfAbsent(item.slot, k -> new ArrayList<>()).add(id);
					notes.put(id, field.itemNotes.getOrDefault(id, field.note));
				}
		ItemCatalogueIndex.Item weapon = part.equipment.containsKey(3) ? exampleItem(part.equipment.get(3).get(0))
				: null;
		for (var entry : candidates.entrySet())
		{
			List<Integer> existing = part.equipment.getOrDefault(entry.getKey(), Collections.emptyList());
			if (!existing.isEmpty() && (entry.getKey() != 13 || weapon == null
					|| SetupEquipmentChoice.allowed(exampleItem(existing.get(0)), "", weapon, Collections.emptyList())))
				continue;
			entry.getValue().sort(
					Comparator.comparingInt(id -> EXAMPLES.contains(id) ? EXAMPLES.indexOf(id) : Integer.MAX_VALUE));
			for (int id : entry.getValue())
			{
				var item = exampleItem(id);
				if (!SetupEquipmentChoice.allowed(item, notes.get(id), weapon, Collections.emptyList()))
					continue;
				part.equipmentExample.put(entry.getKey(), id);
				if (entry.getKey() == 3)
					weapon = item;
				break;
			}
		}
	}

	static void finish(SetupLoadout plan)
	{
		plan.wildernessBudget = true;
		for (SetupLoadout part : plan.sections())
		{
			part.wildernessBudget = true;
			recommendMissing(part);

			for (var iterator = part.inventoryExample.entrySet().iterator(); iterator.hasNext();)
			{
				var entry = iterator.next();
				var field = entry.getValue();
				List<Integer> kept = new ArrayList<>();
				for (int id : field.ids)
					if (allowedPreview(id))
						kept.add(id);
				if (kept.isEmpty())
				{
					iterator.remove();
					part.inventory.remove(entry.getKey());
				}
				else if (!kept.equals(field.ids))
				{
					SetupLoadout.Field copy = new SetupLoadout.Field(new String[] { "", field.name, "", field.note },
							field.guideOnly);
					copy.ids.addAll(kept);
					copy.itemNotes.putAll(field.itemNotes);
					entry.setValue(copy);
				}
			}
			part.equipment.forEach((slot, ids) ->
			{
				for (int id : ids)
					part.equipmentNotes.put(id,
							(wildernessWeapon(id) ? "Owned Wilderness weapon; charges and ether add risk. "
									: "Owned budget choice for Wilderness travel/content. ")
									+ "Check items kept on death; no protection is assumed. "
									+ part.equipmentNotes.getOrDefault(id, ""));
			});
		}
	}
}

