	@Test
	public void potionViewHidesUnderlyingBankItemsAndRestoresOnlyItsOwnVisibility()
	{
		for (boolean originallyHidden : new boolean[] { false, true })
		{
			Harness h = new Harness();
			Cell container = h.extra(InterfaceID.Bankmain.POTIONSTORE_CONTAINER, h.f.container, 1, 39, 409, 300);
			h.extra(InterfaceID.Bankmain.POTIONSTORE_ITEMS, container, 0, 0, 409, 300);
			h.f.items.widget.setHidden(originallyHidden);
			h.build();
			assertTrue(h.f.items.widget.isSelfHidden());
			for (int width : new int[] { 600, 450, 700 })
			{
				h.f.container.widget.setOriginalWidth(width);
				h.frame();
				assertTrue(h.f.items.widget.isSelfHidden());
			}
			container.widget.setHidden(true);
			h.frame();
			assertEquals(originallyHidden, h.f.items.widget.isSelfHidden());
			container.widget.setHidden(false);
			h.frame();
			assertTrue(h.f.items.widget.isSelfHidden());
			h.c.shutDown();
			h.flush();
			assertEquals(originallyHidden, h.f.items.widget.isSelfHidden());
		}
	}

	@Test
	public void potionViewportFitsBesideButtonsAndScrollsWithoutChangingBankScroll()
	{
		Harness h = new Harness();
		Cell container = h.extra(InterfaceID.Bankmain.POTIONSTORE_CONTAINER, h.f.container, 1, 39, 53, 81);
		container.widget.setXPositionMode(2);
		container.widget.setYPositionMode(2);
		container.widget.setWidthMode(1);
		container.widget.setHeightMode(1);
		Cell items = h.extra(InterfaceID.Bankmain.POTIONSTORE_ITEMS, container, 16, 0, 16, 0);
		items.widget.setXPositionMode(2);
		items.widget.setWidthMode(1);
		items.widget.setHeightMode(1);
		Cell scroll = h.extra(InterfaceID.Bankmain.POTIONSTORE_SCROLLBAR, container, 0, 0, 16, 0);
		scroll.widget.setXPositionMode(2);
		scroll.widget.setHeightMode(1);
		h.f.items.widget.setHidden(true);
		items.widget.setScrollHeight(1600);
		h.varcs.put(net.runelite.api.gameval.VarClientID.BANK_SCROLLPOS, 180);
		h.build();
		assertTrue(scroll.widget.isSelfHidden());
		assertTrue(items.bounds().x + items.bounds().width <= h.f.container.bounds().x + h.f.container.bounds().width
				- 51);
		for (Rectangle button : h.bar.plan.bounds.values())
		{
			Rectangle translated = new Rectangle(button);
			translated.translate(h.f.container.bounds().x, h.f.container.bounds().y);
			assertFalse(translated.intersects(items.bounds()));
		}
		Rectangle area = items.bounds();
		Point cursor = new Point(area.x + 20, area.y + 50);
		assertTrue(h.bar.mouseWheelMoved(wheel(cursor, 2)).isConsumed());
		h.flush();
		assertEquals(72, items.widget.getScrollY());
		assertEquals(Integer.valueOf(180), h.varcs.get(net.runelite.api.gameval.VarClientID.BANK_SCROLLPOS));
		h.c.shutDown();
		h.flush();
		assertFalse(scroll.widget.isSelfHidden());
		assertEquals(53, container.widget.getOriginalWidth());
		assertEquals(16, items.widget.getOriginalWidth());
	}

	@Test
	public void disablingTheDividerHidesItsBarAndRetainsTheSavedSplit() throws Exception
	{
		Harness h = new Harness();
		when(h.c.config.bankActionTagSpace()).thenReturn(true);
		h.saved = "v2;split:80;SEARCH:T:0;PLACEHOLDERS:T:50;";
		h.build();
		int split = h.bar.plan.tagTop;
		String saved = h.saved;
		Map<String, Rectangle> positions = new LinkedHashMap<>(h.bar.plan.bounds);
		when(h.c.config.bankTagDividerResizable()).thenReturn(false);
		h.frame();
		Rectangle area = h.f.container.bounds();
		Point grip = new Point(area.x + 25, area.y + split - 3);
		List<Object> mocks = new ArrayList<>();
		mocks.add(h.c.config);
		mocks.add(h.c.client);
		h.f.cells.values().forEach(cell -> mocks.add(cell.widget));
		clearInvocations(mocks.toArray());
		SwingUtilities.invokeAndWait(
				() -> assertFalse(h.bar.mousePressed(mouse(MouseEvent.MOUSE_PRESSED, grip, false)).isConsumed()));
		verifyNoInteractions(mocks.toArray());
		java.awt.Graphics2D graphics = mock(java.awt.Graphics2D.class);
		when(graphics.create()).thenReturn(graphics);
		h.bar.overlay.render(graphics);
		verify(graphics, times(2)).drawLine(anyInt(), anyInt(), anyInt(), anyInt());
		verify(graphics, never()).fillRect(anyInt(), anyInt(), anyInt(), anyInt());
		assertEquals(split, h.bar.plan.tagTop);
		assertEquals(positions, h.bar.plan.bounds);
		assertEquals(saved, h.saved);
		Point button = h.center(BankControl.PLACEHOLDERS), end = new Point(button.x, button.y + 35);
		h.press(button);
		h.drag(end);
		h.frame();
		h.release(end);
		h.frame();
		h.flush();
		assertEquals(80, BankActionLayout.read(h.saved).tagOffset);
		assertEquals(positions.get("PLACEHOLDERS").y + 35, h.bar.plan.bounds.get("PLACEHOLDERS").y);
		when(h.c.config.bankTagDividerResizable()).thenReturn(true);
		h.frame();
		assertTrue(h.bar.mousePressed(mouse(MouseEvent.MOUSE_PRESSED, grip, false)).isConsumed());
	}

