	@Test
	public void splitterDragsWithoutAltAndStopsAtTheOriginalMidpoint()
	{
		Harness h = new Harness();
		when(h.c.config.bankActionTagSpace()).thenReturn(true);
		h.saved = "v1;SEARCH:T:0;PLACEHOLDERS:T:50;";
		h.build();
		Rectangle area = h.f.container.bounds();
		int initial = h.bar.plan.tagTop;
		Point start = new Point(area.x + 25, area.y + initial - 3), end = new Point(start.x, start.y + 90);
		Rectangle search = h.f.cells.get(BankControl.SEARCH.button).bounds();
		assertTrue(h.bar.mousePressed(mouse(MouseEvent.MOUSE_PRESSED, start, false)).isConsumed());
		h.drag(end);
