		for (int i = 0; i < 5; i++)
			h.build();
		assertEquals(initial + 90, h.bar.plan.tagTop);
		start = new Point(area.x + 25, area.y + h.bar.plan.tagTop - 3);
		end = new Point(start.x, start.y - 500);
		h.press(start);
		h.drag(end);
		h.frame();
		h.release(end);
		h.frame();
		h.flush();
		assertEquals(initial, h.bar.plan.tagTop);
		assertEquals(0, BankActionLayout.read(h.saved).tagOffset);
	}

	@Test
	public void splitterLowerLimitReservesEveryButtonOnItsTrack()
	{
		BankActionLayout layout = BankActionLayout.read("v2;split:4000;SEARCH:T:0;PLACEHOLDERS:T:50;");
		Map<String, Dimension> sizes = new LinkedHashMap<>();
		sizes.put("SEARCH", new Dimension(36, 36));
		BankActionLayout.Plan one = layout.plan(718, 650, sizes, true);
		sizes.put("PLACEHOLDERS", new Dimension(36, 36));
		BankActionLayout.Plan two = layout.plan(718, 650, sizes, true);
		assertEquals(one.tagTop - 38, two.tagTop);
		assertEquals(650 - two.bottomHeight - 4, two.bounds.get("PLACEHOLDERS").y + 36);
		assertEquals(two.tagTop + 38, two.bounds.get("PLACEHOLDERS").y);
		for (Rectangle r : two.bounds.values())
			assertTrue(BankActionLayout.rail('T', 718, 650, two.bottomHeight, two.tagTop).contains(r));
		assertEquals(4000, BankActionLayout.read(layout.write()).tagOffset);
	}

	@Test
	public void splitterPreferenceSurvivesSmallerBanksAndHiddenTagSpace()
	{
		BankActionLayout layout = BankActionLayout.read("v2;split:150;SEARCH:T:0;PLACEHOLDERS:T:50;");
		Map<String, Dimension> sizes = new LinkedHashMap<>();
		for (BankControl control : BankControl.values())
			sizes.put(control.name(), new Dimension(control == BankControl.SEARCH ? 36 : control.width, 36));
		BankActionLayout.Plan initial = layout.plan(718, 650, sizes, true);
		String saved = layout.write();
		for (int height : new int[] { 340, 250, 650 })
			for (boolean tags : new boolean[] { false, true })
			{
				BankActionLayout.Plan plan = layout.plan(718, height, sizes, tags);
				assertEquals(sizes.size(), plan.bounds.size());
				plan.bounds.forEach((key, r) ->
				{
					assertTrue(new Rectangle(0, 0, 718, height).contains(r));
					plan.bounds.forEach((other, b) ->
					{
						if (!other.equals(key))
							assertFalse(r.intersects(b));
					});
				});
			}
		assertEquals(saved, layout.write());
		assertEquals(initial.bounds, BankActionLayout.read(saved).plan(718, 650, sizes, true).bounds);
	}

	@Test
	public void splitterInputOnlyUsesThePublishedSnapshotAndCancelsAcrossContexts() throws Exception
	{
		for (boolean profile : new boolean[] { false, true })
		{
			Harness h = new Harness();
			when(h.c.config.bankActionTagSpace()).thenReturn(true);
			h.build();
			Rectangle area = h.f.container.bounds();
			Point start = new Point(area.x + 25, area.y + h.bar.plan.tagTop - 3),
					end = new Point(start.x, start.y + 75);
			List<Object> mocks = new ArrayList<>();
			mocks.add(h.c.client);
			mocks.add(h.c.config);
			h.f.cells.values().forEach(cell -> mocks.add(cell.widget));
			clearInvocations(mocks.toArray());
			SwingUtilities.invokeAndWait(() ->
			{
				assertTrue(h.bar.mousePressed(mouse(MouseEvent.MOUSE_PRESSED, start, false)).isConsumed());
				h.drag(end);
			});
			verifyNoInteractions(mocks.toArray());
			h.frame();
