	@Test
	public void loweredSplitterExpandsTagViewportAndRestoresNativeArrows()
	{
		Harness h = new Harness();
		when(h.c.config.bankActionTagSpace()).thenReturn(true);
		Cell up = h.tag(41, 20), down = h.tag(620, 20);
		when(up.widget.getActions()).thenReturn(new String[] { null, "Scroll up" });
		when(down.widget.getActions()).thenReturn(new String[] { null, "Scroll down" });
		int[] original = down.geometry.clone();
		List<Cell> tags = new ArrayList<>();
		for (int i = 0; i < 15; i++)
		{
			Cell tag = h.tag(62 + i * 41, 40);
			when(tag.widget.getActions()).thenReturn(new String[] { null, "View tag tab" });
			tags.add(tag);
		}
		h.build();
		long initial = tags.stream().filter(t -> !t.widget.isSelfHidden()).count();
		Rectangle area = h.f.container.bounds();
		Point start = new Point(area.x + 25, area.y + h.bar.plan.tagTop - 3), end = new Point(start.x, start.y + 100);
		h.press(start);
		h.drag(end);
		h.frame();
		h.release(end);
		h.frame();
		h.flush();
		assertTrue(tags.stream().filter(t -> !t.widget.isSelfHidden()).count() > initial);
		assertEquals(area.y + h.bar.plan.tagTop - 5, down.bounds().y + down.bounds().height);
		h.c.shutDown();
		h.flush();
		assertArrayEquals(original, down.geometry);
	}

	@Test
	public void nativeActionsArtworkAndDimensionsSurviveRightRailPlacement()
	{
		Harness h = new Harness();
		Map<Widget, int[]> original = new HashMap<>();
		for (Cell c : h.f.cells.values())
			original.put(c.widget, c.geometry.clone());
		h.build();
		Rectangle area = h.f.container.bounds();
		for (BankControl control : BankControl.values())
		{
			Widget w = h.f.cells.get(control.button).widget;
			Rectangle bounds = w.getBounds();
			assertEquals(control == BankControl.SEARCH ? 36 : control.width, bounds.width);
			assertEquals(36, bounds.height);
			if (!control.quantity())
				assertTrue(bounds.x >= area.x + area.width - 50);
			verify(w, never()).setOnOpListener(any(Object[].class));
			verify(w, never()).setClickMask(anyInt());
			verify(w, never()).clearActions();
			Widget icon = h.f.cells.get(control.graphic).widget;
			assertEquals(bounds.x + (control == BankControl.SEARCH ? 4 : control.iconX), icon.getBounds().x);
			assertEquals(bounds.y + control.iconY, icon.getBounds().y);
		}
		assertTrue(h.f.cells.get(InterfaceID.Bankmain.SCROLLBAR).widget.isSelfHidden());
		for (int i = 0; i < 10; i++)
			h.frame();
		h.c.shutDown();
		h.flush();
		for (Map.Entry<Widget, int[]> e : original.entrySet())
			assertArrayEquals(e.getValue(), geometry(e.getKey()));
		assertFalse(h.f.cells.get(InterfaceID.Bankmain.SCROLLBAR).widget.isSelfHidden());
	}

