		Cell equipment = h.extra(InterfaceID.Bankmain.WORNITEMS_BUTTON, h.f.root, 5, 5, 30, 30);
		equipment.widget.setAction(0, "Worn equipment");
		Rectangle original = equipment.bounds();
		h.build();
		Rectangle aligned = equipment.bounds();
		assertEquals(h.f.container.bounds().x + h.f.container.bounds().width - 25, aligned.x + aligned.width / 2);
		assertEquals(h.f.container.bounds().y + (BankActionLayout.TOP - aligned.height) / 2, aligned.y);
		Point start = new Point(aligned.x + 10, aligned.y + 10),
				end = new Point(h.f.container.bounds().x + h.f.container.bounds().width - 20,
						h.f.container.bounds().y + 500);
		h.press(start);
		h.drag(end);
		h.frame();
		h.release(end);
		h.frame();
		h.flush();
		assertTrue(equipment.bounds().x > original.x + 500);
		start = new Point(equipment.bounds().x + 10, equipment.bounds().y + 10);
		end = new Point(h.f.root.bounds().x + 300, h.f.root.bounds().y + 2);
		h.press(start);
		h.drag(end);
		h.frame();
		h.release(end);
		h.frame();
		h.flush();
		assertEquals(aligned, equipment.bounds());
		verify(equipment.widget, never()).setOnOpListener(any(Object[].class));
		h.c.shutDown();
		h.flush();
		assertEquals(original, equipment.bounds());
	}

