	@Test
	public void sharedTagsCanScrollToTheLastTagAndRestoreTheirOriginalCallbacks()
	{
		Harness h = new Harness();
		when(h.c.config.bankActionTagSpace()).thenReturn(true);
		Cell up = h.tag(41, 20), down = h.tag(620, 20);
		when(up.widget.getActions()).thenReturn(new String[] { null, "Scroll up" });
		when(down.widget.getActions()).thenReturn(new String[] { null, "Scroll down" });
		Object[] nativeUp = { (JavaScriptCallback) e ->
		{
		} }, nativeDown = { (JavaScriptCallback) e ->
		{
		} };
		up.widget.setOnOpListener(nativeUp);
		down.widget.setOnOpListener(nativeDown);
		List<Cell> tags = new ArrayList<>();
		List<int[]> positions = new ArrayList<>();
		for (int i = 0; i < 20; i++)
		{
			Cell tag = h.tag(62 + i * 41, 40);
			when(tag.widget.getActions()).thenReturn(new String[] { null, "View tag tab" });
			tags.add(tag);
			positions.add(tag.geometry.clone());
			if (i >= 14)
				tag.widget.setHidden(true);
		}
		h.build();
		Rectangle area = h.f.container.bounds();
		int divider = BankActionLayout.tagTop(area.height, h.bar.plan.bottomHeight) - 5;
		for (Cell tag : tags)
			if (!tag.widget.isSelfHidden())
				assertTrue(tag.bounds().y + tag.bounds().height <= area.y + divider - down.bounds().height);
		assertFalse(tags.get(0).widget.isSelfHidden());
		assertTrue(tags.get(19).widget.isSelfHidden());
		h.c.client.setVarcIntValue(net.runelite.api.gameval.VarClientID.BANK_SCROLLPOS, 123);
		assertTrue(h.bar.mouseWheelMoved(wheel(new Point(area.x + 10, area.y + 100), 50)).isConsumed());
		h.flush();
		h.frame();
		assertFalse(tags.get(19).widget.isSelfHidden());
		assertTrue(tags.get(0).widget.isSelfHidden());
		assertEquals(0, h.f.items.widget.getScrollY());
		assertEquals(123, h.c.client.getVarcIntValue(net.runelite.api.gameval.VarClientID.BANK_SCROLLPOS));
		for (int i = 0; i < 10; i++)
		{
			h.bar.apply(h.f.container.widget);
			h.frame();
		}
		h.c.shutDown();
		h.flush();
		assertArrayEquals(nativeUp, up.widget.getOnOpListener());
		assertArrayEquals(nativeDown, down.widget.getOnOpListener());
		for (int i = 0; i < 20; i++)
		{
			assertEquals(i >= 14, tags.get(i).widget.isSelfHidden());
			assertArrayEquals(positions.get(i), tags.get(i).geometry);
		}
	}

