	@Test
	public void layoutFitsEveryButtonWithoutShrinkingOrOverlap()
	{
		Map<String, Dimension> sizes = new LinkedHashMap<>();
		for (BankControl c : BankControl.values())
			sizes.put(c.name(), new Dimension(c.width, 36));
		sizes.put("PRESETS", new Dimension(96, 22));
		sizes.put("EQUIPMENT", new Dimension(30, 30));
		for (int width : new int[] { 478, 510, 718, 1000 })
			for (int height : new int[] { 160, 240, 330, 650 })
				for (char dock : new char[] { 'B', 'L', 'R', 'T' })
				{
					BankActionLayout layout = BankActionLayout.read("");
					int n = 0;
					for (String key : sizes.keySet())
						layout.move(key, dock, n++ * 40);
					BankActionLayout.Plan plan = layout.plan(width, height, sizes, true);
					assertEquals(sizes.keySet(), plan.bounds.keySet());
					for (Map.Entry<String, Rectangle> e : plan.bounds.entrySet())
					{
						Rectangle r = e.getValue();
						assertEquals(sizes.get(e.getKey()), r.getSize());
						assertTrue(new Rectangle(0, 0, width, height).contains(r));
						for (Map.Entry<String, Rectangle> other : plan.bounds.entrySet())
							if (!other.getKey().equals(e.getKey()))
								assertFalse(e.getKey() + " overlaps " + other.getKey(), r.intersects(other.getValue()));
