				}
	}

	@Test
	public void customViewFitsFullColumnsBetweenTheTagStripAndRightRack()
	{
		for (int width : new int[] { 478, 624, 718, 1000 })
		{
			Harness h = new Harness();
			h.f.container.widget.setOriginalWidth(width);
			when(h.c.config.bankLayoutEnabled()).thenReturn(false);
			when(h.c.config.columns()).thenReturn(4);
			List<Cell> cells = new ArrayList<>();
			for (int i = 0; i < 48; i++)
			{
				Cell cell = h.extra(20000 + i, h.f.items, 51 + (i % 8) * 48, (i / 8) * 36, 36, 32);
				when(cell.widget.getType()).thenReturn(net.runelite.api.widgets.WidgetType.GRAPHIC);
				when(cell.widget.getItemId()).thenReturn(385);
				h.f.items.children.add(cell.widget);
				cells.add(cell);
			}
			h.build();
			Rectangle area = h.f.container.bounds(), viewport = h.f.items.bounds();
			int row = cells.get(0).bounds().y, right = 0, count = 0;
			for (Cell cell : cells)
				if (cell.bounds().y == row)
				{
					Rectangle r = cell.bounds();
					assertTrue(viewport.contains(r));
					assertTrue(r.x >= area.x + 56);
					assertEquals(36, r.width);
					assertEquals(32, r.height);
					right = Math.max(right, r.x + r.width);
					count++;
