	private static final class Harness
	{
		final BankControlLayoutTest.Fixture f = new BankControlLayoutTest.Fixture();
		final BankLayoutController c = f.controller;
		final BankActionBar bar = c.actionBar;
		final List<Runnable> pending = new ArrayList<>();
		final Map<Integer, Integer> varcs = new java.util.HashMap<>();
		String saved = "";
		int id = 10000;

		Harness()
		{
			when(c.client.getVarcIntValue(anyInt())).thenAnswer(call -> varcs.getOrDefault(call.getArgument(0), 0));
			doAnswer(call ->
			{
				varcs.put(call.getArgument(0), call.getArgument(1));
				return null;
			}).when(c.client).setVarcIntValue(anyInt(), anyInt());
			for (Cell cell : f.cells.values())
				prepare(cell);
			when(c.config.bankActionRail()).thenReturn(true);
			when(c.config.bankButtonDragging()).thenReturn(true);
			when(c.config.bankTagDividerResizable()).thenReturn(true);
			when(c.config.bankActionLayout()).thenAnswer(call -> saved);
			when(c.client.getGameState()).thenReturn(GameState.LOGGED_IN);
			c.configs = mock(ConfigManager.class, RETURNS_DEEP_STUBS);
			when(c.configs.getProfile().getId()).thenReturn(10L);
			doAnswer(call ->
			{
				pending.add(call.getArgument(0));
				return null;
			}).when(c.clientThread).invokeLater(any(Runnable.class));
			doAnswer(call ->
			{
				saved = call.getArgument(2);
				ConfigChanged e = new ConfigChanged();
				e.setGroup("windowmarkers");
				e.setKey("bankActionLayout");
				f.bus.post(e);
				return null;
			}).when(c.configs).setConfiguration(eq("windowmarkers"), eq("bankActionLayout"), anyString());
		}

		void prepare(Cell cell)
		{
			when(cell.widget.getParent()).thenReturn(cell.parent == null ? null : cell.parent.widget);
			when(cell.widget.isSelfHidden()).thenAnswer(call -> cell.properties.getOrDefault("Hidden", false));
			when(cell.widget.isHidden()).thenAnswer(call -> (boolean) cell.properties.getOrDefault("Hidden", false)
					|| cell.parent != null && cell.parent.widget.isHidden());
		}

		Cell extra(int id, Cell parent, int x, int y, int w, int height)
		{
			Cell cell = f.add(id, parent, x, y, w, height, 0, 0, 0, 0);
			prepare(cell);
			return cell;
		}

		Cell tag(int y, int height)
		{
			Cell cell = extra(id++, f.container, 1, y, 39, height);
			f.container.children.add(cell.widget);
			return cell;
		}

		void build()
		{
			f.build();
			frame();
		}

		void nativeInventoryRebuild()
		{
			f.bus.post(new ScriptPreFired(ScriptID.BANKMAIN_BUILD));
			f.build();
			int maximum = Math.max(0, f.items.widget.getScrollHeight() - f.items.widget.getHeight());
			f.items.widget.setScrollY(Math.max(0,
					Math.min(maximum, c.client.getVarcIntValue(net.runelite.api.gameval.VarClientID.BANK_SCROLLPOS))));
			f.bus.post(new net.runelite.api.events.ScriptPostFired(ScriptID.BANKMAIN_BUILD));
			frame();
		}

		void frame()
		{
			f.bus.post(new BeforeRender());
		}

		void flush()
		{
			int tries = 0;
			while (!pending.isEmpty() && tries++ < 20)
			{
				List<Runnable> batch = new ArrayList<>(pending);
				pending.clear();
				batch.forEach(Runnable::run);
			}
			assertTrue(pending.isEmpty());
			frame();
		}

		Point center(BankControl control)
		{
			Rectangle r = f.cells.get(control.button).bounds();
			return new Point(r.x + r.width / 2, r.y + r.height / 2);
		}

		void press(Point p)
		{
			assertTrue(bar.mousePressed(mouse(MouseEvent.MOUSE_PRESSED, p, true)).isConsumed());
		}

		void drag(Point p)
		{
			bar.mouseDragged(mouse(MouseEvent.MOUSE_DRAGGED, p, true));
		}

		void release(Point p)
		{
			bar.mouseReleased(mouse(MouseEvent.MOUSE_RELEASED, p, true));
		}

		MouseEvent click(Point p)
		{
			return bar.mouseClicked(mouse(MouseEvent.MOUSE_CLICKED, p, true));
		}
	}
}

package com.windowmarkers;

import java.awt.Dimension;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;

public class BankActionLayoutTest
{
	@Test
	public void legacyOffsetsPreserveGapsAndCenterOnTheStripAxis()
	{
		BankActionLayout layout = BankActionLayout.read("v2;A:R:0:1:300;B:R:1:9:50;C:B:0:300:10;D:B:1:50:0;");
		Map<String, Dimension> sizes = sizes("A", "B", "C", "D");
		BankActionLayout.Plan plan = layout.plan(718, 650, sizes, true);
		assertEquals(104, plan.bounds.get("B").y);
		assertEquals(354, plan.bounds.get("A").y);
		assertEquals(693, plan.bounds.get("A").getCenterX(), 0.5);
		assertEquals(plan.bounds.get("A").getCenterX(), plan.bounds.get("B").getCenterX(), 0.5);
		assertEquals(52, plan.bounds.get("D").x);
		assertEquals(302, plan.bounds.get("C").x);
		assertEquals(plan.bounds.get("C").getCenterY(), plan.bounds.get("D").getCenterY(), 0.5);
		assertEquals(plan.bounds, BankActionLayout.read(layout.write()).plan(718, 650, sizes, true).bounds);
	}

	@Test
	public void shrinkingSideStripsFillsThemBeforeOverflowingInOrder()
	{
		BankActionLayout layout = layout('R', "A", "B", "C", "D", "E", "F");
		Map<String, Dimension> sizes = sizes("A", "B", "C", "D", "E", "F");
		String saved = layout.write();
		Map<String, Rectangle> large = layout.plan(718, 650, sizes, true).bounds;
		BankActionLayout.Plan small = layout.plan(718, 240, sizes, true);
		assertEquals(Arrays.asList("A", "B", "C"), on(small, 'R'));
		assertEquals(Arrays.asList("D", "E", "F"), on(small, 'B'));
		assertEquals(36, small.bottomHeight);
		assertFits(small, sizes, 718, 240);
		assertEquals(saved, layout.write());
		assertEquals(large, layout.plan(718, 650, sizes, true).bounds);
	}

	@Test
	public void overflowUsesNearbyAvailableSideBeforeBottom()
	{
		BankActionLayout layout = layout('T', "A", "B", "C", "D");
		BankActionLayout.Plan plan = layout.plan(718, 240, sizes("A", "B", "C", "D"), true);
		assertEquals(Arrays.asList("A"), on(plan, 'T'));
		assertEquals(Arrays.asList("B", "C", "D"), on(plan, 'L'));
		assertTrue(on(plan, 'B').isEmpty());
	}

	@Test
	public void shrinkingBottomStripMovesTheTailToNearestSide()
	{
		String[] keys = { "A", "B", "C", "D", "E", "F", "G", "H", "I", "J", "K", "L", "M", "N" };
		Map<String, Dimension> sizes = sizes(keys);
		BankActionLayout layout = layout('B', keys);
		BankActionLayout.Plan plan = layout.plan(478, 400, sizes, false);
		assertEquals(12, on(plan, 'B').size());
		assertEquals(Arrays.asList("M", "N"), on(plan, 'R'));
		assertEquals(36, plan.bottomHeight);
		assertFits(plan, sizes, 478, 400);
		assertEquals(14, on(layout.plan(718, 400, sizes, false), 'B').size());
	}

	@Test
	public void existingMembersKeepTheirOrderBeforeOverflowArrives()
	{
		BankActionLayout layout = layout('T', "A", "B", "C", "D");
		layout.move("X", 'L', 0);
		layout.move("Y", 'L', 1);
		Map<String, Dimension> sizes = sizes("A", "B", "C", "D", "X", "Y");
		BankActionLayout.Plan plan = layout.plan(718, 240, sizes, true);
		assertEquals(Arrays.asList("X", "Y", "B"), on(plan, 'L'));
		assertEquals(Arrays.asList("C", "D"), on(plan, 'B'));
		assertFits(plan, sizes, 718, 240);
	}

	@Test
	public void unavailableLeftStripDoesNotChangeSavedDestination()
	{
		BankActionLayout layout = layout('L', "A", "B", "C", "D");
		String saved = layout.write();
		Map<String, Dimension> sizes = sizes("A", "B", "C", "D");
		for (boolean tags : new boolean[] { false, true })
		{
			BankActionLayout.Plan plan = layout.plan(478, 240, sizes, tags);
			assertTrue(on(plan, 'L').isEmpty());
			assertFits(plan, sizes, 478, 240);
		}
		assertEquals(saved, layout.write());
		assertEquals(4, on(layout.plan(718, 650, sizes, true), 'L').size());
	}

	@Test
	public void mixedButtonsStayVisibleAlignedAndOrderedThroughRepeatedResizes()
	{
		Map<String, Dimension> sizes = new LinkedHashMap<>();
		BankActionLayout layout = BankActionLayout.read("");
		char[] docks = { 'R', 'L', 'T', 'B' };
		for (int i = 0; i < 18; i++)
		{
			String key = "BUTTON_" + (char) ('A' + i);
			sizes.put(key,
					new Dimension(i % 6 == 0 ? 96 : i % 3 == 0 ? 46 : 36, i % 6 == 0 ? 22 : i % 4 == 0 ? 30 : 36));
			layout.move(key, docks[i % 4], i);
			layout.entries.get(key).offset = i * 57;
		}
		String saved = layout.write();
		Map<String, Rectangle> initial = layout.plan(1000, 650, sizes, true).bounds;
		for (int width : new int[] { 1000, 718, 536, 510, 478, 718, 1000 })
			for (int height : new int[] { 650, 330, 240, 160, 240, 650 })
				for (boolean tags : new boolean[] { false, true })
				{
					BankActionLayout.Plan plan = layout.plan(width, height, sizes, tags);
					assertFits(plan, sizes, width, height);
					for (char dock : docks)
					{
						List<String> own = new ArrayList<>();
						for (String key : on(plan, dock))
							if (layout.entries.get(key).dock == dock)
								own.add(key);
						for (int i = 1; i < own.size(); i++)
							assertTrue(layout.entries.get(own.get(i - 1)).order < layout.entries.get(own.get(i)).order);
					}
				}
		assertEquals(saved, layout.write());
		assertEquals(initial, layout.plan(1000, 650, sizes, true).bounds);
	}

	@Test
	public void spacedButtonsCloseGapsBeforeOverflowAndRecoverOnExpansion()
	{
		BankActionLayout layout = BankActionLayout.read("v2;A:R:0:0:40;B:R:1:0:200;C:R:2:0:400;D:R:3:0:500;");
		Map<String, Dimension> sizes = sizes("A", "B", "C", "D");
		String saved = layout.write();
		BankActionLayout.Plan original = layout.plan(718, 650, sizes, true);
		BankActionLayout.Plan medium = layout.plan(718, 300, sizes, true);
		assertEquals(Arrays.asList("A", "B", "C", "D"), on(medium, 'R'));
		assertFits(medium, sizes, 718, 300);
		BankActionLayout.Plan small = layout.plan(718, 240, sizes, true);
		assertEquals(Arrays.asList("A", "B", "C"), on(small, 'R'));
		assertEquals(Arrays.asList("D"), on(small, 'B'));
		assertFits(small, sizes, 718, 240);
		assertEquals(saved, layout.write());
		assertEquals(original.bounds, layout.plan(718, 650, sizes, true).bounds);
	}

	@Test
	public void slidingIntoTheMiddleRetainsOrderAndOffsetAfterReload()
	{
		BankActionLayout layout = layout('R', "A", "B", "C", "D");
		Map<String, Dimension> sizes = sizes("A", "B", "C", "D");
		BankActionLayout.Plan initial = layout.plan(718, 650, sizes, false);
		Rectangle rail = BankActionLayout.rail('R', 718, 650, initial.bottomHeight);
		layout.insert("D", 'R', new java.awt.Point(rail.x, 110), rail, initial.bounds, initial.docks);
		BankActionLayout.Plan result = layout.plan(718, 650, sizes, false);
		assertEquals(Arrays.asList("A", "B", "D", "C"), on(result, 'R'));
		assertEquals(result.bounds, BankActionLayout.read(layout.write()).plan(718, 650, sizes, false).bounds);
	}

	private static BankActionLayout layout(char dock, String... keys)
	{
		BankActionLayout layout = BankActionLayout.read("");
		for (int i = 0; i < keys.length; i++)
			layout.move(keys[i], dock, i);
		return layout;
	}

	private static Map<String, Dimension> sizes(String... keys)
	{
		Map<String, Dimension> sizes = new LinkedHashMap<>();
		for (String key : keys)
			sizes.put(key, new Dimension(36, 36));
		return sizes;
	}

	private static List<String> on(BankActionLayout.Plan plan, char dock)
	{
		List<String> keys = new ArrayList<>();
		plan.docks.forEach((key, value) ->
		{
			if (value == dock)
				keys.add(key);
		});
		keys.sort((a, b) ->
		{
			Rectangle first = plan.bounds.get(a), second = plan.bounds.get(b);
			int row = Double.compare(first.getCenterY(), second.getCenterY());
			return row != 0 ? row : Integer.compare(first.x, second.x);
		});
		return keys;
	}

	private static void assertFits(BankActionLayout.Plan plan, Map<String, Dimension> sizes, int width, int height)
	{
		assertEquals(width + "x" + height, sizes.keySet(), plan.bounds.keySet());
		plan.bounds.forEach((key, r) ->
		{
			assertEquals(sizes.get(key), r.getSize());
			assertTrue(new Rectangle(0, 0, width, height).contains(r));
			plan.bounds.forEach((other, b) ->
			{
				if (!key.equals(other))
					assertFalse(key + " overlaps " + other, r.intersects(b));
			});
			char dock = plan.docks.get(key);
			if (dock != 'B')
				assertEquals(BankActionLayout.rail(dock, width, height, plan.bottomHeight, plan.tagTop).getCenterX(),
						r.getCenterX(), 0.5);
		});
	}
}

package com.windowmarkers;

import java.util.Collections;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.BooleanSupplier;
import java.awt.Color;
import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageCapture;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class BankCaptureTest
{
	private BankCapture capture;
	private Widget item;
	private AsyncBufferedImage image;
	private final List<BooleanSupplier> tasks = new ArrayList<>();
	private final List<Boolean> results = new ArrayList<>();

	private void setup()
	{
		capture = new BankCapture();
		capture.client = mock(Client.class);
		capture.items = mock(ItemManager.class);
		capture.clientThread = mock(ClientThread.class);
		doAnswer(call ->
		{
			tasks.add(call.getArgument(0));
			return null;
		}).when(capture.clientThread).invokeLater(any(BooleanSupplier.class));
		capture.config = new WindowMarkersConfig()
		{
		};
		capture.capture = mock(ImageCapture.class);
		Widget bank = mock(Widget.class), grid = mock(Widget.class);
		item = mock(Widget.class);
		when(capture.client.getWidget(InterfaceID.Bankmain.UNIVERSE)).thenReturn(bank);
		when(capture.client.getWidget(InterfaceID.Bankmain.ITEMS)).thenReturn(grid);
		when(grid.getWidth()).thenReturn(80);
		when(grid.getDynamicChildren()).thenReturn(new Widget[] { item });
		when(item.getItemId()).thenReturn(385);
		when(item.getItemQuantity()).thenReturn(1);
		when(capture.items.getItemComposition(385)).thenReturn(mock(ItemComposition.class));
		image = new AsyncBufferedImage(mock(ClientThread.class), 36, 32, BufferedImage.TYPE_INT_ARGB);
		when(capture.items.getImage(385, 1, true)).thenReturn(image);
	}

	@Test
	public void coldItemImagesMustFinishBeforeScreenshotIsSaved()
	{
		setup();
		assertTrue(capture.save(Collections.emptyList(), () -> true, results::add));
		assertFalse(tasks.get(0).getAsBoolean());
		verifyNoInteractions(capture.capture);

		when(item.getRelativeX()).thenReturn(50);
		when(item.getItemId()).thenReturn(999);
		image.setRGB(0, 0, Color.RED.getRGB());
		image.loaded();
		assertTrue(tasks.get(0).getAsBoolean());
		ArgumentCaptor<BufferedImage> saved = ArgumentCaptor.forClass(BufferedImage.class);
		verify(capture.capture).saveScreenshot(saved.capture(), eq("bank"), eq("bank-markers"), eq(true), eq(false));
		assertEquals(Color.RED.getRGB(), saved.getValue().getRGB(0, 40));
		assertEquals(Collections.singletonList(true), results);
	}

	@Test
	public void contextChangesDiscardLateImages()
	{
		setup();
		AtomicBoolean valid = new AtomicBoolean(true);
		assertTrue(capture.save(Collections.emptyList(), valid::get, results::add));
		valid.set(false);
		image.loaded();
		assertTrue(tasks.get(0).getAsBoolean());
		verifyNoInteractions(capture.capture);
		assertTrue(results.isEmpty());
	}

	@Test
	public void missingImagesTimeOutAndAllowRetry()
	{
		setup();
		AtomicLong time = new AtomicLong();
		capture.clock = time::get;
		assertTrue(capture.save(Collections.emptyList(), () -> true, results::add));
		assertFalse(capture.save(Collections.emptyList(), () -> true, results::add));
		assertFalse(tasks.get(0).getAsBoolean());
		time.set(java.util.concurrent.TimeUnit.SECONDS.toNanos(10));
		assertTrue(tasks.get(0).getAsBoolean());
		assertEquals(Collections.singletonList(false), results);
		assertTrue(capture.save(Collections.emptyList(), () -> true, results::add));
		verifyNoInteractions(capture.capture);
	}

	@Test
	public void cancelledCaptureCannotReplaceNewRequest()
	{
		setup();
		assertTrue(capture.save(Collections.emptyList(), () -> true, results::add));
		capture.cancel();
		assertTrue(capture.save(Collections.emptyList(), () -> true, results::add));
		image.loaded();
		assertTrue(tasks.get(0).getAsBoolean());
		verifyNoInteractions(capture.capture);
		assertTrue(tasks.get(1).getAsBoolean());
		verify(capture.capture, times(1)).saveScreenshot(any(), eq("bank"), eq("bank-markers"), eq(true), eq(false));
	}
}

