	private MouseEvent mouse(int id, Point point, boolean alt)
	{
		return new MouseEvent(canvas, id, 0, alt ? InputEvent.ALT_DOWN_MASK : 0, point.x, point.y, 1, false,
				id == MouseEvent.MOUSE_DRAGGED ? MouseEvent.NOBUTTON : MouseEvent.BUTTON1);
	}

	private static final class Harness
	{
		final BankControlLayoutTest.Fixture f = new BankControlLayoutTest.Fixture();
		final BankControlDrag drag = f.controller.controlDrag;
		final AtomicBoolean custom = new AtomicBoolean();
		final AtomicReference<String> saved = new AtomicReference<>("");
		final List<Runnable> pending = new ArrayList<>();

		Harness(boolean enabled)
		{
			custom.set(enabled);
			when(f.controller.config.customBankControls()).thenAnswer(call -> custom.get());
			when(f.controller.config.bankControlLayout()).thenAnswer(call -> saved.get());
			when(f.controller.config.bankButtonDragging()).thenReturn(true);
			f.controller.configs = mock(ConfigManager.class);
			doAnswer(call ->
			{
				pending.add(call.getArgument(0));
				return null;
			}).when(f.controller.clientThread).invokeLater(any(Runnable.class));
			doAnswer(call ->
			{
				saved.set(call.getArgument(2));
				changed("bankControlLayout");
				return null;
			}).when(f.controller.configs).setConfiguration(eq("windowmarkers"), eq("bankControlLayout"),
					any(String.class));
			doAnswer(call ->
			{
				custom.set(call.getArgument(2));
				changed("customBankControls");
				return null;
			}).when(f.controller.configs).setConfiguration(eq("windowmarkers"), eq("customBankControls"), eq(true));
			f.build();
			frame();
		}

		void changed(String key)
		{
			ConfigChanged event = new ConfigChanged();
			event.setGroup("windowmarkers");
			event.setKey(key);
			f.bus.post(event);
		}

		void frame()
		{
			f.bus.post(new BeforeRender());
			List<Runnable> tasks = new ArrayList<>(pending);
			pending.clear();
			tasks.forEach(Runnable::run);
			f.build();
			f.bus.post(new BeforeRender());
		}

		Point center(BankControl control)
		{
			Rectangle r = f.cells.get(control.button).bounds();
			return new Point(r.x + r.width / 2, r.y + r.height / 2);
		}

		BankControlLayout.Entry entry(BankControl control)
		{
			return BankControlLayout.read(saved.get()).entries.stream().filter(e -> e.control == control).findFirst()
					.get();
		}
	}
}

