	@Test
	public void everyControlFitsWithoutOverlapAndOverflowReturnsToBottom()
	{
		Random random = new Random(20261029);
		for (int width : new int[] { 478, 525, 526, 718, 1100 })
			for (int height : new int[] { 160, 290, 760 })
				for (int iteration = 0; iteration < 20; iteration++)
				{
					BankControlLayout layout = BankControlLayout.read("");
					for (BankControlLayout.Entry entry : layout.entries)
					{
						entry.position = random.nextInt(1001);
						entry.left = random.nextBoolean();
					}
					layout.sort();
					Set<BankControl> visible = EnumSet.allOf(BankControl.class);
					if (iteration % 2 == 0)
						visible.remove(BankControl.WORN);
					BankControlLayout.Plan plan = layout.plan(width, height, visible);
					assertEquals(visible, plan.bounds.keySet());
					for (Map.Entry<BankControl, Rectangle> entry : plan.bounds.entrySet())
					{
						Rectangle r = entry.getValue();
						assertTrue(new Rectangle(0, 0, width, height).contains(r));
						assertEquals(entry.getKey().width, r.width);
						assertEquals(36, r.height);
						if (plan.docked.contains(entry.getKey()))
						{
							assertTrue(r.x >= 40);
							assertTrue(r.x + r.width < 100);
						}
						for (Map.Entry<BankControl, Rectangle> other : plan.bounds.entrySet())
							if (other.getKey() != entry.getKey())
								assertFalse(r.intersects(other.getValue()));
					}
					if (width < 526)
						assertEquals(0, plan.inset);
				}
	}

