				when(controller.config.customHeight()).thenReturn(true);
				when(controller.config.height()).thenReturn(bankHeight);
				Cell screen = new Cell(-1, null, 0, 0, 1200, 900, 0, 0, 0, 0);
				Cell root = new Cell(InterfaceID.Bankmain.UNIVERSE, screen, 0, 0, 488, 800, 0, 0, 0, 0);
				Cell menu = new Cell(InterfaceID.Bankmain.MENU_CONTAINER, root, 0, 5, 10, 40, 1, 2, 1, 1);
				Cell items = new Cell(InterfaceID.Bankmain.ITEMS, root, 0, 0, 478, 600, 0, 0, 0, 0);
				when(items.widget.isHidden()).thenReturn(true);
				when(client.getWidget(InterfaceID.Bankmain.INFINITE)).thenReturn(screen.widget);
				when(client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER)).thenReturn(mock(Widget.class));
				for (Cell cell : Arrays.asList(root, menu, items))
					when(client.getWidget(cell.id)).thenReturn(cell.widget);
				List<Cell> rows = new ArrayList<>();

				for (int i = 0; i < 10; i++)
				{
					int y = i < 6 ? (760 - 28) / 2 - 108 + (i / 2) * 28 : 23 + (i / 2) * 28;
					Cell row = new Cell(InterfaceID.Bankmain.INCINERATOR_TOGGLE + i, menu, 251, y, 220, 28,
							i % 2 == 0 ? 2 : 0, 0, 0, 0);
					when(client.getWidget(row.id)).thenReturn(row.widget);
					rows.add(row);
				}
				controller.startUp();
				clearInvocations(controller.clientThread);
				bus.post(new BeforeRender());
				assertEquals(bankWidth, root.bounds().width);
				assertEquals(Math.max(330, bankHeight), root.bounds().height);
				assertEquals(478, menu.bounds().width);
				assertEquals(290, menu.bounds().height);
				assertEquals((bankWidth - 478) / 2, menu.bounds().x - root.bounds().x);
				assertEquals(35, menu.bounds().y - root.bounds().y);
				for (int i = 0; i < rows.size(); i++)
				{
					Rectangle row = rows.get(i).bounds();
					assertTrue(menu.bounds().contains(row));
					assertTrue("Checkbox rows must stay above native buttons",
							row.y + row.height <= menu.bounds().y + 174);
					for (int j = i + 1; j < rows.size(); j++)
						assertFalse("Native checkbox hit boxes must not overlap", row.intersects(rows.get(j).bounds()));
					verify(rows.get(i).widget, never()).clearActions();
					verify(rows.get(i).widget, never()).setOnOpListener(any(Object[].class));
				}

				root.widget.setOriginalWidth(488);
				bus.post(new ScriptPostFired(ScriptID.BANKMAIN_SIZE_CHECK));
				assertEquals(bankWidth, root.bounds().width);
				for (int i = 0; i < 12; i++)
					bus.post(new ClientTick());
				verifyNoInteractions(controller.clientThread);
				when(menu.widget.isHidden()).thenReturn(true);
				when(items.widget.isHidden()).thenReturn(false);
				bus.post(new BeforeRender());
				assertEquals(bankHeight, root.bounds().height);
				when(menu.widget.isHidden()).thenReturn(false);
				when(items.widget.isHidden()).thenReturn(true);
				bus.post(new BeforeRender());
				assertEquals(Math.max(330, bankHeight), root.bounds().height);
				doAnswer(call ->
				{
					((Runnable) call.getArgument(0)).run();
					return null;
				}).when(controller.clientThread).invokeLater(any(Runnable.class));
				controller.shutDown();
				assertArrayEquals(new int[] { 0, 5, 10, 40, 1, 2, 1, 1 }, menu.geometry);
				assertEquals((760 - 28) / 2 - 108, rows.get(0).geometry[1]);
			}
	}

