	static final class Cell
	{
		final int id;
		final Widget widget;
		final Cell parent;
		final int[] geometry;
		final List<Widget> children = new ArrayList<>();
		final Map<String, Object> properties = new HashMap<>();

		Cell(int id, Cell parent, int x, int y, int width, int height, int xMode, int yMode, int widthMode,
				int heightMode)
		{
			this.id = id;
			this.parent = parent;
			geometry = new int[] { x, y, width, height, xMode, yMode, widthMode, heightMode };
			List<String> fields = Arrays.asList("OriginalX", "OriginalY", "OriginalWidth", "OriginalHeight",
					"XPositionMode", "YPositionMode", "WidthMode", "HeightMode");
			widget = mock(Widget.class, call ->
			{
				String method = call.getMethod().getName();
				Object[] args = call.getArguments();
				if (method.startsWith("get") && fields.contains(method.substring(3)))
					return geometry[fields.indexOf(method.substring(3))];
				if (method.startsWith("set") && fields.contains(method.substring(3)))
				{
					geometry[fields.indexOf(method.substring(3))] = (int) args[0];
					return call.getMock();
				}
				switch (method)
				{
					case "getId":
						return id;
					case "getWidth":
						return bounds().width;
					case "getHeight":
						return bounds().height;
					case "getBounds":
						return bounds();
					case "getParent":
						return parent == null ? null : parent.widget;
					case "getRelativeX":
						return bounds().x - (parent == null ? 0 : parent.bounds().x)
								+ (parent == null ? 0 : parent.widget.getScrollX());
					case "getRelativeY":
						return bounds().y - (parent == null ? 0 : parent.bounds().y)
								+ (parent == null ? 0 : parent.widget.getScrollY());
					case "getChildren":
					case "getDynamicChildren":
						return children.toArray(new Widget[0]);
					case "getStaticChildren":
						return new Widget[0];
					case "setChildren":
						children.clear();
						children.addAll(Arrays.asList((Widget[]) args[0]));
						return null;
					case "setPos":
						geometry[0] = (int) args[0];
						geometry[1] = (int) args[1];
						geometry[4] = (int) args[2];
						geometry[5] = (int) args[3];
						return call.getMock();
					case "setSize":
						geometry[2] = (int) args[0];
						geometry[3] = (int) args[1];
						geometry[6] = (int) args[2];
						geometry[7] = (int) args[3];
						return call.getMock();
					case "createChild":
						Cell child = new Cell(id, this, 0, 0, 0, 0, 0, 0, 0, 0);
						children.add(child.widget);
						return child.widget;
				}
				if (method.startsWith("set") && args.length == 1)
				{
					properties.put(method.substring(3), args[0]);
					return call.getMethod().getReturnType() == Widget.class ? call.getMock() : null;
				}
				if (method.equals("setOnOpListener"))
				{
					properties.put("OnOpListener", args.clone());
					return call.getMock();
				}
				if (method.startsWith("get") && properties.containsKey(method.substring(3)))
				{
					Object value = properties.get(method.substring(3));
					return method.equals("getOnOpListener") && !(value instanceof Object[]) ? new Object[] { value }
							: value;
				}
				return org.mockito.Answers.RETURNS_DEFAULTS.answer(call);
			});
		}

		Rectangle bounds()
		{
			Rectangle p = parent == null ? new Rectangle() : parent.bounds();
			int[] g = geometry;
			int w = g[6] == 1 ? p.width - g[2] : g[2], h = g[7] == 1 ? p.height - g[3] : g[3];
			int x = g[4] == 1 ? (p.width - w) / 2 + g[0] : g[4] == 2 ? p.width - w - g[0] : g[0];
			int y = g[5] == 1 ? (p.height - h) / 2 + g[1] : g[5] == 2 ? p.height - h - g[1] : g[1];
			return new Rectangle(p.x + x, p.y + y, w, h);
		}
	}
}

