		f.values.put("storedPotion.1000.tab", "2");
		f.values.put("storedPotion.2000.search", "true");
		f.open().accept(f.added);
		assertEquals(2, f.views.settings.bankTab(1000));
		assertTrue(f.views.settings.search(1000));
