	private void layout(Container c)
	{
		c.doLayout();
		for (Component child : c.getComponents())
			if (child instanceof Container)
				layout((Container) child);
	}

	private void checkButtons(Container c)
	{
		for (Component child : c.getComponents())
		{
			if (!child.isVisible())
				continue;
			if (child instanceof JButton)
			{
				JButton b = (JButton) child;
				if (!b.getText().isEmpty())
					assertTrue(b.getText() + " clipped at " + b.getWidth(), b.getFontMetrics(b.getFont())
							.stringWidth(b.getText()) <= b.getWidth() - b.getInsets().left - b.getInsets().right);
			}
			if (child instanceof Container)
				checkButtons((Container) child);
		}
	}
