			assertTrue(WikiCatalogue.entries(ammo).stream().anyMatch(e -> e.group.equals("Ammo — cannon")));
			assertFalse(WikiCatalogue.entries(ammo).stream()
					.anyMatch(e -> e.group.equals("Ranged weapons") || e.group.equals("Equipment — weapons")));
		}
		AutoCategories.Item quest = item(24265, "V's shield");
		assertFalse(WikiCatalogue.entries(quest).stream()
				.anyMatch(e -> e.group.contains("equipment — shield") || e.group.equals("Equipment — shield")));
