	@Test
	public void lookupClickAddsColoredSecondaryGroupEvenWhenItemIsAlreadyGrouped() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			AutoCategories.Item empty = item(5331, "Watering can");
			String category = WikiCatalogue.entries(empty).stream().filter(e -> e.group.startsWith("Farming"))
					.findFirst().get().group;
			String membership = "Category: " + ItemVariantState.annotate(category, empty);
			ItemLookupPanel lookup = new ItemLookupPanel(Collections.singletonList(empty.name),
					Collections.singletonList(Collections.singleton(membership)));
			lookup.list.setSelectedIndex(0);
			lookup.send.doClick();
			assertEquals(membership, lookup.membership);
			List<BankCatalogue.Choice> targets = BankCatalogue.targets(lookup.membership, Collections.emptyList());
			assertEquals(1, targets.size());
			Map<String, List<AutoCategories.Item>> groups = BankCatalogue.categoryGroups(targets.get(0),
					Collections.singletonList(empty));
			Marker first = new Marker(0, 0, 48, 36);
			first.label = "My tools";
			first.linkedItemIds = new int[] { 5331 };
			first.borderArgb = Color.CYAN.getRGB();
			List<Marker> markers = new ArrayList<>(Collections.singletonList(first));
			CategoryGroups.Result added = CategoryGroups.add(markers, groups, "All classifications", true, Color.YELLOW,
					250);
			assertEquals(1, added.added);
			assertEquals(2, markers.size());
			Marker fresh = added.selected.get(0);
			assertArrayEquals(new int[] { 5331 }, fresh.linkedItemIds);
			assertNotEquals(first.borderArgb, fresh.borderArgb);
			assertEquals(fresh.borderArgb & 0xffffff, fresh.backgroundArgb & 0xffffff);
			assertEquals(65, new Color(fresh.backgroundArgb, true).getAlpha());
			assertTrue(fresh.category.contains("fill before watering"));
			MarkerLegend legend = new MarkerLegend(m ->
			{
			}, m ->
			{
			});
			List<MarkerLegend.Entry> rows = Arrays.asList(new MarkerLegend.Entry(first, first.label, Color.CYAN),
					new MarkerLegend.Entry(fresh, fresh.label, new Color(fresh.borderArgb, true)));
			legend.replace(rows);
			legend.search.setText("unrelated search");
			legend.showGroups(added.selected);
			assertEquals(Collections.singletonList(fresh), legend.selected());
			assertEquals(fresh.borderArgb.intValue(), legend.list.getSelectedValue().color.getRGB());
			int color = fresh.borderArgb;
			CategoryGroups.Result repeated = CategoryGroups.add(markers, groups, "All classifications", true,
					Color.YELLOW, 250);
			assertEquals(0, repeated.added);
			assertEquals(1, repeated.existing);
			assertSame(fresh, repeated.selected.get(0));
			assertEquals(color, fresh.borderArgb.intValue());
			legend.close();
		});
	}

