import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class EditingTest
{
	@Test
	public void historySupportsUndoRedoBranchingAndBoundedMemory()
	{
		MarkerHistory h = new MarkerHistory();
		h.reset("a");
		h.record("b");
		h.record("c");
		assertEquals("b", h.undo());
		assertEquals("a", h.undo());
		assertNull(h.undo());
		assertEquals("b", h.redo());
		h.record("d");
		assertNull(h.redo());
		assertEquals("b", h.undo());
		h.reset("0");
		for (int i = 1; i <= 60; i++)
		{
			h.record("" + i);
		}
		for (int i = 59; i >= 10; i--)
		{
			assertEquals("" + i, h.undo());
		}
		assertNull(h.undo());
	}

	@Test
	public void moveAndResizeClampToWindowWithoutLosingMinimumSize()
