	@Test
	public void enhancedCapacityIsDiscoverableButDoesNotPretendToIncludeCharges()
	{
		ItemCatalogueIndex index = new ItemCatalogueIndex(Arrays.asList(item(11905, "Trident of the Seas (full)", 3),
				item(11908, "Uncharged trident", 3), item(22290, "Uncharged trident (e)", 3),
				item(12900, "Uncharged toxic trident", 3), item(22294, "Uncharged toxic trident (e)", 3)));
		ItemCatalogueIndex.Result result = index.find("fossil island wyverns weapon", "");
		assertTrue(ids(result).contains(22294));
		assertEquals(0, result.ranks.get(22294).tier);
