package com.windowmarkers;

import com.google.gson.Gson;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class GroupCatalogueTest
{
	@Test
	public void categorySearchPreservesEveryDocumentedVariantNote()
	{
		int checked = 0;
		for (String[] row : ItemTaxonomy.readRows("item-variant-states.tsv", 5))
		{
			AutoCategories.Item item = new AutoCategories.Item(Integer.parseInt(row[0]), row[1], true, null, 0, 0, 0);
			if (ItemVariantState.identityNeedsReview(item))
				continue;
			for (WikiCatalogue.Entry entry : WikiCatalogue.entries(item))
			{
				Map<String, List<AutoCategories.Item>> groups = BankCatalogue.categoryGroups(entry.group,
						Collections.singletonList(item));
				String expected = ItemVariantState.annotate(entry.group, item);
				assertTrue(row[0] + " / " + entry.group, groups.containsKey(expected));
				assertEquals(1, groups.values().stream().mapToInt(List::size).sum());

				Map<String, List<AutoCategories.Item>> clicked = BankCatalogue.categoryGroups(expected,
						Collections.singletonList(item));
				assertEquals(row[0] + " / " + expected, Collections.singleton(expected), clicked.keySet());
				assertEquals(item.id, clicked.get(expected).get(0).id);
				checked++;
			}
		}
		assertTrue("Exercise the bundled state catalogue", checked > 1000);
	}

	@Test
	public void categorySearchDoesNotMixChargedAndEmptyToolsOrDuplicateNotes()
	{
		List<AutoCategories.Item> items = Arrays.asList(
				new AutoCategories.Item(5331, "Watering can", false, null, 0, 0, 0),
				new AutoCategories.Item(5340, "Watering can(8)", false, null, 0, 0, 0));
		String category = WikiCatalogue.entries(items.get(0)).stream().filter(e -> e.group.startsWith("Farming"))
				.findFirst().get().group;
		Map<String, List<AutoCategories.Item>> groups = BankCatalogue.categoryGroups(category, items);
		assertEquals(2, groups.size());
		assertTrue(groups.values().stream().allMatch(list -> list.size() == 1));
		String annotated = AutoCategories.suggest(AutoCategories.Preset.ALL_CATEGORIES, items).keySet().iterator()
				.next();
		Map<String, List<AutoCategories.Item>> exact = BankCatalogue.categoryGroups(annotated, items);
		assertEquals(Collections.singleton(annotated), exact.keySet());
	}

	private Marker marker(String label, int... ids)
	{
		Marker m = new Marker(0, 0, 48, 36);
		m.label = label;
		m.linkedItemIds = ids;
		return m;
	}

	@Test
	public void fuzzySearchFindsTyposPunctuationAndRaidAliases()
	{
		assertTrue(SearchText.score("Guthan’s warspear", "guthans") < Integer.MAX_VALUE);
		assertTrue(SearchText.score("Herblore — ingredients", "herblroe") < Integer.MAX_VALUE);
		assertEquals(Integer.MAX_VALUE, SearchText.score("Magic weapons", "woodcutting"));
		List<BankCatalogue.Choice> choices = BankCatalogue.choices(Collections.emptyList(), Collections.emptyList(),
				new CustomPresets());
		assertTrue(BankCatalogue.search(choices, "cox", 150).stream()
				.anyMatch(c -> c.kind == BankCatalogue.Kind.ACTIVITY));
		assertTrue(BankCatalogue.search(choices, "herblroe", 150).stream()
				.anyMatch(c -> c.kind == BankCatalogue.Kind.CATEGORY));
		assertTrue(choices.stream().anyMatch(c -> c.kind == BankCatalogue.Kind.ACTIVITY));
		for (String query : new String[] { "herb", "herbl", "herblor", "herblroe", "ingredients herblroe" })
			assertTrue(query, SearchText.score("Herblore — ingredients", query) < Integer.MAX_VALUE);
		assertTrue(SearchText.score("Ancestral hat", "ancsetr") < Integer.MAX_VALUE);
		assertEquals(Integer.MAX_VALUE, SearchText.score("Magic equipment", "axe"));
		assertEquals(Integer.MAX_VALUE, SearchText.score("Herblore", "x".repeat(300)));
	}

	@Test
	public void palettePreservesSameNameVariantsAndBankScope()
	{
		var a = new BankItemSearch.Choice(1409, "Iban's staff");
		var b = new BankItemSearch.Choice(1410, "Iban's staff");
		var c = new BankItemSearch.Choice(6570, "Fire cape");
		var all = BankItemSearch.rank(Arrays.asList(a, b, c), "iban staf", null);
		assertEquals(Arrays.asList(a, b), all);
		assertEquals(Collections.singletonList(b),
				BankItemSearch.rank(Arrays.asList(a, b, c), "iban staf", Collections.singleton(1410)));
		assertEquals(Collections.emptyList(), BankItemSearch.rank(Arrays.asList(a, b, c), "", Collections.emptySet()));
	}

	@Test
	public void draggingFilteredGroupsKeepsHiddenSlotsAndRejectsStaleOrder()
	{
		Marker a = marker("A", 1), hidden = marker("H", 9), b = marker("B", 2), c = marker("C", 3);
		List<Marker> all = new ArrayList<>(Arrays.asList(a, hidden, b, c));
		assertTrue(GroupEdits.reorder(all, Arrays.asList(a, b, c), Arrays.asList(a, c), 3));
		assertEquals(Arrays.asList(b, hidden, a, c), all);
		assertFalse(GroupEdits.reorder(all, Arrays.asList(a, b, c), Collections.singletonList(a), 3));
		assertFalse(GroupEdits.reorder(all, Arrays.asList(b, a, c), Collections.singletonList(marker("stale", 1)), 0));
		assertFalse(GroupEdits.reorder(all, Arrays.asList(b, a, c), Collections.singletonList(c), 3));
	}

	@Test
	public void disconnectedGroupsMergeIdsWithoutCollapsingVariants()
	{
		assertArrayEquals(new int[] { 1409, 1410, 6570 },
				GroupEdits.union(Arrays.asList(marker("one", 1409, 1410), marker("two", 1410, 6570))));
	}

	@Test
	public void presetRoundTripKeepsAppearanceAndCopiesAreIndependent()
	{
		Marker group = marker("My Food", 385, 3144);
		group.borderArgb = 0xff119933;
		group.labelSize = 18;
		CustomPresets.Preset p = new CustomPresets.Preset();
		p.name = "Supplies";
		p.groups.add(group);
		CustomPresets library = new CustomPresets();
		library.presets.add(p);
		Gson gson = new Gson();
		CustomPresets copied = gson.fromJson(gson.toJson(library), CustomPresets.class);
		copied.normalize();
		assertEquals(group.borderArgb, copied.presets.get(0).groups.get(0).borderArgb);
		copied.presets.get(0).groups.get(0).linkedItemIds[0] = 999;
		assertEquals(385, group.linkedItemIds[0]);
		CustomPresets.Preset duplicate = new CustomPresets.Preset();
		duplicate.name = " Supplies ";
		duplicate.groups.add(group);
		copied.presets.add(duplicate);
		copied.normalize();
		assertEquals(1, copied.presets.size());
	}

	@Test
	public void lookupIncludesSecondaryRolesAndCustomMembershipWithoutInferringReadiness()
	{
		var item = new AutoCategories.Item(13329, "Fire max cape", true, null, 0, 0, 0);
		var groups = Collections.singletonList(marker("My capes", 13329));
		var membership = BankCatalogue.memberships(item, Collections.singletonList(item), groups, new CustomPresets());
		assertTrue(membership.stream().anyMatch(s -> s.contains("Runecraft — pouch protection")));
		assertTrue(membership.contains("Saved group: My capes"));
		assertTrue(membership.stream().noneMatch(s -> s.contains("Crafting Guild teleport")));
		var broken = new AutoCategories.Item(1410, "Iban's staff", true, null, 0, 0, 0);
		var brokenMembership = BankCatalogue.memberships(broken, Collections.singletonList(broken),
				Collections.emptyList(), new CustomPresets());
		assertTrue(brokenMembership.stream().anyMatch(s -> s.contains("review")));
	}

	@Test
	public void comparisonSeparatesSharedAndUniqueMemberships()
	{
		String output = BankCatalogue.compare("A", new HashSet<>(Arrays.asList("food", "cooking")), "B",
				new HashSet<>(Arrays.asList("food", "fishing")));
		assertTrue(output.contains("Shared (1)\nfood\n"));
		assertTrue(output.contains("Only A (1)\ncooking\n"));
		assertTrue(output.contains("Only B (1)\nfishing\n"));
	}

	@Test
	public void focusedLookupRetainsWholeBankSetContext()
	{
		List<AutoCategories.Item> bank = Arrays.asList(
				new AutoCategories.Item(13072, "Elite void top", true, null, 0, 0, 0),
				new AutoCategories.Item(13073, "Elite void robe", true, null, 0, 0, 0),
				new AutoCategories.Item(8842, "Void knight gloves", true, null, 0, 0, 0),
				new AutoCategories.Item(11664, "Void ranger helm", true, null, 0, 0, 0),
				new AutoCategories.Item(28997, "Dual macuahuitl", true, null, 0, 0, 0),
				new AutoCategories.Item(385, "Shark", false, new String[] { "Eat" }, 0, 0, 0));
		for (AutoCategories.Item item : bank)
		{
			Set<String> expected = new TreeSet<>();
			for (AutoCategories.Preset preset : AutoCategories.Preset.values())
				AutoCategories.suggest(preset, bank).forEach((group, items) ->
				{
					if (items.stream().anyMatch(i -> i.id == item.id))
						expected.add("Preset: " + preset + " / " + group);
				});
			Set<String> actual = BankCatalogue.memberships(item, bank, Collections.emptyList(), new CustomPresets());
			actual.removeIf(s -> !s.startsWith("Preset:"));
			assertEquals(item.name, expected, actual);
		}
	}
}

package com.windowmarkers;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class HiddenWikiSetupsTest
{
	@Test
	public void choicesPersistPerProfileAndStaleActionsCannotChangeAnotherProfile()
	{
		HiddenWikiSetups hidden = new HiddenWikiSetups();
		hidden.configs = mock(ConfigManager.class, RETURNS_DEEP_STUBS);
		AtomicLong profile = new AtomicLong(10);
		Map<Long, String> saved = new HashMap<>();
		when(hidden.configs.getProfile().getId()).thenAnswer(i -> profile.get());
		when(hidden.configs.getConfiguration("windowmarkers", HiddenWikiSetups.KEY))
				.thenAnswer(i -> saved.get(profile.get()));
		doAnswer(i ->
		{
			saved.put(profile.get(), i.getArgument(2));
			return null;
		}).when(hidden.configs).setConfiguration(eq("windowmarkers"), eq(HiddenWikiSetups.KEY), any());
		hidden.hide("224363:1", 10);
		assertEquals(Set.of("224363:1"), hidden.read());
		HiddenWikiSetups reopened = new HiddenWikiSetups();
		reopened.configs = hidden.configs;
		assertEquals(hidden.read(), reopened.read());
		profile.set(20);
		assertTrue(reopened.read().isEmpty());
		reopened.hide("224363:1", 10);
		reopened.restore(Set.of("224363:1"), 10);
		assertTrue(reopened.read().isEmpty());
		profile.set(10);
		hidden.hide("569290:3", 10);
		hidden.restore(Set.of("224363:1"), 10);
		assertEquals(Set.of("569290:3"), hidden.read());
		hidden.restore(hidden.read(), 10);
		assertTrue(hidden.read().isEmpty());
	}

	@Test
	public void rowChoicesStayWithinTheirActivityAndRetainExistingSetupChoices()
	{
		HiddenWikiSetups hidden = new HiddenWikiSetups();
		hidden.configs = mock(ConfigManager.class, RETURNS_DEEP_STUBS);
		when(hidden.configs.getProfile().getId()).thenReturn(10L);
		String row = HiddenWikiSetups.rowId("Sarachnis", "00:Head alternatives");
		String other = HiddenWikiSetups.rowId("Hespori", "00:Head alternatives");
		String special = HiddenWikiSetups.rowId("Tombs of Amascut", "11:Kephri, scarabs & swarms");
		assertFalse(special.contains(","));
		assertEquals("Tombs of Amascut / Kephri, scarabs & swarms", HiddenWikiSetups.label(special));
		when(hidden.configs.getConfiguration("windowmarkers", HiddenWikiSetups.KEY))
				.thenReturn("224363:1," + other);
		hidden.hide(row, 10);
		verify(hidden.configs).setConfiguration("windowmarkers", HiddenWikiSetups.KEY,
				String.join(",", new java.util.TreeSet<>(Set.of("224363:1", row, other))));
		when(hidden.configs.getConfiguration("windowmarkers", HiddenWikiSetups.KEY))
				.thenReturn(String.join(",", Set.of("224363:1", row, other)));
		var plan = SetupLoadout.build(List.of(ActivitySetups.byId("224363:1")), Map.of(), Set.of(), "");
		assertEquals(Set.of("224363:1", row), HiddenWikiSetups.forPlan(hidden.read(), plan));
		assertFalse(hidden.layoutIdentity("activity:Sarachnis::true", plan).contains(other));
		hidden.restore(HiddenWikiSetups.forPlan(hidden.read(), plan), 10);
		verify(hidden.configs).setConfiguration("windowmarkers", HiddenWikiSetups.KEY, other);
	}

	@Test
	public void hiddenLayoutsUseSeparatePositionsWithoutChangingOtherActivitiesOrCustomViews()
	{
		HiddenWikiSetups hidden = new HiddenWikiSetups();
		hidden.configs = mock(ConfigManager.class);
		SetupLoadout plan = SetupLoadout.build(List.of(ActivitySetups.byId("224363:1")), Map.of(), Set.of(), "");
		String original = "activity:Sarachnis::true";
		assertEquals(original, hidden.layoutIdentity(original, plan));
		when(hidden.configs.getConfiguration("windowmarkers", HiddenWikiSetups.KEY)).thenReturn("569290:3");
		assertEquals(original, hidden.layoutIdentity(original, plan));
		when(hidden.configs.getConfiguration("windowmarkers", HiddenWikiSetups.KEY)).thenReturn("224363:1,569290:3");
		assertEquals(original + ":hidden:224363:1", hidden.layoutIdentity(original, plan));
		assertEquals("saved:My gear", hidden.layoutIdentity("saved:My gear", plan));
		when(hidden.configs.getConfiguration("windowmarkers", HiddenWikiSetups.KEY)).thenReturn("");
		assertEquals(original, hidden.layoutIdentity(original, plan));
		verify(hidden.configs, never()).setConfiguration(anyString(), anyString(), any());
	}
}

package com.windowmarkers;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class InventoryGearAlternativesTest
{
	private static ItemCatalogueIndex.Item item(int id, String name, int slot)
	{
		return GeSearchIndexTest.item(id, name, slot);
	}

	private SetupLoadout muspah(ItemCatalogueIndex.Item... items)
	{
		Map<Integer, ItemCatalogueIndex.Item> owned = new LinkedHashMap<>();
		for (var item : items)
			owned.put(item.id, item);
		return SetupLoadout.build(ActivitySetups.forActivity("Phantom Muspah"), owned, owned.keySet(), "373815:4");
	}

	@Test
	public void muspahInventoryUsesOwnedRangedAccessoriesAcrossEveryPhase()
	{
		SetupLoadout plan = muspah(item(32879, "Aquanite hopper", 5), item(19547, "Necklace of anguish", 2),
				item(13337, "Accumulator max cape", 1));
		for (SetupLoadout section : plan.sections())
		{
			assertEquals(Integer.valueOf(13337), section.inventory.get(4));
			assertEquals(Integer.valueOf(19547), section.inventory.get(5));
			assertEquals(Integer.valueOf(32879), section.inventory.get(9));
		}
		assertTrue(plan.itemIds().containsAll(Arrays.asList(32879, 19547, 13337)));
	}

	@Test
	public void exactAndReviewedHigherChoicesWinBeforeDowngrades()
	{
		for (SetupLoadout p : muspah(item(21000, "Twisted buckler", 5), item(32879, "Aquanite hopper", 5),
				item(28902, "Dizana's max cape", 1), item(13337, "Accumulator max cape", 1),
				item(33639, "Necklace of rupture", 2), item(19547, "Necklace of anguish", 2)).sections())
		{
			assertEquals(Integer.valueOf(21000), p.inventory.get(9));
			assertEquals(Integer.valueOf(28902), p.inventory.get(4));
			assertEquals(Integer.valueOf(33639), p.inventory.get(5));
		}
		for (SetupLoadout p : muspah(item(22109, "Ava's assembler", 1), item(10499, "Ava's accumulator", 1)).sections())
			assertEquals(Integer.valueOf(22109), p.inventory.get(4));
		for (SetupLoadout p : muspah(item(10499, "Ava's accumulator", 1)).sections())
			assertEquals(Integer.valueOf(10499), p.inventory.get(4));
	}

	@Test
	public void ornamentsWorkBothWaysButRestrictedCopiesAndBrokenCapesDoNot()
	{
		assertTrue(InventoryGearAlternatives.sameCombatItem(22249, item(19547, "Necklace of anguish", 2).fact));
		assertTrue(InventoryGearAlternatives.sameCombatItem(19547, item(22249, "Necklace of anguish (or)", 2).fact));
		assertFalse(InventoryGearAlternatives.sameCombatItem(19547, item(27172, "Necklace of anguish", 2).fact));
		assertFalse(InventoryGearAlternatives.sameCombatItem(28902, item(28830, "Dizana's max cape (broken)", 1).fact));
		assertFalse(
				InventoryGearAlternatives.sameCombatItem(28327, item(28329, "Ring of shadows (uncharged)", 12).fact));
		assertFalse(InventoryGearAlternatives.sameCombatItem(22249, item(19547, "Unreviewed impostor", 2).fact));
		for (SetupLoadout p : muspah(item(28830, "Dizana's max cape (broken)", 1),
				item(28947, "Dizana's quiver (uncharged)", 1), item(27172, "Necklace of anguish", 2),
				item(12825, "Arcane spirit shield", 5)).sections())
		{
			assertFalse(p.inventory.containsKey(4));
			assertFalse(p.inventory.containsKey(5));
			assertFalse(p.inventory.containsKey(9));
		}
	}

	@Test
	public void allInventoryAnguishExamplesAcceptTheOtherCosmeticVersion()
	{
		int checked = 0;
		for (ActivitySetups.Setup setup : ActivitySetups.all())
			if (SetupLoadout.inventoryTable(setup) && (setup.itemIds.contains(22249) || setup.itemIds.contains(19547)))
			{
				int wanted = setup.itemIds.contains(22249) ? 22249 : 19547, held = wanted == 22249 ? 19547 : 22249;
				var owned = item(held, held == 19547 ? "Necklace of anguish" : "Necklace of anguish (or)", 2);
				SetupLoadout plan = SetupLoadout.build(Collections.singletonList(setup),
						Collections.singletonMap(held, owned), Collections.singleton(held), setup.id);
				if (plan == null || plan.wildernessBudget)
					continue;
				for (var entry : plan.inventoryExample.entrySet())
					if (entry.getValue().inventoryChoice() && entry.getValue().ids.contains(wanted))
					{
						assertEquals(setup.id, Integer.valueOf(held), plan.inventory.get(entry.getKey()));
						checked++;
					}
			}
		assertEquals(10, checked);
	}

	@Test
	public void sharedSearchIncludesTheReplacementWithoutGivingItTheExamplesRank()
	{
		var index = new ItemCatalogueIndex(Arrays.asList(item(32879, "Aquanite hopper", 5),
				item(19547, "Necklace of anguish", 2), item(13337, "Accumulator max cape", 1)), false);
		var result = index.find("muspah", "", "373815:4");
		assertNotNull(result.loadout);
		Set<Integer> shown = new HashSet<>();
		result.items.forEach(i -> shown.add(i.id));
		assertTrue(shown.containsAll(Arrays.asList(32879, 19547, 13337)));
		assertNotEquals(1, result.ranks.get(32879).tier);
		assertNotEquals(1, result.ranks.get(19547).tier);
		assertFalse(result.loadout.retainItems(Collections.singleton(19547)).itemIds().contains(32879));
	}
}

package com.windowmarkers;

import java.util.*;
