	@Test
	public void lookupOffersSeparateFilterAndHighlightActionsForOneOrTwoItems() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			ItemLookupPanel one = new ItemLookupPanel(Collections.singletonList("Shark"),
					Collections.singletonList(Collections.singleton("Category: Food — general use")));
			assertFalse(one.send.isEnabled());
			one.list.setSelectedIndex(0);
			one.send.doClick();
			assertEquals("Food — general use", one.filter);
			assertFalse(one.highlightRequested);
			ItemLookupPanel two = new ItemLookupPanel(Arrays.asList("Fire cape", "Fire max cape"),
					Arrays.asList(
							new TreeSet<>(Arrays.asList("Category: Capes", "Preset: Chambers of Xeric / CoX Melee")),
							new TreeSet<>(Arrays.asList("Category: Capes", "Category: Runecraft — pouch protection"))));
			assertEquals(3, two.list.getModel().getSize());
			assertEquals("Both items", two.list.getModel().getElementAt(0).owner);
			two.highlight.doClick();
			assertTrue(two.highlightRequested);
			assertNull(two.filter);
			ItemLookupPanel unknown = new ItemLookupPanel(Collections.singletonList("Unknown"),
					Collections.singletonList(Collections.emptySet()));
			assertFalse(unknown.send.isEnabled());
			assertTrue(unknown.highlight.isEnabled());
		});
	}

