		{
			queued.add(call.getArgument(0));
			return null;
		}).when(search.clientThread).invokeLater(any(Runnable.class));
		set(search, "index",
				new BankSearchIndex(
						Collections.singletonList(new AutoCategories.Item(5331, "Watering can", false, null, 0, 0, 0)),
						Collections.emptyList(), new CustomPresets()));
