	private static void runQueued(java.util.concurrent.BlockingQueue<Runnable> queued) throws Exception
	{
		Runnable pending = queued.poll(10, java.util.concurrent.TimeUnit.SECONDS);
		assertNotNull("Search must complete", pending);
		pending.run();
	}

