package com.windowmarkers;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class PresentationTest
{
	private AutoCategories.Item item(int id, String name)
	{
		return new AutoCategories.Item(id, name, true, null, 0, 0, 0);
	}

	@Test
	public void loneSetWeaponsKeepTheirStandaloneRole()
	{
		String[][] pairs = { { "Dual macuahuitl", "Blood moon chestplate", "Melee weapons" },
				{ "Guthan's warspear", "Guthan's helm", "Melee weapons" },
				{ "Eclipse atlatl", "Eclipse moon tassets", "Ranged weapons" } };
		for (AutoCategories.Preset preset : new AutoCategories.Preset[] { AutoCategories.Preset.ALL_CATEGORIES,
				AutoCategories.Preset.COMBAT_GROUPS })
			for (String[] pair : pairs)
			{
				AutoCategories.Item weapon = item(-1, pair[0]);
				assertTrue(AutoCategories.suggest(preset, Collections.singletonList(weapon)).containsKey(pair[2]));
				Map<String, List<AutoCategories.Item>> grouped = AutoCategories.suggest(preset,
						Arrays.asList(weapon, item(-2, pair[1])));
				assertEquals(2, grouped.get(ItemTaxonomy.equipmentSet(pair[0])).size());
			}
	}

	@Test
	public void paletteAvoidsExistingColorsAcrossBatches()
	{
		List<Color> used = new ArrayList<>(Arrays.asList(Color.RED, Color.GREEN, Color.BLUE));
		Set<Integer> unique = new HashSet<>();
		for (Color c : used)
		{
			unique.add(c.getRGB());
		}
		for (int n = 0; n < 100; n++)
		{
			Color c = MarkerPresentation.nextColor(used);
			assertTrue(unique.add(c.getRGB()));
			used.add(c);
		}
	}

	@Test
	public void shortTitlesKeepDetailedReviewNamesSeparate()
	{
		assertEquals("Guthan", MarkerPresentation.title(ItemTaxonomy.equipmentSet("guthan's warspear")));
		assertEquals("Blood Moon", MarkerPresentation.title(ItemTaxonomy.equipmentSet("dual macuahuitl")));
		assertEquals("Potions", MarkerPresentation.title("Potions — general, not activity advice"));
	}

	@Test
	public void badgesStayWithinBankAndNeverOverlap()
	{
		List<Rectangle> occupied = new ArrayList<>();
		Rectangle clip = new Rectangle(0, 0, 200, 100), region = new Rectangle(175, 0, 25, 35);
		Rectangle first = MarkerPresentation.place(region, clip, 100, 18, Marker.LabelPlacement.ABOVE, occupied);
		Rectangle second = MarkerPresentation.place(region, clip, 100, 18, Marker.LabelPlacement.ABOVE, occupied);
		assertNotNull(first);
		assertNotNull(second);
		assertTrue(clip.contains(first));
		assertTrue(clip.contains(second));
		assertFalse(first.intersects(second));
		Rectangle third = MarkerPresentation.place(region, clip, 100, 18, Marker.LabelPlacement.ABOVE, occupied);
		assertNotNull(third);
		assertTrue(clip.contains(third));
		assertFalse(first.intersects(third));
		assertFalse(second.intersects(third));
		Graphics2D g = new BufferedImage(200, 100, BufferedImage.TYPE_INT_ARGB).createGraphics();
		try
		{
			String label = MarkerPresentation.fit("A very long category description", g.getFontMetrics(), 80);
			assertTrue(g.getFontMetrics().stringWidth(label) <= 80);
		}
		finally
		{
			g.dispose();
		}
	}

	@Test
	public void occupiedItemSlotsPreventLabelsFromCoveringIcons()
	{
		Rectangle clip = new Rectangle(0, 0, 200, 100), region = new Rectangle(20, 30, 100, 32);
		List<Rectangle> protectedItems = new ArrayList<>(Collections.singletonList(new Rectangle(clip)));
		assertNull(MarkerPresentation.place(region, clip, 90, 18, Marker.LabelPlacement.ABOVE, protectedItems));
	}

	@Test
	public void crowdedCustomRowsUseFreeGutterAndCacheInvalidatesAfterScroll()
	{
		Rectangle clip = new Rectangle(0, 0, 500, 250), region = new Rectangle(45, 72, 288, 36);
		List<Rectangle> items = new ArrayList<>();
		for (int row = 0; row < 7; row++)
			for (int col = 0; col < 6; col++)
				items.add(new Rectangle(45 + col * 48, row * 36, 48, 36));
		MarkerLabelCache cache = new MarkerLabelCache();
		cache.begin(items);
		List<Rectangle> occupied = new ArrayList<>(items);
		Rectangle badge = cache.place(region, clip, 90, 18, Marker.LabelPlacement.ABOVE, occupied);
		assertNotNull(badge);
		assertTrue(clip.contains(badge));
		assertTrue(badge.x >= 333);
		assertTrue(items.stream().noneMatch(badge::intersects));
		cache.begin(items);
		occupied = new ArrayList<>(items);
		assertSame(badge, cache.place(region, clip, 90, 18, Marker.LabelPlacement.ABOVE, occupied));
		assertEquals(items.size() + 1, occupied.size());
		List<Rectangle> full = Collections.singletonList(new Rectangle(clip));
		cache.begin(full);
		assertNull(cache.place(region, clip, 90, 18, Marker.LabelPlacement.ABOVE, new ArrayList<>(full)));
	}

	@Test
	public void dialogsFitSmallAndOffsetMonitorWorkAreas()
	{
		for (Rectangle screen : new Rectangle[] { new Rectangle(0, 0, 640, 440), new Rectangle(-1920, 40, 1920, 1000) })
		{
			assertTrue(screen.contains(MarkerDialogs.initialBounds(screen, 620, 640)));
		}
	}
}

package com.windowmarkers;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class PresetVisibilityTest
{
	@Test
	public void outlinesBackgroundsAndRankLabelsCanBeHiddenIndependently() throws Exception
	{
		WindowMarkersPlugin p = new WindowMarkersPlugin();
		p.layouts = new BankLayouts(mock(net.runelite.client.config.ConfigManager.class), new com.google.gson.Gson());
		p.client = mock(Client.class);
		p.config = mock(WindowMarkersConfig.class, CALLS_REAL_METHODS);
		p.borders = new BorderRenderer();
		when(p.config.bankLabels()).thenReturn(WindowMarkersConfig.BankLabels.OFF);
		when(p.config.style()).thenReturn(WindowMarkersConfig.BorderStyle.PLAIN);
		p.searchView = BankSearchViewTest.availableView();
		p.searchView.bankTags = mock(BankTagsService.class);
		p.searchView.tags = mock(TagManager.class);
		p.searchView.items = mock(ItemManager.class);
		when(p.searchView.items.canonicalize(anyInt())).thenAnswer(c -> c.getArgument(0));
		doAnswer(c ->
		{
			when(p.searchView.bankTags.getActiveTag()).thenReturn(c.getArgument(0));
			return null;
		}).when(p.searchView.bankTags).openBankTag(anyString(), anyInt());
		Marker marker = new Marker(0, 0, 48, 36);
		marker.linkedItemIds = new int[] { 1 };
		marker.scrollWithItems = true;
		marker.backgroundArgb = Color.RED.getRGB();
		p.searchView.show("Hydra", Collections.singletonList(marker), true, null,
				Collections.singletonMap(1, new ItemCatalogueIndex.Rank(1, "First choice")));
		field(p, "bank", new Rectangle(0, 0, 140, 110));
		field(p, "itemArea", new Rectangle(0, 0, 140, 110));
		field(p, "itemCells", Collections.singletonList(new ItemAnchors.Cell(1, new Rectangle(26, 22, 36, 32))));
		field(p, "rankingIndex",
				new BankSearchIndex(Collections.emptyList(), Collections.emptyList(), new CustomPresets()));
		BufferedImage normal = render(p);
		assertNotEquals(0, normal.getRGB(40, 30));
		when(p.config.hidePresetItemOutlines()).thenReturn(true);
		BufferedImage labels = render(p);
		assertEquals(0, labels.getRGB(40, 30));
		assertTrue(pixels(labels) > 0);
		when(p.config.hidePresetItemLabels()).thenReturn(true);
		assertEquals(0, pixels(render(p)));
		marker.label = "Hydra";
		when(p.config.bankLabels()).thenReturn(WindowMarkersConfig.BankLabels.MINI);
		assertEquals("Preset name tags start hidden", 0, pixels(render(p)));
		when(p.config.hidePresetNameTags()).thenReturn(false);
		assertTrue(pixels(render(p)) > 0);
		when(p.config.hidePresetNameTags()).thenReturn(true);
		p.bankLayout = new BankLayoutController();
		p.bankLayout.config = p.config;
		p.bankLayout.searchView = p.searchView;
		var headings = BankLayoutController.class.getDeclaredField("searchHeadings");
		headings.setAccessible(true);
		@SuppressWarnings("unchecked")
		java.util.List<SetupItemLayout.Heading> list = (java.util.List<SetupItemLayout.Heading>) headings
				.get(p.bankLayout);
		list.add(new SetupItemLayout.Heading("Equipment", 1, 80));
		assertTrue("Section headings remain independently visible", pixels(render(p)) > 0);
		when(p.config.hidePresetSectionHeadings()).thenReturn(true);
		assertEquals(0, pixels(render(p)));
		when(p.config.hidePresetItemOutlines()).thenReturn(false);
		assertNotEquals(0, render(p).getRGB(40, 30));
		p.searchView.clear();
		assertFalse(p.hidePresetOutlines());
		assertFalse(p.hidePresetLabels());
	}

	private static void field(Object o, String name, Object value) throws Exception
	{
		var f = o.getClass().getDeclaredField(name);
		f.setAccessible(true);
		f.set(o, value);
	}

	private static BufferedImage render(WindowMarkersPlugin p)
	{
		BufferedImage image = new BufferedImage(140, 110, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		p.new BackgroundOverlay().render(g);
		p.new MarkerOverlay().render(g);
		g.dispose();
		return image;
	}

	private static int pixels(BufferedImage image)
	{
		int count = 0;
		for (int pixel : image.getRGB(0, 0, image.getWidth(), image.getHeight(), null, 0, image.getWidth()))
			if ((pixel >>> 24) > 0)
				count++;
		return count;
	}
}

package com.windowmarkers;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class RaidGearFilterTest
{
	private AutoCategories.Item item(int id, String name)
	{
		return new AutoCategories.Item(id, name, true, null, 0, 0, 0);
	}

	private Map<String, List<AutoCategories.Item>> filtered(AutoCategories.Preset preset, int[] levels,
			AutoCategories.Item... items)
	{
		Map<String, List<AutoCategories.Item>> groups = AutoCategories.suggest(preset, Arrays.asList(items));
		RaidGearFilter.filter(preset, groups, levels, new LinkedHashMap<>());
		return groups;
	}

	private boolean has(Map<String, List<AutoCategories.Item>> groups, int id)
	{
		return groups.values().stream().flatMap(Collection::stream).anyMatch(i -> i.id == id);
	}

	@Test
	public void coxMagicRemovesLowerOwnedHatButNotOtherSlotsOrSpecialists()
	{
		Map<String, List<AutoCategories.Item>> result = filtered(AutoCategories.Preset.CHAMBERS_OF_XERIC,
				new int[] { 99, 99, 99, 99, 99, 99 }, item(-1, "Ancestral hat"), item(-2, "Mystic hat (dark)"),
				item(-3, "Mystic robe top"), item(-4, "Virtus mask"), item(-5, "Ahrim's hood"));
		assertFalse(has(result, -2));
		for (int id : new int[] { -1, -3, -4, -5 })
		{
			assertTrue(has(result, id));
		}
	}

	@Test
	public void replacementMustMeetActualLevelsAndBeUsable()
	{
		assertTrue(has(filtered(AutoCategories.Preset.CHAMBERS_OF_XERIC, new int[] { 99, 99, 64, 99, 99, 99 },
				item(-1, "Ancestral hat"), item(-2, "Mystic hat")), -2));
		assertTrue(has(filtered(AutoCategories.Preset.CHAMBERS_OF_XERIC, new int[] { 99, 99, 99, 99, 74, 99 },
				item(-1, "Ancestral hat"), item(-2, "Mystic hat")), -2));
		assertTrue(has(filtered(AutoCategories.Preset.CHAMBERS_OF_XERIC, new int[] { 99, 99, 99, 99, 99, 99 },
				item(-1, "Ancestral hat (broken)"), item(-2, "Mystic hat")), -2));
	}

	@Test
	public void allRaidsCompareSameSlotArmourAcrossCombatStyles()
	{
		for (AutoCategories.Preset preset : new AutoCategories.Preset[] { AutoCategories.Preset.CHAMBERS_OF_XERIC,
				AutoCategories.Preset.THEATRE_OF_BLOOD, AutoCategories.Preset.TOMBS_OF_AMASCUT })
		{
			Map<String, List<AutoCategories.Item>> result = filtered(preset, new int[] { 99, 99, 99, 99, 99, 99 },
					item(-1, "Torva platebody"), item(-2, "Bandos chestplate"), item(-3, "Bandos tassets"));
			assertFalse(preset.toString(), has(result, -2));
			assertTrue(has(result, -3));
		}
		Map<String, List<AutoCategories.Item>> ranged = filtered(AutoCategories.Preset.CHAMBERS_OF_XERIC,
				new int[] { 99, 99, 99, 99, 99, 99 }, item(-1, "Masori body (f)"), item(-2, "Armadyl chestplate"));
		assertFalse(has(ranged, -2));
	}

	@Test
	public void generalClassificationDoesNotPretendToBeAnActivityRanking()
	{
		assertTrue(has(filtered(AutoCategories.Preset.ALL_CATEGORIES, new int[] { 99, 99, 99, 99, 99, 99 },
				item(-1, "Ancestral hat"), item(-2, "Mystic hat")), -2));
	}

	@Test
	public void weaponsAreComparedOnlyWithinInterchangeableRoles()
	{
