package com.windowmarkers;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ProfileChanged;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class ReleaseNotesNoticeTest
{
	private final ReleaseNotesNotice notice = new ReleaseNotesNotice();
	private final Client client = mock(Client.class);
	private final ClientThread thread = mock(ClientThread.class);
	private final ConfigManager config = mock(ConfigManager.class);
	private final ChatMessageManager chat = mock(ChatMessageManager.class);
	private final List<Runnable> pending = new ArrayList<>();
	private String seen;

	@Before
	public void setup() throws Exception
	{
		inject("eventBus", mock(net.runelite.client.eventbus.EventBus.class));
		inject("client", client);
		inject("clientThread", thread);
		inject("configManager", config);
		inject("chat", chat);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(config.getConfiguration("windowmarkers", ReleaseNotesNotice.SEEN_KEY)).thenAnswer(i -> seen);
		doAnswer(i ->
		{
			seen = i.getArgument(2);
			return null;
		}).when(config).setConfiguration(eq("windowmarkers"), eq(ReleaseNotesNotice.SEEN_KEY), any(String.class));
		doAnswer(i ->
		{
			pending.add(i.getArgument(0));
			return null;
		}).when(thread).invokeLater(any(Runnable.class));
	}

	@Test
	public void printsOneBulletedReleaseBlockOnceAcrossLoginAndReenable()
	{
		notice.start();
		flush();
		ArgumentCaptor<QueuedMessage> messages = ArgumentCaptor.forClass(QueuedMessage.class);
		verify(chat, times(1)).queue(messages.capture());
		String message = messages.getValue().getRuneLiteFormattedMessage();
		assertEquals(1, message.split("Improved Banking", -1).length - 1);
		assertEquals(5, message.split("<br>\\* ", -1).length - 1);
		assertTrue(message.contains("Missing equipment now appears as a faded recommendation"));
		assertFalse(message.contains("Recent updates"));
		assertEquals(ReleaseNotesNotice.RELEASE, seen);
		notice.onGameStateChanged(loggedIn());
		flush();
		notice.stop();
		notice.start();
		flush();
		verify(chat, times(1)).queue(any(QueuedMessage.class));
	}

	@Test
	public void waitsForLoginAndDoesNotMarkUnshownNotesAsRead()
	{
		when(client.getGameState()).thenReturn(GameState.LOGIN_SCREEN);
		notice.start();
		flush();
		verifyNoInteractions(chat);
		assertNull(seen);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		notice.onGameStateChanged(loggedIn());
		flush();
		verify(chat, times(1)).queue(any(QueuedMessage.class));
	}

	@Test
	public void currentReceiptSuppressesNoticeButOlderReleaseDoesNot()
	{
		seen = ReleaseNotesNotice.RELEASE;
		notice.start();
		flush();
		verifyNoInteractions(chat);
		seen = "previous-release";
		notice.onProfileChanged(new ProfileChanged());
		flush();
		verify(chat, times(1)).queue(any(QueuedMessage.class));
	}

	@Test
	public void shutdownAndProfileChangeInvalidateOldCallbacks()
	{
		notice.start();
		notice.stop();
		flush();
		verifyNoInteractions(chat);
		assertNull(seen);
		notice.start();
		notice.onProfileChanged(new ProfileChanged());
		flush();
		verify(chat, times(1)).queue(any(QueuedMessage.class));
		seen = null;
		notice.onProfileChanged(new ProfileChanged());
		flush();
		verify(chat, times(2)).queue(any(QueuedMessage.class));
	}

	private GameStateChanged loggedIn()
	{
		GameStateChanged event = new GameStateChanged();
		event.setGameState(GameState.LOGGED_IN);
		return event;
	}

	private void flush()
	{
		List<Runnable> work = new ArrayList<>(pending);
		pending.clear();
		work.forEach(Runnable::run);
	}

	private void inject(String name, Object value) throws Exception
	{
		Field field = ReleaseNotesNotice.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(notice, value);
	}
}

package com.windowmarkers;

import java.util.*;
import org.junit.*;
import static org.junit.Assert.*;

public class SearchQualifiersTest
{
	private static ItemCatalogueIndex ge;

	@BeforeClass
	public static void catalogue()
	{
		ge = GeSearchIndexTest.index();
	}

	private Set<Integer> ids(String query)
	{
		var result = ge.find(query, "");
		assertNotNull(query, result);
		Set<Integer> ids = new HashSet<>();
		result.items.forEach(i -> ids.add(i.id));
		return ids;
	}

	@Test
	public void tierQualifiersPreserveGuideColumnsAndExcludeUnrankedBrokenItems()
	{
		for (String word : new String[] { "1", "1st", "bis", "first" })
			assertEquals(Collections.singleton(21018), ids("toa magic head " + word));
		for (String word : new String[] { "2", "2nd", "second" })
			assertEquals(Collections.singleton(26241), ids("toa magic head " + word));
		for (String word : new String[] { "3", "3rd", "third" })
			assertEquals(Collections.singleton(4708), ids("toa magic head " + word));
		assertEquals(new HashSet<>(Arrays.asList(21018, 4708)), ids("toa magic head 1 3"));
		assertTrue(ids("food bis").isEmpty());
	}

	@Test
	public void aliasesApplyToBothBankAndGe()
	{
		assertEquals(ids("toa body"), ids("toa top"));
		assertEquals(ids("toa legs"), ids("toa bottom"));
		assertEquals(ids("toa head"), ids("toa helmet"));
		assertEquals(ids("cox hands"), ids("cox gloves"));
		List<AutoCategories.Item> items = new ArrayList<>();
		for (var item : ge.find("toa", "").items)
			items.add(item.fact);
		BankSearchIndex bank = new BankSearchIndex(items, Collections.emptyList(), new CustomPresets());
		assertEquals(ids("toa magic head 2nd"), bank.find("toa magic head 2nd"));
		assertEquals(ids("toa top"), bank.find("toa top"));
	}

	@Test
	public void numberedItemNamesAndOtherSearchSyntaxRemainNative()
	{
		var index = new ItemCatalogueIndex(
				Collections.singletonList(GeSearchIndexTest.item(6691, "Saradomin brew(1)", -1)));
		assertNull(index.find("Saradomin brew(1)", ""));
		assertNull(index.find("tag:toa 1st", ""));
		assertNull(index.find("ge>1000", ""));
	}

	@Test
	public void openingACategoryKeepsItsSpecificFacet()
	{
		var choice = new BankCatalogue.Choice(BankCatalogue.Kind.CATEGORY, "Mining — boosts", "Mining — boosts");
		assertEquals("Mining — boosts", choice.viewQuery());
		var index = new ItemCatalogueIndex(
				Arrays.asList(GeSearchIndexTest.item(11920, "Dragon pickaxe", 3),
						GeSearchIndexTest.item(1275, "Rune pickaxe", 3), GeSearchIndexTest.item(385, "Shark", -1)),
				false);

		var result = index.find(choice.viewQuery(), "");
		if (result != null)
			assertFalse(result.items.stream().anyMatch(i -> i.id == 1275 || i.id == 385));
	}
}

