	private Widget mutableCell()
	{
		Widget w = cell(-1, "Preview", -1, "", 0, 0);
		AtomicInteger id = new AtomicInteger(-1);
		when(w.getItemId()).thenAnswer(i -> id.get());
		doAnswer(i ->
		{
			id.set(i.getArgument(0));
			return w;
		}).when(w).setItemId(anyInt());
		return w;
	}

	private void assertNoOverlap(List<Widget> widgets, List<SetupItemLayout.Heading> headings)
	{
		List<java.awt.Rectangle> cells = new ArrayList<>();
		for (Widget w : widgets)
			cells.add(new java.awt.Rectangle(w.getOriginalX(), w.getOriginalY(), 36, 32));
		for (var h : headings)
			if (h.emptySlot)
				cells.add(new java.awt.Rectangle(h.x, h.y, 36, 32));
		for (int a = 0; a < cells.size(); a++)
			for (int b = a + 1; b < cells.size(); b++)
				assertFalse(cells.get(a) + " overlaps " + cells.get(b), cells.get(a).intersects(cells.get(b)));
	}

