		{
			px.set(i.getArgument(0));
			return w;
		}).when(w).setOriginalX(anyInt());
		doAnswer(i ->
		{
			py.set(i.getArgument(0));
			return w;
		}).when(w).setOriginalY(anyInt());
		return w;
	}

