				if (!id.isEmpty())
					ids.add(Integer.parseInt(id));
			allowed.put(r[0] + "/" + r[1], ids);
		}
		Map<String, Integer> order = new HashMap<>();
		for (String[] r : ItemTaxonomy.readRows("setup-layout-options.tsv", 5))
		{
