	@Test
	public void bankAndGeShareHeadFilteringColoursAndBrokenStateRules()
	{
		List<AutoCategories.Item> items = Arrays.asList(item(21018, "Ancestral hat"), item(26241, "Virtus mask"),
				item(4708, "Ahrim's hood"), item(4860, "Ahrim's hood 0"), item(21021, "Ancestral robe top"));
		BankSearchIndex.Match result = bank(items, Collections.emptyList()).search("toa magic head", "");
		assertTrue(result.slots);
		assertFalse(result.ids.contains(21021));
		assertEquals(1, result.ranks.get(21018).tier);
		assertEquals(2, result.ranks.get(26241).tier);
		assertEquals(3, result.ranks.get(4708).tier);
