				new BankCatalogue.Choice(BankCatalogue.Kind.CATEGORY, "Mining tools", "Mining tools"),
				new BankCatalogue.Choice(BankCatalogue.Kind.CATEGORY, "Minigame tools", "Minigame tools"));
