		tekton.linkedItemIds = new int[] { 22978 };
		tekton.guideQuery = "cox weapon";
		tekton.guideContext = "94147:14";
		BankSearchIndex index = bank(Collections.singletonList(item(22978, "Dragon hunter lance")),
				Arrays.asList(olm, tekton));
		Marker copy = new com.google.gson.Gson().fromJson(new com.google.gson.Gson().toJson(olm), Marker.class);
		assertEquals(2, index.ranks(Collections.singletonList(copy)).get(22978).tier);
