package com.windowmarkers;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TaxonomyTest
{
	private static AutoCategories.Item item(int id, String name)
	{
		return new AutoCategories.Item(id, name, true, new String[] { "Eat", "Drink" }, 200, 0, 0);
	}

	private static final AutoCategories.Preset[] RAIDS = { AutoCategories.Preset.CHAMBERS_OF_XERIC,
			AutoCategories.Preset.THEATRE_OF_BLOOD, AutoCategories.Preset.TOMBS_OF_AMASCUT };

	private static boolean marked(Map<String, List<AutoCategories.Item>> groups, int id)
	{
		return groups.values().stream().flatMap(Collection::stream).anyMatch(i -> i.id == id);
	}

	@Test
	public void weaponRolesBeatMisleadingStatsAndItemNames()
	{
		for (String name : Arrays.asList("Ancient sceptre", "Ice ancient sceptre", "Twinflame staff", "Toktz-mej-tal",
				"Void knight mace", "Tumeken's shadow", "Trident of the swamp", "Warped sceptre"))
		{
			assertEquals(name, "Magic weapons", AutoCategories.category(item(1, name), true));
		}
		assertEquals("Ranged weapons", ItemTaxonomy.weaponRole("eclipse atlatl"));
		assertEquals("Hybrid weapons", ItemTaxonomy.weaponRole("black salamander"));
		assertEquals("Melee weapons", ItemTaxonomy.weaponRole("ancient mace"));
		assertEquals("Tools", ItemTaxonomy.weaponRole("dragon pickaxe"));
		assertEquals("Melee weapons", ItemTaxonomy.weaponRole("dragon battleaxe"));
	}

	@Test
	public void everyBarrowsAndMoonWeaponBelongsWithItsArmour()
	{
		String[][] pairs = { { "Ahrim's robetop", "Ahrim's staff" }, { "Dharok's platebody", "Dharok's greataxe" },
				{ "Guthan's chainskirt", "Guthan's warspear" }, { "Karil's leathertop", "Karil's crossbow" },
				{ "Torag's platelegs", "Torag's hammers" }, { "Verac's brassard", "Verac's flail" },
				{ "Blood moon chestplate", "Dual macuahuitl" }, { "Blue moon tassets", "Blue moon spear" },
				{ "Eclipse moon helm", "Eclipse atlatl" } };
		for (String[] pair : pairs)
		{
			assertNotNull(pair[0], ItemTaxonomy.equipmentSet(pair[0]));
			assertEquals(pair[1], ItemTaxonomy.equipmentSet(pair[0]), ItemTaxonomy.equipmentSet(pair[1]));
		}
		for (int condition : new int[] { 100, 75, 50, 25, 0 })
		{
			assertEquals(ItemTaxonomy.equipmentSet("guthan's warspear"),
					ItemTaxonomy.equipmentSet("Guthan's warspear " + condition));
		}
		assertNull(ItemTaxonomy.equipmentSet("Guthan's armour set"));
		assertNull(ItemTaxonomy.equipmentSet("Void knight mace"));
		assertNull(ItemTaxonomy.equipmentSet("Crystal pickaxe"));
		assertNull(ItemTaxonomy.equipmentSet("Atlatl dart"));
		assertNull(ItemTaxonomy.equipmentSet("Toktz-mej-tal"));
	}

	@Test
	public void unrelatedFoodAndPotionsNeverLeakIntoAnyRaid()
	{
		String[] excluded = { "Dwarven rock cake", "Rock cake", "Blighted anglerfish", "Blighted manta ray",
				"Blighted super restore(4)", "Purple sweets", "Sailing brew", "Fisherman's brew", "Zamorak brew(4)",
				"Attack potion(4)", "Fishing potion(4)", "Agility potion(4)", "Hunter potion(4)", "Compost potion(4)",
				"Super antifire potion(4)", "Antifire potion(4)", "Combat potion(4)", "Energy potion(4)",
				"Weapon poison(++)", "Beer", "Basket", "Saradomin brew(0)", "Super combat potion mix(2)", "Mind rune",
				"Body rune", "Blood moon armour set", "Tumeken's shadow ornament kit" };
		List<AutoCategories.Item> items = new ArrayList<>();
		for (int i = 0; i < excluded.length; i++)
		{
			items.add(item(i, excluded[i]));
		}
		for (AutoCategories.Preset raid : RAIDS)
		{
			assertTrue(raid.toString(), AutoCategories.suggest(raid, items).isEmpty());
		}
	}

	@Test
	public void armourAccessoriesAndWeaponsAreIncludedForEveryRaid()
	{
		List<AutoCategories.Item> bank = Arrays.asList(item(1, "Torva platebody"), item(2, "Bandos tassets"),
				item(3, "Virtus robe top"), item(4, "Ancestral robe bottom"), item(5, "Occult necklace"),
				item(6, "Primordial boots"), item(7, "Super restore(2)"), item(8, "Saradomin brew(4)"));
		for (AutoCategories.Preset raid : RAIDS)
		{
			Map<String, List<AutoCategories.Item>> groups = AutoCategories.suggest(raid, bank);
			for (AutoCategories.Item i : bank)
			{
				assertTrue(raid + " missing " + i.name, marked(groups, i.id));
			}
		}
		assertTrue(marked(AutoCategories.suggest(AutoCategories.Preset.TOMBS_OF_AMASCUT,
				Arrays.asList(item(10, "Karil's leathertop 75"), item(11, "Masori body (f)"))), 10));
		assertFalse(marked(AutoCategories.suggest(AutoCategories.Preset.THEATRE_OF_BLOOD,
				Arrays.asList(item(10, "Karil's leathertop 75"))), 10));
	}

	@Test
	public void incompleteSetsAndBrokenGearAreNotDefaultRecommendations()
	{
		List<AutoCategories.Item> bank = new ArrayList<>(Arrays.asList(item(1, "Elite void top"),
				item(2, "Elite void robe"), item(3, "Void ranger helm"), item(4, "Ancestral robe top (broken)")));
		Map<String, List<AutoCategories.Item>> groups = AutoCategories.suggest(AutoCategories.Preset.THEATRE_OF_BLOOD,
				bank);
		assertTrue(groups.containsKey("ToB Incomplete Void set — review"));
		assertFalse(RaidRecommendations.defaultSelected("ToB Incomplete Void set — review"));
		assertFalse(RaidRecommendations.defaultSelected("ToB Needs repair/charge — review"));
		bank.add(item(5, "Void knight gloves"));
		assertEquals(4, AutoCategories.suggest(AutoCategories.Preset.THEATRE_OF_BLOOD, bank)
				.get("ToB Elite Void switches — choose helm for role").size());
	}

	@Test
	public void variantsAreConservativeAndPotionsRetainTheirIdentity()
	{
		assertTrue(ItemTaxonomy.matches("Holy sanguinesti staff", "Sanguinesti staff"));
		assertTrue(ItemTaxonomy.matches("Bow of faerdhinen (c)", "Bow of faerdhinen"));
		assertTrue(ItemTaxonomy.matches("Twisted ancestral robe top", "Ancestral robe top"));
		assertTrue(ItemTaxonomy.matches("Imbued zamorak cape", "God capes"));
		assertTrue(ItemTaxonomy.matches("Saradomin d'hide body", "Blessed body"));
		assertFalse(ItemTaxonomy.matches("Berserker ring", "Berserker ring (i)"));
		assertFalse(ItemTaxonomy.matches("Ancient sceptre ornament kit", "Ancient sceptre"));
		assertEquals("saradomin brew", ItemTaxonomy.baseName("Saradomin brew(3)"));
		assertEquals("blighted super restore", ItemTaxonomy.baseName("Blighted super restore(4)"));
		assertNull(RaidRecommendations.supplyGroup("tob", "Sanfew serum(4)"));
		assertNotNull(RaidRecommendations.supplyGroup("cox", "Sanfew serum(4)"));
		assertNull(RaidRecommendations.supplyGroup("toa", "Stamina potion(4)"));
	}

	@Test
	public void sharedAccessoriesDoNotBecomeMeleeBecauseItsScoreIsHigher()
	{
		AutoCategories.Item gloves = new AutoCategories.Item(-1, "Barrows gloves", true, null, 24, 12, 6);
		assertTrue(AutoCategories.category(gloves, true).startsWith("Hybrid equipment"));
		AutoCategories.Item drink = new AutoCategories.Item(-2, "Fisherman's brew", false, new String[] { "Drink" }, 0,
				0, 0);
		assertFalse(AutoCategories.category(drink, false).startsWith("Combat"));
	}
}

package com.windowmarkers;

import java.util.*;
import java.util.stream.Collectors;
import org.junit.Test;
import static org.junit.Assert.*;

public class WildernessLoadoutTest
{
	private static Map<Integer, ItemCatalogueIndex.Item> bank()
	{
		Map<Integer, ItemCatalogueIndex.Item> bank = new LinkedHashMap<>();
		for (String[] row : ItemTaxonomy.readRows("ge-item-slots.tsv", 3))
		{
			int id = Integer.parseInt(row[0]);
			bank.put(id, GeSearchIndexTest.item(id, row[2], Integer.parseInt(row[1])));
		}
		for (Object[] row : new Object[][] { { 23733, "Divine ranging potion(4)" }, { 24589, "Blighted manta ray" },
				{ 24595, "Blighted karambwan" }, { 24598, "Blighted super restore(4)" } })
		{
			int id = (int) row[0];
			bank.put(id, GeSearchIndexTest.item(id, (String) row[1], -1));
		}
		return bank;
	}

	@Test
	public void wildernessDefaultsUseOwnedSpecialistWeaponsAndBudgetArmour()
	{
		var bank = bank();
		var index = new ItemCatalogueIndex(new ArrayList<>(bank.values()), false);
		for (String activity : Arrays.asList("Callisto", "Artio", "Venenatis", "Spindel", "Vet'ion", "Calvar'ion",
				"Scorpia", "Chaos Fanatic", "Chaos Elemental", "Revenants", "Krystilia", "King Black Dragon",
				"Green dragon", "Chaos Temple (church)", "Abyss", "Chest (Rogues' Castle)"))
		{
			var result = index.find(activity, "");
			assertNotNull(activity, result);
			assertNotNull(activity, result.loadout);
			assertTrue(activity, result.loadout.wildernessBudget);
			for (var item : result.items)
				assertTrue(activity + " included " + item.name, WildernessLoadout.allowed(item));
			for (var part : result.loadout.sections())
			{
				for (var ids : part.equipment.values())
					for (int id : ids)
						assertFalse(activity + " unready " + id,
								ItemVariantState.needsActivityReview(bank.get(id).fact));
				for (var field : part.inventoryExample.values())
					for (int id : field.ids)
						assertTrue(activity + " expensive preview " + id, WildernessLoadout.allowedPreview(id));
				assertFalse(activity, part.sectionName.contains("BIS smuggle"));
			}
		}
		var callisto = index.find("callisto", "").loadout;
		var ranged = callisto.sections().stream().filter(s -> s.sectionName.equals("Ranged")).findFirst().orElseThrow();
		assertEquals(Integer.valueOf(27655), ranged.equipment.get(3).get(0));
		assertEquals(Integer.valueOf(2503), ranged.equipment.get(4).get(0));
		assertEquals(Integer.valueOf(2497), ranged.equipment.get(7).get(0));
		assertEquals(Integer.valueOf(23733), ranged.inventory.get(2));
		var magic = callisto.sections().stream().filter(s -> s.sectionName.equals("Magic")).findFirst().orElseThrow();
		assertEquals(Integer.valueOf(27665), magic.equipment.get(3).get(0));
		assertEquals(Integer.valueOf(4091), magic.equipment.get(4).get(0));
		assertEquals(Integer.valueOf(4093), magic.equipment.get(7).get(0));
		var calvar = index.find("calvar'ion", "").loadout;
		assertTrue(calvar.inventoryName, calvar.inventoryName.startsWith("Low-Risk"));
		assertEquals(Integer.valueOf(27660), calvar.equipment.get(3).get(0));
	}

	@Test
	public void expensiveOnlyBankDoesNotQuietlyBecomeABisWildernessSetup()
	{
		var bank = bank();
		bank.keySet().retainAll(new HashSet<>(Arrays.asList(27238, 27241, 31097, 26382, 21021, 27275, 20997)));
		var result = new ItemCatalogueIndex(new ArrayList<>(bank.values()), false).find("callisto", "");
		assertTrue(result.items.isEmpty());
		for (var part : result.loadout.sections())
			assertTrue(part.equipment.isEmpty());
		assertTrue(result.loadout.notEnoughGear());
		assertTrue(result.loadout.hasExamples());
		var ranged = result.loadout.sections().get(0);
		assertEquals(Integer.valueOf(2503), ranged.equipmentExample.get(4));
		assertEquals(Integer.valueOf(2497), ranged.equipmentExample.get(7));
		assertEquals(Integer.valueOf(12788), ranged.equipmentExample.get(3));
		assertEquals(Integer.valueOf(892), ranged.equipmentExample.get(13));
		assertEquals(Integer.valueOf(7460), result.loadout.sections().get(1).equipmentExample.get(9));
		assertTrue(result.loadout.itemIds().isEmpty());
		assertFalse(result.loadout.retainItems(Collections.emptySet()).hasExamples());
	}

	@Test
	public void suggestionsNeverBroadenTheBudgetFilterOrReplaceOwnedGear()
	{
		var bank = bank();
		var full = new ItemCatalogueIndex(new ArrayList<>(bank.values()), false).find("callisto", "").loadout;
		assertFalse(full.notEnoughGear());
		for (var part : full.sections())
			assertFalse(part.equipmentExample.containsKey(3));
		var empty = SetupLoadout.build(ActivitySetups.forActivity("Callisto"), Collections.emptyMap(),
				Collections.emptySet(), "");
		for (var part : empty.sections())
			for (int id : part.equipmentExample.values())
			{
				assertTrue(WildernessLoadout.allowed(bank.get(id)));
				assertFalse(WildernessLoadout.wildernessWeapon(id));
				assertTrue(ActivitySetups.byId(part.equipmentSource).itemIds.contains(id));
				assertFalse(ItemVariantState.needsActivityReview(bank.get(id).fact));
			}
		bank.keySet().retainAll(Collections.singleton(22947));
		var noWeapon = SetupLoadout.build(ActivitySetups.forActivity("Callisto"), bank, bank.keySet(), "").sections()
				.get(0);
		assertEquals(Integer.valueOf(12788), noWeapon.equipmentExample.get(3));
		assertEquals(Integer.valueOf(892), noWeapon.equipmentExample.get(13));
		assertEquals(Collections.singleton(22947), noWeapon.itemIds());
	}

	@Test
	public void explicitSourceChoicesAndNonWildernessActivitiesKeepTheirReviewedGear()
	{
		var bank = bank();
		var index = new ItemCatalogueIndex(new ArrayList<>(bank.values()), false);
		var exact = index.find("callisto", "61964:1");
		assertFalse(exact.loadout.wildernessBudget);
		assertTrue(exact.items.stream().anyMatch(i -> i.id == 27238));
		var hydra = index.find("hydra", "");
		assertFalse(hydra.loadout.wildernessBudget);
		assertTrue(hydra.items.stream().anyMatch(i -> i.id == 27238));
		var custom = index.find("callisto", "").loadout.retainItems(Collections.singleton(2503));
		assertTrue(custom.wildernessBudget);
		assertEquals(Collections.singleton(2503), custom.itemIds());
	}

	@Test
	public void blightedAndDivineInventoryItemsAreNotLabelledAsUnreadyInTheirGuide()
	{
		var result = new ItemCatalogueIndex(new ArrayList<>(bank().values()), false).find("callisto", "");
		for (int id : new int[] { 23733, 24589, 24595 })
		{
			assertFalse(result.ranks.get(id).explanation.contains("not a ready-to-use"));
			assertFalse(result.ranks.get(id).explanation.contains("Activity restrictions — review"));
		}
	}
}

package com.windowmarkers;

import java.lang.reflect.*;
import java.util.*;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class WindowMarkersConfigProxyTest
{

	static WindowMarkersConfig proxy(Map<String, String> saved) throws Exception
	{
		ConfigManager manager = mock(ConfigManager.class, CALLS_REAL_METHODS);
		doAnswer(call -> saved.get(call.getArgument(1))).when(manager).getConfiguration(eq("windowmarkers"),
				anyString());
		Constructor<?> constructor = Class.forName("net.runelite.client.config.ConfigInvocationHandler")
				.getDeclaredConstructor(ConfigManager.class);
		constructor.setAccessible(true);
		InvocationHandler handler = (InvocationHandler) constructor.newInstance(manager);
		return (WindowMarkersConfig) Proxy.newProxyInstance(WindowMarkersConfig.class.getClassLoader(),
				new Class<?>[] { WindowMarkersConfig.class }, handler);
	}

	@Test
	public void everyConfigDefaultCanBeReadThroughRunelitesProxy() throws Exception
	{
		WindowMarkersConfig actual = proxy(Collections.emptyMap()), defaults = new WindowMarkersConfig()
		{
		};
		for (Method method : WindowMarkersConfig.class.getMethods())
			if (method.isAnnotationPresent(ConfigItem.class))
				assertEquals(method.getName(), method.invoke(defaults), method.invoke(actual));
	}

	@Test
	public void activityModeRetainsEveryExistingStoredValue() throws Exception
	{
		Method method = WindowMarkersConfig.class.getMethod("geActivityFilter");
		assertEquals("geActivityFilter", method.getAnnotation(ConfigItem.class).keyName());
		for (Object value : method.getReturnType().getEnumConstants())
		{
			WindowMarkersConfig config = proxy(Collections.singletonMap("geActivityFilter", ((Enum<?>) value).name()));
			assertSame(value, config.geActivityFilter());
		}
	}
}

