	@Test
	public void legendCombinesSearchAndGroupManagementAtSidebarWidth() throws Exception
	{
		WindowMarkersPlugin p = plugin();
		try
		{
			var captured = org.mockito.ArgumentCaptor.forClass(net.runelite.client.ui.NavigationButton.class);
			verify(p.toolbar).addNavigation(captured.capture());
			SwingUtilities.invokeAndWait(() ->
			{
				try
				{
					Container panel = captured.getValue().getPanel();
					javax.swing.JTabbedPane tabs = null;
					for (Component child : panel.getComponents())
						if (child instanceof javax.swing.JTabbedPane)
							tabs = (javax.swing.JTabbedPane) child;
					assertNotNull(tabs);
					assertEquals(3, tabs.getTabCount());
					assertEquals("Legend", tabs.getTitleAt(0));
					assertEquals("Custom", tabs.getTitleAt(1));
					assertEquals("Tools", tabs.getTitleAt(2));
					Container legend = (Container) tabs.getComponentAt(0);
					legend.setSize(205, 700);
					layoutTree(legend);
					layoutTree(legend);
					java.util.List<javax.swing.JButton> buttons = new java.util.ArrayList<>();
					visibleButtons(legend, buttons);
					var names = buttons.stream().map(javax.swing.JButton::getText)
							.collect(java.util.stream.Collectors.toList());
					assertTrue(names.containsAll(
							java.util.Arrays.asList("Show in bank", "Clear bank filter", "Add to Legend")));
					assertEquals(1, names.stream().filter("Browse activities…"::equals).count());
					assertFalse(names.contains("Open saved view"));
