					for (var button : buttons)
						assertTrue(button.getText(), button.getFontMetrics(button.getFont()).stringWidth(button
								.getText()) <= button.getWidth() - button.getInsets().left - button.getInsets().right);
					BufferedImage image = new BufferedImage(205, 700, BufferedImage.TYPE_INT_ARGB);
					Graphics2D graphics = image.createGraphics();
					legend.printAll(graphics);
					graphics.dispose();
					java.io.File file = new java.io.File("build/ui-preview/sidebar.png");
					file.getParentFile().mkdirs();
					javax.imageio.ImageIO.write(image, "png", file);
				}
				catch (Exception ex)
				{
					throw new RuntimeException(ex);
				}
			});
		}
		finally
		{
			p.shutDown();
			SwingUtilities.invokeAndWait(() ->
			{
			});
		}
	}

	private void layoutTree(Container parent)
	{
		parent.doLayout();
		for (Component child : parent.getComponents())
			if (child instanceof Container && child.isVisible())
				layoutTree((Container) child);
	}

	private void visibleButtons(Container parent, java.util.List<javax.swing.JButton> buttons)
	{
		for (Component child : parent.getComponents())
			if (child.isVisible())
			{
				if (child instanceof javax.swing.JButton)
					buttons.add((javax.swing.JButton) child);
				if (child instanceof Container)
					visibleButtons((Container) child, buttons);
			}
	}

