	@Test
	public void customPresetsUseAccountAndRuneLiteProfileAndRetainSavedMarkers() throws Exception
	{
		WindowMarkersPlugin p = plugin();
		Map<String, String> saved = new HashMap<>();
		when(p.configs.getConfiguration(eq("windowmarkers"), anyString(), anyString()))
				.thenAnswer(call -> saved.get(call.getArgument(1) + "/" + call.getArgument(2)));
		doAnswer(call ->
		{
			saved.put(call.getArgument(1) + "/" + call.getArgument(2), call.getArgument(3));
			return null;
		}).when(p.configs).setConfiguration(eq("windowmarkers"), anyString(), anyString(), anyString());
		var field = BankLayouts.class.getDeclaredField("customPresets");
		field.setAccessible(true);
		var save = WindowMarkersPlugin.class.getDeclaredMethod("savePresets");
		save.setAccessible(true);
		try
		{
			CustomPresets library = (CustomPresets) field.get(p.layouts);
			CustomPresets.Preset preset = new CustomPresets.Preset();
			preset.name = "My Food";
			Marker group = new Marker(0, 0, 48, 36);
			group.linkedItemIds = new int[] { 385, 3144 };
			group.label = "Food";
			preset.groups.add(group);
			preset.bankView = true;
			preset.groupBySlot = true;
			library.presets.add(preset);
			save.invoke(p);
			String original = saved.get("account-a/markersV3_profile_10_customPresets");
			assertNotNull(original);
			p.createNamedLayout("Raid", false, false);
			assertEquals("My Food", ((CustomPresets) field.get(p.layouts)).presets.get(0).name);
			when(p.configs.getProfile().getId()).thenReturn(20L);
			p.onProfileChanged(new ProfileChanged());
			assertTrue(((CustomPresets) field.get(p.layouts)).presets.isEmpty());
			when(p.configs.getProfile().getId()).thenReturn(10L);
			p.onProfileChanged(new ProfileChanged());
			assertEquals(1, ((CustomPresets) field.get(p.layouts)).presets.size());
			assertTrue(((CustomPresets) field.get(p.layouts)).presets.get(0).bankView);
			assertTrue(((CustomPresets) field.get(p.layouts)).presets.get(0).groupBySlot);
			when(p.configs.getRSProfileKey()).thenReturn("account-b");
			p.onRuneScapeProfileChanged(new RuneScapeProfileChanged("account-a", "account-b"));
			assertTrue(((CustomPresets) field.get(p.layouts)).presets.isEmpty());
			assertEquals(original, saved.get("account-a/markersV3_profile_10_customPresets"));
			assertNull(saved.get("account-b/markersV3_profile_10_customPresets"));
		}
		finally
		{
			p.shutDown();
		}
	}

